export default [{"id":17,"question":"هناك شخصٌ استهزأ بآيةٍ من كتاب الله الكريم، وسخر من الآية، وأتى بكلامٍ لا يليق، كأنَّ قائله هو الله تبارك وتعالى، ولما علم الحكم في ذلك استغفر الله في نفس اللحظة، فهل يُعتبر هذا الاستغفار توبةً له؟","title":"حكم الاستهزاء بآيات القرآن الكريم","answer":"الجواب: إذا كان استغفارًا مع الندم بقلبه والرجوع إلى الله والصدق فهو توبة، أما إن كان استغفارًا باللسان وقلبه مقيمٌ على الخبث والاستهزاء فما ينفع الكلام، قال الله تعالى: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنْتُمْ تَسْتَهْزِئُونَ ۝ لَا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65- 66].\nفالواجب التوبة الصَّادقة من قلبه، فإذا تاب من قلبه توبةً صادقةً تاب الله عليه، وعليه مع هذا أن يجتهد في العمل الصالح والاستغفار، كما قال : وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82]، وقال سبحانه لما ذكر الشِّرك والقتل والزنا: إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُولَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ [الفرقان:70].\nفالمؤمن إذا وقع في المُصيبة -في الزلة، في المعصية- أو في الكفر عليه أن يُبادر بالتوبة الصَّادقة: بالندم بقلبه، والعزم ألا يعود، وكثرة الاستغفار، والله يتوب على التائبين .","link":"https://binbaz.org.sa/fatwas/2796/حكم-الاستهزاء-بايات-القران-الكريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0269.mp3","categories":["نواقض الإسلام"]},{"id":80,"question":"سائل يقول: هل كل مَن يقع في الشرك الأكبر يكون مشركًا وتُطبق عليه أحكام المشركين؟","title":"هل كل من يقع بالشرك الأكبر يكون مشركاً؟","answer":"الجواب: نعم، مَن كفر بالله صار كافرًا، ومَن أشرك بالله صار مُشركًا، كما أنَّ مَن آمن بالله ورسوله صار مُوحِّدًا مُؤمِنًا. أما مَن لم تبلغه الدَّعوةُ فهذا لا يُقال له: مؤمن ولا كافر، ولا يُعامل معاملة المسلمين، بل أمره إلى الله يوم القيامة، وهم أهل الجهل الذين ما بلغتهم الدعوةُ، فهؤلاء يُمتحنون يوم القيامة؛ فيبعث الله إليهم عنقًا من النار ويُقال: ادخلوا، فمَن أجاب صارت عليه بردًا وسلامًا، ومَن لم يُجِب ورث النار -نسأل الله العافية.\nوالمقصود أنَّ مَن بلغته الدعوةُ ولم يُؤمن ولم يُسلم فهو كافرٌ عدوٌّ لله.","link":"https://binbaz.org.sa/fatwas/3061/هل-كل-من-يقع-بالشرك-الاكبر-يكون-مشركا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0057.mp3","categories":["نواقض الإسلام"]},{"id":84,"question":"هناك مَن يتلفَّظ بألفاظٍ فيها الاستعانة بالجنِّ، والدُّعاء والحلف بالنبي ﷺ، وعندما يُنَبَّه يقول: اعتاد عليها لساني، فما الحكم في ذلك؟","title":"حكم من اعتاد لسانه ترديد ألفاظ شركية","answer":"الجواب: يجب أن يُعوِّد لسانه الكلام الطيب، ويحذر الكلام المنكر، وليس هذا بعذرٍ، يجب أن يحفظ لسانَه عمَّا حرَّم الله، فالاستغاثة بالجن والدُّعاء من الشرك بالله جلَّ وعلا، قال تعالى: وَأَنَّهُ كَانَ رِجَالٌ مِنَ الْإِنْسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا [الجن:6]، وكان الكثير من العرب في جاهليتهم يعبدون الجنَّ، ويستعيذون بهم، ويخافونهم.\nفالواجب على المؤمن أن يحذر ذلك، وأن يثق بالله، ويعتمد على الله، ويستعيذ بكلمات الله التامَّات ليلًا ونهارًا من شرِّ ما خلق، ويقيه الله شرَّهم، يقول: \"أعوذ بكلمات الله التامَّات من شرِّ ما خلق\"، في ليله ونهاره، وفي أي منزلٍ، وفي أي مكانٍ: \"أعوذ بكلمات الله التامَّات من شرِّ ما خلق\"، يُكررها ثلاثًا أو أكثر، دائمًا، صباحًا ومساءً، ويقيه الله من شرِّهم.\nوهكذا إذا قال: \"بسم الله الذي لا يضرُّ مع اسمه شيءٌ في الأرض ولا في السَّماء، وهو السميع العليم\" ثلاث مرات، صباحًا ومساءً، هذا من أسباب العافية من كل شيءٍ.\nوهكذا قراءة قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين صباحًا ومساءً، ثلاث مرات: بعد الفجر، وبعد المغرب، من أسباب السلامة من كل شرٍّ.\nفالمقصود أن الواجب عليه أن يحفظ لسانَه عمَّا حرم الله من سائر الكلام الرديء: من دعاء الجن، ومن الحلف بغير الله، ومن غير هذا من سائر كلامه المنكر، وليس له عذر بقوله: اعتاده لساني، بل يحذر ويحفظ لسانه عمَّا حرم الله، يقول النبيُّ ﷺ: مَن كان يُؤمن بالله واليوم الآخر فليقل خيرًا أو ليصمت، والله يقول في كتابه العظيم: مَا يَلْفِظُ مِنْ قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌ [ق:18].\nوهو مسؤول عن كلامه، فعليه أن يحفظ لسانه عن كل ما حرم الله: من الغيبة، والنَّميمة، والسَّب، ودعاء الجن، والتوسل بالمخلوقات إلى الله، كأن يتوسل بالنبي، أو بجاه النبي، أو بحقِّ النبي؛ فكل هذا لا يجوز، فالتوسل يكون بدعاء الله وتوحيده، وبالإيمان به سبحانه، واتباع الشريعة، والتوسل بأعمالك الصَّالحة، كل هذا طيب.\n\"اللهم إني أسألك بإيماني بك، وبمحبَّتي لك، وباتِّباعي لنبيك محمد ﷺ، وببري والدي، وبصلتي الرحم، وبأدائي للأمانة\"، فتتوسل بأعمالك مثل أصحاب الغار الذين توسَّلوا إلى الله بأعمالهم الصَّالحة؛ فأنجاهم الله وفرَّج كربتهم، فقد أخبر الرسولُ ﷺ عن ثلاثةٍ ممن قبلنا دعاهم المبيت من المطر إلى غارٍ، فدخلوا فيه من أجل المطر والليل، يبيتون فيه، فأنزل الله صخرةً تدحرجت من أعلى الجبل حتى سدَّت عليهم الغار، ولم يستطيعوا لها دفعًا، فقالوا فيما بينهم: لن يُخلصكم من هذه الصَّخرة إلا أن تدعوا الله بصالح أعمالكم، فتوسَّلوا إلى الله بصالح أعمالهم، فأنجاهم الله منها.\nقال أحدهم: \"اللهم إنه كان لي أبوان شيخان كبيران، وكنتُ لا أغبق قبلهما أهلًا ولا مالًا\".\nالغبوق: الحليب في أول الليل، فكان من عادة البادية أن يصبُّوا الغبوقَ في الليل إذا حلبوا الإبل.\nفكان يأتي بالحليب ليسقي والديه قبل أهله، فنأى به طلبُ الشجر ذات ليلةٍ فتأخَّر، فجاء فوجدهما نائمين، فكره أن يُوقظهما، وبقي واقفًا بالقدح ينتظر استيقاظهما، والصِّبية عند قدميه يتباكون يُريدون الحليب، ومن شدَّة حبِّه لوالديه وبره لهما بقي واقفًا حتى طلع الفجر، فاستيقظا، فسقاهما، ثم قال: \"اللهم إن كنتَ تعلم أني فعلتُ ذلك ابتغاء وجهك فافرج عنا ما نحن فيه\"، فانفرجت الصخرةُ بعض الشيء، لكنَّهم لا يستطيعون الخروج.\nثم قال الثاني: \"اللهم إنه كانت لي ابنةُ عمٍّ من أحبِّ الناس إليَّ، فراودتُها عن نفسها -أي: الزنا- فأبت عليَّ\"، فألمّت بها سنةٌ شديدةٌ -أي: حاجة- فجاءت إليه تطلب الرفد وسدّ الحاجة، فقال: \"لا، حتى تُمكنيني من نفسك\"، أي: حتى تسمح له بالزنا بها، وعند الضَّرورة سمحت، فلما جلس بين رجليها قالت: \"يا عبدالله، اتَّقِ الله ولا تفضَّ الخاتمَ إلَّا بحقِّه\"، وقد أعطاها مئة وعشرين دينارًا، فلما قالت له ذلك خاف من الله، وقام وتركها، وترك الذهبَ لها، ثم قال في هذه الحادثة: \"اللهم إن كنتَ تعلم أني فعلتُ هذا ابتغاء وجهك -أي: تركت الزنا وتركت الذهب خوفًا منك- فافرج عنا ما نحن فيه\"، فانفرجت الصخرةُ قليلًا أيضًا، لكنَّهم لا يستطيعون الخروج.\nثم قام الثالث فقال: \"اللهم إنه كان لي أُجراء -عمَّال عنده- فأعطيتُهم حقوقَهم إلَّا واحدًا بقي له حقٌّ عندي، فنمَّيتُه وثمَّرته في إبلٍ وبقرٍ وغنمٍ وعبيدٍ، وبقيتُ أنتظر مجيئه ليأخذ حقَّه\"، فصار يتصرف ويتَّجر فيه، واشترى من الإبل، وهو إنما بقيت له آصُعٌ من شعيرٍ، أو من ذرة، أو من الأرز، فنَمَّى هذا المال، واتَّجر فيه، واشترى من الإبل والبقر والغنم والرقيق، فجاء بعد مدةٍ وقال: \"يا عبدالله، أعطني حقِّي الذي تركتُه عندك\"، قال: \"يا فلان، كل ما ترى من حقِّك\"، كل الإبل والبقر والغنم والعبيد من حقِّك، \"ثمَّرته لك\"، فقال: \"يا عبدالله، لا تستهزئ بي\"، قال: \"إني لا أستهزئ بك، هو من حقِّك فخذه، فاستاقه كلَّه\"، استاق الإبل والبقر والغنم والعبيد، ثم قال الرجل: \"اللهم إن كنتَ تعلم أني فعلتُ هذا ابتغاء وجهك فافرج عنا ما نحن فيه\"، فانفرجت الصَّخرةُ وخرجوا.\nفبسبب أعمالهم الصَّالحة التي توسَّلوا بها إلى الله  أنجاهم الله من الشدَّة التي حلَّت بهم، فتوسل إلى الله بإيمانك، وتقواك، وبرّ والديك، وأدائك الحقوق وأسلة صالحة وهكذا التوسل بتوحيد الله، والإخلاص له، والإيمان به؛ فكلها أعمال صالحة.\nتوسل إلى الله بأنَّك تشهد أن لا إله إلا الله، وأنَّ محمدًا رسول الله، وأنَّك تُؤمن بالله ورسوله، وأنَّك تؤمن باليوم الآخر، فهذا كله وسيلة شرعيَّة، مثل: \"اللهم إني أسألك بأسمائك وصفاتك\".\nأما التوسل بالمخلوقات، أو بجاه النبي، أو بحقِّ النبي، أو بجاه فلان، أو برأس فلان، أو بشرف فلان، فلا، فهذه وسيلة باطلة ما تُذْكَر، وليست وسيلةً شرعيةً.","link":"https://binbaz.org.sa/fatwas/3079/حكم-من-اعتاد-لسانه-ترديد-الفاظ-شركية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0061.mp3","categories":["نواقض الإسلام"]},{"id":139,"question":"ما حكم الاستهزاء باللحية وتقصير الثياب إلى ما فوق الكعبين؟","title":"حكم الاستهزاء باللحية وتقصير الثياب","answer":"الجواب: هذا محرَّم، الاستهزاء باللحية والاستهزاء بتقصير الثياب وعدم الإسبال؛ هذا منكرٌ عظيمٌ، قد يكون صاحبه مُرتدًّا -نعوذ بالله- قد يكفر بذلك، فإن كان قصده الاستهزاء بالدِّين فهذا يكون ردةً عن الإسلام، يقول الله جلَّ وعلا: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنْتُمْ تَسْتَهْزِئُونَ ۝ لَا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65- 66]، فالاستهزاء باللحية أو بالصلاة أو بالصيام أو بتقصير الثياب وعدم إسبالها هذا خطرٌ عظيمٌ، فإذا كان قصده احتقار الدين والتَّنقص بالدِّين فإنه يكون ردَّةً عن الإسلام -نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/3675/حكم-الاستهزاء-باللحية-وتقصير-الثياب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0131.mp3","categories":["نواقض الإسلام"]},{"id":577,"question":"وهل الصحابة سواء في السب؟","title":"ما حكم سب الصحابة؟","answer":"الجواب: المعروف عند العلماء أن من سبهم يُقتل؛ مرتد عن الإسلام، ما يسبهم إلا وهو قادح في دينهم وهم النَّقَلة الذين نقلوا لنا الدين كله.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6408/ما-حكم-سب-الصحابة","audio":"undefined","categories":["الجنايات والحدود","نواقض الإسلام"]},{"id":578,"question":"بعض الناس يقول إن سب الدين إذا صدر عن اعتقاد يكون كفرًا أكبر وإذا كان عملي فصار كفر أصغر.","title":"ما حكم من يسب الدين؟","answer":"الجواب: هذا كلام باطل، تفريق باطل، سب الدين مطلقًا ردة عن الإسلام، سواء قال الإنسان إني أعتقد أو ما أعتقد، ما دام سب؛ وجب قتله وحُكم بكفره.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6409/ما-حكم-من-يسب-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/maram143 - 01 -  Start.mp3","categories":["الجنايات والحدود","نواقض الإسلام"]},{"id":701,"question":"يقول: هل الإنسان معذور بالتَّلفظ بكلمة الشرك، مثل: يا أم الصبيان، وغير ذلك، وإن لم يكن معذورًا، وكان له من الأقرباء مَن يفعل ذلك، فماذا عليه أن يفعل تجاه هؤلاء؟","title":"حكم قول: \"يا أم الصبيان خذيه\" ونحوها","answer":"الجواب: ليس هناك أحدٌ معذورٌ أن يفعل معصيةً، ما هو بالشرك، لا يجوز أن يرتكب المعصية ولو هي أدنى من الشرك، فكيف بالشرك؟ لا يجوز للمسلم أن يفعل المعصية ولا الشرك أبدًا، بل يجب الحذر من ذلك، الحذر من الشرك بأنواعه كلها، والحذر من المعاصي بأنواعها كلها، يجب الحذر أينما كان، إلا المكره كما قال الله جلَّ وعلا: مَنْ كَفَرَ بِاللَّهِ مِنْ بَعْدِ إِيمَانِهِ إِلَّا مَنْ أُكْرِهَ [النحل:106]، مَن أُكره -أُخِذَ بالسياط والضرب- حتى يتكلم بكلمة الكفر جاز أن يتكلم بها مع طمأنينة قلبه بالإيمان: مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالْإِيمَانِ، إنما تكلم خوفًا من السلاح، أو من الضرب، هذا مُكْرَهٌ.\nأما أن يتكلم مُراعاةً لخاطر فلان أو مُدارةً لفلانٍ فهذا لا يجوز، فإذا تكلَّم بالكفر كفر، وإذا عصى صار معه عاصيًا، وإذا قال: \"يا أم الصّبيان، خذيه\"، أو: \"يا سبعة، خذوه\"، أو: \"يا جنّ الظَّهيرة، خذوه\"، أو: \"يا جنّ فلانٍ، خذوه\"؛ هذا شركٌ بالله، هذا واقعٌ من بعض إخواننا في الجنوب، وهذا غلطٌ، فيجب التَّحذير منه، ولا يجوز إقراره، لا مع أبٍ، ولا مع أخٍ، ولا مع جارٍ، ولا مع زوجةٍ، يجب إنكاره بجدٍّ وقوةٍ وإخلاصٍ وصدقٍ ومتابعةٍ، واستعانة بالإخوان الطيبين، حتى يُعينوك على هذا الشيء، ويُجاهد معك.\nفأمور الشرك لا يُتساهل فيها أبدًا، لا مع الأب، ولا مع الأم، وأنت محسنٌ إذا جاهدتَ في هذا، أنت مُصلحٌ، فيك الخير، مأجورٌ، تُنجيه من النار، قد تسعى في نجاته من النار، لا تتساهل في هذا، لا يجوز التَّساهل في هذا أبدًا، لا مع الشرك، ولا مع المعصية، لكن الشرك أكبر: إذا كان في الأهل مَن يدعو إلى الجن، أو يذبح لهم، أو ينذر لهم، أو يتوسل بحجارةٍ، أو أصنام، أو أشجار يدعوها، فلا بد من إنكار ذلك؛ لأنَّ هذا شركٌ، وأنه واجبٌ تركه، والتعاون في ذلك مع الأقارب الطيبين: مع الأخوال، مع الجيران، مع غيرهم ممن هو طيب لا يرضى بهذا الشرك؛ لأن الله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2].","link":"https://binbaz.org.sa/fatwas/20545/حكم-قول-يا-ام-الصبيان-خذيه-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0508فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["نواقض الإسلام"]},{"id":724,"question":"ما حكم مَن يستهزئ بالشباب المُلتزم بكتاب الله وسنة رسوله ﷺ، ويُلقبهم بالألقاب البذيئة؟","title":"ما حكم مَن يستهزئ بالشباب المُتدينين؟","answer":"الجواب: هذا منكرٌ، هذا منكرٌ -نعوذ بالله- وعلى صاحبه خطرٌ من الردة؛ لأنه استهزأ بهم لدينهم، فهو على خطرٍ عظيمٍ للردة، ردَّة عن الإسلام -نعوذ بالله.\nالذي يستهزئ بالمحافظين على الصَّلوات، أو بمَن وفَّر لحيته، أو شمَّر ثيابه ولم يُسبلها؛ هذا خطرٌ عظيمٌ -نعوذ بالله- الواجب تشجيعهم، والثناء عليهم، وأن تعمل عملهم، لا تثبيطهم والاستهزاء بهم -نسأل الله العافية والسلامة.","link":"https://binbaz.org.sa/fatwas/20585/ما-حكم-من-يستهزى-بالشباب-المتدينين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0538فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["نواقض الإسلام"]},{"id":1038,"question":"تكلمتَ عن وجوب الأخذ بالكتاب والسنة، ووجد جماعةٌ يُقال لهم: القرآنيون، فما موقفنا منهم؟","title":"ما حكم من ينكر السنة بزعم الاكتفاء بالقرآن؟","answer":"الجواب: مثلما تقدَّم، ليسوا قرآنيين، ولكنَّهم كذَّابون، أعداء للقرآن؛ لأنَّ القرآن أمر بالسنة، وأمر بطاعة الرسول ﷺ، ومَن أنكر السنة فقد أنكر القرآن، ومَن عصى الرسول فقد عصى القرآن، فليسوا قرآنيين، ولكنَّهم ضد القرآن، وملاحدة، وضالُّون، بل كفَّار بإجماع أهل العلم. مَن أنكر السنة ولم يعمل بها وزعم أنَّه لا يعمل إلا بالقرآن؛ فهو كاذبٌ، لم يعمل بالقرآن، وضالٌّ مُضِلٌّ، كافرٌ بإجماع أهل العلم، وقد كتبتُ في هذا رسالةً مطبوعةً سميتُها \"وجوب العمل بالسنة\".","link":"https://binbaz.org.sa/fatwas/21087/ما-حكم-من-ينكر-السنة-بزعم-الاكتفاء-بالقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0883وجد جماعة يقال لهم القرآنيون فما رأي سماحتكم؟ ابن باز فتاوى المحاضرات.mp3","categories":["الفرق والمذاهب","نواقض الإسلام"]},{"id":1082,"question":"يتهاون البعض بأمر الاستهزاء ببعض أحكام الدين أو المُتمسكين به، فما موقف المسلم تجاه ذلك؟","title":"ما حكم الاستهزاء بالدين والمتمسّكين به","answer":"الجواب:\nالموقف الإنكار، مَن استهزأ بالدين نُنكر عليه إنكارًا شديدًا، وقد ذكر العلماء -ذكر ابنُ عمر وجماعة- أنَّ أناسًا في عهد النبي ﷺ من المنافقين قالوا: ما رأينا مثل قُرَّائنا هؤلاء أرغب بطونًا، ولا أكذب ألسنًا، ولا أجبن عند اللِّقاء! فنُقل قولهم إلى النبي ﷺ، فجاءوا إليه يعتذرون، وسبقهم التنزيل، أنزل الله فيهم: وَلَئِنْ سَأَلْتَهُمْ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُ قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنْتُمْ تَسْتَهْزِئُونَ  ۝  لَا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65- 66].\nفالاستهزاء بالجنة، أو بالنار، أو بالإسلام عمومًا، أو بالتوحيد، أو بالصلاة، أو بالزكاة، أو بشيءٍ من الدين: ردَّة بإجماع المسلمين، وناقضٌ من نواقض الإسلام، ذكره أئمَّة العلم في باب حُكم المرتد، وذكره شيخ الإسلام رحمه الله محمد بن عبدالوهاب في نواقض الإسلام العشرة التي جمعها ولخَّصها من كلام أهل العلم، ذكر منها: الاستهزاء بشيءٍ من دين الله.\nوالمستهزئ بالعلماء، أو بطلبة العلم، أو بطالبات العلم، إذا كان مقصوده الاستهزاء بالدِّين؛ كفر.  أما إن كان يستهزئ بطالب العلم من أجل رثاثة ثيابه، أو من أجل عِلَّة فيه: من مرضٍ، أو شبه ذلك، أو عرجٍ، فهذا الاستهزاء منكر، وليس بكفرٍ، هذا منكر ومعصية. أما إذا استهزأ به لدينه ولتقواه فهذا استهزاء بالدين -نعوذ بالله- يكون من الردّة عن الإسلام؛ لأنه استهزأ بالدِّين، إذا كان يتنقّص بالدين، ويرى أن الدين ناقص، ويرى أن الذين ينتسبون إليه ناقصون، وأن المنتسبين إلى غيره أوْلى منهم وأزكى؛ فهذا هو التنقص في الدين، وهذا هو الذي فيه الاستهزاء بالله وبآياته ورسوله.\nوهكذا يقول مَن قال في الجنة: هذه جنة من حرمل، أو: جنة من زفت، أو: جنة من كذا، يستهزئ؛ هذا كفرٌ وردَّةٌ عن الإسلام -نعوذ بالله- هكذا النار: إذا استهزأ بها ردَّة عن الإسلام -نعوذ بالله- أو استهزأ بالملائكة، أو بالرسل، أو بالأنبياء، أو بغير هذا مما أخبر الله به ورسوله.","link":"https://binbaz.org.sa/fatwas/21134/ما-حكم-الاستهزاء-بالدين-والمتمسكين-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0930ما حكم الاستهزاء ببعض أحكام الدين أو المتمسكين بالدين؟ ابن باز فتاوى المحاضرات.mp3","categories":["نواقض الإسلام"]},{"id":1242,"question":"أحبَّك في الله يا سماحة الشيخ، وأسألك بالله أن تدعو لي ولأقربائي دائمًا بأن يُوفقنا الله لكل ما يُحبه ويرضاه، وقد ذكرتُم سماحتكم في كتابكم \"العقيدة الصحيحة وما يُضادها\" عدة نواقض للإسلام، فإذا حدث للشخص ناقضٌ من هذه النواقض، فهل يكفي أن يستغفر الله ويتوب ويرجع عن ذلك؟","title":"كيف تكون توبة مَن وقع في نواقض الإسلام؟","answer":"الجواب:\nأولًا: أحبَّك الله الذي أحببتنا له، ونسأل الله أن يجعلنا وإياكم من المتحابين بجلاله، يقول النبي ﷺ: يقول الله  يوم القيامة: أين المتحابون بجلالي؟ اليوم أظلهم في ظلي يوم لا ظلَّ إلا ظلي، فالتحابّ في الله من أعظم القربات، ويقول عليه الصلاة والسلام: سبعة يُظلهم الله في ظلِّه يوم لا ظلَّ إلا ظله: إمام عادل، وشابٌّ نشأ في عبادة الله، ورجل قلبه مُعلَّق بالمساجد، ورجلان تحابَّا في الله، اجتمعا على ذلك، وتفرَّقا عليه، ورجل دعته امرأةٌ ذات منصبٍ وجمالٍ فقال: إني أخاف الله أي: دعته للفاحشة فقال: إني أخاف الله، وهكذا الرجل الذي يدعو المرأة إلى الفاحشة وهي تقول: إني أخاف الله، من السبعة، هذه أصناف، والسادس: رجل تصدَّق بصدقةٍ فأخفاها، حتى لا تعلم شمالُه ما تُنفق يمينه، وهكذا المرأة أيضًا، والسابع: رجل ذكر الله خاليًا ففاضت عيناه، وهكذا المرأة أيضًا، المعنى عام للجميع.\nفالتَّحاب في الله من أفضل القربات، نسأل الله أن يُوفقنا وإياك وقراباتك وجميع المستمعين وجميع المسلمين لكل ما يُحبُّ ويرضى، وأن يهدينا جميعًا صراطه المستقيم، إنه جلَّ وعلا جوادٌ كريمٌ.\nما سؤاله؟\nس: يقول: ذكرتُم سماحتكم في كتابكم \"العقيدة الصحيحة\"؟\nالشيخ: نعم، إذا تاب ورجع إلى الله نعم، أي ناقضٍ، باب التوبة مفتوحٌ حتى لفرعون، لو تاب تاب الله عليه، باب التوبة مفتوحٌ لجميع العُصاة، ولجميع الكفار، قال تعالى: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، وقال النبيُّ ﷺ: التائب من الذنب كمَن لا ذنبَ له، وقال عليه الصلاة والسلام: التوبة تهدم ما كان قبلها.\nفنواقض الإسلام: كالشرك بالله، وعبادة الأوثان، ودعاء الأموات، والاستغاثة بالأموات، والنذر لهم، والذبح لهم؛ هذا من نواقض الإسلام، وسبّ الدين والاستهزاء به من نواقض الإسلام، سبّ الله، وسبّ الرسول، وسبّ الأنبياء؛ هذا من نواقض الإسلام، تكذيب الآخرة، تكذيب الجنة، تكذيب النار؛ هذا من نواقض الإسلام، كون الإنسان يعتقد أنَّ غير الشريعة أحسن منها، وأنَّ حُكم الطاغوت -حكم القوانين- أفضل من حكم الشريعة، أو يُساوي حكم الشريعة، أو يجوز أيضًا؛ هذا ردَّة عن الإسلام، حتى ولو قال: إن الشريعة أفضل، إذا استجاز حكم القوانين بدلًا من الشريعة، ولو قال: إنَّ الشريعة أفضل، فهو من نواقض الإسلام.\nوهكذا إذا ظاهر المشركين وساعدهم على المسلمين وعاونهم: كالذي يُعين الروس والشيوعيين على المجاهدين الأفغان، أو يُعين اليهود على الفلسطينيين؛ يكون ردَّة عن الإسلام، وهكذا، لكن مَن تاب تاب الله عليه، مَن تاب صادقًا وندم وأقلع وعزم ألا يعود تاب الله عليه من سائر الذنوب.","link":"https://binbaz.org.sa/fatwas/21293/كيف-تكون-توبة-من-وقع-في-نواقض-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1036إذا حدث للشخص ناقض من نواقض الإسلام فهل يكفي أن يستغفر الله ويتوب ويرجع عن ذلك؟ ابن باز.mp3","categories":["نواقض الإسلام"]},{"id":1511,"question":"مَن عرَّف الشرك الأكبر بأنه: تسوية غير الله بالله فيما هو من خصائص الله؟","title":"تعريف الشرك الأكبر ومعناه","answer":"الجواب:\nالمعنى مستقيم، تسويته بشيءٍ من خصائص الله: كالدعاء، والخوف، والرجاء، والتوكل، ونحو ذلك.  لكن قد يُشكل عليهم التسوية، فإذا قيل: صرف بعض العبادة لغير الله فهذا أجْمَع، صرف بعض العبادة لغير الله ولو ما سوَّاه بالله، ولو قال: إنَّ الله أفضل، ما دام أشرك بالله، كما قال بعضُ الكفار لما سأله النبيُّ ﷺ: كم تعبد؟ قال: سبعة، قال: مَن تعد لرغبتك ورهبتك؟ قال: الذي في السماء، يعني: الإله الحق ، ما ينفعه ذلك ما دام جعل شريكًا مع الله.","link":"https://binbaz.org.sa/fatwas/21610/تعريف-الشرك-الاكبر-ومعناه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعريف الشرك الأكبر ومعناه.mp3","categories":["نواقض الإسلام"]},{"id":1651,"question":"الذين يسبُّون أبا بكر وعمر وعائشة  هل يكفرون؟","title":"ما حكم من سب الصحابة؟","answer":"الجواب:\nالصواب أنَّ مَن سبَّ عائشة أو زعم أنها كفرت ورماها بالإفك كافر؛ لأنَّه مُكذِّب للقرآن. أما مجرد السّب فيستحق أن يُعزر ويُؤدَّب عليه. أما مَن قال إنها قد فعلت الفاحشة ورماها بالإفك فهذا مُكذِّبٌ لله، ويكون كافرًا، كما يفعل بعضُ الرافضة –نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21756/ما-حكم-من-سب-الصحابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من يسب الصحابة.mp3","categories":["نواقض الإسلام"]},{"id":1667,"question":"مَن سبَّ الدِّينَ أو مَن استهزأ به متى يمتنع تكفيره؟","title":"حكم تكفير مَن سَبَّ الدين أو استهزأ به","answer":"الجواب:\nيَكْفُر، ويُستتاب؛ فإن تاب وإلا قُتِلَ، وجماعة من أهل العلم يقولون: لا يُستتاب، هذه مسألة خلاف بين أهل العلم.\nس: هل يُعذر بجهله؟\nج: لا، ما يُعذر، هذا ما يجهله أحد، سبُّ الدِّين منكر يعلمه الصغيرُ والكبيرُ.","link":"https://binbaz.org.sa/fatwas/21773/حكم-تكفير-من-سب-الدين-او-استهزا-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يكون الامتناع عن تكفير من سب الدين أو استهزأ به.mp3","categories":["نواقض الإسلام"]},{"id":1948,"question":"شرك الألفاظ متى يكون كفرًا أكبر؟","title":"متى يكون شرك الألفاظ كفرًا أكبر؟","answer":"الجواب:\nإذا دعا غير الله.\nس: إذا قاله مُستحلًّا له؟\nج: ولو ما استحلَّه، إذا دعا غير الله يكون شركًا أكبر، ولو قال: ما استحللته.\nس: أقصد في الحلف خاصةً؟\nج: الحلف بغير الله كفر أصغر، إلا إذا اعتقد أنَّ المحلوف يعلم الغيب، وأنه يتصرَّف في الكون؛ فهذا كفرٌ أكبر من جهة العقيدة، أما من جهة أنه حلف بغير الله لأنَّه يرى أنه مُعظَّم كالمَلَكِ والنبي ونحو ذلك؛ فهذا شركٌ أصغر.\nس: عبارة لبعض الشّراح يقول: \"شرك الألفاظ قد يكون كفرًا أكبر ينقل عن المِلَّة إذا استحلَّ المرءُ ذلك، أو استهان، أو استهزأ\"؟\nج: هذا صحيح: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنْتُمْ تَسْتَهْزِئُونَ ۝ لَا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65، 66]، إذا استهزأ بالدين أو بالرسول أو بالله يكون كفرًا أكبر، أو حلف بغير الله يعتقد أن المحلوف به يتصرف في الكون، أو أنه ينفع ويضرّ، أو يعلم الغيب؛ صار كفرًا أكبر بسبب العقيدة، أما إذا جرى على لسانه من غير قصدٍ مثلما جرى على لسان الصحابة في أول الإسلام: وأبيك، لا وأبيك، لا وفلان؛ فهذا من باب الشرك الأصغر.","link":"https://binbaz.org.sa/fatwas/22062/متى-يكون-شرك-الالفاظ-كفرا-اكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يكون شرك الألفاظ كفرا أكبر.mp3","categories":["نواقض الإسلام"]},{"id":1949,"question":"بعضهم إذا قلت له: احلف بالله، يحلف، وإذا قلت له: احلف بالولي فيحلف؟","title":"حكم الحلف بالأولياء وتعظيمهم","answer":"الجواب:\nما يحلف بالوَلِي، هذا من تعظيمه للولي، نسأل الله العافية، إذا كان تعظيمه للولي أعظم من الله كان كفرًا أكبر.","link":"https://binbaz.org.sa/fatwas/22063/حكم-الحلف-بالاولياء-وتعظيمهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الحلف بالولي أو بالوالدين.mp3","categories":["الأيمان والنذور","نواقض الإسلام"]},{"id":1951,"question":"الشرك والكفر هل هما مُترادفان أو إذا اجتمعا افترقا؟","title":"هل الشرك والكفر مترادفان؟","answer":"الجواب:\nمُترادفان في الجملة، وقد يُطلق الكفر على الجحود، والشرك على صرف العبادة لغير الله، كل كافر مشرك، وكل مشرك كافر، لكن إذا كان من طريق الجحود يُسمَّى كفرًا غالبًأ، وإن كان من طريق دعوة غير الله والاستغاثة بغير الله أُطلق عليه الشرك.","link":"https://binbaz.org.sa/fatwas/22065/هل-الشرك-والكفر-مترادفان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الشرك والكفر مترادفان.mp3","categories":["نواقض الإسلام"]},{"id":1953,"question":"مَن يحلف بغير الله ويطوف بالقبور ويُمارس الأعمال الشركية ولكنه جاهل؟","title":"حكم مَن يعمل أمورًا شركية جاهلًا","answer":"الجواب:\nيُعلَّم، هو مشرك ويُعلَّم، مثل مشركي الجاهلية، يُؤمر حتى يتوب.\nس: وإذا مات على ذلك يكون مشركًا؟\nج: إذا كان يعبد القبور مات مشركًا، ولا يُصلَّى عليه، ولا يُغسَّل، ولا يُدْفَن مع المسلمين.\nس: ولو كان جاهلًا؟\nج: ولو كان جاهلًا، عُبَّاد البدوي وأشباههم هم الكفار.","link":"https://binbaz.org.sa/fatwas/22067/حكم-من-يعمل-امورا-شركية-جاهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم مَن يحلف بغير الله ويطوف بالقبور جاهلا.mp3","categories":["نواقض الإسلام"]},{"id":1971,"question":"نسبة السَّعد والنَّحس إلى الكواكب؟","title":"ما حكم نِسبة السعد والنحس إلى الكواكب؟","answer":"الجواب:\nما يجوز هذا، هذا غلط، هذا من أعمال الجاهلية.","link":"https://binbaz.org.sa/fatwas/22086/ما-حكم-نسبة-السعد-والنحس-الى-الكواكب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نسبة السعد والنحس إلى الكواكب.mp3","categories":["نواقض الإسلام"]},{"id":2382,"question":"حبوط العمل يدل على الكفر؟","title":"هل حبوط العمل يدل على الكفر؟","answer":"الجواب:\nيدل على الكفر، هذا من دلائل بالقول بالتكفير.\nس: حبوط العمل عن ترك الصلاة أو فوات الصلاة؟\nالشيخ: تركها بالكلية عمدًا، أما إذا فاتته فقد أصابته مصيبة عظيمة، إذا ما تعمد تركها إما بنوم أو بسهو وغفلة؛ فكأنما وُتِر أهله وماله، كأنه أصيب في ماله وأهله .","link":"https://binbaz.org.sa/fatwas/22507/هل-حبوط-العمل-يدل-على-الكفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل حبوط العمل يدل على الكفر.mp3","categories":["نواقض الإسلام"]},{"id":2736,"question":"ما الفرق بين الشرك والكفر؟","title":"ما الفرق بين الشرك والكفر؟","answer":"الجواب: قد يفرق بينهما في المعنى وإلا الحكم واحد، الكافر والمشرك كلهم خرجوا عن الإسلام، كلهم في النار، لكن من كان يدعو غير الله ويشرك في عبادة الله أُلصق باسم الشرك، وإذا كان كفره بالتكبُّر عن دين الله أو بجُحْد ما أوجب الله أو تحليل ما حرم الله أُلصق باسم الكفر، ويسمى كل واحد مشركًا، يجمعهم وجود ناقض من نواقض الإسلام، إذا وجد ناقض من نواقض الإسلام يسمى كافراً ويسمى مشركًا.","link":"https://binbaz.org.sa/fatwas/22884/ما-الفرق-بين-الشرك-والكفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين الشرك والكفر.mp3","categories":["نواقض الإسلام"]},{"id":3014,"question":"سَبُّ الصحابة هل هو كُفْر على الإطلاق، أو فيه تفصيل؟","title":"حكم مَن سب الصحابة","answer":"الجواب: الصواب أنه كُفْر، مَنْ سَبَّهم على العموم أو أبغضهم كَفَر، لا يبغضهم إلا كافر؛ فهم حَمَلَةُ الشريعة.\nس: هل هناك فرق بين كبار الصحابة وغيرهم؟\nالشيخ: المقصود عموم الصحابة أو جمهورهم، أما بعض الأفراد كمعاوية وغير معاوية، هذا فِسْق، إذا سَبَّ واحدًا منهم يستحق أن يُعَزّر ويُؤدّب.\nس: لكن لو سَبَّ أحدُ العشرة المبشّرين؟\nالشيخ: ولَوْ سَبَّ يكون فاسقَا يستحق أن يؤدّب.\nس: هذا مشهود له بالجنة؟\nالشيخ: السَبُّ قد يكون له أسباب، أما سَبُّ الجمهور أو سَبُّ العموم هذا لشك في دينه وبُغْض في الدين.","link":"https://binbaz.org.sa/fatwas/23172/حكم-من-سب-الصحابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم سب الصحابة رضي الله عنهم.mp3","categories":["نواقض الإسلام"]},{"id":3315,"question":"إطلاق \"كُفْر\" في شيء أنه كفر بالله: هل يكون كفرًا أكبر؟","title":"ما المراد بالكُفر إذا أُطلق في شيء؟","answer":"الجواب: يختلف، على حسب الأدلة، قد يكون كفراً أكبر، وقد يكون كفراً أصغر، على حسب الأدلة الشرعية.","link":"https://binbaz.org.sa/fatwas/23481/ما-المراد-بالكفر-اذا-اطلق-في-شيء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المراد بالكفر إذا أطلق في شيء.mp3","categories":["نواقض الإسلام"]},{"id":3779,"question":"الاستغاثة (بالأموات) شرك أم بدعة؟","title":"حكم الاستغاثة بالأموات","answer":"الجواب: من الشرك الأكبر، الاستغاثة بالأموات من الشرك الأكبر.","link":"https://binbaz.org.sa/fatwas/23976/حكم-الاستغاثة-بالاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاستغاثة بالأموات، من الشرك الأكبر.mp3","categories":["نواقض الإسلام"]},{"id":3947,"question":"بعض الناس لو طلب منه اليمين بالله يحلف، ولو طلب منه اليمين على الولي فلان أو السيد فلان يخاف؟","title":"حكم تعظيم الأولياء في الحَلِف وخشيتهم","answer":"الجواب: يختلف، لا شك أن قلوبهم مريضة بالشرك، نسأل الله العافية، ولهذا يعظّمون أولياءهم أكثر مما يعظّمون الله، هذا إنما يقع من الكفرة الفجار، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24170/حكم-تعظيم-الاولياء-في-الحلف-وخشيتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحلف بالله والخوف عن الحلف على الولي أو السيد.mp3","categories":["الأيمان والنذور","نواقض الإسلام"]},{"id":4028,"question":"إذا استحل؟","title":"حكم من استحلّ المعاصي؟","answer":"الجواب: هذا يكون كافرًا مخلدًا في النار بإجماع المسلمين، إذا استحل دماء المسلمين أو استحل الزنا، وقال: إنه حلال، أو استحل الخمر أو استحل عقوق الوالدين؛ كفر بإجماع المسلمين، نسأل الله العافية، وهو مخلّد في النار، نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/24264/حكم-من-استحل-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من استحل المعاصي.mp3","categories":["نواقض الإسلام"]},{"id":4238,"question":"العلمانيون هل كفرهم أكبر ؟","title":"ما معنى العلمانية وحكم المنتسبين إليها؟","answer":"الجواب: العلمانيون ما يؤمنون بالدين، يدعون الدنيا، ما يؤمنون بالله ولا باليوم الآخر، هذا العلماني يدعو إلى متابعة العالمين، وأن يكون على رأي العالمين في شركهم وضلالهم وخرافاتهم.\nس: هم يقولون بفصل الدين عن الدولة؟\nج: هذا معناه، ما عندهم دين، يدعون إلى العالمية.\nس: إذًا كفار؟\nج: نعم.\nس: يقولون الدين في المسجد أما برا المسجد لا؟\nج: ولو، بعضهم ما يرى الدين بالكلية، يرى الدعوة إلى ما عليه الناس وبس.","link":"https://binbaz.org.sa/fatwas/24505/ما-معنى-العلمانية-وحكم-المنتسبين-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على العلمانيين.mp3","categories":["الفرق والمذاهب","نواقض الإسلام"]},{"id":4239,"question":"ما الفرق بين الشرك الأصغر ووسائل الشرك؟","title":"ما الفرق بين الشرك الأصغر ووسائل الشرك؟","answer":"الجواب: وسائل الشرك كثيرة، مثل البناء على القبور، اتخاذ المساجد على القبور، وأسألك بجاه فلان وبحق فلان، هذه وسائل تجر إلى الغلو. أما الشرك الأصغر فهو أن يتكلم بالشيء الذي سماه النبي شركًا ولكنه ما وصل إلى حد الشرك الأكبر، كيسير الرياء، ولولا الله وفلان، هذا من الله ومن فلان، والحلف بغير الله، هذا من الشرك الأصغر.","link":"https://binbaz.org.sa/fatwas/24506/ما-الفرق-بين-الشرك-الاصغر-ووساىل-الشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين الشرك الأصغر ووسائل الشرك.mp3","categories":["نواقض الإسلام"]},{"id":4240,"question":"يأثم الإنسان بالوسائل؟","title":"هل يأثم الإنسان بفعل وسائل الشرك؟","answer":"الجواب: هو الشرك الأصغر، وسيلة للشرك الأكبر أيضًا.\nس: الوسائل كالتي ذكرتها هل يأثم بها فاعلها كالبناء على القبور ؟\nج: وسائل الشرك أعظم من جنس المعاصي؛ لأن وسائل الشرك توقع في الشرك وهي البدع، البدع أعظم من المعاصي، البناء على القبور واتخاذ المساجد عليها أعظم من جنس المعاصي؛ لأنها وسيلة للشرك.","link":"https://binbaz.org.sa/fatwas/24507/هل-ياثم-الانسان-بفعل-وساىل-الشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يأثم الإنسان بفعل وسائل الشرك.mp3","categories":["نواقض الإسلام"]},{"id":4241,"question":"الغلو في الصالحين ما يؤدي إلى الشرك؟","title":"حكم الغلو في الصالحين وما يكون شركًا منه؟","answer":"الجواب: الغلو قسمان: غلو فيهم يدعوهم مع الله، يعظّمهم بالشرك، يستغيث بهم، ينذر لهم، هذا الشرك الأكبر .\nوالغلو فيهم الذي هو ليس من الشرك الأكبر كونه يتمسح بهم، يرى أن التمسح بهم قربة إلى الله، ويقوم لهم إذا دخلوا أو يقوم على رؤوسهم يظن أن هذا قربة، هذا من وسائل الشرك.\nس: تقبيل حذاء الصالحين والمسح عليها؟\nج: هذا قد يقع في الشرك الأكبر، أما إذا رأى أن هذا قربة إلى الله وأن تقبيلهم والقيام لهم ونحو ذلك، هذا فيه تفصيل، تقبيلهم التقبيل العادي ومصافحتهم؛ هذا لا بأس به، أما كونه يتبرك بمسح أيديهم أو مسح مشالحهم أو ما أشبه ذلك، هذا من وسائل الشرك كما قد يقع لبعض الصوفية وغيرهم؛ لأن هذا ما يُفعل إلا مع النبي ﷺ هو الذي يُتبرَّك بعرقه وبيده وشعره، هذا خاص بالنبي ﷺ لا يقاس عليه غيره.","link":"https://binbaz.org.sa/fatwas/24508/حكم-الغلو-في-الصالحين-وما-يكون-شركا-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الغلو في الصالحين يؤدي إلى الشرك.mp3","categories":["نواقض الإسلام"]},{"id":4242,"question":"وسائل الشرك أعظم من أكبر الكبائر؟","title":"هل وسائل الشرك أعظم من أكبر الكبائر؟","answer":"الجواب: نعم، البدعة ووسائل الشرك أعظم من جنس الكبائر؛ لأنها بدعة. المراتب: الشرك الأكبر ثم الأصغر ثم البدعة ثم كبائر الذنوب ثم صغائر الذنوب.","link":"https://binbaz.org.sa/fatwas/24509/هل-وساىل-الشرك-اعظم-من-اكبر-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل وسائل الشرك أعظم من أكبر الكبائر.mp3","categories":["نواقض الإسلام"]},{"id":4249,"question":"قوله: ما زادتك إلا وهنًا بعض الناس يستدل بهذا على أنها صحيًّا تضر؟","title":"معنى \"ما زادتك إلا وهنًا..\" في الحديث","answer":"الجواب: يعني التعلق بغير الله يزيده ضعفًا ويزيده بلاء، وقد يُملى عليه كما قال الله جل وعلا: وَلَا تَحْسَبَنَّ اللَّهَ غَافِلًا عَمَّا يَعْمَلُ الظَّالِمُونَ إِنَّمَا يُؤَخِّرُهُمْ لِيَوْمٍ تَشْخَصُ فِيهِ الْأَبْصَارُ [إبراهيم:42] ويقول جل وعلا: سَنَسْتَدْرِجُهُمْ مِنْ حَيْثُ لَا يَعْلَمُونَ [القلم:44] وَأُمْلِي لَهُمْ إِنَّ كَيْدِي مَتِينٌ [القلم:45] قد يُملى له، وقد تضره عاجلا، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24519/معنى-ما-زادتك-الا-وهنا-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله في الحديث ما زادتك إلا وهنا..mp3","categories":["شروح الحديث","نواقض الإسلام"]},{"id":4265,"question":"عُبّاد القبور هل يسمون عُبّاد أوثان أم عُبّاد أصنام؟","title":"هل يُعَدُّ عُبّادُ القبور عبدةَ أصنام أم أوثان؟","answer":"الجواب: عباد أوثان، ويطلق عليها أصنام، قد تسمى الأصنام أوثانًا، قال إبراهيم: إِنَّمَا تَعْبُدُونَ مِنْ دُونِ اللَّهِ أَوْثَانًا [العنكبوت:17] وهم يعبدون أصنامًا، تسمى أصنامًا، وتسمى أوثانا، لكن نفس القبور تسمى أوثانًا، أما الأصنام تسمى أصنامًا، وتسمى أوثانًا جميعا.\nالقاعدة: الصنم ما نحت على صورة، يسمى صنم مثل صورة الأسد أو صورة نبي أو صورة صالح أو صورة ضبع، هذه تسمى صورة، وتسمى صنمًا، وتسمى وثنًا أيضًا.","link":"https://binbaz.org.sa/fatwas/24535/هل-يعد-عباد-القبور-عبدة-اصنام-ام-اوثان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ماذا يُسمى عبّاد القبور.mp3","categories":["نواقض الإسلام"]},{"id":4270,"question":"في المسائل: إذا ثبت كونه عبادة فصرفه إلى غيره شرك؟","title":"صرف العبادة أو النذر إلى غير الله شرك","answer":"الجواب: إذا نذر أنه يصلي للبدوي أو للنبي أو يذبح أو يسجد، هذا شرك.","link":"https://binbaz.org.sa/fatwas/24540/صرف-العبادة-او-النذر-الى-غير-الله-شرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صرف العبادة أو النذر إلى غير الله شرك.mp3","categories":["نواقض الإسلام"]},{"id":4276,"question":"في المسائل: أن كون الشيء يحصل به منفعة دنيوية من كف شر أو جلب نفع لا يدل على أنه ليس من الشرك.","title":"حكم طاعة الشياطين حذرًا من أذاهم","answer":"الجواب: نعم، لو أجاب الجن وأجابوهم ما يُدعى أنه جائز، حتى ولو أجاب الجن لو كفوه شرهم إذا قال لهم، هم يجرُّون إلى الشرك، يفرحون بهذا حتى يكفوا، ولهذا تجده يؤذي بعض أهل البيوت بالنار وغيرها حتى يستعيذوا به حتى كذا.  فشياطين الجن يريدون من الناس أن يكفروا فإذا فعلوا شيئًا ليجرُّوهم إلى الكفر لا يجوز أن يطاعوا، بل يجب أن يستعاذ بالله من شرهم وألا يقع في حبالهم، وهكذا فعلوا مع العزى ومع اللات ومع مناة ومع غيرها، يتشكلون للناس حتى يدعوهم إلى الشرك، ويتكلموا على ألسنة الأصنام والأوثان حتى يجرّوا الناس إلى الشرك، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24546/حكم-طاعة-الشياطين-حذرا-من-اذاهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما يحصل به منفعة دنيوية لا يدل على أنه ليس من الشرك.mp3","categories":["نواقض الإسلام"]},{"id":4278,"question":"الاستعاذة بغير الله شرك؟","title":"حكم الاستعاذة بغير الله","answer":"الجواب: نعم شرك أكبر.","link":"https://binbaz.org.sa/fatwas/24548/حكم-الاستعاذة-بغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الاستعاذة بغير الله.mp3","categories":["نواقض الإسلام"]},{"id":4284,"question":"حكم من يتصل بالشياطين ويخبر عن الأشياء الضائعة مثلًا والمسروقة؟","title":"حكم الاستعانة بمن يتصلون بالشياطين","answer":"الجواب: ما يجوز سؤالهم ولا إتيانهم، لا يُسألون عن مسروق ولا عن مكان الضالة، هذا باطل، لا يجوز سؤالهم.","link":"https://binbaz.org.sa/fatwas/24555/حكم-الاستعانة-بمن-يتصلون-بالشياطين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من يتصل بالشياطين.mp3","categories":["نواقض الإسلام"]},{"id":4307,"question":"يقولون في قاعدة \"للوسائل أحكام الغايات\" فإذا قلنا مثلًا أن عبادة القبر..؟","title":"ما الفرق بين الشرك ووسائل الشرك؟","answer":"الجواب: يعني في التحريم، ما هو في كل شيء، يعني في التحريم.  وسائل الشرك محرمة لكن لا تكون الوسائل شركًا، الشرك غير، والوسائل غير، فاتخاذ القبور مساجد والصلاة عندها من وسائل الشرك، والشرك عبادتها من دون الله. وهكذا الصلاة بعد العصر وبعد الفجر من وسائل الشرك، وليست شركًا، فالشرك أن تعبد الشمس من دون الله، أما كونك تصلي بعد العصر أو عند الغروب أو عند طلوع الشمس وأن تقصد الله؛ هذا لا يجوز، هذا من وسائل الشرك، والشرك أن تعبد الشمس مع الله جل وعلا. وهكذا الصلاة عند القبور وسيلة، والشرك أن تعبد أصحاب القبور، نسأل الله العافية.\nس: لا يقتضي إذا كانت الغاية كفرًا أن تكون الوسيلة كفرًا؟\nج: لا، الوسيلة لا، الوسيلة فيها تفصيل.","link":"https://binbaz.org.sa/fatwas/24581/ما-الفرق-بين-الشرك-ووساىل-الشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قاعدة للوسائل أحكام الغايات.mp3","categories":["نواقض الإسلام"]},{"id":4314,"question":"في المسائل أنه ﷺ لم يستعذ إلا مما يخاف وقوعه؟","title":"هل النبي ﷺ لم يستعذ إلا مما يخاف وقوعه؟","answer":"الجواب: نعم، وقد وقع، خاف وقوعه، وقد وقع واشتهر.","link":"https://binbaz.org.sa/fatwas/24588/هل-النبي-ﷺ-لم-يستعذ-الا-مما-يخاف-وقوعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النبي عليه الصلاة والسلام لم يستعذ إلا مما يخاف وقوعه.mp3","categories":["نواقض الإسلام"]},{"id":4403,"question":"كتاب القول المفيد للشيخ ابن عثيمين حفظه الله يقول: إن سابّ الرسول ﷺ تقبل توبته ويجب قتله، بخلاف من سب الله فإنه تقبل توبته ولا يقتل لأن حق الله دون حق الرسول ﷺ، بل لأن الله أخبرنا بعفوه عن حقه إذا تاب العبد بأنه يغفر الذنوب جميعًا، أما سب الرسول ﷺ فإنه يتعلق به أمران؟","title":"حكم سابّ الله تعالى وسابّ الرسول","answer":"الجواب: مسألة خلاف بين العلماء؛ أحد الأقوال: أنه تقبل توبة الساب إذا ندم وجاء تائبًا نادمًا تقبل، والقول الثاني: أنه يقتل سواء ساب الرسول أو ساب الله ، الخلاف مشهور، والمعروف عند العلماء: أن الساب لا تقبل توبته؛ يقتل، حق الله أعظم، لكن مقصود من قال سب الرسول؛ لأنه حق مخلوق، هذا مقصوده.\nس: يقام عليه الحد؟\nالشيخ: حده القتل، هذا حده، لكن لو جاءنا تائبًا نادمًا قبل أن نقدر عليه فالصواب أنه يقبل مثل بقية الكفار الذين أسلموا بعد السب.\nس: ما يعذر بجهله؟\nالشيخ: لا ما هو بهذا يجهل، هذا ما يجهله حتى الأطفال، ما يجهلون أن السب منكر، لو تقول للطفل الذي يسب أباه أو أخاه ... ما هو بطيب.","link":"https://binbaz.org.sa/fatwas/24680/حكم-ساب-الله-تعالى-وساب-الرسول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة سابّ الله وسابّ الرسول.mp3","categories":["نواقض الإسلام"]},{"id":4935,"question":"قال في المسائل: تفسير العبادة؟","title":"معنى العبادة لله سبحانه وصرفها لغيره","answer":"الجواب: لأنها من العبادة هي، يعني: دعاء الأموات والاستغاثة بالأموات ودعاء الميت، هذا عبادة؛ لأنه قال: \"اللهم لا تجعل قبري وثنًا يعبد\" يعني: يدعى من دون الله ويستغاث به من دون الله، فالعبادة دعاء الميت والاستغاثة بالميت عبادة له.\nكما أنها مع الله عبادة لله: اللهم اغفر لي عبادة لله، اللهم ارحمني عبادة لله، اللهم أدخلني الجنة عبادة لله، اللهم أنجني من النار عبادة لله، اللهم ثبتني على الحق عبادة لله، فإذا قالها المخلوق يا سيدي فلان انصرني أو أنا في جوارك فقد عبده.","link":"https://binbaz.org.sa/fatwas/27029/معنى-العبادة-لله-سبحانه-وصرفها-لغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى العبادة لله سبحانه وصرفها لغيره.mp3","categories":["نواقض الإسلام"]},{"id":5049,"question":"السجود إلى الصنم؟","title":"حكم السجود لغير الله تعالى","answer":"الجواب: السجود إلى الصنم كفر أكبر، للصنم أو لصحاب القبر، أو للسلطان، أو لزيد أو عمرو، السجود لغير الله كفر أكبر، الله يقول: فاسْجُدُوا لله واعْبُدُوا.\nس: قول يقول: لازم تعتقد يا شيخ؟\nج: لا، لا، هذا متى ما سجد لغير الله؛ كفر\nس: قاسوه على سجود معاذ للرسول ﷺ؟\nج: لا، لا هذا سجود معاذ، نبهه النبي ﷺ، أنه لا يسجد أحد لأحد، وقال: لو كنت آمرًا أحد أن يسجد لأحد، لأمرت المرأة أن تسجد لزوجها، أما سجود إخوة يوسف، هذا في شرع من قبلنا، سجود تحية، وسجود الملائكة لآدم سجود إكرام وتحية، هذا خاص، أما شريعتنا فليس فيها سجود لغير الله فاسْجُدُوا لله واعْبُدُوا.","link":"https://binbaz.org.sa/fatwas/29286/حكم-السجود-لغير-الله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم السجود لغير الله تعالى.mp3","categories":["نواقض الإسلام"]},{"id":5120,"question":"س: مَن لم يُكفِّر اليهود والنَّصارى؟","title":"ما حكم مَن لم يُكفِّر اليهود والنَّصارى؟","answer":"الجواب: هو مثلهم، مَن لم يكفر الكفَّار فهو مثلهم، لا بد من الإيمان بالله وتكفير مَن كفر به؛ ولهذا يقول النبيُّ ﷺ في الحديث الصَّحيح: مَن وحَّد الله وكفر بما يعبد من دون الله حرم ماله ودمه، وحسابه على الله، ويقول الله جلَّ وعلا: فَمَنْ يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِنْ بِاللَّهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَى لَا انْفِصَامَ لَهَا وَاللَّهُ سَمِيعٌ عَلِيمٌ [البقرة:256]، فلا بد من الإيمان بالله، وتوحيده، والإخلاص له، والإيمان بإيمان المؤمنين، ولا بد من تكفير الكافرين الذين بلغتهم الشريعةُ ولم يُؤمنوا: كاليهود، والنَّصارى، والمجوس، والشُّيوعيين، وغيرهم ممن يُوجد اليوم وقبل اليوم وبلغتهم رسالةُ الله ولم يُؤمنوا؛ فهم كفَّارٌ من أهل النار.","link":"https://binbaz.org.sa/fatwas/30033/ما-حكم-من-لم-يكفر-اليهود-والنصارى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 37.mp3","categories":["نواقض الإسلام"]},{"id":5123,"question":"سائل يقول: هل كل مَن يقع في الشرك الأكبر يكون مشركًا وتُطبق عليه أحكام المشركين؟","title":"هل كل مَن يقع في الشرك الأكبر يكون مشركًا؟","answer":"الجواب: نعم، مَن كفر بالله صار كافرًا، ومَن أشرك بالله صار مُشركًا، كما أنَّ مَن آمن بالله ورسوله صار مُوحِّدًا مُؤمِنًا. أما مَن لم تبلغه الدَّعوةُ فهذا لا يُقال له: مؤمن ولا كافر، ولا يُعامل معاملة المسلمين، بل أمره إلى الله يوم القيامة، وهم أهل الجهل الذين ما بلغتهم الدعوةُ، فهؤلاء يُمتحنون يوم القيامة؛ فيبعث الله إليهم عنقًا من النار ويُقال: ادخلوا، فمَن أجاب صارت عليه بردًا وسلامًا، ومَن لم يُجِب أُدخل النار -نسأل الله العافية. والمقصود أنَّ مَن بلغته الدعوةُ ولم يُؤمن ولم يُسلم؛ فهو كافرٌ عدوٌّ لله.","link":"https://binbaz.org.sa/fatwas/30036/هل-كل-من-يقع-في-الشرك-الاكبر-يكون-مشركا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 57.mp3","categories":["نواقض الإسلام"]},{"id":5126,"question":"هناك مَن يتلفَّظ بألفاظٍ فيها الاستعانة بالجنِّ، والدُّعاء والحلف بالنبي ﷺ، وعندما يُنَبَّه يقول: اعتاد عليها لساني، فما الحكم في ذلك؟","title":"ما حكم التلفظ بألفاظ فيها استعانة بالجن؟","answer":"الجواب: يجب أن يُعوِّد لسانه الكلام الطيب، ويحذر الكلام المنكر، وليس هذا بعذرٍ، فيجب أن يحفظ لسانَه عمَّا حرَّم الله، فالاستغاثة بالجن والدُّعاء من الشرك بالله جلَّ وعلا، قال تعالى: وَأَنَّهُ كَانَ رِجَالٌ مِنَ الْإِنْسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا [الجن:6]، وكان الكثير من العرب في جاهليتهم يعبد الجنَّ، وتستعيذ بهم، وتخافهم. فالواجب على المؤمن أن يحذر ذلك، وأن يثق بالله، ويعتمد على الله، ويستعيذ بكلمات الله التامَّات ليلًا ونهارًا من شرِّ ما خلق، ويقيه الله شرَّهم، يقول: \"أعوذ بكلمات الله التامَّات من شرِّ ما خلق\"، في ليله ونهاره، وفي أي منزلٍ، وفي أي مكانٍ: \"أعوذ بكلمات الله التامَّات من شرِّ ما خلق\"، يُكررها ثلاثًا أو أكثر، دائمًا، صباحًا ومساءً، وينجيه الله من شرِّهم. وهكذا إذا قال: \"بسم الله الذي لا يضرُّ مع اسمه شيءٌ في الأرض ولا في السَّماء، وهو السميع العليم\" ثلاث مرات، صباحًا ومساءً، هذا من أسباب العافية من كل شيءٍ. وهكذا قراءة قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين صباحًا ومساءً، ثلاث مرات: بعد الفجر، وبعد المغرب، من أسباب السلامة من كل شرٍّ. فالمقصود أن الواجب عليه أن يحفظ لسانَه عمَّا حرم الله من سائر الكلام الرديء: لا من دعاء الجن، ولا من الحلف بغير الله، ومن غير هذا من سائر كلامه المنكر، وليس له عذر بقوله: اعتاده لساني، بل يحذر ويحفظ لسانه عمَّا حرم الله، يقول النبيُّ ﷺ: مَن كان يُؤمن بالله واليوم الآخر فليقل خيرًا أو ليصمت، والله يقول في كتابه العظيم: مَا يَلْفِظُ مِنْ قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌ [ق:18]. وهو مسؤول عن كلامه، فعليه أن يحفظ لسانه عن كل ما حرم الله: من الغيبة، والنَّميمة، والسَّب، ودعاء الجن، والتوسل بالمخلوقات إلى الله، كأن يتوسل بالنبي، أو بجاه النبي، أو بحقِّ النبي؛ فكل هذا لا يجوز، فالتوسل يكون بدعاء الله وتوحيده، وبالإيمان به سبحانه، واتباع الشريعة، والتوسل بأعمالك الصَّالحة، كل هذا طيب. \"اللهم إني أسألك بإيماني بك، وبمحبَّتي لك، وباتِّباعي لنبيك محمد ﷺ، وببري والدي، وبصلتي الرحم، وبأدائي للأمانة\"، فتتوسل بأعمالك مثل أصحاب الغار الذين توسَّلوا إلى الله بأعمالهم الصَّالحة؛ فأنجاهم الله وفرَّج كربتهم، أخبر الرسولُ ﷺ عن ثلاثةٍ ممن قبلنا دعاهم المبيت والمطر إلى غارٍ، فدخلوا فيه من أجل المطر والليل، يبيتون فيه، فأنزل الله صخرةً تدحرجت من أعلى الجبل حتى سدَّت عليهم الغار، ولم يستطيعوا لها دفعًا، فقالوا فيما بينهم: لن يُخلصكم من هذه الصَّخرة إلا أن تدعوا الله بصالح أعمالكم، فتوسَّلوا إلى الله بصالح أعمالهم، فأنجاهم الله منها. قال أحدهم: اللهم إنه كان لي أبوان شيخان كبيران، وكنتُ لا أغبق قبلهما أهلًا ولا مالًا. الغبوق: الحليب في أول الليل، فكان من عادة البادية أن يصبُّوا الغبوقَ في الليل إذا حلبوا الإبل. فكان يأتي بالحليب ليسقي والديه قبل أهله، فنأى به طلبُ الشجر ذات ليلةٍ فتأخَّر، فجاء فوجدهما نائمين، فكره أن يُوقظهما، وبقي واقفًا بالقدح ينتظر استيقاظهما، والصِّبية عند قدميه يتباكون يُريدون الحليب، ومن شدَّة حبِّه لوالديه وبره لهما بقي واقفًا حتى طلع الفجر، فاستيقظا، فسقاهما، ثم قال: اللهم إن كنتَ تعلم أني فعلتُ ذلك ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصخرةُ بعض الشيء، لكنَّهم لا يستطيعون الخروج. ثم قال الثاني: اللهم إنه كانت لي ابنةُ عمٍّ من أحبِّ الناس إليَّ، فراودتُها عن نفسها -أي: الزنا- فأبت عليَّ، فألمّت بها سنةٌ شديدةٌ -أي: حاجة- فجاءت إليه تطلب الرفد وسدّ الحاجة، فقال: لا، حتى تُمكّنيني من نفسك، أي: حتى تسمح له بالزنا بها، وعند الضَّرورة سمحت، فلما جلس بين رجليها قالت: يا عبدالله، اتَّقِ الله ولا تفضَّ الخاتمَ إلَّا بحقِّه، وقد أعطاها مئة وعشرين دينارًا، فلما قالت له: اتَّقِ الله ولا تفضَّ الخاتمَ إلَّا بحقِّه؛ خاف من الله، وقام وتركها، وترك الذهبَ لها، ثم قال في هذه الحادثة: اللهم إن كنتَ تعلم أني فعلتُ هذا ابتغاء وجهك -أي: تركت الزنا وتركت الذهب خوفًا منك- فافرج عنا ما نحن فيه، فانفرجت الصخرةُ قليلًا أيضًا، لكنَّهم لا يستطيعون الخروج. ثم قام الثالث فقال: اللهم إنه كان لي أُجراء -عمَّال عنده- فأعطيتُهم حقوقَهم إلَّا واحدًا بقي له حقٌّ عندي، فنمَّيتُه وثمَّرته في إبلٍ وبقرٍ وغنمٍ وعبيدٍ، وبقيتُ أنتظر مجيئه ليأخذ حقَّه، فصار يتصرف ويتَّجر فيه، واشترى من الإبل، وهو إنما بقيت له آصُعٌ من شعيرٍ، أو من ذرة، أو من الأرز، فنَمَّى هذا المال، واتَّجر فيه، واشترى من الإبل والبقر والغنم والرقيق، فجاء بعد مدةٍ وقال: يا عبدالله، أعطني حقِّي الذي تركتُه عندك، قال: يا فلان، كل ما ترى من حقِّك، كل الإبل والبقر والغنم والعبيد من حقِّك، ثمَّرته لك، فقال: يا عبدالله، لا تستهزئ بي، قال: إني لا أستهزئ بك، هو من حقِّك فخذه، فاستاقه كلَّه، استاق الإبل والبقر والغنم والعبيد، ثم قال الرجل: اللهم إن كنتَ تعلم أني فعلتُ هذا ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصَّخرةُ وخرجوا؛ بأسباب أعمالهم الصَّالحة التي توسَّلوا بها إلى الله  فنفعتهم عند الشدة، وأنجاهم الله بها عند الشدَّة. فتوسل إلى الله بإيمانك، وتقواك، وبرّ والديك، وأدائك الحقوق، وسيلة صالحة، وهكذا التوسل بتوحيد الله، والإخلاص له، والإيمان به؛ فكله وسيلة صالحة. توسل إلى الله بأنَّك تشهد أن لا إله إلا الله، وأنَّ محمدًا رسول الله، وأنَّك تُؤمن بالله ورسوله، وأنَّك تؤمن باليوم الآخر، كله وسيلة شرعيَّة، مثل: \"اللهم إني أسألك بأسمائك وصفاتك\". أما التوسل بالمخلوقات، أو بجاه النبي، أو بحقِّ النبي، أو بجاه فلان، أو برأس فلان، أو بشرف فلان، فلا، فهذه وسيلة باطلة ما تُذْكَر، وليست وسيلةً شرعيةً.","link":"https://binbaz.org.sa/fatwas/30040/ما-حكم-التلفظ-بالفاظ-فيها-استعانة-بالجن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 61.mp3","categories":["نواقض الإسلام"]},{"id":5174,"question":"ما حكم الاستهزاء باللحية وتقصير الثياب إلى ما فوق الكعبين؟","title":"ما حكم الاستهزاء باللحية وتقصير الثياب؟","answer":"الجواب: هذا محرَّم، الاستهزاء باللحية والاستهزاء بتقصير الثياب وعدم الإسبال هذا منكرٌ عظيمٌ، قد يكون صاحبه مُرتدًّا -نعوذ بالله- قد يكفر بذلك، فإن كان قصده الاستهزاء بالدِّين فهذا يكون ردةً عن الإسلام، يقول الله جلَّ وعلا: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنْتُمْ تَسْتَهْزِئُونَ  ۝  لَا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65- 66]، فالاستهزاء باللحية أو بالصلاة أو بالصيام أو بتقصير الثياب وعدم إسبالها هذا خطرٌ عظيمٌ، فإذا كان قصده احتقار الدين والتَّنقص بالدِّين فإنه يكون ردَّةً عن الإسلام -نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/30104/ما-حكم-الاستهزاء-باللحية-وتقصير-الثياب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 131.mp3","categories":["نواقض الإسلام"]},{"id":5224,"question":"ما حكم أناسٍ يستهزئون بالدِّين وبأهل الدِّين، ويستهزئون بالمُتبعين للسنة من ترك اللّحى وعدم إطالة الملابس؟","title":"ما حكم المستهزئين بالدِّين وأهله؟","answer":"الجواب: الاستهزاء بالدين كفرٌ أكبر، الاستهزاء بالله أو برسوله أو بكتابه أو بالمؤمنين لأنَّهم اتبعوا الدِّين كفرٌ أكبر، قال الله جلَّ وعلا: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنْتُمْ تَسْتَهْزِئُونَ  ۝  لَا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:66]. أما الاستهزاء بواحدٍ معينٍ فهذا يختلف: إن كان الاستهزاء به لأنه متساهلٌ في لباسه، في مشيته، في أشياء مُستغربة؛ فهذا معصية، وإن كان الاستهزاء به في دِينه؛ لأنَّه مُتدين؛ لأنه مؤمن، يستهزئ بالدِّين لأجل الدِّين، أو باللِّحية لأجل أن الله شرعها؛ فهذا كفرٌ أكبر -نعوذ بالله، ونسأل الله العافية. فالاستهزاء بدين الله أو بشيءٍ منه، حتى اللِّحية، الاستهزاء بأهلها من أجل إرخائها، ويرون أن إرخاءها نقصٌ وعيبٌ؛ فهذا كفرٌ أكبر -نعوذ بالله- لأنه استهزأ بدين الله، والله الذي شرع إرخاءها، سواء قلنا أنها مُستحبَّة أو واجبة. فالذي عليه أهلُ العلم أنَّ إرخاءها وتوفيرها واجبٌ، وأنَّ قصَّها وحلقها منكرٌ وحرامٌ، فالاستهزاء بهذا الأمر جريمةٌ عظيمةٌ -نعوذ بالله من ذلك. وهكذا الاستهزاء بالجنة، أو بالنار، أو الاستهزاء بنعيم أهل الجنة، أو ما يُذكر عن نعيمهم، أو عن عذاب أهل النار، فالاستهزاء بهذه الأمور من الكفر الأكبر، ومن نواقض الإسلام عند أهل السنة، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/30168/ما-حكم-المستهزىين-بالدين-واهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 239.mp3","categories":["نواقض الإسلام"]},{"id":5371,"question":"لا يلزم من الطواف أن يكون الطائفُ مُشركًا؟","title":"ما حكم مَن يطوف بالقبور؟","answer":"الجواب: إذا كان يقصد التَّقرب إلى الله يكون بدعةً. لكن غالب هؤلاء الذين يطوفون يتقرّبون إلى القبور، هذا الغالب عليهم. لكن لو طاف يقول: إني أتقرب إلى الله، يكون هذا بدعةً ووسيلةً إلى الشرك بصاحب القبر.[1]","link":"https://binbaz.org.sa/fatwas/31103/ما-حكم-من-يطوف-بالقبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/dorar_saniya_najdiya001.mp3","categories":["نواقض الإسلام","البدع والمحدثات"]},{"id":5372,"question":"الطواف بغير الكعبة قد يكون شركًا وقد يكون بدعةً؟","title":"هل الطواف بغير الكعبة شرك أو بدعة؟","answer":"الجواب: قد يكون شركًا، وقد يكون بدعةً، نعم، على حسب حال صاحبه؛ إن كان يظن أنَّ الطواف عبادة بهذا الشيء لله سبحانه يكون بدعةً ووسيلةً إلى الشرك، أما إذا كان يطوف يتقرب إليه فهو مثل الصلاة له والسجود له. س: عندنا يطوفون ثم يُصلون تجاه القبر، هذا شرك أم بدعة؟ ج: ماذا؟ س: يطوفون ثم يُصلون ركعتين تجاه القبر؟ ج: يُعلَّمون أنَّ هذا شرك أكبر، الصلاة إلى القبور إذا قصد التَّقرب لصاحب القبر صار شركًا أكبر، وأما إن قصد أنَّ الصلاة عند القبر مُستحبة فهذه بدعة، والطواف بدعة. س: الصلاة تجاهه ولو ضدّ القبلة؟ ج: هذا إذا صلَّى إلى القبر يرى أنه قبلة يُبَيَّن له أنَّ هذا باطل، أما إن كان يتقرب إليها فشرك أكبر. س: يقول: إن الصلاة هنا فيها تقرب إلى الله، يتعبد الله؟ ج: يُعلَّم أنَّ الصلاة عند القبور بدعة، وإذا أراد بها صاحب القبر صار شركًا أكبر، أو الطواف إذا أراد به التَّقرب إلى صاحب القبر صار شركًا أكبر، نسأل الله العافية، أما إذا صلَّى عندها يظنها قربةً، وأن الصلاة عند القبور أو القراءة عندها طيبة فهذه بدعة.[1]","link":"https://binbaz.org.sa/fatwas/31106/هل-الطواف-بغير-الكعبة-شرك-او-بدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/dorar_saniya_najdiya002.mp3","categories":["نواقض الإسلام","البدع والمحدثات"]},{"id":5373,"question":"الصلاة تجاهه (القبر) ولو ضدّ القِّبلة؟","title":"ما حكم الصلاة عند القبر لغيرالقِبلة؟","answer":"الجواب: هذا إذا صلَّى إلى القبر يرى أنه قبلة: يُبَيَّن له أنَّ هذا باطل، أما إن كان يتقرب إليها فشرك أكبر. س: يقول: إن الصلاة هنا فيها تقرُّب إلى الله، يتعبّد الله؟ ج: يُعلَّم أنَّ الصلاة عند القبور بدعة، وإذا أراد بها صاحب القبر صار شركًا أكبر، أو الطواف إذا أراد به التَّقرب إلى صاحب القبر صار شركًا أكبر، نسأل الله العافية. أما إذا صلَّى عندها يظنها قربةً، وأن الصلاة عند القبور أو القراءة عندها طيبة؛ فهذه بدعة.[1]","link":"https://binbaz.org.sa/fatwas/31107/ما-حكم-الصلاة-عند-القبر-لغيرالقبلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/dorar_saniya_najdiya003.mp3","categories":["نواقض الإسلام","البدع والمحدثات"]},{"id":5379,"question":"إذا نفى أن يكون نزل مُنَجَّمًا؟","title":"ما حكم مَن نفى نزول القرآن مُنَجَّمًا؟","answer":"الجواب: لا، غلط، مَن أنكر هذا فهو كافر: كالجهمية وأشباههم.[1]","link":"https://binbaz.org.sa/fatwas/31116/ما-حكم-من-نفى-نزول-القران-منجما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/mnbr_002.mp3","categories":["نواقض الإسلام"]},{"id":5503,"question":"من طاف حول القبر، ليس بقصد أنها تنفع أو تضر، لكن بقصد التقرب إلى الله ، هل يحكم عليه بالكفر؟","title":"حكم الطواف حول القبر بقصد التقرُّب إلى الله","answer":"الجواب: مثل: لو صلَّى لهم؛ كفر أكبر، مثل: لو صلَّى لهم يدعوهم، صلَّى لهم أو دعاهم أو استغاث بهم وهو يعتقد أنهم شُفعاء يدعوهم، لا أنهم يخلقون أو يُدبرون، يدعوهم ليشفعوا، وهذا الشرك الأكبر. أما لو أطاعه، يحسب أنه مشروع، وإلا هو قصد الله، ما قصدهم هم، يقصد الله بطوافهم، يحسب أنه مثل الكعبة يجوز: هذا بدعة، ووسيلة إلى الشرك، وهذا نادر، فالطواف الذي يحصل منهم في الغالب يقصدون التَّقرب إليهم.[1]","link":"https://binbaz.org.sa/fatwas/31413/حكم-الطواف-حول-القبر-بقصد-التقرب-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 017.mp3","categories":["نواقض الإسلام"]},{"id":5514,"question":"حكم مَن حكم بغير ما أنزل الله؟","title":"ما حكم مَن حكم بغير ما أنزل الله؟","answer":"الجواب: لو حكم بغير ما أنزل الله لهوى يكون كفرًا دون كفرٍ، ما لم يستحل: إما لأجل أن يثبت في ملكٍ، أو يرضي فلانًا، أو من أجل فلان، لا يعلم أنه مُخطئ وظالم، يكون معصيةً دون الكفر ما دام لم يستحلها، فهو كفر دون كفرٍ، فإذا استحلَّها كفر كفرًا أكبر، وهكذا الزنا؛ لو زنا بمئة امرأةٍ ما يكفر حتى يستحلَّ، ولو قتل مئة قتيلٍ ولم يستحل لم يكفر، مثل قصة الذي قتل تسعةً وتسعين ثم كمل المئة. س: الذي يستحلّ الحكم بغير ما أنزل الله يُعتبر طاغوتًا؟ ج: كافر، طاغوت، كافر، يُسمَّى: طاغوتًا ولو ما استحلَّ، لو حكم بغير ما أنزل الله ولو ما استحلَّ، لكن الطاغوت تارةً يكون طاغوتًا أكبر. س: مَن استدلَّ على الحكم بغير ما أنزل الله أنه يختلف عن الزنا والأحكام الأخرى بالآيات والأحاديث؟ ج: ما علينا، مثلما صرح الصحابةُ -ابن عباس وغيره- كفر دون كفرٍ، لو أنَّ إنسانًا حكم لأخيه أو لأمه أو لأبيه أو لصديقه، ومال في الحكم، ويعلم أنه مائل، هل يكفر؟ لا يكفر. س: يا شيخ، على مستوى الدول؟ ج: الدول، لكن المعصية تعظم: إذا حكم لاثنين أكبر، أو إذا حكم لثلاثةٍ في اليوم أكبر، وإذا حكم لعشرةٍ يكون أكبر. س: يكون أكبر من الكبائر؟ ج: نعم. س: قول ابن عباس: كفرًا دون كفر، وظلمًا دون ظلم، ما المراد به؟ ج: يعني الحكم بغير ما أنزل الله من غير استحلال. س: وإنْ زنى وإنْ سرق؟ ج: كذلك وإنْ زنى وإنْ سرق أيكون كافرًا؟ لا، إنما يُنافي كمال الإيمان. س: لكن الفعل نفسه ما يدل على استحلالٍ: إقامة المحاكم والدَّعوى إليها؟ ج: لو زنى يُحكم عليه أنه مستحلّ؟ ما الذي يُخرج هذا؟ لو زنى أو تلوّط أو شرب الخمر هل يُقال له: كفرت؟[1]","link":"https://binbaz.org.sa/fatwas/31446/ما-حكم-من-حكم-بغير-ما-انزل-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 029.mp3","categories":["نواقض الإسلام"]},{"id":5520,"question":"هل مَن استهزأ بشيءٍ من شرائع الإسلام ثم تاب، هل يلزمه أن ينطق بالشَّهادتين؟","title":"هل يلزم نطقُ الشَّهادتين ممن استهزأ بالدين ثم تاب؟","answer":"الجواب: إذا تاب ورجع الحمد لله، التوبة تجبّ ما قبلها، إذا تاب يكفي، وبعض الفقهاء يُجيز أن ينطق الشَّهادة، والشهادة ما أنكرها، لكن إذا قال: \"الصلاة ليست واجبةً\" ثم تاب؛ تاب الله عليه، أو قال: \"الصوم ليس بواجبٍ\" ثم تاب؛ تاب الله عليه، ويكفي.[1]","link":"https://binbaz.org.sa/fatwas/31454/هل-يلزم-نطق-الشهادتين-ممن-استهزا-بالدين-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 036.mp3","categories":["نواقض الإسلام"]},{"id":5557,"question":"مَن فرَّق بين سبِّ الرسول ﷺ وبين سبِّ الرب ؟","title":"ما حكم من سبِّ الرب أو الرسول وهل له توبة؟","answer":"الجواب: لا أعلم فرقًا، كله رِدَّة شعناء.\nس: في قبول التَّوبة: مَن سبَّ الله تُقبل توبته، ومَن سبَّ الرسولَ لا تُقبل؟\nج: بعضهم يُفرِّق؛ لأنَّ سبَّ الرسول حقُّ آدمي، بخلاف سبِّ الله فهو حقُّ الله، والله جلَّ وعلا يعفو ويصفح، هذا وجه التَّفريق، والشيخ تقي الدين رحمه الله بسط الكلام في \"الصارم المسلول\".\nس: ألا يكون سبُّ الرسول أيضًا سبًّا لله؟\nج: لا، سبّ الرسول في الضمن تكذيب، والأقرب -والله أعلم- أنَّ مَن جاء تائبًا نادمًا؛ لأنَّ الشِّرك أعظم السَّبِّ، الشِّرك بالله وعبادة غيره من أعظم السَّب، نسأل الله العافية، فإذا جاء تائبًا فالحمد لله.[1]","link":"https://binbaz.org.sa/fatwas/31509/ما-حكم-من-سب-الرب-او-الرسول-وهل-له-توبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 020.mp3","categories":["نواقض الإسلام"]},{"id":5647,"question":"أيش معنى يا شيخ: الشِّرك صغيره وكبيره، وخفيّه ودقيقه؟","title":"ما معنى صغير الشِّرك وكبيره وخفيّه ودقيقه؟","answer":"الجواب: على ظاهره، الشرك أنواع: الشرك الأكبر معروف: عبادة الأوثان، والتَّعلق بالأصنام، ودعاء الأموات، والاستغاثة بالأموات، هذا كله شرك أكبر ظاهر. ومنه دقيقٌ: ما يكون في القلوب من الرِّياء، وطلب محمدة الناس وثنائهم، فقد يتعبد أو يُصلي أو يصوم أو يقرأ عند الناس، وسرّه في قلبه؛ ليُثنوا عليه ويحمدوه، وقد يقرأ لذلك، وقد يذهب إلى محلات ليُثنى على الذَّهاب إليها: كحلقات العلم، أو المساجد البعيدة؛ ليُصلي فيها، لا لقصد وجه الله، بل للرِّياء. فالشِّرك يكون فيه أشياء دقيقة تكون في القلوب، ما يعلمها إلا علَّام الغيوب ، من أنواع الرياء؛ ولهذا قال في الحديث الآخر -حديث أبي سعيد- ألا أُخبركم بما هو أخوف عليكم عندي من المسيح الدجال؟ قلنا: بلى يا رسول الله، قال: الشرك الخفي، يقوم الرجلُ فيُصلي فيُزين صلاتَه لما يرى من نظر الرجل إليه، وفي اللَّفظ الآخر: مَن سمَّع سمَّع اللهُ به، ومَن راءى راءى اللهُ به. فالحاصل: أنَّ الشرك فيه الخفي، وفيه الجلي، فيه الدَّقيق، وفيه الكبير: فالدَّقيق ما يكون في القلوب، ما يكون في بعض الألفاظ التي لا يفطن لها الناس. والشِّرك الظاهر ما يراه الناس ويسمعونه: كدعاء الأموات، والاستغاثة بالأموات، وسبّ الإسلام، والطَّعن في الإسلام، وسبّ الأنبياء، أشياء واضحة، نسأل الله العافية. وما يكون من الشِّرك الخفي: مثل ما قد يشتبه على الناس، مثل: ما شاء الله وشاء فلان، لولا الله والنبي، والأمانة، هذا يخفى على بعض الناس، ولا ينتبه أنه شرك؛ ولهذا يقع في كلام الناس كثيرًا الحلفُ بغير الله، وقول \"ما شاء الله وشاء فلان\"؛ لجهلهم وقلَّة علمهم.[1]","link":"https://binbaz.org.sa/fatwas/31682/ما-معنى-صغير-الشرك-وكبيره-وخفيه-ودقيقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alaistiqama 008.mp3","categories":["نواقض الإسلام","مسائل متفرقة في العقيدة"]},{"id":5982,"question":"لقد وردت إلينا أسئلة كثيرة تتعلق بالموضوع، وبغير الموضوع، ولكن أحد الإخوة الغيورين على دينهم جاءنا بنتيجة هذا العام، وهذه النتيجة تعلن عن طيب نوع من العطر اسمه عطر جنة الفردوس، وجاء بآيات قرآنية، وأحاديث نبوية، وشهادة أن لا إله إلا الله على كتب رجل جالس  حتى أن حرف الشهادة عند قدم الرجل، وفرجه عند محمد، وأصبعه عند أشهد أن لا إله إلا الله، وآيات أخرى على شكل مركب، وآيات أخرى على شكل دائرة، وهكذا إمعانًا في الدعاية، وأرى أمامي أن العلامة التجارية قريبة الشبه بالصليب عند النصارى، ويستحث سماحتكم أن تعالجوا هذا الموضوع بحكمتكم؟","title":"خطر الاستهزاء بالدين","answer":"الجواب: أما ما يتعلق بالصورة، صورة رجل ومعه الشهادتين، هذه وصلتنا، وكتبنا للمسؤولين فيما يجب من عقوبة الذي فعل هذا الشيء، وأما ما يتعلق بالعطر، ما سمعته إلى الآن، نسأل الله السلامة. لا شك أن الناس إذا وجدوا ضعفًا تسارعوا إلى كل شر، هذه حال الناس مثل ما قال الله جل وعلا: إِنَّ الْإِنْسَانَ لَظَلُومٌ كَفَّارٌ [إبراهيم:34] هذه صفة الإنسان إِنَّهُ كَانَ ظَلُومًا جَهُولًا [الأحزاب:72] فإذا رأى الإنسان ضعفًا من الرادع السلطاني تساهل في كل شيء يجلب عليه المال ويدر عليه شيء من المال أو بما في نفسه من الفساد والشر يدعو إلى الفساد أيضاً ولربما كان ما فيه مال. فالحاصل أن طبيعة الناس وحال الناس في الأكثر هو الرجوع إلى الباطل، والميل إلى الباطل والظلم والعدوان ونشر الفساد لكونه نشأ على ذلك، ونشأ في ذلك بين شياطين الإنس والجن فاعتاد الشر والفساد، فإن وجد ضعفًا وتساهلاً وقلة وازع فإنه سوف يفعل ما يستطيع من الشر والبلاء ليفسد به غيره وَدُّوا لَوْ تَكْفُرُونَ كَمَا كَفَرُوا [النساء:89] مثل ما قال الله عن الكافرين: وَدُّوا لَوْ تُدْهِنُ فَيُدْهِنُونَ [القلم:9] نسأل الله السلامة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1350/خطر-الاستهزاء-بالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_307.mp3","categories":["نواقض الإسلام"]},{"id":6127,"question":"فضيلة الشيخ، قلتم -أثابكم الله- إن الذي يجيز الحكم بغير ما أنزل الله؛ يكون مرتدًا، فكيف إذا لم يجز ذلك بلسان، ولكنه حكم بغير ما أنزل الله، وجعل هذه القوانين مكان الشريعة، وحمل الناس عليها، وعاقب من يخرج عليها، ومن دعا إلى تحكيم شرع الله؟","title":"حكم من حكم بغير ما أنزل الله بفعله","answer":"الجواب: هذا ظاهره الكفر الأكبر، ولكن الجزم بذلك محل نظر؛ لأنه قد يدعي أنه فعل ذلك؛ لأن الشعوب لا تقبل ذلك، أو لأن الدولة التي هو رئيسها لا تطاوعه في ذلك، وهو يعلم أن هذا باطل، وأن هذا منكر، ويعتقد أن الحكم بغير ما أنزل الله باطل، ويعلم أن حكم الله هو الحق، ولكن حمله على ذلك الهوى، وطاعة الشيطان، وإيثار الدنيا، ونحو ذلك، ولا يستحل ذلك فهو محل نظر، تكفيره محل نظر، وإن كان ظاهره الكفر. ظاهر أحوال دول اليوم -إلا القليل- ظاهر أحوالهم الكفر بالله  واستحلال الحكم بغير ما أنزل الله، لكن الجزم بذلك محل نظر إذا كان يدعي أنه لا يجيز ذلك، وأنه يرى أن الحكم بالشريعة لازم، وأن تحكيم القوانين باطل، ولكنه حمله على هذا كيت، وكيت، وكيت، فهذا هو محل نظر، والله  أعلم.","link":"https://binbaz.org.sa/fatwas/1525/حكم-من-حكم-بغير-ما-انزل-الله-بفعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_455.mp3","categories":["نواقض الإسلام"]},{"id":6128,"question":"هل الحاكم الذي يدعي الإسلام، ويحكم بغيره كافر؟ وإذا كان يكفر بذلك هل الذي لم يكفره كافر؟","title":"التفصيل فيمن حكم بغير ما أنزل الله","answer":"الجواب: تقدم السؤال هذا في الجمعة الماضية فيما يغلب على ظني، وتقدم الجواب عن هذا، وأنه يحتاج إلى تفصيل؛ لأن الحكام الذين يحكمون بغير الشريعة قد يكونون يزعمون أنهم مضطرون، وأن شعوبهم أو دولًا أخرى تضطرهم إلى هذا، وأنهم يؤمنون بأن عملهم باطل، وأنه منكر، وأنه معصية، ولكنهم اضطروا إليه، وفعلوه كما يفعل سابقًا شيوخ القبائل يحكمون قوانين أسلافهم، فهؤلاء الذين حكموا القوانين الوضعية إذا كانوا يرونها جائزة. تقدم نعم في الجمعة الماضية إذا كانوا يرون أن هذه القوانين جائزة، وأنها أفضل من الشريعة، أو أنها تساوي الشريعة؛ فهم كفار بهذا، في جميع الأحوال الثلاثة؛ لأن القوانين تارة يعتبرها أصحابها أنها أفضل من الشريعة، وتارة يعتقدونها مثل الشريعة إذا حكمها، أو حكم الشريعة كله واحد، وتارة يعتقدون أن الشريعة أفضل، وأولى، لكن هذه جائزة، ولا بأس بتحكيم القوانين الوضعية، والذي اعتقد هذا فهو كافر، مرتد عن الإسلام -نعوذ بالله- لأن من استباح ما حرم الله؛ فهو كافر، ومن تنقص شريعة الله؛ فهو كافر، ومن استهزأ بدين الله؛ فهو كافر: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنْتُمْ تَسْتَهْزِئُونَ [التوبة:65] لَا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:66] ذَلِكَ بِأَنَّهُمْ كَرِهُوا مَا أَنْزَلَ اللَّهُ فَأَحْبَطَ أَعْمَالَهُمْ [محمد:9].  المقصود: أن إباحة المحرم المعروف من الدين بالضرورة أنه محرم، كفر بالله، وردة عن الإسلام، كما أن تحريم ما عرف من الدين بالضرورة أنه حلال كفر بالله، وردة. لو قال قائل: إن الغنم حرام، أو البقر حرام، أو الإبل حرام، أو اللبن حرام؛ فهو مرتد عن دين الله، بعدما يبين له أنه خاطئ، وأنه ظالم لنفسه، أو قال: إن الزنا حلال، أو الخمر حلال؛ فهو مرتد عن الإسلام، فالذي يقول: إن الشرك حلال أعظم في الكفر، وأشر، وأخبث.  فالحاصل: أن الذي يرى أن تحكيم القوانين التي تخالف شريعة الله في أمور الناس أنها جائزة، أو أنها مثل الشريعة، أو أنها أفضل من الشريعة هذا كافر عند جميع أهل العلم، وإنما الذي لا يكفر الذي قد يقع منه الحكم بغير ما أنزل الله، يحكم بعض القوانين، لكن يعتقد أنه ظالم، وأنه مخطئ، خاطئ في ذلك، وأنه عاص لربه، ولكن حكمها لأغراض، وأسباب، وهو يعلم أنه ظالم، فهذا قال فيه ابن عباس: إن هذا ليس كالشرك بالله، وليس كالظلم الأكبر، وقال فيه مجاهد، وطاوس، وجماعة: أنه ظلم دون ظلم، وكفر دون كفر.  فالحاصل: أنه إذا لم يعتقد إباحة ذلك، وإنما فعله ليعلم أنه عاص، وأنه ظالم لنفسه، وأن الواجب عليه تحكيم الشريعة؛ فإنه لا يكون كافرًا كفرًا أكبر، بل كفر أصغر، وظلم أصغر، وفسق أصغر، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/1520/التفصيل-فيمن-حكم-بغير-ما-انزل-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_450.mp3","categories":["نواقض الإسلام"]},{"id":6296,"question":"ذكر أحد العلماء في برنامج يذاع في الراديو بأن من أنكر آية من القرآن الكريم؛ يكفر، ولكن من لم يصدق حديثًا، أو أنكره، لا يكفر، فما رأي سماحتكم مع الدليل؟","title":"حكم من أنكر آية قرآنية أو حديثاً نبوياً","answer":"الجواب:  أما الآيات فلا شك أن من أنكرها؛ فهو كافر، من أنكر القرآن، أو بعض القرآن؛ فهو كافر بإجماع المسلمين؛ لأنه مقطوع بأنه كلام الله.  أما الحديث ففيه تفصيل، الأحاديث الثابتة التي لا شبهة فيها، ولا مطعن من أنكرها؛ فهو كافر عند جميع أهل العلم، وأما الأحاديث التي فيها خلاف، وفيها نظر، فهذا هو محل نظر، لا يكفر صاحبه. والإطلاق بأن من أنكر الحديث لا يكفر، قول فاسد، لا يجوز على إطلاقه، بل فيه تفصيل، من أنكر الأحاديث الصحيحة المعروفة عن النبي ﷺ فهذا كافر، وهكذا من أنكر السنة، وقال: السنة لا يحتج بها، ويكفي القرآن، هذا كافر، نعوذ بالله. الله أعطى النبي القرآن، ومثله معه، لكن بعض الأحاديث التي فيها شبهة؛ لعدم استقامة أسانيدها، أو في بعض أسانيدها نظر، أو كذا هذا هو محل النظر.","link":"https://binbaz.org.sa/fatwas/1809/حكم-من-انكر-اية-قرانية-او-حديثا-نبويا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_650.mp3","categories":["نواقض الإسلام"]},{"id":6301,"question":"ما حكم لعن دين الشخص؟","title":"حكم لعن دين الشخص","answer":"الجواب: لعن الدين إن كان دين الإسلام؛ يكون ردة عن الإسلام، أما إذا قصد اليهودية، أو الوثنية، أو المجوسية؛ فهذا لا، لكن يلعن دين المسلم، دين المسلم هو الإسلام، هذا ردة، نعوذ بالله. يجب أن ينبه على هذا، ويحذر من هذا، ويؤدب؛ لأنه يستحق التأديب على هذا العمل السيئ.  السؤال: هل له كفارة؟  الجواب: التوبة إلى الله.","link":"https://binbaz.org.sa/fatwas/1814/حكم-لعن-دين-الشخص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_655.mp3","categories":["نواقض الإسلام"]},{"id":6346,"question":"يا شيخ، هنا يقول: ومن خلت به هذه الخصال كان منافقًا خالصًا؟","title":"النفاق العملي سُلَّمٌ للنفاق الاعتقادي","answer":"الجواب: هذا من حديث عبدالله بن عمر.. يقول ﷺ: أربع من كن فيه؛ كان منافقًا خالصًا، ومن كانت فيه خصلة منها؛ كانت فيه خصلة من النفاق حتى يدعها، إذا حدث كذب، وإذا ائتمن خان، وإذا خاصم فجر، وإذا عاهد غدر -نعوذ بالله- في اللفظ الآخر: آية المنافق ثلاث: إذا حدث كذب، وإذا وعد أخلف، وإذا ائتمن خان نسأل الله العافية. هذه صفاتهم، لكن لا يلزم أن يكون منافقًا اعتقاديًّا، لكنها في الأغلب إذا استحكمت، وكثرت فيه؛ تجره إلى النفاق الاعتقادي، نعوذ بالله.  ولو كانت الخيانة نفاقًا أكبر؛ فمن يسلم منها اليوم، ولا حول ولا قوة إلا بالله،  لو كان نفاقًا أكبر، أو إخلاف الوعد، أو الكذب في الحديث نفاقًا أكبر يوجب الكفر بالله؛ لكان الأمر خطيرًا جدًّا، ولا حول ولا قوة إلا بالله.  لكن النفاق -مثل ما تقدم- نفاقان: نفاق عملي ظاهر، ونفاق اعتقادي باطن، فإذا وجد الاعتقادي صار صاحبه كافرًا كفرًا أكبر ومخلدًا في النار -نعوذ بالله- إذا مات على ذلك. وأما أنواع الكفر العملي الذي يتخلّق به المنافقون: فهذا إذا كان صاحبه مؤمنًا في الباطن يؤمن بالله واليوم الآخر ويوحّد الله ولكن قد يغلبه الطمع فيكذب، أو يخون الأمانة؛ فهذا يكون فاسقًا، ويكون فيه خصلة من خصال أهل النفاق، وهو على خطر عظيم، نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/1943/النفاق-العملي-سلم-للنفاق-الاعتقادي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_730.mp3","categories":["نواقض الإسلام"]},{"id":6511,"question":"هل الذبح قبل دخول الإنسان إلى فلته، أو منزله الجديد على الباب، وتلطيخ الباب بالدم من التفاؤل، والخير، أم هو من التشاؤم؟ علمًا أنني أقصد بذلك دفع الشر، والشياطين عن هذا المنزل، واعترافًا بشكر الله، وشكر نعمته.","title":"حكم الذبيحة عند دخول البيت الجديد","answer":"الجواب: هذا من أمر الجاهلية، كان أهل الجاهلية يذبحون عند نزول المنزل، يذبحون ... على الباب، أو عند ... الجدران، وعند الآبار يقولون: هذا لدفع الجن، وشر الجن، ويذبحونها للجن، يتقربون إليهم حتى يدفعوا شرهم بزعمهم، هذا من الشرك الأكبر والعياذ بالله، هذا لا يجوز، هذا منكر لا يجوز أبدًا، بل هو منكر، ومن أعمال الجاهلية -نعوذ بالله- وقد روي عن النبي أنه نهى عن ذبائح الجن. والمقصود: أن هذا من الذبح لغير الله، والله يقول -جل وعلا-: فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:2] ويقول: قُلْ إِنَّ صَلَاتِي وَنُسُكِي يعني ذبحي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ  ۝  لَا شَرِيكَ لَهُ [الأنعام:162، 163] ويقول النبي ﷺ: لعن الله من ذبح لغير الله وهذا من يذبح عند الأبواب، وإن كان قصد بالذبح وجه الله، لكنه وسيلة إلى الشرك، وعادة جاهلية يحييها، فلا يجوز هذا، أما إذا جمع قراباته، وجيرانه بعدما ينزل، يجمعهم على الطعام، يشكر الله على ما أنعم به من سكنى البيت الذي استأجره، أو اشتراه، أو عمره، هذا لا بأس إذا جمعهم على ذبيحة، أو أقل، أو أكثر، جيرانه، وقراباته، شكرًا لله؛ فلا بأس. السؤال: يسمى عيدًا؟ الجواب: ما يسمى عيدًا، هذا مجرد شكر لله على أن الله يسر له المنزل، ليس أعيادًا إلا عيد النحر، وعيد الفطر، هذه أعياد المسلمين ما في أعياد. السؤال: .. النزالة؟ الجواب: هذه يسمونها النزالة هذه النزالة هذه مباحة، لا بأس بها.","link":"https://binbaz.org.sa/fatwas/2252/حكم-الذبيحة-عند-دخول-البيت-الجديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_873.mp3","categories":["نواقض الإسلام"]},{"id":6793,"question":"يوجد في قبائل من البوادي خاصة بعدما يحكم القاضي بين الطرفين يتخذون أناسًا يحكموهم بينهم حكم آخر غير حكم الشرع، ويقولون: هذه عادة قديمة عندنا، فما حكم هؤلاء؟","title":"حكم التحاكم إلى غير شرع الله","answer":"الجواب: ليس لهم ذلك، لا يجوز لهم أن يحكموا غير شرع الله، ومن رضي بذلك؛ كفر -نسأل الله العافية- من رضي بتحكيم غير شرع الله، ورأى أنها أحسن من شرع الله، أو أنه مباح، أو أنه طيب، أو ما أشبه ذلك مثل ما تقدم في الأصناف الثلاثة؛ يكون كافرًا، سواء كان رضيه، وأنه أحسن من شرع الله، أو مثل شرع الله، أو أنه جائز، ولكن شرع الله أحسن، كله كافر.  فالواجب على المسلمين جميعًا أن يخضعوا لحكم الله، ما هو لحكم القاضي، القاضي قد يخطئ ويصيب، أن يحكموا بحكم الله في نفس الأمر، أما إذا القاضي حكم عليهم بشيء، وتراضوا على أن يسمحوا عن بعض الشيء، حكم القاضي على زيد أنه يعطي عمرًا ألف ريال، وتراضوا أنه يسمح المحكوم له بخمسمائة، هذه ما فيها بأس، صلح بينهم.","link":"https://binbaz.org.sa/fatwas/2670/حكم-التحاكم-الى-غير-شرع-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1167.mp3","categories":["نواقض الإسلام"]},{"id":6816,"question":"إذا الداعية دعا إلى الإسلام، وإلى الصلاة، وقام سب الدين، وسب الرسول، وسب الله؟ من الذي سب الدين؟ المدعو؟ المدعو.","title":"كيفية التعامل مع من سب الله أو دينه أو رسوله","answer":"الجواب: أولًا: ينصحه، يبين له أن هذا كفر، وضلال، والحاضرون ينصحونه، ويتكلمون عليه، ويبينون خطأه، فإن تاب، وإلا يرفع بأمره إلى من ينفذ فيه الأمر، إذا كان في بلد فيها من يحكم بشرع الله.  فإذا كان ما فيها حكم بشرع الله يرفع إلى من جعل له الأمر في مثل حتى يؤدبه، حتى يسجنه، يعني لا يعجلوا في الأمور، بل ينصحونه أولًا، يتكلمون عليه كلامًا شديدًا؛ إذا أصر على باطله، ويتوعدونه بالرفع عنه إلى ولاة الأمور؛ لعله يرجع إلى الصواب، لعله يرجع إلى الحق، لأن سب الدين ردة عن الإسلام، نعوذ بالله.  سب الرسول ردة عن الإسلام، سب الرسول تنقص ردة عن الإسلام، وسب الدين كذلك ردة عن الإسلام، لو قال: الرسول ﷺ ما يفهم هذه الأمور، ما يعرف هذه الأمور، أو قال: الرسول بدوي ما يعرف هذه الأمور، أو كذا؛ هذا ردة عن الإسلام، كفر أكبر -نعوذ بالله-. أو قال: الشريعة ما تصلح لهذا الدين، ما تصلح لهذا العصر، شريعة الإسلام ما تصلح لهذا العصر، تصلح لعصر مضى، هذا ردة عن الإسلام -نعوذ بالله-.","link":"https://binbaz.org.sa/fatwas/2692/كيفية-التعامل-مع-من-سب-الله-او-دينه-او-رسوله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1190.mp3","categories":["الدعوة والدعاة","نواقض الإسلام"]},{"id":6934,"question":"هناك جماعة من عبدة القبور يحفظون القرآن، ويجيدون تلاوته، وإذا قرأوه، أو سمعوه؛ بكوا، ولربما أغمي عليهم من شدة الوجد -كما يقولون- فهل هؤلاء مع السفرة الكرام البررة؟","title":"حكم من يحفظ القرآن ويعبد القبور","answer":"الجواب: حتى النصارى يبكون، ليس البكاء دليلًا، فإذا كان يحفظ القرآن، ويبكي، ولكنه يعبد الأموات، ويستغيث بالأموات؛ فهو مشرك، مثل النصارى -والعياذ بالله- بل الشيطان يحفظ آية الكرسي، علمها أبا هريرة، لما أمسكه أبو هريرة؛ قال: دعني أعلمك آية من كتاب الله، ولا يزال عليك من الله حافظ إذا قلتها عند النوم، وهي آية الكرسي، قال: اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255]. المقصود يا أخي: العمل، المقصود العمل، فلو حفظ القرآن، وصام النهار، وقام الليل وهو يعبد غير الله، أو يسب القرآن، أو يسب دين الله؛ فهو مع الكفار، نسأل الله العافية، ولو صام النهار، وقام الليل، وحفظ القرآن.","link":"https://binbaz.org.sa/fatwas/2864/حكم-من-يحفظ-القران-ويعبد-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1312.mp3","categories":["نواقض الإسلام"]},{"id":7096,"question":"ذكرتم في الأسبوع الماضي أن من حكم بغير ما أنزل الله وهو يعتقد أن حكم الله أفضل الأحكام، وأنه لا يجوز الحكم بغيره، أن ذلك لا يعتبر فعله مخرجًا عن الملة، ولكن هل تقبل هذه الدعوى من جميع أحكامه، أو كثيرها من قوانين بشرية، وهو ينصب محاكم كاملة تقوم على الحكم بالقوانين البشرية التي تحل ما حرم الله وحولها هذا؟","title":"حكم بغير ما أنزل الله ويعتقد أن حكم الله الأفضل","answer":"الجواب:\n\nهذا شيء بينه وبين الله، هذا هو الحكم فيما بينه وبين الله، فمن حكم بغير ما أنزل الله وهو يعلم أن حكم الله هو واجب الاتباع، وهو الحق، ولكن حكم لهدف من الأهداف كرشوة، أو غيرها؛ فقد أتى منكرًا عظيمًا، وركب كفرًا، لكنه كفر دون كفر، وظلم دون ظلم، وفسق دون فسق.\n\nومن استحل الحكم بغير ما أنزل الله، ولو زعم أن حكم الله أفضل؛ فهو مرتد عن الإسلام نعوذ بالله وكفره كفر أكبر، ونسأل الله العافية والسلامة.","link":"https://binbaz.org.sa/fatwas/3117/حكم-بغير-ما-انزل-الله-ويعتقد-ان-حكم-الله-الافضل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1484.mp3","categories":["نواقض الإسلام"]},{"id":7327,"question":"لي عم شقيق والدي، وهو لا يصلي، ولا يعرف الله، ويزعم أنه لا يعرف الرسول ﷺ على حد تعبيره، وعندما أنصحه يسخر ويهزأ بي، ويقول لي: إنك مجنون، وقد طردت من المنزل بسببه، وعندما قلت لأبي: إما أنا وإما هو في المنزل، قال لي: اخرج أنت، علمًا أنه يملك بيتًا خاصًا به، وأنا لا أريده أن يأخذ إخوتي معه بالسيارة، لاسيما وأنه لا يعرف الدين، سماحة الشيخ ما هو الحل معه، وكذلك مع أهلي، هل موقفي معهم سليم، علمًا أني الآن مطرود من البيت؟","title":"كيف التعامل مع من يستهزئ بالدين أو بالرسول","answer":"الجواب: هذا منكر عظيم، ومثل هذا ردة عن الإسلام، وكفر أكبر، لكن إذا كنت صادقًا فارفع بأمره إلى المحكمة، أو إلى الهيئة، أو إليهما جميعًا، ارفع إلى المحكمة والهيئة وأثبت الشهود عليه حتى يحكم فيه بحكم الله من القتل، أو الاستتابة، ولا تسكت، لكن لا تكن وحدك، انظر الذين يعرفونه من أقاربك الثقات العدول؛ لأنهم قد يقولون عنك: إنك كاذب، ولكن طردناك؛ لأنك قلت هذا الكلام لا، لا بد تلتمس ناسًا ثقاتًا، اثنين ثلاثة أربعة يشهدون معك عند المحكمة، وعند رئيس الهيئة؛ حتى ينفذ فيه أمر الله -إن شاء الله-. بارك الله فيك لا تسكت، لا أنت ولا غيرك ممن يشاهد هؤلاء، من عرف هؤلاء الذين يسبون الدين، ويسبون الرسول ﷺ ويفعلون ما يخالف الإسلام، الواجب الرفع بأمرهم إلى المحاكم، وإلى الهيئات في البلد التي أنت فيها، ولكن لا تكن واحدًا، الواحد ما ينفع، لا بد تلتمس ناسًا معك ثقاتًا تراقبون الرجل، وتعرفون أعماله الخبيثة، وأقواله السيئة؛ حتى يرفع بأمره عن بصيرة، عن شهادة جماعة؛ حتى لا يقال: هذا له غلط، وهذا له كذا، وهذا له كذا.","link":"https://binbaz.org.sa/fatwas/3399/كيف-التعامل-مع-من-يستهزى-بالدين-او-بالرسول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1713.mp3","categories":["نواقض الإسلام"]},{"id":7439,"question":"حكم من يذبح الذبائح عند قبر الميت بعد دفنه صدقة على روحه؟","title":"حكم الذبح عند قبر الميت بعد دفنه صدقة عليه","answer":"الجواب: هذا منكر ما يجوز، كانوا في الجاهلية يسمونه \"عقر\" يقيمون عنده إذا مروا وهو جواد عقروا عند قبره، النبي ﷺ قال: لا عقر في الإسلام وهكذا لو ذبحوا عند قبره لقصد الصدقة، هذا لا يجوز، هذا بدعة، منكر.","link":"https://binbaz.org.sa/fatwas/3519/حكم-الذبح-عند-قبر-الميت-بعد-دفنه-صدقة-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1823.mp3","categories":["نواقض الإسلام"]},{"id":7564,"question":"سماحة الشيخ! هذه الرسالة وردتنا من المرسل (ج.م.ع) من السلوم، يقول في رسالته: أما بعد: فإنني أود أن أعرض عليكم هذه القضية التي تهم قطاعاً كبير من المسلمين الباحثين عن الحقيقة، والقضية هي: أن كثيراً من الناس يشدون الرحال إلى الأضرحة وقبور الصالحين سائلين أهلها من الأموات شفاء مرضهم أو قضاء حوائجهم، ويقدمون لأصحاب هذه الأضرحة النذور والذبائح، ويدعونهم ويستغيثون بهم، وما شابه ذلك من أعمال، وهذه القضية اختلفت فيها الآراء: فالذين يقيمون بهذا العمل يقولون: إن لله في الأرض عباد يستجيب الله الدعاء من أجلهم، والذين يعارضون هذا العمل قالوا: إن هذا شرك صريح، ومخرج لصاحبه من الملة، نرجو أن تلقوا مزيداً من الضوء على جوانب وزوايا هذا الموضوع؟ مع بيان هل يجوز الصلاة خلف مرتكبيه أو لا يجوز، وفقكم الله؟","title":"شد الرحال إلى الأضرحة وسؤال أهلها قضاء الحوائج","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن هذا السؤال مهم جداً، وعظيم جداً، وهو شد الرحال إلى الأضرحة لطلب الحاجات وشفاء المرضى من أصحاب القبور، ولدعائهم والاستغاثة بهم، والنذر لهم، وتقديم الذبائح ونحو ذلك.\nأما شد الرحال لمجرد الزيارة للقبور فهذا لا يجوز على الصحيح من أقوال العلماء؛ لأنه منهي عنه؛ ولأنه وسيلة إلى الشرك، والأصل في هذا قوله عليه الصلاة والسلام في الحديث الصحيح: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا -يعني: مسجد النبي ﷺ في المدينة- والمسجد الأقصى هذه الثلاثة تشد لها الرحال بنص النبي عليه الصلاة والسلام، وما سواها لا تشد له الرحال، فيدخل في ذلك بقية المساجد، ويدخل في ذلك أيضاً الأضرحة من باب أولى، فإنه إذا كان لا تشد الرحال إلى المساجد وهي أفضل البقاع، فغيرها من البقاع التي تشد لها الرحال من أجل فضل المدفون بها أو نحو ذلك من باب أولى في المنع، ولهذا أصح أقوال العلماء في هذا الباب تحريم شد الرحال لزيارة القبور، وإنما تزار من دون شد الرحل، فزيارتها سنة كما قال النبي ﷺ: زوروا القبور فإنها تذكركم الآخرة، فالسنة زيارة القبور، والدعاء لأهلها بالمغفرة والرحمة، للرجال خاصة دون النساء؛ لأن الرسول ﷺ أمر بزيارة القبور وقال: إنها تذكر الموت تذكر الآخرة وكان يعلم أصحابه ذلك، يعلمهم إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، وكان يزور البقيع عليه الصلاة والسلام، ويترحم عليهم، ويدعو لهم بالمغفرة، أما بشد الرحال فلا، لا تشد الرحال لزيارة القبور كما لا تشد لأجل زيارة المساجد الأخرى غير الثلاثة.\nأما إذا قصد بشد الرحال دعاء الميت والاستغاثة بالميت فهذا منكر وحرام بالإجماع؛ بإجماع المسلمين، ولو فعل هذا من دون شد الرحل، لو أتى القبور التي في بلاده من دون شد رحل يستغيث بها، أو ينذر لها، أو يذبح لها، أو يسألها قضاء الحاجات، شفاء المرضى، تفريج الكروب، كان هذا منكراً عظيماً وشركاً ظاهراً، وهذا هو شرك الأولين من الجاهلية، كانوا يفعلون هذا مع الأموات، كانت الجاهلية تشرك بالأموات وتستغيث بهم، وتنذر لهم، ويقولون: هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18]، ويقولون: مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:3]، كما حكى الله عنهم ذلك سبحانه وتعالى، فإنه سبحانه قال: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18] فرد الله عليهم بقوله: قُلْ أَتُنَبِّئُونَ اللَّهَ بِمَا لا يَعْلَمُ فِي السَّمَوَاتِ وَلا فِي الأَرْضِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ [يونس:18].\nوقال سبحانه: فََاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ ۝ أَلا لِلَّهِ الدِّينُ الْخَالِصُ وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:2-3] يعني: يقولون: ما نعبدهم إلا ليقربونا إلى الله زلفى، فرد الله عليهم بقوله: إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ [الزمر:3] فبين سبحانه وتعالى أن عبادتهم إياهم بالدعاء والضراعة والاستغاثة، والذبح والنذر، والسجود على القبور، أو نحو ذلك أن هذا هو الشرك بالله، وأن هذا هو الكفر والضلال، وأن هذا لا ينفعهم بل يضرهم، وإن زعموا أنهم شفعاء عند الله، وإن زعموا أنهم يقربونهم زلفى فهو باطل؛ لأن دعاء الأموات، والاستغاثة بالأموات، أو بالأصنام، أو بالأشجار لا يقرب إلى الله، ولا يدني من رضاه، بل يباعد من رحمته، ويوجب غضبه، ويوجب النار، ويحرم عليه الجنة، كما قال الله جل وعلا في كتابه العظيم: إِنَّهُ مَنْ يُشْرِكْ بِاللَّهِ فَقَدْ حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ وَمَأْوَاهُ النَّارُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ [المائدة:72]، وقال سبحانه: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]، فبين سبحانه أنه لا يغفر الشرك ولكن يغفر ما دونه لمن يشاء، فما دون الشرك معلق بمشيئة الله، إن شاء غفر سبحانه، وإن شاء عذب أصحابه إن ماتوا قبل التوبة.\nوأما الشرك فلا يغفر إذا مات عليه صاحبه، وكذلك الشرك يحبط الأعمال كما قال الله سبحانه: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88].\nوالشرك معناه: صرف بعض العبادة لغير الله، من دعاء، أو خوف، أو رجاء، أو توكل، أو ذبح، أو نذر، أو صلاة، أو صوم، أو نحو ذلك، فالذي يدعو الأموات ويستغيث بهم، وينذر لهم، ويزعم أنهم يشفعون له، أو يقربونه إلى الله زلفى، قد فعل فعل المشركين الأولين سواء بسواء، وهكذا إذا تقرب إليهم بالذبائح والنذور، فهذا كله شرك بالله عز وجل .. كله منكر، يجب على أهل العلم إنكاره، وبيان بطلانه، وتحذير العامة من ذلك، وهذا هو نفس الشرك الذي فعله أبو جهل وأشباهه في الجاهلية مع اللات والعزى ومناة، وهذا هو شرك الأولين مع أصنامهم وأوثانهم في كل مكان.\nومن المصائب: أن يظن العامة أن هذا دين وأن هذا قربة، وأن يسكت على ذلك من ينسب إلى العلم، ويتساهل في هذا الأمر، فإن هذا يضر العامة ضرراً عظيماً، إذا سكت المنسوبون للعلم ولم ينكروا هذا الشرك ظن العامة أنه جائز وأنه دين، وأنه قربة، فبقوا عليه واستمروا عليه.\nفالواجب على أهل العلم إنكار الشرك بالله، وإنكار البدع، وإنكار المعاصي، والتحذير من ذلك، وتنبيه العامة على كل ما حرم الله عليهم، حتى يحذروه.. من الشرك فما دونه، ولا شك ولا ريب أن دعاء الأموات، والاستغاثة بالأموات، وطلب شفاء المرضى، وطلب المدد، أن هذا هو الشرك بالله عز وجل، وهذا يفعله كثير من الناس عند بعض القبور، كما يفعله بعض الناس عند قبر النبي ﷺأيام الحج من بعض الجهلة، وكما يفعله الكثير من الناس عند قبر السيد البدوي في مصر، وعند قبر الحسين في مصر، وعند قبور أخرى، وهكذا يفعل عند قبر الشيخ عبد القادر الجيلاني ، ويفعله بعض الناس وهم بعيدون عن هذه القبور، يدعونها من بعيد، ويسألونها قضاء الحاجات، وشفاء المرضى من بعيد، وهكذا يفعل عند قبور أهل البيت من بعض من يزورها من الشيعة وغير الشيعة ، وهكذا عند قبر ابن عربي في الشام، وهكذا عند قبور أخرى في بلدان لا يحصيها إلا الله عز وجل، وهذه بلية عمت، وطم شرها، وعظم ضررها؛ بأسباب قلة العلم، وقلة من ينبه على هذا الأمر الخطير، وإني أهيب بجميع أهل العلم في كل مكان أن يتقوا الله، وأن ينذروا الناس من هذا الشرك، وأن يحذروهم منه، وأن يبينوا لهم أن العبادة حق الله وحده، كما قال سبحانه: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]، وقال عز وجل: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23]، وقال سبحانه وتعالى: وَاعْبُدُوا اللَّهَ وَلا تُشْرِكُوا بِهِ شَيْئًا [النساء:36]، وقال عز وجل: فََاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ ۝ أَلا لِلَّهِ الدِّينُ الْخَالِصُ [الزمر:2-3]، وقال سبحانه: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، في آيات كثيرات تدل على وجوب إخلاص العبادة لله وحده، وأنه لا يجوز أبداً أن يعبد أحد من دونه من الأشجار، أو الأحجار، أو الأموات، أو الأصنام، أو الكواكب، أو غير ذلك، فالعبادة حق الله وحده، ليس لأحد فيها حق، لا الملائكة، ولا الأنبياء، ولا الصالحون، ولا غيرهم، بل العبادة حق الله وحده، الرسل بعثوا ليعلموا الناس دينهم؛ ولينذروهم من الشرك بالله؛ وليوجهوهم إلى عبادة الله وحده، كما قال سبحانه: وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِ اُعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ [النحل:36]، وقال عز وجل: وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَسُولٍ إِلَّا نُوحِي إِلَيْهِ أَنَّهُ لا إِلَهَ إِلَّا أَنَا فَاعْبُدُونِ [الأنبياء:25]، في آيات كثيرات أخرى، وقال النبي عليه الصلاة والسلام لـمعاذ: أتدري ما حق الله على العباد وما حق العباد على الله؟ قلت: الله ورسوله أعلم، قال: حق الله على العباد: أن يعبدوه ولا يشركوا به شيئاً، وحق العباد على الله: أن لا يعذب من لا يشرك به شيئاً فهما حقان: حق الله على عباده، وحق العباد على الله، أما حق الله على عباده: وهو حق مفترض، وحق عظيم، يجب عليهم أن يؤدوه، قد خلقوا لأجله، كما قال سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]، والله أرسل الرسل من أجله كما تقدم، فوجب على العباد أن يعبدوا الله وحده، هذا حقه عليهم، حق فرضه عليهم، فعليهم أداؤه، وعليهم أن يؤدوا كل ما أمر الله به ورسوله، وأن ينتهوا عما نهى الله عنه ورسوله، كل هذا من عبادته سبحانه وتعالى، أداء الفرائض، وترك المحارم، وابتغاء وجه الله، والإخلاص له سبحانه، كل ذلك من عبادته، ومن طاعته وتعظيمه.\nأما حق العباد على الله: هو حق تفضل وإحسان، وجود وكرم، من كرمه وجوده وإحسانه أن من لقيه بالتوحيد والإيمان والهدى فإن الله يدخله الجنة ولا يعذبه بالنار، هذا فضله وإحسانه جل وعلا، كما يقول سبحانه: إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ جَنَّاتُ النَّعِيمِ [لقمان:8]، إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَنَعِيمٍ [الطور:17]، إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَعُيُونٍ [الحجر:45].\nفالواجب على أهل الإسلام أن يعبدوا الله وحده، وأن يخصوه بالعبادة، وأن يتفقهوا في دين الله، وأن يحذروا الشرك بالله ، فإن دعوى الإسلام مع وجود الشرك لا تنفع، بل ينتقض إسلامه بشركه بالله، بل الشرك ينقض الإسلام ويبطله، فوجب على من ينتسب إلى الإسلام أن يحقق إسلامه، وأن يتفقه في دين الله، وأن يحفظ دينه من أنواع الشرك بالله عز وجل، حتى يبقى له إسلامه، وحتى يبقى له دينه، وهكذا يجب على كل أهل الأرض من المكلفين، من جن وإنس وعرب وعجم، يجب عليهم جميعاً أن يعبدوا الله وحده، وأن ينقادوا لما جاء به محمد عليه الصلاة والسلام فهو رسول الله حقاً، وهو خاتم الأنبياء؛ لأن الله بعثه إلى أهل الأرض جميعاً من الجن والإنس، ومن العرب والعجم، من سائر الأمم، يجب عليهم أن يعبدوا الله، وأن ينقادوا لما جاء به رسوله محمد عليه الصلاة والسلام، كما قال الله سبحانه آمراً النبي ﷺ أن يبلغ الناس: قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللَّهِ إِلَيْكُمْ جَمِيعًا [الأعراف:158]، وقال سبحانه: وَمَا أَرْسَلْنَاكَ إِلَّا كَافَّةً لِلنَّاسِ بَشِيرًا وَنَذِيرًا [سبأ:28]، وقال : وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِلْعَالَمِينَ [الأنبياء:107]، فهو رسول الله إلى الجميع، إلى الجن والإنس، إلى العرب والعجم، إلى اليهود والنصارى والفرس، وجميع أهل الأرض من الجن والإنس، عليهم جميعاً أن يعبدوا الله، ويوحدوه، ويخصوه بالعبادة، وأن لا يعبدوا معه لا ملكاً مقرباً، ولا نبياً مرسلاً، ولا شجراً، ولا ميتاً، ولا صنماً، ولا وثناً، ولا غير ذلك، بل عليهم أن يخصوا الله بالعبادة دون كل ما سواه، وعليهم أيضاً أن ينقادوا لما جاء به نبيه محمد عليه الصلاة والسلام، وأن يحكموه فيما بينهم، وأن لا يخرجوا عن هديه وطريقه، كما قال سبحانه وتعالى في كتابه العظيم: فَلا وَرَبِّكَ لا يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لا يَجِدُوا فِي أَنفُسِهِمْ حَرَجًا مِمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْلِيمًا [النساء:65]، وقال سبحانه: قُلْ أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِنْ تَوَلَّوا فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُمْ مَا حُمِّلْتُمْ وَإِنْ تُطِيعُوهُ تَهْتَدُوا وَمَا عَلَى الرَّسُولِ إِلَّا الْبَلاغُ الْمُبِينُ [النور:54] عليه الصلاة والسلام، ويقول : فَالَّذِينَ آمَنُوا بِهِ وَعَزَّرُوهُ وَنَصَرُوهُ وَاتَّبَعُوا النُّورَ الَّذِي أُنزِلَ مَعَهُ أُوْلَئِكَ هُمُ الْمُفْلِحُونَ [الأعراف:157] فالمفلحون هم هؤلاء، هم أتباع النبي محمد عليه الصلاة والسلام، أما الذين خرجوا عن دين محمد صلى الله عليه وسلم ولم ينقادوا لشرعه، ولم يصدقوه، فهؤلاء هم الخاسرون، هم الهالكون، هم الضالون، هم الكافرون من أي جنس كانوا، وقال سبحانه: قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللَّهِ إِلَيْكُمْ جَمِيعًا الَّذِي لَهُ مُلْكُ السَّمَوَاتِ وَالأَرْضِ لا إِلَهَ إِلَّا هُوَ يُحْيِي وَيُمِيتُ فَآمِنُوا بِاللَّهِ وَرَسُولِهِ النَّبِيِّ الأُمِّيِّ الَّذِي يُؤْمِنُ بِاللَّهِ وَكَلِمَاتِهِ وَاتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ [الأعراف:158]، فجعل الهداية في اتباعه، فدل ذلك على أن من خرج عن شريعة محمد ﷺ فهو الخاسر وهو الضال غير المهتدي، فالهداية والفلاح والنجاة في اتباع رسول الله ﷺ، وفي إخلاص العبادة لله وحده، وفي تحكيم شريعة الله التي جاء بها رسوله محمد عليه الصلاة والسلام، وبهذا يعلم أن الواجب على جميع الأمم توحيد الله والإخلاص له، وعلى جميع الدول أن تعبد الله وأن تلزم شعوبها بعبادة الله، وأن تدع ما هي عليه من الشرك والباطل، هذا عام لجميع الدول، لجميع الناس، ولكن المسلمين المنتسبين للإسلام الواجب عليهم أخص وأكبر؛ لأنهم انتسبوا إلى دين الله، ووجب عليهم أن يحققوا دين الله، وأن يعظموا دين الله، وأن يصونوه عما حرم الله، وأن يخلصوا العبادة لله وحده حتى يتحقق إسلامهم، وحتى يكونوا مسلمين حقاً لا بالانتساب، فالانتساب لا يفيد ولا ينفع، بل يجب أن يكون إسلامهم حقاً بعبادة الله وحده، والإخلاص له، وتعظيم أمره ونهيه، واتباع نبيه محمد عليه الصلاة والسلام.\nويجب على الأمم الأخرى التي لا تنتسب للإسلام من اليهود والنصارى والمجوس وغيرهم من جميع الأمم التي لا تتبع محمد عليه الصلاة والسلام، عليهم جميعاً أن يعبدوا الله وحده، وعليهم جميعاً أن ينقادوا للشرع الذي جاء به محمد عليه الصلاة والسلام، عليهم جميعاً ذلك؛ لأنهم مأمورون بذلك، مخلوقون لذلك، والله بعث محمد إلى الجميع عليه الصلاة والسلام، إلى جميع أهل الأرض من الجن والإنس، فلا يجوز لأحد منهم أن يخرج عن شريعة محمد عليه الصلاة والسلام، كائناً من كان، فنسأل الله للجميع الهداية والتوفيق، والفقه في الدين، ولا حول ولا قوة إلا بالله. نعم.","link":"https://binbaz.org.sa/fatwas/4569/شد-الرحال-الى-الاضرحة-وسوال-اهلها-قضاء-الحواىج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_015/01501.mp3","categories":["نواقض الإسلام"]},{"id":7565,"question":"شق سؤال المستمع زكري فرج مسعود من جمهورية مصر العربية يقول: هل تجوز الصلاة خلف أولئك الذين يدعون إلى زيارة الأضرحة؟","title":"حكم الصلاة خلف عباد الأضرحة","answer":"الجواب: من عرف بأنه من عباد الأضرحة، من عرف بأنه يأتي القبور ويستغيث بأهلها، ويسألهم شفاء المرضى ونحو ذلك، فهذا لا يصلى خلفه؛ لأن ظاهره الشرك، والمشرك لا يصلى خلفه، الصلاة خلفه باطلة، فلا يجوز أن يصلى خلف هؤلاء، بل يجب أن ينبهوا وأن يحذروا من الشرك، وأن ينصحوا، فإذا تابوا ورجعوا عن الباطل ووحدوا الله سبحانه وتعالى، وقبلوا النصيحة يصلى خلفهم، أما ما داموا يعبدون غير الله، ما داموا يتعلقون بالقبور ويسألونها شفاء المرضى والمدد وقضاء الحاجات، هؤلاء لا، لا يصلى خلفهم، بل شركهم ظاهر، وكفرهم ظاهر، وإن كان بعضهم قد يكون غره الجهل، وغره سكوت العلماء، فإن هذا لا يعذره، بل يجب عليه أن يسأل وأن يتفقه في دين الله، وأن يسأل أهل العلم، ويتبصر في ذلك ولا يتساهل. نعم.","link":"https://binbaz.org.sa/fatwas/4570/حكم-الصلاة-خلف-عباد-الاضرحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_015/01502.mp3","categories":["نواقض الإسلام"]},{"id":7689,"question":"هذه الرسالة وردت من الصومال، يقول الأخ إسحاق علي عمر الصومالي: نود أن نسأل فضيلة العلماء سؤالاً قد يهم كثيراً من إخواننا المستمعين وهو كالتالي: بعض المسلمين يعتقدون أن للأولياء تصرفات تضر وتنفع، وتجلب المنافع وتدفع البلاء، بينما هم ينتمون إلى الإسلام ويؤدون شعائر الإسلام كالصلاة وغيرها، فهل تصح الصلاة خلف إمامهم، هل يجوز الاستغفار لهم بعد موتهم، أفيدونا مشكورين؟","title":"حكم الصلاة خلف من يعتقد أن الأولياء يضرون وينفعون","answer":"الجواب: هذا قول من أقبح الأقوال، وهذا من الكفر والشرك بالله عز وجل؛ لأن الأولياء لا ينفعون ولا يضرون، ولا يجلبوا منافع ولا يدفعوا مضار، إذا كانوا أموات، وصح أن يسموا أولياء؛ لأنهم معروفون بالعبادة والصلاح، فإنهم لا ينفعون ولا يضرون بل النافع الضار هو الله وحده، هو الذي يجلب النفع على العباد ويدفع عنهم الضرر، كما قال الله جل وعلا لنبيه ﷺ: قُلْ لا أَمْلِكُ لِنَفْسِي ضَرًّا وَلا نَفْعًا إِلَّا مَا شَاءَ اللَّهُ [يونس:49]، هو النافع الضار جل وعلا، وقال سبحانه وتعالى في المشركين: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18]، فالله جل وعلا هو النافع الضار، وجميع الخلق لا ينفعون ولا يضرون، أما الأموات فظاهر؛ لأنهم قد انقطعت حركاتهم وذهبت حياتهم، فلا ينفعون أنفسهم ولا غيرهم، ولا يضرون؛ لأنهم قد فقدوا الحياة وفقدوا القدرة على التصرف، وهكذا في الحياة لا ينفعون ولا يضرون إلا بإذن الله، فمن زعم أنهم يستقلون بالنفع والضر وهم أحياء كفر أيضاً، بل النافع الضار هو الله وحده سبحانه وتعالى، ولهذا لا تجوز عبادتهم ولا دعاؤهم ولا الاستغاثة بهم ولا النذر لهم ولا طلبهم المدد، ومن هذا يعلم كل ذو بصيرة أن ما يفعله الناس عند قبر البدوي أو عند قبر الحسين أو عند قبر الكاظم أو عند قبر الشيخ عبد القادر الجيلاني ، أو ما أشبه ذلك من طلب المدد والغوث أنه من الكفر بالله من الشرك بالله سبحانه وتعالى. \nفيجب الحذر من ذلك والتوبة من ذلك والتواصي بترك ذلك، ولا يصلى خلف هؤلاء؛ لأنهم مشركون، عملهم هذا شرك أكبر، فلا يصلى خلفهم ولا يصلى على ميتهم؛ لأنهم عملوا الشرك الأكبر، الذي كانت عليه الجاهلية في عهد النبي صلى الله عليه وسلم، كان عليه أبو جهل وأشباهه من كفار مكة وعليه كفار العرب، الدعاء للأموات والاستغاثة بالأموات والأشجار والأحجار، فهذا عين الشرك بالله ، والله يقول سبحانه: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88]، والواجب على أهل العلم أن يبينوا لهم، وأن يوضحوا لهم الحق، وأن يرشدوهم إلى الصواب وأن يحذروهم من هذا الشرك بالله عز وجل. \nيجب على العلماء في كل مكان في مصر وفي الشام والعراق ومكة والمدينة والحرمين وسائر البلاد أن يرشدوا الناس، ولا سيما عند وجود الحجاج يجب أن يرشدوا ويبين لهم هذا الأمر العظيم، والخطر الكبير؛ لأن بعض الناس قد وقع فيه في بلاده، فيجب أن يبين لهم توحيد الله ومعنى: لا اله إلا الله، وأن معناها: لا معبود حق إلا الله، فهي تنفي الشرك.. تنفي العبادة عن غير الله، وتثبت العبادة لله وحده، وهذا هو معنى قوله سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] .. وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] ومعنى قوله جل وعلا: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ ۝ أَلا لِلَّهِ الدِّينُ الْخَالِصُ [الزمر:2-3] وقوله سبحانه: فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ [غافر:14]. \nفالواجب توجيه العباد إلى الخير وإرشادهم إلى توحيد الله، وأن الواجب على كل إنسان أن يعبد الله وحده، وأن يخصه بالعبادة من دعاء وخوف ورجاء وتوكل وطلب غوث وصلاة وصوم وغير ذلك، كله لله وحده، لا يجوز أبداً فعل شيء من ذلك لغير الله سبحانه وتعالى سواءً كان نبياً أو ولياً أو غير ذلك، فالنبي لا يملك لنفسه ضراً ولا نفعاً، ولكن يتبع ويطاع في الحق، يطاع ويتبع ويحب محبة صادقة، ونبينا ﷺ أفضل الأنبياء وأشرفهم، ومع هذا لا يدعى من دون الله ولا يستغاث به ولا يسجد له ولا يصلى له ولا يطلب المدد، ولكن يتبع، يصلى عليه ويسلم عليه ويتبع، ويجب أن يكون أحب إلينا من أنفسنا وأموالنا وأولادنا وآبائنا وغير ذلك، هذا واجب كما قال النبي ﷺ: لا يؤمن أحدكم حتى أكون أحب إليه من ولده ووالده والناس أجمعين. \nلكن هذه المحبة لا تجوز لنا أن نشرك به، لا تسوغ لنا أن ندعوه من دون الله أو نستغيث به أو نسأله المدد أو الشفاء لا، نحبه محبة صادقة؛ لأنه رسول الله إلينا؛ ولأنه أفضل الخلق؛ ولأنه بلغ الرسالة وأدى الأمانة، نحبه لله محبة صادقة فوق محبة النفس والمال والولد، ولكن لا نعبده مع الله، وهكذا الأولياء نحبهم في الله نترحم عليهم من العلماء والعباد، ولكن لا ندعوهم مع الله، ولا نبني على قبورهم ولا نستغيث بهم ولا نطوف بقبورهم، ولا نطلبهم المدد، كل هذا شرك بالله لا يجوز، الطواف بالكعبة لله وحده، الذي يطوف بالقبر لأجل طلب الفائدة من الميت.. طلب المدد.. طلب الشفاء.. طلب النصر على الأعداء، كل هذا من الشرك بالله عز وجل، فالواجب الحذر منه غاية الحذر. نعم. \nالمقدم: أحسنتم.","link":"https://binbaz.org.sa/fatwas/4888/حكم-الصلاة-خلف-من-يعتقد-ان-الاولياء-يضرون-وينفعون ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_027/02707.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":7733,"question":"أيضاً لديه أسئلة ووعدناه بالإجابة عليها فالمستمع من حضرموت يسأل عن زيارة القبور وتعظيم الأولياء، يقول في رسالته هذه: في حضرموت وفي مدينة سيئون يذهب الناس في وقت محدد من كل سنة إلى زيارة قبة علي حبشي يقال: إنه أحد الأولياء وفي هذه القبة قبره، والطريقة المتبعة هي: غسل وتلبيس القبر، ثم ثاني يوم وقفة مع خطبة لأحد العلماء، وذلك قبل شروق الشمس، نرجو أن تفتونا بذلك مع دليل؟ وما حكم زيارة القبور والتمسح بالقبر أو الشخص العالم الولي؟","title":"حكم تعظيم القبور واتخاذها مساجد","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: هذا القبر المسئول عنه لا نعرف له أصلاً، ثم لو عرف فإن البناء على القبور وتخصيص يوم معين لزيارتها واتخاذها أعياد أمر منكر، النبي عليه السلام قال: لا تتخذوا قبري عيداً ولا بيوتكم قبوراً فلا يجوز أن تعظم القبور بالبناء عليها واتخاذها مساجد ولا باتخاذها أعياداً يجتمع إليها في السنة مرة أو مرتين، كل هذا مما أحدثه الناس، وإنما المشروع أن تزار فيما يسر الله من الأيام، من غير تحديد يوم معين، تزار ويدعى للميت ويترحم عليه، كما قال النبي ﷺ: زوروا القبور فإنها تذكركم الآخرة فلا بد من تذكر الموت، فيزورها المؤمن يزورها الرجل أما النساء منهيات عن زيارة القبور، لكن يزورها الرجل ويسلم على المقبور ويدعو لهم بالمغفرة والرحمة هذا هو المشروع، من دون شد رحل، أما شد الرحال فلا يجوز شد الرحال إلى القبور، وإنما تشد الرحال إلى المساجد الثلاثة فقط، مسجد الحرام، ومسجد النبي ﷺ والمسجد الأقصى، هكذا بين النبي ﷺ قال: لا تشد الرحال إلا إلى ثلاثة مساجد، المسجد الحرام ومسجدي هذا والمسجد الأقصى أما شد الرحال لقبرٍ معين أو لقبور معينة هذا منكر وخلاف السنة.\nثم قصد القبور للدعاء عندها أو الصلاة عندها أو القراءة عندها أيضاً منكر ومن وسائل الشرك، فلا تتخذ محلاً للدعاء والصلاة والقراءة، بل هذا من نوع اتخاذها مساجد، فلا يجوز، ولا يجوز البناء عليها لا بقبة ولا بسقف لا يتخذ قبر مصلى ولا يبنى عليه قبة ولا يفرش ولا يطيب، لأن هذه من وسائل الشرك ووسائل الغلو فيه، فلا يجوز هذا العمل الذي ذكره السائل، من قصد القبر وتغسيله وتعظيمه والاجتماع عنده والتبرك به كلها من المنكرات التي حرمها الله عز وجل، والنبي ﷺ قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وقال: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك.\nفلا يجوز أن تتخذ مساجد ولا أن يبنى عليها ولا أن يصلى عندها، وقال أيضاً عليه الصلاة والسلام في الحديث الصحيح : اجعلوا من صلاتكم في بيوتكم ولا تتخذوها قبوراً فإن الشيطان يفر من البيت الذي تقرأ فيه سورة البقرة فدل على أن القبور ما هي محل مساجد ولا محل قراءة.\nوقال أيضاً عليه الصلاة والسلام فيما رواه جابر .. روى جابر عن النبي ﷺ: أنه نهى عن تشييد القبور، وعن القعود عليها وعن البناء عليها. رواه مسلم في الصحيح.\nفالقبور لا يبنى عليها لا قبة ولا غيرها ولا يبنى عليها مسجد، ولا تتخذ محلاً للدعاء والصلاة والقراءة، ولكن تزار من البلد من دون شد رحل، يزورها أهل البلد أو المار عليها فيسلم عليهم ويدعو لهم ويستغفر لهم، وفيها عبرة وذكرى، بالزيارة يذكر الموت ويذكر الآخرة ويذكر ما صار إليه هؤلاء الأموات فيستعد للقاء الله عز وجل.\nهذا هو المشروع فينبغي الحذر مما أحدثه الجهال ومما يفعله الجهال من الغلو في القبور ودعاء أهلها والاستغاثة بهم والنذر لهم وطلب منهم المدد فإن هذا من الشرك الأكبر، كونه يقول: يا سيدي فلان المدد المدد، الغوث الغوث، اشف مريضي انصرنا على أعدائنا هذا من الكفر الأكبر، من الكفر والشرك الأكبر، إنما يطلب من الله هو الذي يمد العباد، هو الذي ينصرهم، هو الذي يشفي المرضى سبحانه وتعالى، أما الميت فليس عنده قدرة، لا يشفي نفسه ولا يشفي غيره، فدعاؤه والاستغاثة به والنذر له والذبح له وطلبه المدد كل هذا من أعمال الجاهلية ومن الشرك الأكبر، فيجب الحذر من ذلك، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/4932/حكم-تعظيم-القبور-واتخاذها-مساجد ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_033/03301.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":7761,"question":"هذه الرسالة وردتنا من السودان يقول: من أخيكم في الدين العبيد محمد السودان مديرية الجزيرة، يقول: أتقدم لإخواني في الدين وإخواني مقدمي برنامج نور على الدرب، وأرجو عرض طلب هذا الحكم على الشيخ الذي يجيب على أسئلة المستمعين، يقول: ما الحكم الشرعي للشخص الذي يرتكب جريمة سب الدين وهو متزوج، فإن كنت حوله أو قريباً منه فما الواجب الذي أقوم به نحو هذا الشخص، وشكري لكم؟","title":"واجب المسلمين تجاه من يسب الدين","answer":"الجواب: سب الدين من أعظم الجرائم في الإسلام، وهو من الجرائم الكفرية ومن نواقض الإسلام ومن أنواع الردة عن الإسلام، فالذي يسب الدين أو يسب الله أو يسب الرسول عليه الصلاة والسلام هذا قد أتى كفراً عظيماً وردة عن الإسلام، والواجب على من سمعه أو كان يعلم ذلك منه أن ينكر عليه وأن يعلمه أن هذا ناقض من نواقض الإسلام وكفر بواح، فعليه أن يبادر بالتوبة لعل الله يتوب عليه.\nوأما حكمه في الدنيا بالنسبة إلى ولاة الأمور فالواجب عليهم استتابته، فإن تاب فالحمد لله وإلا وجب أن يقتل، وقال جمع من أهل العلم: لا يستتاب بل يقتل حداً كافراً، فإن تاب فيما بينه وبين الله تاب الله عليه، ولكن يجب أن يقتل ردعاً له ولأمثاله عن سب الله ورسوله وعن سب دين الله.\nوالقولان معروفان لأهل العلم، وبالنظر إلى حالة الناس اليوم وكثرة الجهل واختلاطهم بالمشركين والكفار وضعفاء البصيرة يتضح له أن هذا الشيء قد يكثر في هذا الزمان؛ لكثرة مخالطة الكفرة، ولكثرة الجهل وغلبته على الناس ولضعف الدين والإيمان في قلوب الكثير من الناس، فلهذا قد يقع منه هذا الشيء كثيراً، فالواجب أن يردع عن هذا الشيء بغاية من التأديب الذي يردع الناس عن هذا ثم يستتاب لعله يندم على ما فعل، ولكن لابد من التعزير.. لابد من الأدب عما أقدم عليه ثم استتابته بعد ذلك، فيستتاب فإن تاب الحمد لله مع التعزير والتأديب حتى لا يعود لمثل هذا، وإن لم يتب قتل كفراً وردة عن الإسلام.\nوالقول الثاني: لا يستتاب بل يقتل فوراً ولا يستتاب؛ لأن هذه جريمة عظيمة فلا يستتاب أهلها كما لا يستتاب الساحر على الصحيح، فهكذا من سب الله ورسوله أو سب دينه من باب أولى؛ لظهور كفره ولأنه هتك أمراً عظيماً وأتى جريمة عظمى في سب الدين وسب الله ورسوله.\nوبكل حال فالواجب أن يستتاب فإن تاب وندم وأقلع وأظهر الخير وأظهر العمل الصالح فالحمد لله وإلا قتل، ولكن التعزير لابد منه، لابد أن يعزر ويؤدب حتى لا يعود إلى مثل هذا ولو تاب، وإن قتل فوراً ولم يستتب فهو قول جيد وقول قوي ولا غبار عليه، ولكن الاستتابة لها وجهها، الله جل وعلا أمر باستتابة الكفار ودعوتهم إلى ذلك فإذا استتيب؛ لأن الجهل يغلب على الناس ويغلب عليهم أيضاً التساهل في هذه الأمور؛ بسبب الجلساء الضالين وبسبب غلبة الجهل وبسبب المخالطة الخبيثة للكفرة والمجرمين فإذا استتيب وتاب توبة صادقة وأظهر الخير فالحمد لله، وإلا أمكن قتله إذا عاد إلى مثل هذا ولم يتأثر بالاستتابة ولا بالتعزير الذي فعل معه من ولاة الأمور. نعم.\nوالله المستعان، لا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/4957/واجب-المسلمين-تجاه-من-يسب-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_044/04404.mp3","categories":["الجنايات والحدود","نواقض الإسلام"]},{"id":7891,"question":"هذه رسالة وردتنا من أحمد جاسم الراشدي -الموصل- العراق، يقول فيها: أجمل تحياتي أبعثها إلى إذاعتكم الحبيبة على قلوب المسلمين في كافة أرجاء المعمورة، إن إذاعة نداء الإسلام من مكة المكرمة لها مستمعين كثير جداً في الجمهورية العراقية، وخاصة في مدينة الموصل، وأنا من ضمن هؤلاء المستمعين لدي سؤال موجه إلى أصحاب الفضيلة العلماء أرجو الإجابة عليه، يقول: في مدينة الموصل يوجد مزار يسمى مزار الشيخ: فتحي أبو عبد الله ، وهذا الشيخ له أثر كبير عند أهالي الموصل وخاصة النساء، حيث إذا تمرضن أو يصبن بأذى يذهبن لزيارة الشيخ فتحي ويحصل لهن الشفاء العاجل، كما يدعين وينذرن النذور للشيخ فتحي عند شفائهن من المرض، والعبارات التي يقولها هي النذر لوجه الله، والثاني لأبو عبد الله ، أو يقول: نذر لله والشيخ فتحي أو لله وثوابها لأبي عبد الله ، وسؤالي هذا: هل حلال أم حرام أفيدونا أفادكم الله، والسلام عليكم؟","title":"حكم دعاء الأموات والاستغاثة بهم والنذر لهم","answer":"الجواب: هذا القبر الذي ذكره السائل لا أعرف صاحبه، ولكن بكل حال فلا يجوز إتيان القبور لدعائها والاستغاثة بأهلها والنذر لهم، سواء كان هذا القبر أو غيره لا قبر الفتح ولا غيره، لا يجوز للمسلمين ذكوراً وإناثاً أن يأتوا القبور لدعائها والاستغاثة بأهلها أو النذر لهم أو التمسح بقبورهم أو ما أشبه ذلك بل هذا منكر ولا يجوز، ودعاء الميت والاستغاثة به من الشرك من أنواع الشرك الأكبر.\nفعلى أهل العلم أن يوضحوا للنساء وغير النساء أن هذا لا يجوز، وأن عليهن أن يسألن الله جل وعلا، إذا نزل بهن بأس من مرض أو غيره أن يسألن الله ويضرعن إليه في سجودهن وفي آخر الصلاة وفي آخر الليل وبين الأذان والإقامة، يسألن الله جل وعلا الشفاء والعافية ومن ذلك ... والرقية، كونه يرقي بعضهن بعضاً مثل الرقية الشرعية: رب الناس أذهب الباس واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاء لا يغادر سقماً، وبقراءة قل هو الله أحد والمعوذتين، والفاتحة وآية الكرسي وغير ذلك من الآيات القرآنية.\nفالمقصود: أن إتيان القبور لسؤال أهلها الشفاء أو النصر أو ما أشبه ذلك هذا منكر ومن الشرك الأكبر، وهذا من عمل الجاهلية، وإنما تزار القبور للسلام، تزور القبور للسلام على أهلها والدعاء لهم والترحم عليهم، كما كان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين ويدعو لهم يقول: اللهم اغفر لهم، اللهم ارحمهم ونحو هذا، هذه هي الزيارة الشرعية.\nوقد زار النبي ﷺ قبور البقيع، فقال: السلام يا أهل القبور، يغفر الله لنا ولكم، أنتم سلفنا ونحن بالأثر هذه هي الزيارة الشرعية، أما الزيارة لدعاء الميت أو للاستغاثة بالميت هذا من الشرك الأكبر، أو الطواف بقبره يرجو شفاعته يرجو عائدته، يرجو أنه يشفي مرضه هذا كله من الشرك الأكبر، وهكذا التمسح بتراب القبر، والاستشفاء بتراب القبر هذا من عمل الجاهلية ومن الشرك الذي حرمه الله عز وجل.\nفالواجب على أهل العلم أن ينبهوا العامة وأن يوضحوا لهم أن هذا لا يجوز، وأن الله هو الذي يسأل سبحانه وتعالى ويرجى في شفاء المرض، والنصر على الأعداء وغير ذلك سبحانه وتعالى، وهو القائل جل وعلا: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، وهو القائل: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60]، وقال سبحانه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106]، قال النبي ﷺ: الدعاء هو العبادة.\nفلا يجوز أن يدعى غير الله، لا ملك مقرب ولا نبي مرسل، بل الدعوة لله وحده، هو الذي يرجى ويدعى سبحانه وتعالى، ولا يجوز أن يقول: يا رسول الله! اشف مريضي، انصرني، أو يا شيخ أبا عبد الله ! فلتنصرني، أو يا شيخ عبد القادر الجيلاني ! انصرني أو اشف مريضي، أو يا شيخ..، أو يا سيدي البدوي ! أو يا سيدي الحسين ! أو ما أشبه هذا. كل هذا منكر وكله من الشرك الأكبر.\nفالواجب التنبه لهذا الأمر من الإخوان في العراق وغيرها، والواجب على أهل العلم وفقهم الله أن يوضحوا للناس حقيقة التوحيد وحقيقة الشرك، وأن ينكروا على العامة ما يقعون فيه من الشرك بالله عند قبور من يسمونهم بالأولياء.\nفالحاصل: أن هذه أمور عظيمة يجب على أهل العلم أن يهتموا بها وأن يعنوا بها، حتى ينقذوا العامة من الشرك، وحتى يوجهوهم إلى توحيد الله والإخلاص له ودعائه سبحانه ورفع الأيدي إليه جل وعلا، فهو الذي يشفي ويكفي سبحانه وتعالى، هو الشافي لعباده وهو المالك لكل شيء والقادر على كل شيء سبحانه وتعالى.\nوأما ما قد يقع لبعض الناس كونه يدعو الميت ويشفى، هذا قد يقع استدراجاً وابتلاءً وامتحاناً، والله هو الشافي سبحانه وتعالى، وقد يكون المرض من أسباب الشياطين، يسببون المرض للشخص للإنسان حتى إذا دعا الميت كفوا عنه ما قد فعلوا به.\nفالحاصل أن هذا ليس بحجة، كونه يأتي المريض إلى الميت فيدعوه ويستغيث فيشفى سريعاً هذا قد يكون استدراجاً وابتلاءً وامتحاناً حتى يمتحن صبره وإيمانه، فلا يغتر بهذا، وقد يصادفه القدر الذي قدره الله بالشفاء فيظنه من أسباب الميت، وقد يكون شيء من أسباب الشيطان، قد يفعل الشيطان بالإنسان شيء، يعني: يعمل معه عملاً يؤذيه ويضره ويمرض منه فإذا ذهب إلى الميت ودعاه وسأله كف عنه هذا الشيطان حتى يغريه بالشرك وحتى يوقعه في الشرك، وحتى يظن هذا الجاهل أن هذا من عمل الولي وأنه هو الشافي، وهذا من أقبح الغلط والمنكر، فالله هو الذي يشفي ويعافي سبحانه وتعالى.\nوالولي وغير الولي، لا يملكون لأنفسهم ضراً ولا نفعاً ولا موتاً ولا حياة ولا نشورا، مملوك لله سبحانه وتعالى، هو النافع والضار عز وجل، فينبغي التنبه لهذا الأمر. نعم.","link":"https://binbaz.org.sa/fatwas/5368/حكم-دعاء-الاموات-والاستغاثة-بهم-والنذر-لهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_060/06002.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":7941,"question":"يقول: في حضرموت يذهب الناس في وقت محدود من كل سنة إلى زيارة أحد القبور يقولون: إنه قبر النبي هود الكائن في شعب هود ، وهناك تتم الصلاة وتتم الزيارة والقراءة والبيع والشراء فما حقيقة ذلك، وهل قبر النبي هود هناك أم لا؟","title":"حكم زيارة القبور والطواف حولها ودعاء أصحابها والبناء عليها","answer":"الجواب: لا شك أن هود عليه الصلاة والسلام كان في الأحقاف وكان منزلهم هناك بعثه الله إلى قومه هناك، ولكن لا يعلم قبره ولا يدرى عنه، وليس هناك ما يدل على وجوده هناك، فالذين يقصدون قبراً هناك ليس معهم حجة على أنه قبر هود ولا يحفظ قبر معلوم للأنبياء سوى قبر نبينا محمد ﷺ فهو المحفوظ في المدينة، وهكذا قبر إبراهيم في المغارة في الشام في محله المعروف هناك من دون أن يعلم عينه لكنه موجود في المغارة المعروفة هناك في الخليل، وأما بقية الأنبياء فلا تعلم قبورهم لا هود ولا صالح ولا نوح ولا غيرهم كلهم لا تعلم قبورهم، فمن زعم أن قبر هود في بقعة معينة هناك وأشار إليه بأنه هذا المحل المعين فليس معه حجة وليس معه دليل، فقبور الأنبياء لا تعرف ما عدا قبر نبينا ﷺ وقبر إبراهيم عليه الصلاة والسلام.\nثم لو فرضنا أنه صحيح وأنه قبر هود فإنه لا يجوز شد الرحال إليه للسلام عليه أو الصلاة عنده أو غير ذلك، لكن لو مر إنسان به وهو يعلم أنه قبره وسلم عليه فلا بأس، كما يسلم على نبينا محمد عليه الصلاة والسلام، أما أن يزار بشد الرحال فلا، قال النبي ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام ومسجدي هذا، والمسجد الأقصى.\nفلا يشد الرحل لقبر أي أحد لا قبر هود ولا غيره، ثم لو فرض أنه مر عليه وزاره فليس له أن يصلي عند القبر، الصلاة لا تجوز عند القبور، الرسول ﷺ نهى عن ذلك قال: ألا وإن من كان قبلكم كانوا يتخذونن قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك، فالصلاة عند القبر اتخاذ له مسجد، فلا يجوز الصلاة عند القبور ولا اتخاذها مساجد.\nلو فرضنا أنه علم أنه قبر هود أو غيره فلا يجوز للمسلمين أن يشدوا الرحال من أجل زيارة القبور لا قبر هود ولا غيره، وليس للمسلمين أيضاً أن يصلوا عند القبور، ولا أن يتخذوا عليها مساجد؛ لأن الرسول زجر عن ذلك عليه الصلاة والسلام فقال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، قالت عائشة رضي الله عنها: يحذر ما صنعوا، وقال أيضاً عليه الصلاة والسلام: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك.\nفصرح ﷺ أنه ينهى عن اتخاذ القبور مساجد، والصلاة عندها اتخاذ لها مساجد، فلا يجوز لأي مسلم أن يفعل ذلك، فلا يشد الرحل إلى القبر -أي قبر كان- ولا يصلي عنده، أما إذا مر عليه أو صار في البلد وزاره للسلام على القبور فهذا سنة، النبي عليه السلام قال: زوروا القبور فإنها تذكركم الآخرة، لكن من دون شد رحل، ومن دون أن تتخذ مساجد ويصلى عندها أو تجعل محل قراءة والدعاء لا، يزورها ويسلم على المقبورين ويدعو لهم وينصرف.\nكان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، وفي لفظ: يرحم الله المستقدمين منا والمستأخرين، فهذه السنة أن تزار القبور من دون شد رحل، يسلم عليهم ويدعى لهم بالرحمة والمغفرة، ولك معهم، وفي زيارة القبور ذكرى وعبرة، فإن الزائر يتذكر الموت وما بعد الموت ويعتبر ويدعوه هذا إلى إعداد العدة، والتأهب إلى الآخرة، أما اتخاذها مساجد أو اتخاذها محلاً للدعاء والقراءة فلا، هذا لا يجوز وليست محلاً للدعاء ولا للقراءة ولا الصلاة، ولكن يسلم عليهم ويدعو لهم بعرض السلام، ويكفي ذلك كما علمنا الرسول ﷺ وبين لنا وحذرنا من خلاف ذلك، فشد الرحال للقبور منكر ولا يجوز، وهكذا الصلاة عندها واتخاذها مساجد والبناء عليها، واتخاذ القباب عليها كل هذا منكر.\nولا ينبغي لك أيها السائل ولا لغيرك أن يغتر بالناس، فإن أكثر الناس اليوم ليس عندهم بصيرة وإنما تحكمهم العادات وما ورثوه عن الآباء والأجداد، فاتخاذ المساجد على القبور اليوم في بعض الدول الإسلامية واتخاذ القباب عليها كله منكر كله من وسائل الشرك، النبي ﷺ نهى عن هذا قال: لعن اللهه اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، يحذرنا من أعمالهم.\nوكذلك نهى عن تجصيص القبور والقعود عليها والبناء عليها، فلا يجوز أن تجصص ولا أن يبنى عليها قبة ولا غيرها، ولا يتخذ عليها مسجد؛ لأن هذا كله مصادم لما جاء عنه عليه الصلاة والسلام؛ ولأنه أيضاً وسيلة من وسائل الشرك والغلو في القبور.\nفالواجب على رؤساء الدول الإسلامية الواجب عليهم أن يزيلوا ما على القبور من أبنية من قباب ومساجد وأن تكون القبور بارزة ليس عليها قبة وليس عليها مسجد، هذا هو الواجب في جميع الدول الإسلامية، الواجب عليهم جميعاً أن يبرزوا القبور وأن يزيلوا ما عليها من مساجد وقباب وأبنية طاعة للرسول صلى الله عليه وسلم، وامتثالاً لأمره، وعملاً بشرعه عليه الصلاة والسلام.\nوأيضاً في ذلك سد ذرائع الشرك وحسم موادها؛ لأن الناس إذا رأوا قبراً مشيداً معظماً بالقباب والبناء والفرش غلت فيه العامة وظنت أنه ينفع ويضر، وأنه يستجيب الداعي، وأنه يشفي المريض، وأنه يتوسط بينه وبين الله؛ فيقع الشرك بالله نعوذ بالله كما قد وقع لعباد القبور في الزمن الأول، فإنهم عظموا القبور وزعموا أن أهلها شفعاء عند الله، ودعوهم واستغاثوا بهم، وهذا هو الشرك الأكبر نسأل الله العافية.\nوهذا واقع اليوم في كثير من البلاد الإسلامية، واقع فيها هذا الغلو في القبور كما يقع في مصر عند قبر البدوي والحسين وغيرهما، وكما قد يقع في الشام عند قبر ابن عربي وغيره، وكما قد يقع في العراق عند قبر موسى الكاظم وأبي حنيفة وغيرهما، وكما قد يقع من بعض الجهال عند قبر النبي في المدينة عليه الصلاة والسلام، بعض الجهال من الحجاج والزوار، قد يقع منهم الشرك عند قبر النبي ﷺ يقول: يا رسول الله! اشف مريضي.. انصرني.. المدد المدد.. اشفع لي، وهذا لا يجوز، لا مع النبي ولا مع غيره من الأموات عليه الصلاة والسلام، وإنما هذا في حياته، في حياته يقال: اشفع لي يا رسول الله، يعني: ادعوا لنا، وهكذا يوم القيامة إذا قام الناس من قبورهم يأتيه المؤمنون ويسألونه أن يشفع لهم إلى الله، حتى يحكم بينهم وحتى يدخلوا الجنة، أما بعد الموت وقبل البعث في حال البرزح فلا، لا يطلب منه الشفاعة، ولا يجوز أن يطلب منه المدد ولا غوث ولا نصر على الأعداء؛ لأن هذا بيد الله سبحانه وتعالى، ليس بيد الأنبياء ولا غيرهم، بل النصر والشفاء للمرضى والغوث والمدد كله بيد الله سبحانه وتعالى.\nوهكذا قد يقع من بعض الجهلة عند قبر خديجة في المحلاة في مكة المكرمة إلا إذا لوحظوا ووجهوا وبين لهم ما يجب عليهم، فأنت -أيها السائل- ينبغي لك أن تحذر هذه المسائل وأن تكون على بينة، وأن تعلم أن القبور -لا قبر هود ولا غيره- لا يجوز أن تتخذ معابد مصلى مساجد، لا، ولا أن تدعى مع الله، ولا أن يستغاث بأهلها، ولا يطاف بقبورهم، ولا أن يبنى عليها قبة، ولا أن تفرش، ولا أن تطيب، كل هذا لا يجوز؛ لأنه من وسائل الشرك، ودعاء الميت وطلب الغوث منه والمدد وشفاء المريض هذا كله شرك بالله عز وجل. نعم.","link":"https://binbaz.org.sa/fatwas/5467/حكم-زيارة-القبور-والطواف-حولها-ودعاء-اصحابها-والبناء-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_067/06705.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":8004,"question":"من فؤاد محمد أحمد علي وردتنا هذه الرسالة تحمل هذه الأسئلة يقول: بسم الله الرحمن الرحيم. أولاً: هل يجوز للمسلم أن يكفر رجلاً مسلماً لا يصلي الصلوات المكتوبة، أو استهزأ بالقرآن، فهل يجوز أن نقول لمثل هؤلاء: كفار وهم يشهدون أن لا إله إلا الله وأن محمداً رسول الله؟","title":"حكم من أتى بناقض من نواقض الإسلام وهو ينطق بالشهادتين","answer":"الجواب: نعم أيها السائل! إذا وجد ممن يشهد أن لا إله إلا الله وأن محمداً رسول الله ما يقتضي كفره وجب أن يكفر؛ لأن المسلم يكفر بشيء من نواقض الإسلام، فليس من قال: أشهد أن لا إله إلا الله وأن محمداً رسول الله معصوماً من أن يقع منه مكفر، لا، بل متى وجد منه مكفر كفر به، فالذي يستهزئ بالقرآن أو يستهزئ بالرسول صلى الله عليه وسلم، أو يستهزئ بالصلاة، أو يستهزئ بالصيام أو بشيء مما شرعه الله يكون كافرا عند جميع العلماء، وقد ذكر العلماء ذلك في باب حكم المرتد، فينبغي لك إذا كنت طالب علم أن تراجع كلام أهل العلم، وإلا فلتعلم أن هذا كفر وضلال وردة عن الإسلام، كما قال الله جل وعلا: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ ۝ لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65-66].\nوهكذا الذي يترك الصلاة عمداً ولا يصلي هذا كافر أيضاً في أصح قولي العلماء، وإن لم يجحد وجوبها، متى تركها تهاوناً وتكاسلاً فإنه يكفر بذلك في أصح قولي العلماء؛ لقول النبي عليه الصلاة والسلام: رأس الأمر الإسلام وعموده الصلاة فمن ترك عمود الإسلام كفر؛ ولقوله عليه الصلاة والسلام فيما رواه مسلم في الصحيح: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح من حديث جابر رضي الله عنه؛ ولقوله عليه الصلاة والسلام أيضاً: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر هذا هو الصواب من أقوال أهل العلم.\nوقال بعض أهل العلم: إنه لا يكفر كفراً أكبر بل كفره كفر أصغر ما لم يجحد وجوبها، فإن جحد وجوبها كفر بالإجماع، أما ما دام يعلم أنها فريضة ولكن يغلب عليه الكسل والتساهل فلا يصلي فلا يكفر بذلك عند جمع من أهل العلم، ولكن يكون عاصياً معصية عظيمة أعظم من معصية الزنا وشرب الخمر ونحو ذلك، ويكون كافراً كفراً دون كفر، هذا قول جمع من أهل العلم.\nوالصواب: القول الأول أنه كافر كفراً أكبر؛ للأحاديث السابقة ولأدلة أخرى دلت على ذلك، فالواجب على أهل الإسلام الحذر من ذلك، والمحافظة على الصلوات والعناية بها، والعناية بأدائها في الجماعة هذا هو الواجب على كل مسلم، وليس قوله: أشهد أن لا إله إلا الله وأن محمداً رسول الله عاصماً من تكفيره إذا وجد منه ناقض من نواقض الإسلام، كما عرفت أيها السائل، فإن الاستهزاء بالدين كفر بالإجماع، ولو قال: أشهد أن لا إله إلا الله، وأن محمداً رسول الله. وهكذا لو أنكر البعث بعد الموت، أو أنكر الجنة أو أنكر النار كفر بإجماع المسلمين، ولو قال: أشهد أن لا إله إلا الله وأشهد أن محمداً رسول الله؛ لأن إنكاره لهذه الأمور تكذيب للرسول ﷺ، وتكذيب لله فيما أخبر به في كتابه، وهكذا لو سب الدين .. سب الله .. سب الرسول ﷺ كفر بالإجماع، ولو أتى بالشهادتين، وهكذا لو قال: إن صوم رمضان غير واجب، أو الزكاة مع توافر شروطها غير واجبة، أو الحج مع الاستطاعة غير واجب؛ كفر بالإجماع.\nفينبغي لك -أيها السائل- وينبغي لكل مسلم التنبه لهذه الأمور، والحذر من كل ما يسبب الكفر والخروج عن دائرة الإسلام وينبغي للمؤمن أيضاً أن يتفقه في دينه، وأن يتبصر وأن يحذر الوقوع فيما حرم الله عليه وهو لا يشعر، ولا حول ولا قوة إلا بالله! نعم.","link":"https://binbaz.org.sa/fatwas/5570/حكم-من-اتى-بناقض-من-نواقض-الاسلام-وهو-ينطق-بالشهادتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_075/07503.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":8018,"question":"سؤاله الثاني يقول: بعض الناس ينذرون النذور من الذبائح وغيرها للأمة والصحابة، فهل هذا جائز، وهل من الصحيح أن يأخذوا من النذور لأنفسهم، أفيدونا وفقكم الله وجزاكم الله عنا خيرا؟الشيخ: لعل قصده للأئمة؟المقدم: نعم.","title":"حكم تقديم النذور والذبائح للأموات","answer":"الجواب: النذور والذبائح التي تنذر للأموات أو للأنبياء أو غيرهم، هذه النذور والذبائح من المحرمات الشركية كونه ينذر لغير الله ذبيحة أو شمعاً أو صدقات أو ما أشبه ذلك سواء كان المنذور له نبياً أو ولياً إماماً أو غير إمام لا يجوز، النذر يكون لله والذبيحة تكون لله، قال الله تعالى: قُلْ إِنَّ صَلاتِي وَنُسُكِي [الأنعام:162] يعني: ذبحي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:162-163] ويقول سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:1-2] وثبت عن النبي عليه الصلاة والسلام أنه قال: لعن الله من ذبح لغير الله خرجه مسلم في الصحيح، وقال سبحانه: وَمَا أَنفَقْتُمْ مِنْ نَفَقَةٍ أَوْ نَذَرْتُمْ مِنْ نَذْرٍ فَإِنَّ اللَّهَ يَعْلَمُهُ [البقرة:270] يعني: فيجازيكم عليه، وقال النبي عليه الصلاة والسلام: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه.\nفالنذور عبادات فيها تعظيم الله وفيها تعظيم المخلوق إذا نذر له، كما أن الذبح عبادة يعظم بها الرب ويعظم بها المخلوق، فلا تليق إلا بالله سبحانه وتعالى، فليس له أن يذبح للجن ولا للأنبياء ولا للأولياء يتقرب إليهم بذلك يريد شفاعتهم أو شفاء مريضه، أو رد غائبه، أو قضاء دينه، أوما أشبه ذلك، لا للأنبياء، ولا للملائكة، ولا للجن، ولا للأولياء ولا لغيرهم، ما يكون الذبح إلا لله وحد يتقرب به إلى الله سبحانه وتعالى.\nوهكذا النذر كالذي يقول بعض الجهلة: إن شفى الله مريضي فللشيخ كذا وكذا، وللولي الفلاني كذا وكذا، ويقول: إن شفي مريضي فلك يا شيخ فلان كذا وكذا، يتقرب إليه؛ لأنه واسطة بزعمه في الشفاء، هذا من الشرك الأكبر لا يجوز، بل يجب على من فعل هذا أن يتوب إلى الله، وأن يقلع من هذا العمل السيئ، وأن يندم على ما مضى منه ومن تاب تاب الله عليه سبحانه وتعالى.\nوهذا غير الذبيحة التي يذبحها الإنسان كرامة للضيف أو أهله .. يأكلون هذا لا بأس، إذا ذبح ذبيحة للضيف الذي نزل به لإكرامه، فإكرام الضيف حق، كالذي ذبح ذبيحة ليأكلها وأولاده أو ليجعلوها موزعة على أيام، كل هذا لا بأس به، وهذا غير الضحية التي تذبح أيام النحر، هذه ذبيحة لله .. ضحية يتقرب بها إلى الله سبحانه وتعالى، فإذا ذبحها عنه أو عن أبيه أو عن أمه، ما يقال: إنه ذبحها لغير الله، هذه ذبحها لله يتقرب بها إلى الله ويريد ثوابها له أو لأهل بيته أو له ولأهل بيته، هذا لا حرج فيه، وإنما المنكر أن يتقرب بالذبيحة لغير الله، يذبح للنبي أو الولي أو للجن أو للملائكة يقصد أنه بهذه الذبيحة يتوسط بهم في قضاء حاجاته .. في شفاعته .. الله ليشفى مريضه، ليرد غائبه ليشفى هو من مرضه، يرى أن هذه العبادة تكون سبباً لوساطتهم له وتقريبهم له إلى الله سبحانه وتعالى. نعم.","link":"https://binbaz.org.sa/fatwas/5585/حكم-تقديم-النذور-والذباىح-للاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_077/07703.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":8245,"question":"هنا رسالة باعثها يقول: لدينا مسجد نصلي فيه الفريضة والسنة، والإمام يقول عندنا: إن الشيخ عبد القادر يقول: إن شاء الله إن فلان يموت. فيموت في ساعته، كيف ترون هذا سماحة الشيخ، وبم توجهون المسلمين في ذلك المكان؟","title":"حكم القول بأن الأموات يعلمون الغيب","answer":"الجواب: الشيخ عبد القادر من جنس سائر أهل العلم لا يعلم الغيب لا في حياته ولا بعد وفاته، ومن ادعى أن الشيخ عبد القادر يعلم الغيب أو يتصرف في الكون، أو يغيث السائلين فهو كافر نعوذ بالله من ذلك؛ لأن الأموات قد انقطعت أعمالهم كما قال النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له ولأنهم مرتهنون بأعمالهم، وليس لهم تصرف في أمور الناس، بل الله المتصرف فيها جل وعلا.\nفمن زعم أن النبي ﷺ أو الشيخ عبد القادر أو البدوي أو الحسين أو علي بن أبي طالب أو غيرهم يتصرفون في الكون، ويعطون من يشاءون ويمنعون من يشاءون، أو أنهم يعلمون الغيب ومن يموت ومن لا يموت هذا كافر بالله عز وجل نعوذ بالله؛ لأن الله يقول سبحانه: قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ [النمل:65]، ويقول سبحانه لنبيه ﷺ: قُلْ لا أَمْلِكُ لِنَفْسِي نَفْعًا وَلا ضَرًّا إِلَّا مَا شَاءَ اللَّهُ وَلَوْ كُنتُ أَعْلَمُ الْغَيْبَ لاسْتَكْثَرْتُ مِنَ الْخَيْرِ وَمَا مَسَّنِيَ السُّوءُ إِنْ أَنَا إِلَّا نَذِيرٌ وَبَشِيرٌ لِقَوْمٍ يُؤْمِنُونَ [الأعراف:188] فبين سبحانه على لسان نبيه ﷺ في كتابه العظيم أنه بشير ونذير وليس يعلم الغيب: إِنْ أَنَا إِلَّا نَذِيرٌ وَبَشِيرٌ [الأعراف:188] يعني: ما أنا إلا نذير وبشير.\nفمن زعم أن الشيخ عبد القادر يعلم أن فلان يموت اليوم أو غداً فهذا كله باطل وكله منكر، وكله من وحي الشياطين لهذا الشخص، ويكذب على عبد القادر ، وإنما هذه الشياطين تقول له، أما عبد القادر فلا يتكلم ولا يقول له شيئاً وهو مرتهن بعمله، قد انقطع عمله.\nفالحاصل: أن هذا الشيء من وحي الشياطين إلى هؤلاء الضلال، توحي إليهم ما يسترقون من السمع، قد يكون يسمعون أن فلان يموت بما استرقوه من السماء، فيوحونه إلى بعض أوليائهم فيخبرون بذلك، كما قال النبي ﷺ: أنهم قد يستمعون كلمة فيلقونها بين الناس، ثم يصدقهم الناس بما سمعوه منهم من هذه الكلمة التي صدقوا فيها وهي التي سمعوها من السماء من الملائكة حين استرق السمع، ثم يصدقونهم بكل كلامهم الكذب من أجل الكلمة التي صدقوا فيها.\nفالحاصل: أن هذا ليس من عبد القادر وليس من الأموات، ولكنه مما توحيه الشياطين إلى أوليائها من الإنس الأحياء، فيكذبون ويقولون: هذا من عبد القادر أو هذا من الرسول ﷺ أو هذا من فلان، أو هذا من فلان. كله كذب وافتراء ولا صحة له، وقد يكون الشيطان كذب عليهم، وقال لهم: إن عبد القادر قال له كذا، أو قال: أنا عبد القادر ، أو قال: أنا الرسول ﷺ، يكذب عليهم، كل هذا قد يقع، فيأتي الشيطان ويتصور في غير صورة النبي ﷺ؛ الشيطان ما يستطيع يتصور بصورته عليه الصلاة والسلام ولا يتمثل بصورته، لكن قد يأتي إلى بعض الناس بغير صورة النبي عليه الصلاة والسلام، ويزعم أنه النبي ﷺ أو أنه الخضر أو أنه عبد القادر أو أنه علي أو أنه عمر أو فلان أو أنه البدوي .. إلى غير هذا من كذب الشياطين.\nفلا يجوز تصديقهم في هذه الأمور أبداًَ ولو وافق قولهم، قد يكون هذا الذي وافقوا فيه مما سمع من السماء مما استرقته الشياطين وأوحته إلى أوليائها، نسأل الله العافية. نعم.","link":"https://binbaz.org.sa/fatwas/6046/حكم-القول-بان-الاموات-يعلمون-الغيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09706.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":8380,"question":"الرسالة التالية من مكة المكرمة، بعث بها أخونا محمد عبد الحميد محمد حاتم من لواء إب، أخونا يقول: يوجد في قريتنا امرأة تدعي بأن روحها تسرح في المقابر ليلة كل خميس وجمعة أثناء منامها، وتقول: إنها تنظر موتى المسلمين، و: كُلُّ امْرِئٍ بِمَا كَسَبَ رَهِينٌ [الطور:21] ومع ذلك فإنها تنظر الرجل أو المرأة الذين كانوا يعيشون على ظاهر الأرض، وانتقلوا إلى عالم الآخرة، فإن كان الرجل في الدنيا قاطعاً للصلاة أو آكلاً لأموال الناس بالباطل، فإن هذه المرأة تنظره وهو يعذب في الآخرة، والرجل الصالح في الدنيا تقول: إنه في الآخرة مع الصالحين، علماً أن هذه المرأة تزعم وتقول: إنها محملة أمانة من الموتى لأهلهم في الدنيا أن يسددوا عنهم ديونهم أو السرقات، فإنهم يعذبون بها في قبورهم، وفعلاً فإن أهل الميت يقضون ديون موتاهم، وفي المرة الثانية تأتي هذه المرأة وقد خفف عنهم العذاب كما تزعم، سؤالي: أفتونا عن رأي هذه المرأة وغيرها من النساء اللائي يدعين هذه الأقاويل، هل هو حقٌ ما ذكر في سؤالي أم أنه كذب وخرافات، جزاكم الله خيرا؟","title":"حكم تصديق من يدعي رؤية الموتى المنعمين والمعذبين في المنام","answer":"الجواب: هذا وأمثاله لا يعتمد عليه، ولا يجوز تصديقه، ولا الاعتبار به من كل الوجوه، فإنها قد ترى بعض الرؤيا، وتصدق في بعض الرؤيا، وقد ترى رؤيا غير صادقة، وقد تكذب في رؤياها، وقد يخيل إليها الشيطان أشياء لا صحة لها، ولا وجود لها.\nفالحاصل أن هذه المرائي التي تدعيها، يدعيها بعض الناس، أو يدعيها بعض النساء، كل ذلك لا يجوز الاعتماد عليه، لا في قضاء الديون ولا في السرقات ولا في غير ذلك، ولكن إذا كانت امرأةً صالحة قد ترى مرائي صالحة، وتصدق فيها، فمثل ما أخبر النبي ﷺ: الرؤيا الصالحة جزء من ستةٍ وأربعين جزءاً من النبوة ويقول ﷺ: ذهبت النبوة وبقيت المبشرات، وهي الرؤيا الصالحة يراها المسلم أو ترى له والرؤيا الصالحة من الرجل الصالح لها شأن ولها قيمة، لكن لا يعتمد عليها في تشريع أمور، في إيجاب أمور، أو تحريم أمور، أو تكليف أهل الميت بكذا، أو تحميلهم كذا، أو ما أشبه ذلك، لا؛ لأن هذه المرائي قد تصدق وقد تكذب، وقد يكون الرائي صالحاً، وقد يكون غير صالح، وقد يكون لبس عليه، وقد تأتيه الشياطين فتخيل إليه أشياء، يزعم أنه رآها في النوم.\nفالمقصود أن هذه المرائي وأشباهها، لا يعول عليها، ولا يعتمد عليها في أن فلاناً يعذب، أو فلان ينعم، أو فلان عليه دين يوفى عنه، أو فلان ليس عليه دين، أو ما أشبه ذلك، لا.\nلكن أهل الميت ينبغي لهم أن يراعوا ميتهم، إن كانوا يعلمون عليه شيئاً من الديون أوفوا من تركته، أو من مالهم إذا أعانهم الله على ذلك، وهذا عمل طيب، وإذا كان قد سرق سرقة من الناس يعرفونها، أدوها عنه من ماله إن كان له مال، وإن كان ما له مال وأدوا عنه، فجزاهم الله خيراً.\nالمقصود أن أهل الميت يلاحظون ميتهم، فإن كان عليه ديون أو حقوق للناس أدوها من تركته، أو أدوها من مالهم إن كان ما عنده تركة، واحتسبوا الأجر في ذلك، أو عنده مال ولم يسمح الورثة، فإذا أدى عنه بعض أحبابه، وبعض أصحابه احتياطاً، فهذا حسن، وأما الاعتماد على هذه المرائي فلا يعتمد عليها.","link":"https://binbaz.org.sa/fatwas/6229/حكم-تصديق-من-يدعي-روية-الموتى-المنعمين-والمعذبين-في-المنام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_115/11504.mp3","categories":["نواقض الإسلام","الرؤى والمنامات"]},{"id":8411,"question":"أيضاً يسأل سماحة الشيخ ويقول: هل رؤية الرسول ﷺ في المنام على هيئة ما تعتبر بشارة في حق الرائي أو أنه من أهل الجنة؟","title":"هل رؤية النبي في المنام دليل نجاة وبشارة؟","answer":"الجواب: إذا رآه على صورته كما تقدم فهي خير إن شاء الله، ولكنها لا تتضمن نجاةً ولا سعادةً ولا تقوى؛ فقد رآه في حياته ﷺ الكفرة والمنافقون ولم تنفعهم هذه الرؤية، رآه أبو جهل ومات على الكفر بالله، وقتل يوم بدر، ورآه عتبة بن ربيعة وشيبة بن ربيعة ...... وقتلا على كفرهما، ورآه عمه أبو طالب ومات على كفره، ورآه عمه أبو لهب ومات على كفره، ورآه عبد الله بن أبي بن سلول رأس المنافقين ومات على كفره، فرؤيته في اليقظة لا تتضمن هدايةً ولا إسلاماً، ولا تتضمن سعادةً لأهلها، إلا إذا آمنوا به وصدقوه واتبعوه عليه الصلاة والسلام.\nهكذا في المنام من باب أولى، من رآه في المنام وهو مؤمن متقي يرجى له الخير إذا رآه على صورته.\nأما من رآه ولم يؤمن بشريعته، ولم ينقد لما جاء به؛ فإن هذه الرؤية لا تنفعه بل هي حجة عليه في اليقظة والنوم، كما رآه أولئك الكفار في حياته صلى الله عليه وسلم فلم يوفقوا للإيمان به، فصاروا أشقياء نعوذ بالله من ذلك، فهكذا من رآه في النوم ولم يؤمن به، ولم يتبع ما جاء به؛ فإنها لا تنفعه هذه الرؤية بل تكون حجةً عليه. نعم.","link":"https://binbaz.org.sa/fatwas/6295/هل-روية-النبي-في-المنام-دليل-نجاة-وبشارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_118/11802.mp3","categories":["نواقض الإسلام","الرؤى والمنامات"]},{"id":8423,"question":"ما حكم الإسلام في الرجل المسلم الذي يسب الدين؟","title":"حكم من سب الدين","answer":"الجواب: سب الدين من أعظم الكبائر، ومن نواقض الإسلام، نسأل الله العافية والسلامة، فمن سب دينه سب الإسلام، أو سب نبي الإسلام، أو سب رسولاً من الرسل، ارتد عن الإسلام نعوذ بالله، فإذا لعن الرسول أو لعن الإسلام، أو سب الإسلام بأنواع السب بأن قال: الإسلام دين جامد، أو دين ناقص، أو دين أفيون الشعوب، أو أشباه ذلك من التنقصات؛ فإن هذا يسمى: سباً، ويكون صاحبه مرتداً عن الإسلام، يستتاب فإن تاب وإلا قتل، وذهب بعض أهل العلم إلى أنه لا يستتاب بل يقتل مطلقاً كمن سب الله وسب رسوله عليه الصلاة والسلام.\nفالمقصود أن السب لله أو لرسوله أو لدينه ردة عن الإسلام، وقد قال الرسول ﷺ: من بدل دينه فاقتلوه فالواجب على من فعل ذلك أن يبادر بالتوبة، والرجوع إلى الله، والإنابة إليه، والندم على ما صدر منه، والاستكثار من العمل الصالح؛ لعل الله يتوب عليه.\nأما ولاة الأمور فالواجب عليهم استتابته، وتأديبه على ما فعل، وتوبيخه على ذلك، وتأديبه بما يردعه وأمثاله عن ذلك، أما قبول التوبة فهي محل نظر وخلاف بين أهل العلم، فمن رأى قبول توبته فله وجه، ومن رأى قتله وعدم قبول توبته فله وجه؛ ردعاً للناس عن التساهل بهذا الأمر وحمايةً لدين الله؛ وحمايةً لجنابه سبحانه؛ وحمايةً لجناب رسوله عليه الصلاة والسلام، وبكل حال فالسب ردة عن الإسلام، أما كونه تقبل توبته بحكم الظاهر أم لا تقبل فهذا محل خلاف بين أهل العلم، وأما فيما بينه وبين الله فإنها تقبل توبته، إذا صدق في توبته ورجع إلى الله وأناب إليه، وندم على ما مضى منه؛ فإن الله يقبلها منه؛ لعموم الأدلة الدالة على قبول التوبة، فهو سبحانه الذي يقبل التوبة عن عباده، وهو القائل جل وعلا: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] فالتوبة لها شأن عظيم فإذا فعلها العبد صادقاً نادماً مقلعاً تاركاً لما فعله من الذنب كبيراً أو صغيراً، واستقام على ذلك فالله يقبلها منه سبحانه وتعالى، لكن هل يقبلها ولي الأمر في الدنيا ولا يقتله؟ هذا هو محل الخلاف، فمن.. رأى عدم قبول توبة الساب قال: لأن السب عظيم؛ ولأن قبولها قد يجرئ الناس على التساهل بها، فلهذا رأى جمع من أهل العلم أنه يقتل، ولا تقبل توبته من جهة الحكم، حسماً لمادة هذا الشر؛ وحمايةً لدين الله؛ وحمايةً لرسوله؛ وحمايةً لجنابه سبحانه عن سب السابين، وشتم الشاتمين، وسخرية الساخرين، والله المستعان، ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: جزاكم الله خيرا، لابد أيضاً لسماحة الشيخ من كلمة للناس عامة حتى لا يقعوا في مثل هذه الكبيرة؟\nالشيخ: نعم، سب الدين يقع من كثير من السفهاء، فالواجب على جميع المسلمين أن يحذروا ذلك، وأن يصونوا ألسنتهم عما يتعلق بسب الدين، أو سب الله، أو سب رسوله، أو سب الجنة، أو غير هذا مما شرعه الله سبحانه وتعالى، وهكذا الاستهزاء، لا يجوز الاستهزاء، لا بشرع الله، ولا بالجنة، ولا بالنار، ولا بالله، ولا برسوله، ولا بشيء مما شرعه الله، ولا باللحية، ولا بغير هذا مما شرعه الله.\nيجب أن يصون الإنسان لسانه، وأن تصون المرأة لسانها عن كل ما حرم الله عز وجل من سب، أو شتم، أو استهزاء، قال الله : قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ [التوبة:65]  ۝  لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:66].\nولما بلغه صلى الله عليه وسلم أن شخصاً قتل جاريته كانت تسب النبي ﷺ، فقتلها لما استتابها فأبت قتلها، قال عليه الصلاة والسلام: ألا اشهدوا إن دمها هدر لأنها سبت الرسول عليه الصلاة والسلام.\nفالمقصود أن الواجب على أهل الإسلام من الرجال والنساء أن يحذروا هذا الأمر، هذه الجريمة العظيمة، وأن يحذروها الناس، وأن يصونوا ألسنتهم عن سب الله ورسوله، أو الاستهزاء بالله ورسوله، أو الاستهزاء بشرعه، أو بما أخبر به عن الآخرة، يجب على أهل الإسلام أن يصونوا ألسنتهم وأن يحفظوها عن كل ما يتعلق بالسب والشتم والاستهزاء، رزق الله الجميع العافية والسلامة.","link":"https://binbaz.org.sa/fatwas/6307/حكم-من-سب-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_118/11814.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":8437,"question":"أخونا يقول: توجد في جنوب الأردن المياه المعدنية، والتي يطلق عليها: برك سليمان بن داود، فيقصدها الناس للاستجمام والشفاء، ويحضرون معهم الذبائح لذبحها حال وصولهم، فما حكم ذبح مثل هذه الذبائح، أفيدونا بارك الله فيكم، وجزاكم خير الجزاء؟","title":"حكم الاستشفاء بماء معين والذبح عنده","answer":"الجواب:\n\n إذا كان الماء المذكور مجربًا معروفًا، ينفع في بعض الأمراض فلا بأس بذلك؛ لأن الله جعل في بعض المياه فائدة لبعض الأمراض، فإذا عرف بالتجارب أن هذا الماء ينفع من بعض الأمراض المعينة، كالروماتيزم أو غيره فلا بأس في ذلك.\n\nأما الذبائح ففيها تفصيل: فإن كانت عندما تذبح من أجل حاجتهم وأكلهم ونحو ذلك، وما يقع لهم من ضيوف فلا بأس بذلك، أما إن كانت تذبح لأجل شيء آخر، لأجل التقرب إلى الماء أو التقرب إلى الجن، أو التقرب إلى الأنبياء أو ما أشبه ذلك من الاعتقادات الفاسدة فهذا لا يجوز؛ لأن الله يقول سبحانه وتعالى: قُلْ إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ  ۝  لَا شَرِيكَ لَهُ [الأنعام: 162، 163].\n\nويقول سبحانه: إنَّا أَعْطَيْنَاكَ الْكَوْثَرَ  ۝  فَصَلِّ لِرَبِّكَ وَانْحَر [الكوثر: 1، 2ٍْ] فالذبح لله والنسك لله والصلاة لله، فليس لأحد أن يذبح للجن أو للكوكب الفلاني، أو النجم الفلاني أو الماء الفلاني، أو النبي الفلاني، أو أي شخص، بل التقرب كله لله وحده سبحانه وتعالى بالذبائح والصلوات وسائر العبادات، يقول الله تعالى: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة: 5]، ويقول سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ [البينة: 5]، ويقول سبحانه: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ  ۝  أَلَا لِلَّهِ الدِّينُ الْخَالِصُ [الزمر: 2، 3].\n\nوالذبح من أهم العبادات ومن أفضل العبادات، فإذا كان المقصود من هذه الذبائح الأكل؛ لأنهم جالسون هناك فيذبحونها للأكل والحاجة فلا بأس، وأما إن كان الذبح لأمر آخر ولقصد آخر؛ إما لأجل المكان، أو مسألة الماء من أجل الماء، أو من أجل الجن أو من أجل ملك من الملائكة يقصدونه، أو نبي من الأنبياء يقصدونه، ويتقربون إليه أو أي شخص كان، أو أي كوكب أو أي صنم، أو أي وثن هذا كله شرك بالله، فيجب الحذر والله المستعان، ويقول الرسول صلى الله عليه وسلم: لعن الله من ذبح لغير الله.\n\nخرجه الإمام مسلم في صحيحه من حديث علي أمير المؤمنين رضي الله عنه.","link":"https://binbaz.org.sa/fatwas/6321/حكم-الاستشفاء-بماء-معين-والذبح-عنده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_120/12002.mp3","categories":["الطب والتداوي","نواقض الإسلام"]},{"id":8512,"question":"أخونا يسأل سؤالًا طويلًا أرجو أن يتسع له بقية وقت هذه الحلقة، يقول: يقوم بعض الناس بوضع نقود ليست بسيطة على القبور بما يسمونها قبور الأولياء، ثم تجمع هذه النقود ويصرفونها في تعمير القباب وزخرفتها ووضع الأنوار عليها واستعمال مكبرات الصوت على تلك القباب لنشر دعايات ذلك الولي، كما يؤدون هناك صلاة الفريضة أحياناً داخل المقابر حول ذلك الولي، فما حكم الدين الإسلامي في مثل هذه الأفعال أفادكم الله؟","title":"حكم دفع الأموال لغرض بناء القباب على القبور وزخرفتها","answer":"الجواب: أولاً: التقرب بالنقود أو بالطعام أو بالخبز إلى القبور هذا منكر ومن الشرك الأكبر؛ لأنها تقرب إليهم وعبادة لهم، الصدقات يتقرب إليهم يرجو بهذا فضلهم وثوابهم وبركتهم مثل ما لو ذبح لهم، ومثل لو صلى لهم؛ لأنه إنما تقرب بذلك لأنه يرى أنهم يصلحون لهذا الأمر، وأنه يتقرب إليهم بالصدقات أو بالذبائح أو بغير ذلك حتى ينفعوه، حتى يشفعوا له، حتى يبرئوا مريضه، وحتى يعطوه الولد وإلى غير ذلك.\nوأما ثانياً: فاتخاذ القباب على القبور أيضاً منكر، لا يجوز البناء عليها مطلقاً، بل يجب أن تبقى مكشوفة ليس عليها بناء، لقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد ولما ثبت في الصحيح عن جابر  قال: نهى رسول الله ﷺ عن تجصيص القبور وعن القعود عليها، وعن البناء عليها فالرسول ﷺ نهى عن البناء عليها، ونهى عن الكتابة عليها، فالواجب أن لا يكتب عليها وأن لا يبنى عليها، لا قبة ولا غيره.\nثالثاً: الصلاة عند القبور لا تجوز، الرسول ﷺ لعن من اتخذها مساجد، وقال الرسول ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك رواه مسلم في الصحيح، فنهاهم أن يتخذوها مساجد، ومن صلى عند قبر فقد اتخذه مسجداً، ولو ما بنى عليه قبة، ولو ما بنى عليه مسجد، ما دام يصلي عند القبور أو بين القبور فإنه بهذا يتخذها مسجداً؛ لأن الرسول عليه السلام قال: جعلت لي الأرض مسجداً وطهوراً فمن صلى في محل اتخذه مسجداً؛ ولهذا لا يصلى في المحل النجس، ولا يصلى بين القبور، فإذا صلى عند القبور أو إلى القبر أو في طرف المقبرة كل هذا اتخاذ لها، فالواجب الحذر من ذلك.","link":"https://binbaz.org.sa/fatwas/6583/حكم-دفع-الاموال-لغرض-بناء-القباب-على-القبور-وزخرفتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_127/12708.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":8524,"question":"له سؤال ثالث في رسالته يقول: عندنا في بلدتنا إذا كان الرجل ممن يعتقد فيهم الصلاح فيجعلون الخلافة لابنه من بعده، وإذا مات هذا الابن يجعلوا خليفة بدله من أبنائه، وهكذا يتوارثونها خليفة بعد خليفة، وكل منهم يعتقدون فيه الصلاح والبركة، ويقبل الناس أيديهم، وتأتيهم الأموال والنذور لطلب البركة، فما حكم الشرع في ذلك؟","title":"حكم التبرك بالأشخاص","answer":"الجواب: هذا من عمل بعض الصوفية المخربين، وهذا لا أصل له في الشرع، بل هذا من الخرافات التي أحدثها بعض أهل التصوف ، جعلوا خليفة وجعلوا ابنه يقوم مقامه وهكذا، كل هذا لا أصل له، واتخاذ بعض الناس للبركة هذا لا أصل له، ولا يجوز اتخاذ أحد للتبرك به، بل هذا من المنكرات ومن وسائل الشرك الأكبر، فإن البركة من الله ، هو الذي يأتي بها ، ولا تطلب البركة من غيره، فطلبها من زيد أو من عمرو أن يعطيك البركة هذا لا أصل له، بل هذا من الشرك، إذا طلبها منه واعتقد أنه يبارك في الناس وأنه يعطي البركة هو، هذا شرك أكبر نعوذ بالله، وأما إن ظن أن خدمته أو طاعته فيها بركة؛ لأنه من الصالحين ومن الأخيار، فيرجو بهذا الثواب إذا أطاعه أو ساعده في شيء، فهذا يختلف، إن كان المطاع عالم من علماء المسلمين، أو من العباد والأخيار الذين هم معروفون بالاستقامة على طاعة الله ورسوله فساعده لله بأن قضى حاجته، بأن زاره لله يسلم عليه؛ لأنه من أهل الصلاح، يزوره لله فقط، لا لطلب البركة بل لله يزوره، أو يعوده إذا مرض، هذا شأن المسلمين، هذا مستحب من باب التزاور، ومن باب عيادة المرضى، من باب زيارة الإخوة في الله، هذا حق، أما لطلب البركة فلا يجوز؛ لأنه لا أصل لهذا، وإنما هذا في حق النبي ﷺ، هو الذي جعله الله مباركاً فلا بأس أن يقصد لطلب البركة من مائه.. من عرقه.. من شعره، الله جعل فيه بركة عليه الصلاة والسلام، ولما حلق رأسه في حجة الوداع وزعه بين الصحابة، وكان يعطي لهم وضوءه، فيتبركون بوضوئه لما جعل الله فيه من البركة، هذا خاص به صلى الله عليه وسلم وليس لغيره، فينبغي لأهل الإسلام أن يعرفوا هذا، وأن يحذروا هذه الخرافات التي فعلها أصحاب التصوف، وهذه الخلافات التي جعلوها: هذا خليفة هذا .... هذا كله لا أصل له، ولا ينبغي أن يتخذ هذا الشيء، ولا أن يعطى هدايا ونذور بهذا المعنى، أما إذا أعطى أخاه الفقير مساعدة هدية؛ لأنه يحبه في الله، أو لأنه فقير هذا لا بأس به، أما لاعتقاد البركة، أو أنه خليفة الشيخ الفلاني، خليفة التيجاني ، أو فلان الشاذلي ، أو فلان كذا، هذه لا أصل لها، هذه باطلة، وهذه أمور منكرة، ووسيلة للشرك نعوذ بالله. نعم.","link":"https://binbaz.org.sa/fatwas/6607/حكم-التبرك-بالاشخاص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_204/20410.mp3","categories":["نواقض الإسلام","التبرك وأنواعه"]},{"id":8545,"question":"وهذه رسالة وردتنا من الأخوين (ص. م. ح) وأحمد عبد ربه سالم ، يمنيي الجنسية مقيمين في الرياض، يقولان في رسالتهما: قال الله تعالى في كتابه الكريم في سورة المائدة: يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالأَنصَابُ وَالأَزْلامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ [المائدة:90]  ما معنى الأنصاب والأزلام؟","title":"معنى الأنصاب والأزلام","answer":"الجواب: الأنصاب والأزلام، الأنصاب: شيء ينصب يذبح عليه المشركون ويتقربون لأصنامهم بالذبائح، والأزلام: أشياء يقسمون بها، أشياء يقال لها: السهام، من أنواع الخشب يكتبون عليها افعل ولا تفعل، والثالث يكتبون عليه غفل ما عليه شيء، لا يكتب عليه شيء، فإذا أرادوا أن يسافروا أو يفعلوا شيئاً عندهم فيه اشتباه أجالوها، أعطوها أحد يعني: يخرجوها واحداً واحداً، أو هو نفسه يخرجها واحداً واحداً من محلها، فإن خرج (افعل) نفذ، وإن خرج (لا تفعل) ترك، وإن خرج الغفل الذي ما فيه شيء أعاد إجراءها، خلطها ثم أعاد إخراجها، فإن خرج (افعل) فعل، وإن خرج (لا تفعل) ترك، وإن خرج الغفل أعادها وهكذا، هذه سنة لهم وطريقة جاهلية، فشرع الله سبحانه وتعالى لعباده بدل استعمال الأزلام صلاة الاستخارة، فالمشروع للمؤمن إذا هم بأمر يشكل عليه كالزواج أو السفر أو ما أشبه ذلك صلى ركعتين، يصلي ركعتين ثم يستخير الله جل وعلا ويدعو بدعاء الاستخارة المعروف الثابت عن النبي ﷺ، والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/6627/معنى-الانصاب-والازلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_205/20518.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":8606,"question":"هذه رسالةٌ وردتنا من السائل قدري عبدالمنعم، مصري يعمل بالمملكة، يقول: سمعنا في الحديث: لعن الله قومًا اتخذوا قبور أنبيائهم مساجد، ويحدث في كثيرٍ من الأقطار الإسلامية اتخاذ الأضرحة والمقامات لأولياء الله، وعندما ننهى عن ذلك يحتجون بأن قبر النبي ﷺ موجودٌ بمسجده في المدينة المنورة، مما يُحدث عندنا بعض الإشكال.أفيدونا أفادكم الله.","title":"ما الرد على شبهة وجود قبر النبي داخل المسجد؟","answer":"الجواب: لا ريب أن الرسول ﷺ قال: لعن الله اليهود والنصارى؛ اتخذوا قبور أنبيائهم مساجد، قالت عائشة رضي الله عنها: يُحذِّر ما صنعوا. رواه الشيخان: البخاري ومسلم في \"الصحيحين\". وقال عليه الصلاة والسلام: ألا وإن مَن كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك أخرجه مسلمٌ في \"صحيحه\".\nوهذه الأحاديث وما جاء في معناها كلها واضحةٌ في تحريم اتِّخاذ المساجد على القبور، أو الصلاة عندها، أو القراءة عندها، أو نحو ذلك، ولكن بعض الناس قد تشتبه عليه الأمور، ولا يعرف الحقيقة التي جاء بها المصطفى عليه الصلاة والسلام، فيعمل ما يعمل من البناء على القبور، واتخاذ المساجد عليها؛ جهلًا منه، وقلة بصيرةٍ.\nوأما ما يتعلق بقبر النبي ﷺ فلم يُدفن في ... بالمسجد ﷺ، الرسول ﷺ دُفن في بيت عائشة، ثم وُسِّع المسجد في عهد الوليد بن عبدالملك في آخر القرن الأول، فأُدخلت الحجرة في المسجد، وهذا غلطٌ من الوليد لما أدخلها، وقد أنكر عليه بعض مَن حضره من هناك في المدينة، ولكن لم يُقدر أنه يرعوي لمَن أنكر عليه.\nفالحاصل أن قبر النبي ﷺ كان في البيت -في بيت عائشة رضي الله عنها-، ثم أُدخلت الحجرة -البيت- في المسجد بسبب التوسعة، فلا حُجةَ في ذلك. ثم إنه من فعل الأمير -أمير المؤمنين الوليد بن عبدالملك- وقد أخطأ في ذلك لما أدخله في المسجد. فلا ينبغي لأحدٍ أن يحتج بهذا العمل، فالذي فعله الناس اليوم من البناء على القبور واتخاذ المساجد عليها كله منكرٌ، مخالفٌ لهدي النبي صلى الله عليه وسلم.\nفالواجب على ولاة الأمور من المسلمين إزالته، أي بلدٍ فيها ولي أمرٍ من أمراء المسلمين الواجب عليه أن يُزيل هذه المساجد التي على القبور، وأن يسير على السنة، وأن تكون القبور في الصحراء بارزةً، ليس عليها بناءٌ: لا قباب، ولا مساجد، ولا غير ذلك، كما كانت القبور في عهد النبي ﷺ -في البقيع وغيره- بارزةً، ليس عليها شيءٌ، وهكذا قبور الشهداء -شهداء أحد- لم يكن عليها شيءٌ. فالحاصل أن هذا هو المشروع: أن تكون القبور بارزةً، ضاحيةً، ليس عليها بناءٌ، كما كان في عهد النبي ﷺ وعهد السلف الصالح.\nأما ما أحدثه الناس من البناء فهو بدعةٌ ومنكرٌ، لا يجوز إقراره، ولا التأسي به؛ ولهذا وقع الشرك لما وجد العامَّةُ والجهَّالُ القبور مُشيَّدًا عليها المساجد والقباب، ومُعظَّمة، ومفروشة، ومُطيَّبة؛ ظنوا أنها تقضي حوائجهم، وتشفي مرضاهم، وتنفعهم؛ فدعوها، واستغاثوا بها، ونذروا لها؛ فوقع الشرك -نعوذ بالله- بأسباب ذلك. فالغلو في القبور كله شرٌّ؛ ولهذا قال عليه الصلاة والسلام: إياكم والغلو في الدين، فإنما أهلك مَن كان قبلكم الغلو في الدين، نسأل الله السلامة والعافية. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6749/ما-الرد-على-شبهة-وجود-قبر-النبي-داخل-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_210/21015.mp3","categories":["مسائل متفرقة في العقيدة","نواقض الإسلام","التاريخ والسيرة"]},{"id":8613,"question":"له سؤال ثان يقول فيه: عندنا في بعض المناطق الريفية أناس يعتقدون في الأولياء حسب قولهم، فإذا مرض أي واحد منهم يقطعون من أذن الماعز أو الظأن ويقولون: يا فلان! أي: يدعون الميت أن يشفي هذا المريض، ويذبحون الذبائح ويطلبون أحد القراء يقرأ لهم المولد بعد أكل هذه الذبائح، وبعضهم يذبحون في المقابر، وبعضهم في بيوتهم من أجل هذا الولي الميت بقولهم: أحي المريض، وقد التقيت ببعض هؤلاء الناس وعرفتهم أن هذا العمل غير جائز وأن الله هو الضار والنافع، وأنه هو المحيي والمميت، وهو على كل شيء قدير، فما حكم هؤلاء في هذا الاعتقاد، وما حكم الذين يقرءون لهم الموالد، وما حكم من أكل من هذه الذبائح، أفيدونا وجزاكم الله خير؟","title":"حكم دعاء الأموات والاستغاثة بهم والذبح لهم","answer":"الجواب: هذا عمل خطير وجرم عظيم نسأل الله السلامة، فإن الذبح للموتى، الذبح لأصحاب القبور، ومن يسمونهم بالأولياء، الذبح لهم والتقرب إليهم بالدعاء وطلب المدد كله من الشرك الأكبر، فالذي يذبح لأصحاب القبور وما يسمونهم بالأولياء كـالبدوي والشيخ عبد القادر والحسين وأشباه ذلك، يطلبون المدد، ويطلبون منه العون، يطلبون منه شفاء المرضى، هذا كله شرك أكبر، كله من عمل الجاهلية الأولى، عمل قريش وأشباههم في الجاهلية، هذا شرك أكبر، والذبيحة ميتة لا يجوز أكلها ولا يجوز إقرارهم عليها، بل يجب تنبيههم وإنذارهم وتعليمهم أن هذا منكر، وأن هذا شرك أكبر؛ لأن الله  يقول: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] ويقول جل وعلا: قُلْ إِنَّ صَلاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ [الأنعام:162-163]، والنسك: الذبح ، فكما أن الصلاة لله، فهكذا النسك الذبح لله، قال سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:1-2] فالنحر لله والصلاة لله.\nفالذبح للأصنام أو للأشجار أو لأصحاب القبور، لطلب المدد منهم، أو شفاء المرضى أو ما أشبه ذلك، هذا كله شرك أكبر، لا من جهة الدعاء، ولا من جهة الذبح، فالذي يذبح لهم كالذي يصلي لهم نسأل الله العافية، والميتة تكون حراماً، والذبيحة تكون ميتة وحرام لا يجوز أكلها.\nأما مجرد إقامة المولد هذا بدعة، إذا كان مجرد إقامة مولد، الاحتفال بالموالد هذا من البدع المنكرة، والرسول عليه الصلاة والسلام يقول: من عمل عملاً ليس عليه أمرنا فهو رد ويقول ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد.\nفالموالد بدعة ومردودة على من أحدثها؛ لأن الرسول صلى الله عليه وسلم لم يفعل المولد ولا أصحابه، لا خلفاؤه الراشدون ولا غيره من الصحابة، ولا التابعون لهم بإحسان في القرون المفضلة، هذا شيء لا أصل له في الشرع، والواجب على أهل الإسلام تركه؛ لأن الخير في اتباع الرسول ﷺ واتباع أصحابه، والشر في خلاف ذلك، قال تعالى: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21].\nوقال النبي ﷺ: إياكم ومحدثات الأمور فإن كل محدثة بدعة وكل بدعة ضلالة وإذا كان في المولد دعاء الميت، دعاء النبي ﷺ والاستغاثة بالنبي صار شركاً أكبر، أما مجرد الاحتفال بالمولد وأكل الطعام والاجتماع على القصائد هذا بدعة منكر لا يجوز، فإذا كان فيه ذبح لغير الله أو دعاء لغير الله كدعاء النبي ﷺ والاستغاثة بالنبي وطلبه المدد أو النصر أو شفاء المرضى صار شركاً أكبر، يعني: صار هذا الدعاء شركاً أكبر، صار المولد فيه بدعة وفيه شرك، فيجمع المولد حينئذٍ البدعة والشرك إذا كان فيه دعاء غير الله، والاستغاثة بغير الله، سواء كان في مولد النبي ﷺأو غيره مثل الموالد الأخرى، مولد البدوي ، أو مولد الشيخ عبد القادر ، أو مولد الحسين أو فاطمة أو غير ذلك، كل هذه الموالد مبتدعة لا يجوز فعلها؛ لأنها من المحدثات في الدين، لكن إذا كان فيها دعاء غير الله، و.. طلب المدد من غير الله، أو شفاء المرضى صار ذلك الدعاء وطلب المدد شركاً مع البدعة جميع، نسأل الله السلامة، نسأل الله لنا ولهم الهداية، نسأل الله لنا ولهم الهداية. نعم.\nكذلك القراءة للموتى كونه يطلب قراء يقرءون .. يثوب للموتى هذا أيضاً لا يجوز، بدعة على الصحيح، إنما يقرأ القارئ لنفسه، ذهب بعض أهل العلم إلى أنه يجوز أن يثوب القراءة لغيره، لكن الصحيح إنه لا يجوز ذلك، ثم كونه يستأجر هذا لا وجه له؛ لأن المستأجر ما له ثواب، .. إنما قرأ إلا من أجل الأجرة، فأي ثواب له وهو يقرأ من أجل الأجرة! فقراءة القرآن للموتى بالأجرة هذا شيء لا أصل له، قال بعضهم: إنه بغير نزاع لا يجوز. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6746/حكم-دعاء-الاموات-والاستغاثة-بهم-والذبح-لهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_210/21012.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":8616,"question":"له سؤال ثان يقول فيه: عندنا في بعض المناطق الريفية أناس يعتقدون في الأولياء حسب قولهم، فإذا مرض أي واحد منهم يقطعون من أذن الماعز أو الظأن ويقولون: يا فلان! أي: يدعون الميت أن يشفي هذا المريض، ويذبحون الذبائح ويطلبون أحد القراء يقرأ لهم المولد بعد أكل هذه الذبائح، وبعضهم يذبحون في المقابر، وبعضهم في بيوتهم من أجل هذا الولي الميت بقولهم: أحي المريض، وقد التقيت ببعض هؤلاء الناس وعرفتهم أن هذا العمل غير جائز وأن الله هو الضار والنافع، وأنه هو المحيي والمميت، وهو على كل شيء قدير، فما حكم هؤلاء في هذا الاعتقاد، وما حكم الذين يقرءون لهم الموالد، وما حكم من أكل من هذه الذبائح، أفيدونا وجزاكم الله خير؟","title":"حكم دعاء الأموات والاستغاثة بهم والذبح لهم","answer":"الجواب: هذا عمل خطير وجرم عظيم نسأل الله السلامة، فإن الذبح للموتى، الذبح لأصحاب القبور، ومن يسمونهم بالأولياء، الذبح لهم والتقرب إليهم بالدعاء وطلب المدد كله من الشرك الأكبر، فالذي يذبح لأصحاب القبور وما يسمونهم بالأولياء كـالبدوي والشيخ عبد القادر والحسين وأشباه ذلك، يطلبون المدد، ويطلبون منه العون، يطلبون منه شفاء المرضى، هذا كله شرك أكبر، كله من عمل الجاهلية الأولى، عمل قريش وأشباههم في الجاهلية، هذا شرك أكبر، والذبيحة ميتة لا يجوز أكلها ولا يجوز إقرارهم عليها، بل يجب تنبيههم وإنذارهم وتعليمهم أن هذا منكر، وأن هذا شرك أكبر؛ لأن الله  يقول: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] ويقول جل وعلا: قُلْ إِنَّ صَلاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ [الأنعام:162-163]، والنسك: الذبح ، فكما أن الصلاة لله، فهكذا النسك الذبح لله، قال سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:1-2] فالنحر لله والصلاة لله.\nفالذبح للأصنام أو للأشجار أو لأصحاب القبور، لطلب المدد منهم، أو شفاء المرضى أو ما أشبه ذلك، هذا كله شرك أكبر، لا من جهة الدعاء، ولا من جهة الذبح، فالذي يذبح لهم كالذي يصلي لهم نسأل الله العافية، والميتة تكون حراماً، والذبيحة تكون ميتة وحرام لا يجوز أكلها.\nأما مجرد إقامة المولد هذا بدعة، إذا كان مجرد إقامة مولد، الاحتفال بالموالد هذا من البدع المنكرة، والرسول عليه الصلاة والسلام يقول: من عمل عملاً ليس عليه أمرنا فهو رد ويقول ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد.\nفالموالد بدعة ومردودة على من أحدثها؛ لأن الرسول صلى الله عليه وسلم لم يفعل المولد ولا أصحابه، لا خلفاؤه الراشدون ولا غيره من الصحابة، ولا التابعون لهم بإحسان في القرون المفضلة، هذا شيء لا أصل له في الشرع، والواجب على أهل الإسلام تركه؛ لأن الخير في اتباع الرسول ﷺ واتباع أصحابه، والشر في خلاف ذلك، قال تعالى: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21].\nوقال النبي ﷺ: إياكم ومحدثات الأمور فإن كل محدثة بدعة وكل بدعة ضلالة وإذا كان في المولد دعاء الميت، دعاء النبي ﷺ والاستغاثة بالنبي صار شركاً أكبر، أما مجرد الاحتفال بالمولد وأكل الطعام والاجتماع على القصائد هذا بدعة منكر لا يجوز، فإذا كان فيه ذبح لغير الله أو دعاء لغير الله كدعاء النبي ﷺ والاستغاثة بالنبي وطلبه المدد أو النصر أو شفاء المرضى صار شركاً أكبر، يعني: صار هذا الدعاء شركاً أكبر، صار المولد فيه بدعة وفيه شرك، فيجمع المولد حينئذٍ البدعة والشرك إذا كان فيه دعاء غير الله، والاستغاثة بغير الله، سواء كان في مولد النبي ﷺأو غيره مثل الموالد الأخرى، مولد البدوي ، أو مولد الشيخ عبد القادر ، أو مولد الحسين أو فاطمة أو غير ذلك، كل هذه الموالد مبتدعة لا يجوز فعلها؛ لأنها من المحدثات في الدين، لكن إذا كان فيها دعاء غير الله، و.. طلب المدد من غير الله، أو شفاء المرضى صار ذلك الدعاء وطلب المدد شركاً مع البدعة جميع، نسأل الله السلامة، نسأل الله لنا ولهم الهداية، نسأل الله لنا ولهم الهداية. نعم.\nكذلك القراءة للموتى كونه يطلب قراء يقرءون .. يثوب للموتى هذا أيضاً لا يجوز، بدعة على الصحيح، إنما يقرأ القارئ لنفسه، ذهب بعض أهل العلم إلى أنه يجوز أن يثوب القراءة لغيره، لكن الصحيح إنه لا يجوز ذلك، ثم كونه يستأجر هذا لا وجه له؛ لأن المستأجر ما له ثواب، .. إنما قرأ إلا من أجل الأجرة، فأي ثواب له وهو يقرأ من أجل الأجرة! فقراءة القرآن للموتى بالأجرة هذا شيء لا أصل له، قال بعضهم: إنه بغير نزاع لا يجوز. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6746/حكم-دعاء-الاموات-والاستغاثة-بهم-والذبح-لهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_210/21012.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":8684,"question":"يسأل أيضاً ويقول: يسكن معي بالمنزل شقيقي وهو لا يصلي ويسب الدين، وقد تحدثت معه عدة مرات وقدمت له النصح فأعرض عنه، وقال لي أخيراً -بعد أن ضايقته بالكلام-: لن أصلي أبداً حتى الموت، فهل يجوز لي أن آكل معه بعد ذلك وأن أتعامل معه، والذي أخشى أن يكون هذا العصيان سبب في هلاكه، وما هي الوسيلة التي أحارب بها مثل هذا التصرف مع هذا الأخ، جزاكم الله خير؟","title":"حكم من كان له أخ لا يصلي ويسب الدين","answer":"الجواب: الواجب عليك نصيحته وتحذيره من مغبة عمله، وأن تبين له أن ما فعله ردة عن الإسلام، فإن سب الدين ردة عن الإسلام بإجماع المسلمين، وكذلك ترك الصلاة ردة عن الإسلام في أصح قولي العلماء، فإن كان يجحد وجوبها كان كافراً بالإجماع، وإن كان لا يجحد وجوبها ولكنه يتكاسل ولا يبالي فهو كافر في أصح قولي العلماء، لقول النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة رضي الله عنه، وروى مسلم في صحيحه عن جابر ، عن النبي ﷺ أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة فالذي لا يصلي ومع هذا -والعياذ بالله- يصمم أنه لا يصلي حتى الموت هذا يظهر منه أنه لا يرى وجوبها وأنه جاحد لوجوبها، فهو كافر بلا شك حتى ولو زعم أنه لا يجحد وجوبها، لهذه الأحاديث ولما جاء في معناها، وإذا كان يسب الدين صار كفره أعظم وصارت ردته أشد والعياذ بالله.\nفالواجب عليك مفارقته ومعاداته في الله، والبراءة منه وأن لا تصاحبه، وأن لا تكلمه، وأن لا تأكل معه، بل تهجره، وتخرجه من بيتك، لا تسكن معه، إن كان البيت له فاخرج عنه، وإن كان بيتك فاطرده عنك لأنه نجس خبيث، فلا ينبغي لك أن يبقى معك، بل تطرده إن كان في بيتك أو تخرج من بيته إن كان البيت له، وتسأل الله له الهداية بينك وبين ربك لعل الله يهديه بأسبابك، وأما البقاء معه فلا أبداً، لا يصاحب ولا تؤكل وليمته ولا تجاب دعوته ولا يبقى معك في محلك؛ لأنه خبيث الحال نجس المقال والعقيدة فينبغي لك أن تحاربه وأن تبتعد عنه.\nوإذا كانت البلاد فيها حكم إسلامي يرفع بأمره إلى ولي الأمر، حتى يستتاب فإن تاب وإلا يقتل؛ لأن الله يقول سبحانه: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5] فدل على أن الذي لا يصلي لا يخلى سبيله، بل يقتل إن لم يتب، نسأل الله له الهداية، نسأل الله له الهداية، ونسأل الله لك العون عليه بالحق والصدق والهدى. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6826/حكم-من-كان-له-اخ-لا-يصلي-ويسب-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_215/21513.mp3","categories":["حكم الصلاة وأهميتها","نواقض الإسلام"]},{"id":8690,"question":"الواقع سماحة الشيخ وأنتم تتفضلون بهذا الشرح الموجز لهذا الركن العظيم من أركان الإسلام الركن الأول: شهادة: أن لا إله إلا الله وأن محمداً رسول الله، كثير من إخواننا المسلمين يتساهلون في بعض الأمور، البعض يعتقد أن ذلك التساهل يؤثر على التوحيد، يؤثر على هذا الركن من أركان الإسلام، فمثلاً: عند تحكيم القرآن والسنة وتنفيذ ذلك التحكيم أو تنفيذ بعض الأحكام وترك البعض الآخر، هل يؤثر هذا على القيام بهذا الركن أو لا؟","title":"بيان القول فيمن حكم بغير ما أنزل الله","answer":"الجواب: هذا فيه تفصيل: أما من حكم بغير ما أنزل الله وهو يعلم أنه واجب عليه الحكم بما أنزل الله وأنه خالف الشرع ولكن استباح هذا الأمر ورأى أنه لا حرج عليه في ذلك، وأنه يجوز له أن يحكم بغير شريعة الله فهذا كافر كفراً أكبر عند جميع العلماء، من استحل الحكم بغير ما أنزل الله كالحكم بالقوانين الوضعية التي وضعها الرجال من النصارى أو اليهود أو غيرهم، وزعم أنه يجوز الحكم بها أو زعم أنها أفضل من حكم الله -والعياذ بالله- أو زعم أنها تساوي حكم الله، وأن الإنسان مخير إن شاء حكم بالقرآن والسنة وإن شاء حكم بالقوانين الوضعية، من اعتقد هذا كفر عند جميع المسلمين، من قال: إنه يجوز الحكم بالقوانين أو أنها أفضل، أو أنها مساوية لحكم الله كفر إجماعاً.\nالمقدم: أو أنها هي الصالحة لهذا الزمان.\nالشيخ: أو أنها أنسب لأهل الزمان فهو كافر بالإجماع.\nأما من حكم بغير ما أنزل الله لهوىً وقصد وحظ عاجل، وإلا يعلم أنه مخطي، ويعلم أنه فعل منكراً وأن الواجب حكم الله، ولكن حكم بقانون أو برشوة لطمع أو لحاجات أخرى في نفسه، فهذا يكون أتى منكراً عظيماً ومعصية كبيرة وكفراً لكن يسمى كفراً أصغر، كما قال ابن عباس ومجاهد وغيره: كفر دون كفر، وظلم دون ظلم، وفسق دون فسق، كالذي يحكم بالرشوة، أو يحكم بأي قانون لكن مع إيمانه بأنه مخطئ وأنه غلطان، ولكن حمله الهوى أو حب الرياسة، ويعلم أنه مخطي وأنه ظالم، فهذا قد أتى كفراً لكن ليس هو الكفر الأكبر، بل كفر دون كفر، وظلم دون ظلم، وفسق دون فسق، هذا عند أهل السنة والجماعة.\nأما إذا اعتقد الجواز وأنه يجوز له، أو اعتقد أن حكم الطاغوت -حكم غير الله- أنسب لأهل الزمان، وأصلح لهم من حكم الله، أو أن حكم الله يساوي حكم القانون، أو يجوز ولكن حكم الله أفضل، وإلا يجوز القانون لكن حكم الله أفضل منه، كل هذا كفر أكبر، وردة عن الإسلام نعوذ بالله إذا كان مسلماً، يكون مرتداً عن الإسلام لقول النبي ﷺ: من بدل دينه فاقتلوه وهذا بدل دينه لأنه استحل حكم غير الله، والله يقول جل وعلا: وَأَنِ احْكُمْ بَيْنَهُمْ بِمَا أَنزَلَ اللَّهُ [المائدة:49]، ويقول سبحانه: وَمَنْ لَمْ يَحْكُمْ بِمَا أَنزَلَ اللَّهُ فَأُوْلَئِكَ هُمُُ الْكَافِرُونَ [المائدة:44] .. فَأُوْلَئِكَ هُمُ الظَّالِمُونَ [المائدة:45] .. فَأُوْلَئِكَ هُمُ الْفَاسِقُونَ [المائدة:47]، ويقول : فَلا وَرَبِّكَ لا يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لا يَجِدُوا فِي أَنفُسِهِمْ حَرَجًا مِمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْلِيمًا [النساء:65]، ويقول سبحانه:أَفَحُكْمَ الْجَاهِلِيَّةِ يَبْغُونَ وَمَنْ أَحْسَنُ مِنَ اللَّهِ حُكْمًا لِقَوْمٍ يُوقِنُونَ [المائدة:50]، فلا أحد أحسن حكماً من الله سبحانه وتعالى، فحكم الله هو أحسن الأحكام، وهو الواجب الاتباع، وهو الذي به صلاح الأمة وصلاح العالم، ولكن أكثر الخلق في غفلة عن هذا، نسأل الله السلامة. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/6837/بيان-القول-فيمن-حكم-بغير-ما-انزل-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_130/13002.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":8762,"question":"يسأل أيضاً ويقول الأخ أبكر جمعة: أحد الأشخاص يجهل بأمر الدين ويسب الدين فما حكمه؟ وماذا عليه أن يفعل إذا أدرك خطأه أفيدونا أفادكم الله؟","title":"حكم من سب الدين وحكم توبته","answer":"الجواب: سب الدين كفر أكبر وردة عن الإسلام نعوذ بالله، إذا سب الدين إذا سب المسلم دينه سب الإسلام أو تنقص الإسلام وعابه فهذه ردة عن الإسلام أو استهزأ به قال الله جل وعلا: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ ۝ لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65-66].\nوقد أجمع العلماء قاطبة: على أن المسلم متى سب الدين أو تنقصه أو سب الرسول صلى الله عليه وسلم أو تنقصه أو استهزأ به؛ فإنه يكون مرتداً كافراً حلال الدم والمال، يستتاب فإن تاب وإلا قتل. وبعض أهل العلم يقول: لا توبة له من جهة الحكم بل يقتل، ولكن الأرجح إن شاء الله أنه متى أبدى التوبة وأعلن التوبة ورجع إلى ربه  أنه يقبل، وإن قتله ولي الأمر ردعاً لغيره فلا بأس بذلك.\nأما توبته فيما بينه وبين الله؛ فإنها صحيحة إذا تاب صادقاً فتوبته فيما بينه وبين الله صحيحة ولو قتله ولي الأمر؛ سداً لباب التساهل بالدين وسب الدين، المقصود أن سب الدين والتنقص للدين أو للرسول ﷺ، أو الاستهزاء بذلك ردة وكفر أكبر بإجماع المسلمين، وصاحبها يستتاب فإن تاب قبل الله توبته وعفا عنه، أما كونه يقبل في الدنيا أم لا يقبل هذا محل خلاف بين أهل العلم، فإن قبل وعفا عنه الإمام بتوبته الصحيحة وإظهاره الندم والإقلاع فلا بأس، وإن قتله ولي الأمر سداً لباب التساهل بهذا الأمر العظيم؛ لأن سب الدين وسب الرسول ﷺ له شأن خطير، فإذا قتله ولي الأمر لسبه الرسول ﷺ أو سبه الدين فهذا له وجهه، وهو قول عظيم وقول جيد لأهل العلم ردعاً للناس عن التساهل بسب الدين أو سب الرسول ﷺ، عليه الصلاة والسلام. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6915/حكم-من-سب-الدين-وحكم-توبته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_217/21710.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":8774,"question":"هذه رسالة وردت إلينا من أحمد علي مرزوق ، يماني الجنسية يقيم بالدرعية، يقول: نريد إيضاح الأدلة عما يوجد في بلادنا بلدة الجاح باليمن حيث يوجد أناس كثيرون يذبحون للأولياء سواءً كانوا أموات أو أحياء، ويدعونهم ويطلبون منهم جلب المنافع ودفع المضار، ووصل الأمر بهم عندما نصحناهم أن قالوا لنا: أنتم مشركون. فماذا يجب علينا نحوهم، أفيدونا أفادكم الله؟","title":"حكم الذبح للأولياء وطلبهم المنافع ودفع المضار","answer":"الجواب: قد أحسنتم في إنكاركم عليهم وبيان أن عملهم هذا منكر، وأما إنكارهم عليكم وزعمهم أنكم مشركون فهذا من أغلاطهم وجهلهم كما قيل: رمتني بدائها وانسلت.\nهم المشركون بعملهم هذا، إذا كانوا يسألون الموتى ويتقربون إليهم بالذبائح وينذرون لهم ويدعونهم وبهم يستغيثون، هذا الشرك الأكبر، فإذا فعلوه مع ما يسمونهم بالأولياء سواء كانوا أحياءً أو أمواتاً يعتقدون فيهم أنهم ينفعونهم ويضرونهم، وأنهم يجيبون دعوتهم، وأنهم يشفون مريضهم، وأن لهم فيهم سراً يدعون معهم، ويستغاث بهم وينذر لهم، هذا شرك أكبر والعياذ بالله، وهذا عمل المشركين مع اللات والعزى ومناة ومع أصنامهم ومع آلهتهم الأخرى.\nالواجب على ولاة الأمر في اليمن أن ينكروا هذا الأمر، وأن يعلموا الناس ما يجب عليهم من شرع الله، وأن يمنعوا هذا الشرك ويحولوا بين العامة وبينه، وأن يهدموا القباب التي على القبور ويزيلوها؛ لأنها فتنة، ولأنها من أسباب الشرك، ولأنها محرمة، الرسول ﷺ نهى أن يبنى على القبور، ولعن من اتخذ المساجد عليها، فلا يجوز البناء عليها لا مسجد ولا غيره، بل يجب أن تكون بارزة صاحية ليس عليها بناء كما كان قبور المسلمين في المدينة المنورة وفي كل بلد إسلامي لم يتأثر بالبدع والأهواء.\nودعاء الأموات والاستغاثة بالأموات أو بالأشجار والأحجار أو بالجن أو بالملائكة وعبادتهم من دون الله بطلب المدد منهم أو الغوث أو شفاء المرضى أو رد الغياب أو دخول الجنة أو النجاة من .. كل هذا شرك أكبر، وهكذا الذبح لغير الله قال الله سبحانه: قُلْ إِنَّ صَلاتِي وَنُسُكِي [الأنعام:162] يعني: ذبحي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:162-163]، وقال تعالى: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:1-2]، وقال النبي ﷺ: لعن الله من ذبح لغير الله فالذبح لغير الله من الكواكب والجن والملائكة والأولياء وغيرهم شرك أكبر نعوذ بالله؛ لأن الذبح عبادة يجب أن يكون لله وحده، وهكذا النذر عبادة، فإذا نذر للأولياء ذبيحة أو طعاماً أو نقوداًَ صار شركاً أكبر نعوذ بالله، وهكذا الاستعاذة بهم، والاستغاثة بهم، ودعاؤهم تفريج الكروب وقضاء الحاجات ونحو ذلك كل هذا من الشرك الأكبر، وهكذا طلب المدد: المدد يا فلان، المدد يا فلان.\nفعلى العلماء أن ينكروا هذا ويعلموا هؤلاء الجهال ويرشدوهم، وعلى ولاة الأمور أن ينفذوا حكم الله فيهم، وأن يزجروهم عن هذا الأمر، وأن يحولوا بينهم وبينه، وأن يؤدبوا من لم يرتدع وأن يستتيبوه من هذا الشرك الوخيم، هذا الواجب على العلماء وعلى الحكام والأمراء. نسأل الله للجميع الهداية والتوفيق.\nالمقدم: والعامة يهجرونهم؟\nالشيخ: لمن عرف هذا منهم ولم يستجيبوا لداعي الحق فيجب أن يهجروا، يجب أن يهجروا وينكر عليهم هذا العمل السيء حتى يتوبوا إلى الله منه، حتى يستقيموا على الطريق السوي. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6936/حكم-الذبح-للاولياء-وطلبهم-المنافع-ودفع-المضار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_219/21909.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":8776,"question":"هذه رسالة وردتنا من المرسلة صباح محمد علي يونس من العراق من محافظة نينوى، تقول: ذكرتم في حلقات سابقة من هذا البرنامج عدم زيارة الأضرحة وأنها من الشرك بالله، فهل زيارة النبي يونس والنبي جرجيس في نينوى تدخل ضمن ذلك؟ وهل الصلاة فيها غير جائزة؟","title":"حكم زيارة الأضرحة","answer":"الجواب: الزيارة قسمان، زيارة القبور قسمان:\nزيارة شرعية، وزيارة بدعية شركية، أما الزيارة الشرعية فهذه مشروعة لقبور الصالحين والمسلمين جميعاً، وإذا عرف قبر من قبور الأنبياء كقبر نبينا ﷺ تشرع له الزيارة من دون شد الرحل، شد الرحل لا يشد الرحال للقبور لا تشد إلا للمساجد الثلاثة: المسجد الحرام، ومسجد النبي صلى الله عليه وسلم، والمسجد الأقصى، هؤلاء الثلاثة تشد لهم الرحال، أما القبور لا تشد لها الرحال، لكن إذا كان الإنسان في البلد قصدها زائراً فهذا سنة؛ قال النبي ﷺ: زوروا القبور فإنها تذكركم الآخرة، واللفظ الآخر: تذكركم الموت، فزيارة القبور سنة وقربى وقد فعلها النبي ﷺوفعلها أصحابه  وأرضاهم، فإذا زار المسلم قبور المسلمين في بلده ودعا لهم واستغفر لهم كان هذا قربة وطاعة، وكان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، نسأل الله لنا ولكم العافية، هكذا علمهم النبي ﷺ، وكان يزور القبور ﷺ بنفسه ويدعو للموتى ويستغفر لهم، ويقول: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، اللهم اغفر لأهل بقيع الغرقد، وفي لفظ يقول: نسأل الله لنا ولكم العافية، فعلى المؤمن أن يفعل مثلما فعله النبي ﷺ إذا زار القبور ومثلما علم أصحابه، يسلم عليهم ويدعو لهم بالمغفرة والرحمة ويستغفر لهم يقول: نسأل الله لنا ولكم العافية، هذه الزيارة الشرعية.\nوهكذا إذا زار قبر النبي ﷺ في المدينة إذا زار المسجد ثم زار قبر النبي ﷺ يسلم عليه ويدعو له يقول: صلى الله وسلم عليك وعلى آلك وأصحابك، جزاك الله عن أمتك خيراً.\nوهكذا إذا زار قبور الصالحين في أي مكان يدعو لهم بالمغفرة والرحمة ويستغفر لهم ويسأل الله لهم العافية.\nأما قبر يونس فلا يعلم بنينوى، جميع قبور الأنبياء لا تعلم ولا تعرف، فدعوى أنه موجود في نينوى أو في غيرها أمر باطل لا أصل له، ذكر العلماء أنه لا يوجد قبر معروف من قبور الأنبياء ألبتة إلا قبر نبينا محمد صلى الله عليه وسلم في المدينة وإلا قبر الخليل في الخليل في المغارة المعروفة، هذا هو المعروف، أما قبور بقية الأنبياء فغير معروفة، لا يونس ولا غيرهم من الأنبياء والرسل، قبورهم الآن غير معلومة، ومن ادعى أن قبر يونس موجود أو فلان أو فلان كله كذب لا صحة له، ولا نعلم نبياً يقال له: جرجيس ، ولا يعرف في الأنبياء من يسمى جرجيس .\nفالمقصود أنه ليس هناك قبر نبي معروف غير قبر نبينا محمد ﷺ في المدينة وغير قبر الخليل في بلد الخليل في المغارة المعروفة.\nالمقدم: وهذه الزيارة التي ذكرتم للرجال والنساء؟\nالشيخ: أما هذه الزيارة الشرعية للرجال، أما النساء فلا يشرع لهم الزيارة على الصحيح، النبي صلى الله عليه وسلم لعن زائرات القبور، فدل ذلك على أن النساء لا يزرن القبور وإنما الزيارة للرجال خاصة في أصح قولي العلماء؛ لما جاءت به الأحاديث الصحيحة عن رسول الله ﷺأنه لعن زائرات القبور، جاء هذا من حديث أبي هريرة ، ومن حديث حسان بن ثابت ، ومن حديث ابن عباس ، فلا يشرع لهن الزيارة ولا تجوز لهن الزيارة، ولكن يدعون للموتى المسلمين في بيوتهم في المساجد في البيوت، وإذا زاروا المدينة دعوا للنبي ﷺ وهم في المسجد أو في بيوتهم، صلوا عليه وسلموا عليه في أي مكان عليه الصلاة والسلام، مثلما قال عليه الصلاة والسلام: لا تتخذوا قبري عيداً ولا بيوتكم قبورا، وصلوا علي فإن صلاتكم تبلغني حيث كنتم عليه الصلاة والسلام، فإذا صلى عليه المؤمن والمؤمنة في أي مكان بلغ ذلك، يقول ﷺ: إن لله ملائكة سياحين يبلغوني عن أمتي السلام عليه الصلاة والسلام.\nفالمشروع لك -أيها السائلة- أن تصلي عليه صلى الله عليه وسلم في أي مكان وعلى بقية الأنبياء عليهم الصلاة والسلام، وأما زيارة هذا القبر الذي يقال له: قبر يونس هذا لا أصل له، ثم النساء لا يزرن القبور على الصحيح، ولكن يدعون لموتى المسلمين ويستغفرون لموتى المسلمين في أي مكان. نعم..","link":"https://binbaz.org.sa/fatwas/6937/حكم-زيارة-الاضرحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_219/21910.mp3","categories":["زيارة القبور","نواقض الإسلام","البدع والمحدثات"]},{"id":8795,"question":"وهذه أول رسالة في البرنامج وردت من جماعة من الإخوة من الأردن الشقيق، يقولون فيها: ما هو الشرك أفيدونا أفادكم الله؟","title":"حقيقة الشرك ومعناه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله، وخيرته من خلقه، وأمينه على وحيه، نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه، ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فإن الشرك هو أعظم الذنوب، وهو أعظم الجرائم، وهو الذي جرى بين الرسل وبين الأمم فيه النزاع، فالأمم كانت على الشرك إلا من هداه الله وحفظ من أفراد الناس، والرسل تدعوهم إلى توحيد الله والإخلاص له، وكان هذا الشرك قد حدث في قوم نوح بأسباب غلوهم في ود وسواع ويغوث ويعوق ونسر ، لما غلوا فيهم وعظموهم التعظيم الذي نهى الله عنه، وقعوا في الشرك بعد ذلك، وصاروا يستغيثون بهم، وينذرون لهم، ويذبحون لهم، فلما ظهر فيهم هذا الشرك بعث الله إليهم نوحـاً عليه الصلاة والسلام يدعوهم إلى توحيد الله، وينذرهم هذا الشرك ويحذرهم منه، ولم يزل فيهم يدعوهم إلى الله ويأمرهم بالإخلاص لله  والتوبة إلى الله من شركهم، ولكنهم استمروا على طغيانهم وضلالهم إلا القليل، فبعد ذلك أمره الله بصنع السفينة وأن يحمل فيها من آمن معه ومن كل زوجين اثنين، وأهلك الله أهل الأرض وأغرقهم بسبب كفرهم وشركهم بالله .\nوهكذا بعد ذلك الأمم من قوم هود وقوم صالح ومن بعدهم، أرسل الله إليهم الرسل تدعوهم إلى توحيد الله، وتنذرهم الشرك بالله عز وجل، ولم يؤمن إلا القليل، وأكثر الخلق غلب عليه طاعة الهوى والشيطان، ونبينا محمد عليه الصلاة والسلام هو خاتم الأنبياء وهو أفضلهم وإمامهم بعثه الله إلى هذه الأمة لينذرها الشرك بالله، ويدعوها إلى توحيد الله ، وكان الشرك في وقته قد انتشر في الأرض، وعم ولم يبق على التوحيد إلا البقايا القليلة من أهل الكتاب، فأنذرهم عليه الصلاة والسلام من هذا الشرك، وكانوا يتعلقون على الأشجار والأحجار والأصنام، ويدعون الأنبياء والصالحين ويستغيثون بهم، وينذرون لهم، ويقولون: إنهم شفعاؤنا عند الله، وأنهم يقربونهم إلى الله زلفى، كما ذكر الله ذلك عنهم في قوله سبحانه: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18]، قال الله سبحانه راداً عليهم: قُلْ أَتُنَبِّئُونَ اللَّهَ بِمَا لا يَعْلَمُ فِي السَّمَوَاتِ وَلا فِي الأَرْضِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ [يونس:18]، هذا شأن المشركين يعبدون الأصنام والأشجار والأحجار والأولياء والأنبياء، وبهم يستغيثون، ولهم ينذرون، وإليهم يتقربون بالذبائح، هذا هو الشرك الأكبر، وهذا هو الذي أنكرته الرسل، وأنكره أتباعهم من دعاة الحق، وقال الله فيه سبحانه: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88]، وقال فيه : وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ [الزمر:65]، وقال فيه سبحانه: إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ [لقمان:13]، وقال فيه : إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ وَمَنْ يُشْرِكْ بِاللَّهِ فَقَدِ افْتَرَى إِثْمًا عَظِيمًا [النساء:48]، وفي الآية الأخرى: فَقَدْ ضَلَّ ضَلالًا بَعِيدًا [النساء:136]، وبهذا نعلم حقيقة الشرك، وأنه تشريك غير الله مع الله بعباده ، من أولياء أو أنبياء أو جن أو ملائكة أو أحجار أو أصنام أو شجر أو غير ذلك، هذا هو الشرك الأكبر، وهذا هو الذنب الأعظم الذي نهت عنه الرسل، وأنزل الله فيه الكتب سبحانه وتعالى، وتوعد عليه عز وجل بعدم المغفرة وبعدم دخول الجنة، وهكذا يلحق بذلك جميع أنواع الكفر، كلها حكمها حكم الشرك، كمن سب الله، أو سب رسوله، أو استهزأ بالدين، أو تنقص الرسول صلى الله عليه وسلم، أو طعن في رسالته عليه الصلاة والسلام، أو جحد بعض ما أوجب الله من الأمور المعلومة من الدين بالضرورة، كأن جحد وجوب الصلاة، الصلوات الخمس، أو جحد وجوب زكاة المال، أو جحد وجوب صوم رمضان، أو جحد وجوب الحج مع الاستطاعة، أو جحد تحريم الزنا، أو جحد تحريم الخمر، أو جحد تحريم السرقة، أو ما أشبه ذلك، كل هذا يسمى كفراً ويسمى شركاً بالله ، وصاحبه إذا مات عليه يخلد في النار نعوذ بالله، والجنة عليه حرام، وأعماله حابطة، كما قال سبحانه: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88]، وقال : وَقَدِمْنَا إِلَى مَا عَمِلُوا مِنْ عَمَلٍ فَجَعَلْنَاهُ هَبَاءً مَنْثُورًا [الفرقان:23]، وقال سبحانه: وَمَنْ يَكْفُرْ بِالإِيمَانِ فَقَدْ حَبِطَ عَمَلُهُ وَهُوَ فِي الآخِرَةِ مِنَ الْخَاسِرِينَ [المائدة:5].\nوالواجب على جميع المكلفين الحذر من هذا الشرك، وأن يخصوا الله بالعبادة دون كل ما سواه، وهذا هو معنى: لا إله إلا الله، فإن معناها: لا معبود حق إلا الله، فهي تنفي العبادة لغير الله، وتثبت العبادة لله سبحانه وتعالى، كما قال : ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ [الحج:62]، وقال سبحانه: وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِ اُعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ [النحل:36]، وقال : وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَسُولٍ إِلَّا نُوحِي إِلَيْهِ أَنَّهُ لا إِلَهَ إِلَّا أَنَا فَاعْبُدُونِ [الأنبياء:25] وهذا التوحيد هو الذي خلق الله من أجله الثقلين، كما في قوله سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]، المعنى: إلا ليخصوني بالعبادة، ليفردوني بعبادتي، من صوم وصلاة ودعاء وخوف ورجاء وغير ذلك، فهذا هو واجب المكلفين جميعاً أن يعبدوا الله وحده، ويخصوه بعباداتهم دون كل ما سواه.\nأما الرسل والأنبياء فحقهم الاتباع والمحبة والطاعة، أما العبادة فحق الله ، وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] .. إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] .. وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5].\nوهكذا الأولياء حقهم أن يحبوا في الله، وأن يسلك سبيلهم الطيب، في طاعة الله ورسوله، أما أن يعبدوا مع الله، لا، العبادة حق الله، لا يعبد مع الله أحد لا ملك ولا نبي ولا ولي ولا غير ذلك.\nوالواجب على جميع المكلفين أن يكون اهتمامهم بهذا الأمر أعظم اهتمام؛ لأن التوحيد هو أصل الدين وأساس الملة، وهو أعظم واجب وأهم واجب؛ ولأن الشرك هو أعظم الذنوب وأكبر الجرائم، فوجب أن يكون اهتمام المسلمين واهتمام طلاب العلم بهذا الأمر أعظم من كل اهتمام، وأولى من كل أمر، نسأل الله للجميع الهداية والتوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/6953/حقيقة-الشرك-ومعناه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_221/22106.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":8873,"question":"أخونا أيضًا يقول: أسألكم عن قبور الأولياء؛ أولياء الله الصالحين، مثل: مسجد الحسين والسيد البدوي وهم كثيرون جدًا، وكل واحد يقام له الاحتفالات وتنذر له النذور، ولا أحد ينكر على الناس، أرجو من سماحة الشيخ توجيه الناس إلى ما فيه الخير، وإذا أمكن أيضًا أن يكون التوجيه مكتوبًا فلعله يكون مفيدًا.","title":"حكم زيارة القبور والنذر لها والاحتفال بالموالد","answer":"الجواب: لا شك أن هذا الأمر واقع في الناس، وهو من أعظم المصائب من أعظم الكبائر بل هو الشرك الأعظم ولا حول ولا قوة إلا بالله، فإن الغلو في أصحاب القبور ودعاءهم من دون الله والاستغاثة بهم والتقرب إليهم بالطواف بقبورهم كل هذا من الشرك الأكبر، وهكذا الذبح لهم والنذر لهم كله من الشرك الأكبر.\nأما الاحتفالات بمواليدهم فهذه من البدع التي يجب تركها، لكن لو وقع فيها دعاؤهم والاستغاثة بهم صار ذلك من الشرك الأكبر، وكثير من الناس في الاحتفالات قد يدعون المحتفل به ويستغيثون به كما يفعل هذا بعض الناس عند احتفاله بمولد النبي عليه الصلاة والسلام، فالبدع تجر إلى الشرك وهي بريد له، وهي أعظم المنكرات بعد الشرك البدع، فإن المنكرات مراتب أعظمها الشرك بالله  وأنواع الكفر به سبحانه وتعالى ثم يلي ذلك البدع؛ لأنها زيادة في الدين واعتراض على الله، فهي وسيلة إلى الشرك بالله ، فالواجب الحذر منها ومن ذلك البناء على القبور واتخاذ القباب عليها وإقامة الموالد والاحتفال بها كل هذا من وسائل الشرك، فإن القبر متى عظم بالبناء واتخاذ القبة عليه والمسجد فإن العامة يظنون أن هذا يدل على أنه يدعى من دون الله فيستغيثون به وينذرون له ويظنون أنه يقضي حوائجهم وأنه يشفع لهم عند الله بهذا العمل السيئ، وهذا هو عمل المشركين الأولين هو دينهم دين قريش وأشباههم، الغلو في الأموات والاستغاثة بأصحاب القبور ودعاؤهم من دون الله والنذر لهم هذا هو دين قريش كما قال تعالى: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18] فرد الله عليهم بقوله سبحانه: قُلْ أَتُنَبِّئُونَ اللَّهَ بِمَا لا يَعْلَمُ فِي السَّمَوَاتِ وَلا فِي الأَرْضِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ [يونس:18] فبين سبحانه أنه لا يعلم له شريكًا لا في السماء ولا في الأرض وأنكر عليهم عملهم هذا.\nفليس المشركون على حق بل هم على باطل، وليست آلهتهم التي دعوها من دون الله تشفع لهم، قال الله تعالى: فَمَا تَنْفَعُهُمْ شَفَاعَةُ الشَّافِعِينَ [المدثر:48] وهكذا قوله سبحانه في الآية الأخرى: فاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ ۝ أَلا لِلَّهِ الدِّينُ الْخَالِصُ وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:2-3] يعني: يقولون: ما نعبدهم إلا ليقربونا إلى الله زلفى، فأخبرعن المشركين أنهم اتخذوا آلهتهم التي عبدوها من دون الله يزعمون أنها تقربهم إلى الله زلفى، ولم يزعموا أنها تخلق أو ترزق، لا، وإنما أرادوا تقريبها لهم عند الله وشفاعتها لهم عند الله ومع هذا حكم الله عليهم بالشرك والكفر، قال تعالى في هذه الآية: إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّار [الزمر:3] سماهم كذبة في دعواهم أنها تقربهم كفرة في هذا العمل، فالواجب الحذر من هذا الغلو وهذه البدع التي أحدثها الناس عند القبور فإنها شر عظيم وفساد كبير ووقوعها يجر إلى الشرك فإنه متى عكف على القبر وبنى عليه وعظمه بالستور والأطياب فإن ذلك يجره إلى أن يدعوه من دون الله وإلى أن يستغيث به وهذا هو الشرك الأكبر عند جميع أهل العلم.\nفيجب الحذر من هذا البلاء العظيم، ويجب على العلماء أن يبينوا للناس هذه الشركيات وهذه المنكرات وأن يرشدوهم إلى الحق حتى يدعوه.. حتى يدعوا هذا الباطل .. حتى يدعوا هذا الشرك.\nوقد مكث النبي ﷺ في مكة عشر سنين يدعو الناس إلى توحيد الله وينكر عليهم الشرك بالله وعبادة الأوثان والأصنام وأصحاب القبور ثم فرض الله عليه الصلوات الخمس فبقي بعدها في مكة نحو ثلاث سنين يدعو إلى توحيد الله والإخلاص له ثم هاجر إلى المدينة عليه الصلاة والسلام، ولم يزل يدعو إلى الله ويعلم الناس ما شرع الله لهم حتى توفاه الله عليه الصلاة والسلام ونقله إلى الرفيق الأعلى عليه من ربه أفضل الصلاة والتسليم.\nفالواجب على خلفائه وهم العلماء أن يتقوا الله، وأن يبينوا للناس دينهم على الوجه الذي لا خفاء فيه.\nولا ريب أن سكوت العلماء ومن ينسب إلى العلم عن العامة وهم يفعلون هذه الأفعال التي هي التعلق بالأموات والاستغاثة بالأموات، لا شك أن سكوتهم يشجع هؤلاء على هذا الشرك ويعتقدون أن هذا السكوت دليل على أن هذا جائز وأنه لا حرج فيه.\nفالواجب الحذر، والواجب على العامة أن يسألوا أهل العلم المعروفين بالعقيدة الصالحة وتعظيم كتاب الله وسنة رسوله عليه الصلاة والسلام، والواجب على العلماء أن يتقوا الله ويتبصروا وأن ينكروا ما أنكره الله ورسوله من الشرك وسائر المعاصي، والله المستعان. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7029/حكم-زيارة-القبور-والنذر-لها-والاحتفال-بالموالد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_167/16702.mp3","categories":["نواقض الإسلام","البدع والمحدثات"]},{"id":8884,"question":"أختنا تقول: عندما استمعت لهذا البرنامج استفدت الكثير والكثير، وخاصة عندما عرفت أن الأولياء والموتى لا يفيدون الإنسان، وعندما أخبرت أهلي بذلك اتهمونني بأنني كافرة وأن الأولياء سيضرونني وأنهم يروني في المنام بأن هؤلاء الرجال الصالحين يلومونني، بماذا تنصحون مثل هؤلاء الذين تشبعت عقولهم بالخرافات والبدع والتي تكاد في كل البلدان العربية تنتشر؟","title":"نصيحة لمن تشرب عقله الخرافات والبدع","answer":"الجواب: ننصح الجميع بأن يتقوا الله  ويعلموا أن السعادة والنجاة في الدنيا والآخرة باتباع النبي ﷺ والسير على منهاجه عليه الصلاة والسلام، هو سيد الأولياء وأفضل الأولياء، فالأنبياء هم أفضل الناس هم أفضل الأولياء وأفضل الصالحين، ثم يليهم بعد ذلك الأتقياء من عباد الله من أصحاب النبي ﷺ وبعدهم، فالأولياء هم أهل الصلاح والاستقامة على طاعة الله ورسوله وعلى رأسهم الأنبياء عليهم الصلاة والسلام، فحبهم دين حبهم في الله والتأسي بهم في الخير والأعمال الصالحات هذا أمر مطلوب ولكنهم لا يجوز التعلق بهم وعبادتهم من دون الله، لا يجوز أن يدعوا مع الله ولا أن يستغاث بهم ولا يطلب منهم مدد، كأن يقول: يا سيدي عبد القادر أغثني، أو يا رسول الله أغثني، أو يا علي أغثني أو انصرني، أو يا حسين أو يا فاطمة أو يا ست زينب أو كذا هذا لا يجوز، الدعاء لله وحده، الله يقول سبحانه: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60]، ويقول سبحانه: وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ [البقرة:186].\nويقول سبحانه: أَمَّنْ يُجِيبُ الْمُضطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ السُّوءَ [النمل:62]، ويقول سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117]، فسماهم كفرة بدعائهم غير الله.\nوقال سبحانه: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، وقال جل وعلا: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَاا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلا يُنَبِّئُكَ مِثْلُ خَبِيرٍ [فاطر:13-14] ، فبين سبحانه أن مدعويهم من دون الله من الأولياء وغير الأولياء لا يسمعون دعاءهم، ما بين ميت وما بين مشغول بشأنه مع الله، فلا يسمعون دعاءهم لموتهم أو غيبتهم، وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ [فاطر:14]، ما يستطيعون يستجيبون لهم؛ لأن غفران الذنوب وتفريج الكروب بيد الله ، ثم قال: وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ ، سمى دعاءه إياهم شركاً بالله سبحانه وتعالى كما سماه في الآية الأخرى كفراً، فطلب المدد والعون والغوث من الأموات والغائبين لاعتقاد أن لهم سراً وأنهم يسمعون مع البعد كل هذا باطل، كله من الشرك بالله سبحانه وتعالى.\nفالواجب على كل مسلم أن ينتبه لهذا الأمر، وأن يعرف أن اعتقاد الجهلة بالأولياء أو في الأنبياء أنهم ينفعون ويضرون، وأنهم يغيثون من استجار بهم واستغاث بهم بعد الموت، وأنهم يعطونه مطالبه من غفران الذنوب وشفاء المرضى وغير هذا كل هذا جهل، وكله شرك بالله عز وجل فيجب الحذر من ذلك، والنبي صلى الله عليه وسلم بعثه الله لإنكار هذا، بعثه الله إلى العرب والعجم.. إلى الجن والإنس يدعوهم إلى توحيد الله والإخلاص له، وكانت العرب تعبد الأصنام والأولياء والأشجار والأحجار فدعاهم إلى ترك هذا وحذرهم من هذا، وأمرهم أن يعبدوا الله وحده، وتلا عليهم قوله سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23]، إِيَّاكَ نَعْبُدُُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]، وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5]، إلى غيرها من الآيات.\nفعلى المسلمين جميعاً وعلى المكلفين وعلى كل من له أدنى بصيرة أن ينتبه لهذا الأمر، وأن لا يغتر بالمشركين وعباد الأوثان وعباد القبور، يجب أن يحذر من شبههم الباطلة ويجب أن يحذر من دعوتهم إلى الشرك، ويجب أن يلتزم بما شرعه الله لعباده وما علمه عباده على يد الرسل عليهم الصلاة والسلام، وما أوضحه في كتابه العظيم من وجوب العبادة لله وحده وإخلاصها له وحده دون كل ما سواه، كما قال : فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ [غافر:14].\nوأنت أيها السائلة! اشكري الله الذي علمك وأنقذك وبصرك حتى أراك الحق الذي جهله الناس، ولا تبالي بعيبهم لك أو وعيدهم لك بالأولياء فإن هذا لا يضرك فهم جاهلون ومتى اهتدوا عرفوا الحق الذي عرفتيه وصاروا عوناً لك إن شاء الله على الخير، نسأل الله أن يهدي الجميع.","link":"https://binbaz.org.sa/fatwas/7040/نصيحة-لمن-تشرب-عقله-الخرافات-والبدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_139/13910.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":8909,"question":"الرسالة التالية وصلت إلى البرنامج من عَمَّان، وباعثها أحد الإخوة من هناك، يقول: المرسل علي الأطرش، أخونا يقول: ما حكم من يدعي أنه قد رأى رب العزة في المنام؟ وهل كما يزعم البعض أن الإمام أحمد بن حنبل قدر رأى رب العزة والجلال في المنام أكثر من مائة مرة؟","title":"حكم رؤية الإنسان لربه في المنام","answer":"الجواب: ذكر شيخ الإسلام ابن تيمية رحمه الله وآخرون أنه يمكن أن يرى الإنسان ربه في المنام، ولكن يكون ما رآه ليس هو الحقيقة؛ لأن الله لا يشبهه شيء ، قال تعالى: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] فليس يشبهه، يمكن أن يكلمه ربه، يرى في النوم أنه يكلمه ربه، لكن مهما أرى من الصور، أي صورة، صورة إنسان أو صورة حيوان فليست هي الله جل وعلا، لأن الله لا يشبهه شيء ، لا شبيه له ولا كفء له جل وعلا.\nوذكر الشيخ تقي الدين رحمه الله في هذا أن الأحوال تختلف بحسب حال العبد الرائي، فكل ما كان من أصلح الناس، وأقربهم إلى الخير كانت رؤيته أقرب إلى الصواب والصحة، لكن على غير الكيفية التي يراها أو الصفة التي يراها؛ لأن الأصل الأصيل أن الله لا يشبهه شيء ، فيمكن أن يسمع صوتًا أن يقال له: كذا وافعل كذا، ولكن ليس هناك صورة مشخصة يراها تشبه شيئًا من المخلوقات، ليس له شبيه ولا مثيل .\nوقد روي عن النبي ﷺ أنه رأى ربه في المنام، وقد رواه معاذ عن النبي ﷺ أنه رأى ربه، وقد جاء في عدة طرق أنه رأى ربه وأنه  وضع يده بين كتفيه حتى وجد بردها بين ثدييه أو بين ثدييه حتى وجد بردها بين كتفيه، هذا ورد في الحديث، وألف فيه الحافظ ابن رجب رسالةً سماها اختيار الأولى في شرح حادثة اختصام الملأ الأعلى، وهذا يدل على أن الأنبياء قد يرون ربهم بالنوم، أما رؤية الرب في الدنيا بالعيان فلا، أخبر النبي ﷺ أنه لن يرى أحد ربه حتى يموت قال: واعلموا أنه لن يرى أحد ربه حتى يموت رواه مسلم في الصحيح، ولما سئل ﷺ: هل رأيت ربك؟ قال: رأيت نورًا وفي لفظ: نور أنى أراه رواه مسلم من حديث أبي ذر، وهكذا سئلت عائشة عن ذلك فأخبرت أنه لا يراه أحد في الدنيا؛ لأن رؤية الله أعلى نعيم أهل الجنة، أعلى نعيم المؤمنين، فهي لا تحصل إلا لأهل الجنة، لأهل الإيمان في الدار الآخرة، والدنيا دار الابتلاء والامتحان، ودار الخبيثين والطيبين مشتركة، فليست محل الرؤية؛ لأن الرؤية أعظم نعيم للرائي، قد ادخرها الله لعباده المؤمنين في دار الكرامة في يوم القيامة.\nوأما هذه الرؤيا التي يدعيها الناس لربهم؛ فهي تختلف مثل ما قال شيخ الإسلام رحمه الله بحسب صلاحهم وتقواهم، وقد يخيل لبعض الناس أنه رأى ربه وليس كذلك، فإن الشيطان قد يخيل لهم ويوهمهم أنه ربهم كما يروى أنه تخيل إلى عبدالقادر الجيلاني، الشيخ عبدالقادر على عرش فوق الماء وقال: أنا ربك، فقال له: اخسأ عدو الله لست ربي؛ لأن أمر ربي أوامر لا تليق. نعم.\nفالمقصود: أن رؤية الله عز وجل ممكنة في الدنيا لكن على وجه لا يشبه فيها الخلق سبحانه وتعالى، وإذا أمره بشيء يخالف الشرع فهي علامة أنه لم ير ربه وإنما رأى شيطانًا، فلو رآه وقال له: لا تصل، قد أسقطت عنك التكاليف، أو قال: ما عليك زكاة، أو ما عليك صوم رمضان، أو ما عليك بر والديك، أو قال: لا حرج عليك في أن تأكل الربا، فهذه كلها علامات على أنه رأى شيطانًا وليس ربه، أن هذا الذي يكلمه ليس ربه وإنما هو شيطان.\nفالخلاصة: أن الرؤية ممكنة ولكن على وجه لا يكون فيها مشابهة للمخلوقين، بل ربما سمع صوتًا؛ لكن ليست هناك شخصية يراها تشبه المخلوقين؛ لأن الله لا شبيه له ولا كفء له .\nومن علامات صحة الرؤيا: أن تكون الأوامر موافقة للشرع التي يؤمر بها، وأما إن كانت مخالفة للشرع فهي علامة على أنه رأى شيطانًا ولم ير ربه. نعم.\nالمقدم: ما قيل عن رؤيا الإمام أحمد؟\nالشيخ: لا أعرف صحتها عنه، يروى أنه رأى ربه؛ لكن لا أعرف صحتها عنه.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7064/حكم-روية-الانسان-لربه-في-المنام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_169/16902.mp3","categories":["نواقض الإسلام","الرؤى والمنامات"]},{"id":8948,"question":"أخونا أيضًا يسأل حول هذا الموضوع ويقول: وما حكم النذر على القبور والدعاء لأصحاب القبور، مثلًا يدعو صاحب القبر: يا شيخ فلان، يا شيخ فلان، وما حكم هؤلاء الناس الذين يدعون أصحاب القبور؟","title":"حكم دعاء أهل القبور والنذر لهم","answer":"الجواب: هذا فيه التفصيل، أما النذر للأموات والاستغاثة بهم ودعاؤهم فهذا من الشرك الأكبر ومن العبادة لغير الله، فإذا قال: لله علي كذا وكذا من المال للشيخ البدوي أو للرسول ﷺ، أو للصديق أو للشيخ عبد القادر أو علي ذبيحة أو ذبيحتان للشيخ عبد القادر أو للسيد الحسين أو للبدوي أو للرسول ﷺ  هذا من الشرك الأكبر لأن النذر عبادة، لا ينذر إلا لله وحده سبحانه وتعالى، أو قال: يا رسول الله! أغثني، أو اشف مريضي أو يا سيدي الحسين أو يا علي أو يا فاطمة أو يا سيدي البدوي أو يا فلان أو يا فلان، كل هذا من الشرك الأكبر، لأنه دعوة لغير الله، والله يقول سبحانه في كتابه العظيم: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] (أحدًا) يعم نكرة في سياق النهي تعم الأنبياء وتعم الصالحين وتعم الملائكة وتعم الأصنام عامة، ويقول سبحانه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: المشركين، وجميع المخلوقات لا ينفعون ولا يضرون إلا بالله هو الذي ينفع ويضر ، ويقول : وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] فسمى من دعا غير الله كافرًا، فدل ذلك على أنه من الشرك الأكبر، وقال : ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ [فاطر:13] القطمير: اللفافة التي على النواة على عجمة التمر، وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:13-14] فسماه شركًا، سمى دعاؤهم إياه شركًا ونفى أنهم يسمعون؛ لأنهم ما بين ميت لا يستطيع السمع وما بين ملك مشغول بما هو فيه أو جني مشغول أو لا يعرف شيئًا من ذلك ولا يدري عن شيء من ذلك، أو ميت أو صنم أو شجرة كلها لا تجيب داعيها كل هؤلاء لا يجيبون داعيهم، لا يسمعون ولا يستجيبون وهم مع هذا لو قدر أنهم سمعوا كالملك أو غيره لا يستطيعون أن يجيبوا؛ لأنهم أمرهم بيد الله ، هو مالكهم ومالك غيرهم ، وإذا كانوا أمواتًا فلن يستطيعوا وإذا كانوا جمادًا لن يستطيعوا وإذا كانوا ملائكة أو جنًا فهم لم يشرع لنا أن ندعوهم من دون الله وهم لا يتصرفون إذا كانوا ملائكة إلا بإذن الله، والله لا يأذن لهم أن يعبدوا من دون الله ولا أن يرضوا بذلك، وهكذا الجن المؤمنون لا يرضون بذلك، والكافرون لا يجوز أن يعبدوا فلا يعبد هؤلاء ولا هؤلاء، فالمؤمنون من الجن والإنس لا يرضون بذلك ولو رضوا لكفروا بذلك، والجن لا يرضون بذلك إذا كانوا مؤمنين وأما كفار الإنس وكفار الجن فليسوا أهلًا لأن يعبدوا من دون الله، ولو عبدوا من دون الله لكان عابدهم كافرًا من باب أولى، ولهذا قال سبحانه: وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14] هؤلاء وهؤلاء المعبودون كلهم سيكفرون بشرك العابدين من جن وإنس وملائكة كلهم يكفرون بعبادة عابديهم، فعلم بذلك أن عبادة غير الله من جن أو إنس أو ملائكة أو صنم أو شجر أو غير ذلك كله كفر بالله، كله شرك بالله ، ولهذا يقول سبحانه: وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا ثُمَّ يَقُولُ لِلْمَلائِكَةِ أَهَؤُلاءِ إِيَّاكُمْ كَانُوا يَعْبُدُونَ ۝ قَالُوا سُبْحَانَكَ أَنْتَ وَلِيُّنَا مِنْ دُونِهِمْ بَلْ كَانُوا يَعْبُدُونَ الْجِنَّ أَكْثَرُهُمْ بِهِمْ مُؤْمِنُونَ [سبأ:40-41] قال سبحانه: وَمَنْ أَضَلُّ مِمَّنْ يَدْعُو مِنْ دُونِ اللَّهِ مَنْ لا يَسْتَجِيبُ لَهُ إِلَى يَوْمِ الْقِيَامَةِ وَهُمْ عَنْ دُعَائِهِمْ غَافِلُونَ ۝ وَإِذَا حُشِرَ النَّاسُ كَانُوا لَهُمْ أَعْدَاءً وَكَانُوا بِعِبَادَتِهِمْ كَافِرِينَ [الأحقاف:5-6] نسأل الله العافية.\nفالخلاصة: أنه لا يجوز دعاء غير الله ولا النذر لغير الله ولا الاستغاثة بغير الله، ولا سؤاله شفاء المرضى ولا رد الغياب ولا الرزق ولا غير هذا مما يحتاجه الناس، سواء كانوا أنبياء أو ملائكة أو شجرًا أو صنمًا أو جنًا أو غير ذلك، يجب أن تكون العبادة لله وحده .\nأما كونه يدعو للميت يستغفر له لا بأس إذا كان ميت مسلم، قال: اللهم اغفر لفلان، اللهم اغفر للحسين، اللهم ارض عن الحسين، اللهم اغفر لـأبي بكر اللهم ارض عن أبي بكر أو دعا لغيرهم من الصالحين من المسلمين، هذا مأجور دعاء المسلم لأخيه فيه أجر عظيم وخير كثير، قال الله تعالى عن الصالحين أنهم قالوا: رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالإِيمَانِ [الحشر:10] فالدعاء للميت المسلم والاستغفار له هذا طيب، المنكر أن يدعوهم من دون الله، أن يستغيث به أن ينذر له، أن يسأله الشفاعة أن يسأله شفاء المريض هذا هو المنكر، هذا هو الشرك، أما إذا دعا له قال: اللهم اغفر له، اللهم ارحمه، اللهم ارفع درجته في الجنة اللهم اغفر سيئاته، هذا لا بأس هذا طيب مأمور به. نعم.\nالمقدم: أخونا يسأل سماحة الشيخ عن حكم أولئك الذين يدعون أصحاب القبور؟\nالشيخ: مثل ما تقدم حكمهم أنهم مشركون يعني: إذا دعوا أصحاب القبور أو دعوا الأصنام أو الأشجار أو الأحجار أو الملائكة أو الجن كلها طريقها واحد، كله كفر بالله عز وجل، يستثنى من هذا شيء واحد وهو أنه لا بأس أن يستعين المؤمن بأخيه الحاضر أو بغير المؤمن كما لو اشترى سلعة من كافر أو قال له: يبني هذا المحل أو يصلح السيارة وهو يسمع كلامه ويقدر هذا مستثنى ليس من الشرك، مثل ما قال الله سبحانه في قصة موسى: فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15] فإذا قال الإنسان لأخيه الحاضر أو لغير أخيه من كافر قال له: اصنع لي كذا، أو اعمل لي كذا، أو اعمر لي هذا البيت، أو أصلح لي هذه السيارة أو احرس لي هذه الأرض بكذا وكذا، واتفق معه على شيء لا بأس هذه أمور عادية يقدر عليها المخلوق الحي الحاضر، المنكر أن يدعو غائبًا أو ميتًا أو إنسانًا حي لكن يعتقد فيه السر، أمورًا ما يقدر عليها بطبيعته يعتقد أن له السر وأنه إذا دعي مع الله إذا سئل أن يغفر الذنوب أو سئل أن يدخل الجنة أنه يستطيع هذه الأمور لسر فيه فهذا هو المنكر ولو كان حيًا كمن يعبد من بعض الصوفية شيوخهم وكبارهم ويستغيثون بهم ويطلبونهم شفاء المرضى، هذا من الشرك الأكبر ولو كان حيًا؛ لأنه سأل شيء ليس من طاقته وليس من قدرته، بخلاف إذا قال: سلفني كذا أقرضني كذا، اعمر لي هذه الدار بكذا، أصلح لي هذه الأرض، أصلح هذه السيارة، ناولني هذا المتاع في السيارة.. أمور بين الناس عادية لا بأس بها. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7106/حكم-دعاء-اهل-القبور-والنذر-لهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_172/17210.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":8964,"question":"قال شيخ لمريده الذي يريد أن يدرس في أوروبا قال له وهو يودعه: يا بني! إذا سولت لك نفسك بالمعصية هناك فتذكر شيخك يصرف الله عنك هذا السوء وهذه الفاحشة، فهل هذا شرك بالله؟","title":"حكم الفزع إلى غير الله","answer":"الجواب: هذا منكر عظيم وشرك بالله جل وعلا؛ لأنه فزع إلى الشيخ لينقذه من هذا الشيء، والواجب أن يقول: فاذكر الله واسأل ربك العون والتوفيق واعتصم بالله ونحو ذلك. فأما أن يوصيه بأن يذكر شيخه فهذا من شأن الصوفية يوجهون مريديهم وتلاميذهم على أن يعبدوهم من دون الله ويلجئوا إليهم ويتوكلوا عليهم ويسألوهم قضاء الحاجات وتفريج الكروب، وهذا من تعليمهم الشرك نعوذ بالله من ذلك.\nفالواجب على هذا الشخص أن يتقي الله وأن يفزع إلى الله فيما يهمه ويسأله العون والتوفيق لا إلى شيخه الذي علمه أن يفزع إليه، والله المستعان، ولا حول ولا قوة إلا بالله. نعم.","link":"https://binbaz.org.sa/fatwas/7122/حكم-الفزع-الى-غير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_173/17310.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":8975,"question":"هل يجوز قطع الأشجار المؤذية من المقابر؟","title":"حكم قطع أشجار المقابر المؤذية","answer":"","link":"https://binbaz.org.sa/fatwas/7133/حكم-قطع-اشجار-المقابر-الموذية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_146/14608.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":9133,"question":"وهذه رسالة وصلت إلى البرنامج من الأخ خالد علي من جمهورية السودان الديمقراطية، يقول في رسالته وفي بدايتها: بسم الله الرحمن الرحيم، الحمد لله وحده لا شريك له وأشهد أن محمداً عبده ورسوله، الحمد لله الذي جعل من أمة محمد من يريدون الحق للناس ويردون على من خرب في عقيدة سلفنا الصالح رضوان الله عليهم، أرجو من الأفاضل المشايخ الكرام في برنامج نور على الدرب الإجابة على أسئلتي.السؤال الأول: هل تجوز الصلاة خلف من جوز الدعاء من الأموات، أفيدونا أفادكم الله؟","title":"حكم الصلاة خلف من يدعو الأموات","answer":"الجواب: الذي يُجوز دعاء الأموات يكون مشركاً، فالذي يُجوز أن يُدعى الميت ويقال: المدد المدد يا فلان! أغثني انصرني انصرنا على عدونا أنت تعلم حاجاتنا فأعطنا كذا وكذا هذا يكون مشركاً، ولا يصلى خلفه ولا من يعمل عمله ولا من يرضى عمله ولا خلف من يرضى عمله أيضاً، بل هذا من الشرك الأكبر ومن عمل الجاهلية من جنس عمل أبي جهل وغيره من المشركين؛ لأن الله يقول: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، ويقول سبحانه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: المشركين، ويقول الله : ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:13-14]، سمى دعاءهم إياهم شركاً بالله، قال : وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117].\nوهكذا الذي يدعو الأصنام والأحجار والأشجار والكواكب يستغيث بها أو ينذر لها يسمى مشركاً، فلا يصلى عليه ولا يصلى خلفه ولا يتخذ صاحباً بل يبغض في الله ويعادى في الله سبحانه وتعالى، ولكن ينصح ويوجه ويعلم لعل الله يهديه. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7294/حكم-الصلاة-خلف-من-يدعو-الاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_229/22907.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":9234,"question":"للسائل من تونس أيضاً سؤال آخر في هذه الرسالة يقول فيه: هل أكون خرجت من الإسلام بمجرد قولي عندما نظرت في المرآة: أنا لا يصح أن أكون مسلماً؟","title":"حكم من قال: أنا لا أصلح أن أكون مسلماً","answer":"الجواب: لا تكون خرجت من هذا؛ لأنك تلوم نفسك؛ تلومها على عملك السيئ، وتستقبح منك هذا العمل؛ لأنه عمل الكفار ليس من أعمال المسلمين، كل مسلم يخاف الله يأبى ذلك، فأنت بهذا الكلام تريد أن توبخ نفسك، وأن تستشعر أنك قد فعلت أمراً قبيح العمل قبيح الفعل، فنسأل الله لك التوفيق للتوبة.","link":"https://binbaz.org.sa/fatwas/7398/حكم-من-قال-انا-لا-اصلح-ان-اكون-مسلما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_234/23408.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":9242,"question":"أخيراً يسأل الإخوة أحمد عبدالعزيز وزملائه الذين يعملون بالأردن يقولون: يوجد بقريتنا بمصر ضريح لأحد الأولياء، والناس يأتون إليه ويقدمون إليه النذور والذبائح ويطوفون بالقبر ويتمسحون به ابتغاء البركة، ويقيمون عنده حلقات الذكر، وكل ذلك مع اختلاط النساء بالرجال، ومع ندائهم لصاحب القبر والاستغاثة به، وطلب العون منه، فما الحكم في هؤلاء الناس وفي أفعالهم هذه؟ وما الحكم في المولد لهذا الشيخ ولغيره، أفيدونا أفادكم الله؟","title":"حكم تقديم النذور والذبائح للأولياء ودعائهم والاحتفال بموالدهم","answer":"الجواب: الذي يأتي إلى ضرائح الموتى ويدعوهم، ويسألهم شفاء المرضى أو يطلبهم المدد والعون أو دخول الجنة أو النجاة من النار، أو ينذر لهم أو يذبح لهم أو يطوف بقبورهم يطلب البركة منهم والأجر منهم أو النجاة من النار، أو شفاء المرض، أو سعة الرزق، أو ما أشبه ذلك كله كفر أكبر وشرك أكبر نعوذ بالله، هذا دين المشركين، قال الله جل وعلا: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، قال سبحانه في حق الأصنام والمعبودين من دون الله جميعاً: إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14] ، سماه: شركاً، قال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117]، فسمى دعوة غير الله: كفراً وضلالاً وشركاً.\nوهكذا إقامة الأذكار أو الموالد عند القبر بدعة، فإقامة الحفل عند القبر، بالمولد أو الأذكار أو الحلقات العلمية أو القرآن هذا بدعة، وليس بشرك، أما طلب الحاجات منه، والتمسح بتراب القبر لطلب البركة، أو لطلب شفاء المريض هذا من الكفر الأكبر نسأل الله العافية، ولا حول ولا قوة إلا بالله.\nأما الموالد فكلها بدعة، الاحتفال بالموالد كلها بدعة عند المحققين من أهل العلم؛ لأن الله سبحانه ما شرع لنا ذلك، والرسول ﷺ لم يحتفل بمولده، وهكذا الصحابة رضي الله عنهم لم يحتفلوا بمولد النبي ﷺ، ولا بمولد الصديق ، ولا بمولد عمر ، ولا عثمان ولا علي وهم القدوة، وهم الأخيار فلو كان هذا خيراً لسبقونا إليه.\nفالاحتفال بمولد النبي ﷺ أو المشايخ أو الأمراء أو غيرهم كله بدعة وكله لا يجوز؛ لقول النبي ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد ، ولقوله عليه الصلاة والسلام: من عمل عملاً ليس عليه أمرنا فهو رد أي: مردود، ولقوله: إياكم ومحدثات الأمور، فإن كل محدثة بدعة، وكل بدعة ضلالة.\nوكان يقول في الخطبة عليه الصلاة والسلام، في خطبة الجمعة، يقول عليه الصلاة والسلام: إن خير الحديث كتاب الله، وخير الهدي هدي محمدٍ صلى الله عليه وسلم ، وشر الأمور محدثاتها، وكل بدعة ضلالة ، فالواجب على أهل الإسلام أن يحذروا هذه البدع، وأن يبتعدوا عنها، وإذا كان فيها اختلاط بين الرجال والنساء صار الأمر أكبر، صارت الفتنة أعظم، صار الإثم أكثر، فإن الاختلاط بين الرجال والنساء عند القبر، أو في أي احتفال منكر، ومن أسباب الزنا والفواحش، ومن أسباب ركوب المحارم، فالواجب الحذر من ذلك حتى في غير الاحتفال، حتى في الولائم الأخرى، لا يجوز أن يجتمع الرجال والنساء في حفلة، ويختلطوا في حفلة عرس، أو في حفلة أي حفلة؛ لأن هذا يسبب فتنة للرجال، من الرجال بالنساء، والنساء بالرجال، الواجب التمييز وأن يكون اجتماع النساء على حدة، واجتماع الرجال على حدة في الولائم، وفي الاحتفالات الجائزة شرعاً من الأعراس وغيرها. نعم.\nالمقدم: بارك الله فيكم، وجزاكم الله خير.\nالشيخ: الله المستعان.","link":"https://binbaz.org.sa/fatwas/7406/حكم-تقديم-النذور-والذباىح-للاولياء-ودعاىهم-والاحتفال-بموالدهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_235/23505.mp3","categories":["نواقض الإسلام","البدع والمحدثات"]},{"id":9253,"question":"أخيراً يسأل الإخوة أحمد عبدالعزيز وزملائه الذين يعملون بالأردن يقولون: يوجد بقريتنا بمصر ضريح لأحد الأولياء، والناس يأتون إليه ويقدمون إليه النذور والذبائح ويطوفون بالقبر ويتمسحون به ابتغاء البركة، ويقيمون عنده حلقات الذكر، وكل ذلك مع اختلاط النساء بالرجال، ومع ندائهم لصاحب القبر والاستغاثة به، وطلب العون منه، فما الحكم في هؤلاء الناس وفي أفعالهم هذه؟ وما الحكم في المولد لهذا الشيخ ولغيره، أفيدونا أفادكم الله؟","title":"حكم تقديم النذور والذبائح للأولياء ودعائهم والاحتفال بموالدهم","answer":"الجواب: الذي يأتي إلى ضرائح الموتى ويدعوهم، ويسألهم شفاء المرضى أو يطلبهم المدد والعون أو دخول الجنة أو النجاة من النار، أو ينذر لهم أو يذبح لهم أو يطوف بقبورهم يطلب البركة منهم والأجر منهم أو النجاة من النار، أو شفاء المرض، أو سعة الرزق، أو ما أشبه ذلك كله كفر أكبر وشرك أكبر نعوذ بالله، هذا دين المشركين، قال الله جل وعلا: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، قال سبحانه في حق الأصنام والمعبودين من دون الله جميعاً: إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14] ، سماه: شركاً، قال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117]، فسمى دعوة غير الله: كفراً وضلالاً وشركاً.\nوهكذا إقامة الأذكار أو الموالد عند القبر بدعة، فإقامة الحفل عند القبر، بالمولد أو الأذكار أو الحلقات العلمية أو القرآن هذا بدعة، وليس بشرك، أما طلب الحاجات منه، والتمسح بتراب القبر لطلب البركة، أو لطلب شفاء المريض هذا من الكفر الأكبر نسأل الله العافية، ولا حول ولا قوة إلا بالله.\nأما الموالد فكلها بدعة، الاحتفال بالموالد كلها بدعة عند المحققين من أهل العلم؛ لأن الله سبحانه ما شرع لنا ذلك، والرسول ﷺ لم يحتفل بمولده، وهكذا الصحابة رضي الله عنهم لم يحتفلوا بمولد النبي ﷺ، ولا بمولد الصديق ، ولا بمولد عمر ، ولا عثمان ولا علي وهم القدوة، وهم الأخيار فلو كان هذا خيراً لسبقونا إليه.\nفالاحتفال بمولد النبي ﷺ أو المشايخ أو الأمراء أو غيرهم كله بدعة وكله لا يجوز؛ لقول النبي ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد ، ولقوله عليه الصلاة والسلام: من عمل عملاً ليس عليه أمرنا فهو رد أي: مردود، ولقوله: إياكم ومحدثات الأمور، فإن كل محدثة بدعة، وكل بدعة ضلالة.\nوكان يقول في الخطبة عليه الصلاة والسلام، في خطبة الجمعة، يقول عليه الصلاة والسلام: إن خير الحديث كتاب الله، وخير الهدي هدي محمدٍ صلى الله عليه وسلم ، وشر الأمور محدثاتها، وكل بدعة ضلالة ، فالواجب على أهل الإسلام أن يحذروا هذه البدع، وأن يبتعدوا عنها، وإذا كان فيها اختلاط بين الرجال والنساء صار الأمر أكبر، صارت الفتنة أعظم، صار الإثم أكثر، فإن الاختلاط بين الرجال والنساء عند القبر، أو في أي احتفال منكر، ومن أسباب الزنا والفواحش، ومن أسباب ركوب المحارم، فالواجب الحذر من ذلك حتى في غير الاحتفال، حتى في الولائم الأخرى، لا يجوز أن يجتمع الرجال والنساء في حفلة، ويختلطوا في حفلة عرس، أو في حفلة أي حفلة؛ لأن هذا يسبب فتنة للرجال، من الرجال بالنساء، والنساء بالرجال، الواجب التمييز وأن يكون اجتماع النساء على حدة، واجتماع الرجال على حدة في الولائم، وفي الاحتفالات الجائزة شرعاً من الأعراس وغيرها. نعم.\nالمقدم: بارك الله فيكم، وجزاكم الله خير.\nالشيخ: الله المستعان.","link":"https://binbaz.org.sa/fatwas/7406/حكم-تقديم-النذور-والذباىح-للاولياء-ودعاىهم-والاحتفال-بموالدهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_235/23505.mp3","categories":["نواقض الإسلام","البدع والمحدثات"]},{"id":9349,"question":"من بيشة وصلت إلى البرنامج رسالة وباعثها أحد الإخوة من هناك، يقول علي صنيع الشهراني أخونا يقول: نستعمل كلمة بالعون للتأكيد على الشيء، ويقال: بأن بالعون هذا اسم صنم كان يعبده المشركون ويقال: إنه في منطقة بيشة تبالة، فهل نقع في الشرك إذا كررنا ذلكم اللفظ؟","title":"حكم استعمال كلمة (بالعون) في التأكيد والحلف","answer":"الجواب: هذه كلمة جارية على ألسنة كثير من الأعراب وغيرهم، وما أعرف أصلها، هل أصلها أن هناك صنمًا يسمى بهذا الاسم أم لا، ولكن بكل حال ينبغي تركها؛ لأن الحلف يكون بالله وحده، يقول: بالله، أو بالرحمن، أو بربي، أو بربنا جميعًا أو ما أشبه ذلك ويترك كلمة بالعون، لا حاجة إليها؛ لأن العون كلمة لا يعرف معناها بالنسبة إلى من يحلف بها، وهي اسم مصدر من أعان يعين عونًا، اسم مصدر من أعان، فالأفضل بل يجب ترك ذلك؛ لأن الحلف بهذا الفعل وهو العون لا يجوز داخل في الحديث: من حلف بغير الله فقد أشرك وداخل في الحديث الآخر: من كان حالفًا فلا يحلف إلا بالله أو ليصمت مثل قول بعضهم: بالحيل؟ قول بعض الناس: بالحيل، هو مثل هذا ينبغي تركه ولا يجوز فعله؛ لأن هذا نوع من الحلف؛ لأنهم يقصدون به التأكيد للكلام، بالحيل، بالعون، فينبغي ترك هذه الكلمات. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7507/حكم-استعمال-كلمة-بالعون-في-التاكيد-والحلف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_185/18505.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":9369,"question":"أخ مصري يسأل ويقول: يوجد في بلدتنا رجل متوفى صالح ويبنى له مقام على قبره، وله عادة عندنا في كل عام نذهب مع الناس إليه رجالاً ونساء ويقيمون عنده ثلاثة أيام بالمدح والتهاليل والأذكار، ويستمر في الأوصاف المعروفة سماحة الشيخ ويرجو التوجيه والإرشاد جزاكم الله خيراً؟","title":"حكم زيارة القبور والمكوث فيها للأكل والشرب وقراءة الأذكار","answer":"الجواب: هذا العمل لا يجوز بل هو من البدع التي أحدثها الناس، فلا يجوز أن يقام على قبره بناء سواء سمي مقاماً أو سمي قبة أو سمي غير ذلك، كانت القبور في عهد النبي ﷺ وعهد الصحابة مكشوفة ليس عليها بناء، والنبي ﷺ نهى أن يبنى على القبر وأن يجصص وقال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد متفق على صحته، وقال جابر بن عبد الله الأنصاري : نهى رسول الله ﷺ أن يجصص القبر وأن يقعد عليه وأن يبنى عليه فالبناء على القبور منكر وهكذا تجصيصها ووضع الزينات عليها أو الستور كله منكر ووسيلة إلى الشرك، فلا يجوز وضع القباب أو الستور أو المساجد عليها.\nوهكذا زيارتها على الوجه الذي ذكره السائل من الجلوس عندها والتهاليل وأكل الطعام والتمسح بالقبر أو الدعاء عند القبر أو الصلاة عند القبر كل هذا منكر، كله بدعة لا يجوز، إنما المشروع زيارة القبور كونه يزورها ويدعو لهم ثم ينصرف، يمر على القبور ويقول: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين. وما أشبه من الدعوات فقط، هذا هو المشروع الذي علمه النبي أصحابه عليه الصلاة والسلام كان يعلمهم إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، وحديث عائشة: يرحم الله المستقدمين منا والمستأخرين، وحديث ابن عباس: السلام عليكم يا أهل القبور، يغفر الله لنا ولكم، أنتم سلفنا ونحن بالأثر، هذا المشروع.\nوأما الإقامة عند القبر للأكل والشرب أو للتهاليل أو للصلاة أو لقراءة القرآن كل هذا منكر، يسلم ويذهب، ويدعو للميت ويترحم عليه، أما اتخاذه محل دعاء أو محل قراءة أو محل طواف أو محل تهاليل والجلوس عنده، أو أكل يوم أو يومين أو ثلاثة هذا ماله أصل، هذا بدعة ومن وسائل الشرك فيجب الحذر من ذلك ويجب ترك ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7533/حكم-زيارة-القبور-والمكوث-فيها-للاكل-والشرب-وقراءة-الاذكار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_156/15608.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":9375,"question":"هل صلاة التسابيح واردة في السنة النبوية، وما الحكم في قائل يقول.. -أو نغفل هذا السؤال سؤال الواقع ربما يكون سيئ سماحة الشيخ-؟الشيخ: لا، لا، هاته لا بأس.المقدم: نعم.الشيخ: لا بأس.المقدم: يقول عليه الطلاق من دينه؟الشيخ: أيش؟المقدم: يسأل عن سائل قال تلكم العبارة؟","title":"حكم من قال عليه الطلاق من دينه","answer":"الجواب: هذا على كل حال كلام منكر، أما صلاة التسابيح فقد اختلف فيها العلماء من صحح حديثها، ومنهم من ضعف أحاديثها، والصواب: أنها ضعيفة وأنها لا تشرع ولا تستحب، هذا الصواب في صلاة التسبيح. وأما هذا الذي قال: عليه الطلاق من دينه ما يفعل كذا وكذا، معناه: عليه الخروج من دينه، وهذا كلام منكر، يقول النبي ﷺ: من حلف بملة غير الإسلام كاذبًا متعمدًا فهو كما قال فالمقصود: أن هذا يجب عليه أن يتوب إلى الله، وأن يحذر مثل هذا الكلام، لا يقول عليه الطلاق من دينه، أو هو كافر أو هو يهودي أو نصراني ما يفعل كذا، أو سوف يفعل كذا أو ما أشبه ذلك، لا، يستعمل غير هذا، يقول: والله لأفعلن كذا، أو والله ما أفعل كذا، يكفي هذا، أما أن يقول: هو يهودي أو نصراني أو عليه الطلاق من دينه إنه ما يفعل كل هذا غلط ومنكر لا يجوز، وتعريض لدينه للذهاب والضياع والردة عن الإسلام نعوذ بالله، فيجب الحذر والتوبة من هذا نسأل الله العافية. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7539/حكم-من-قال-عليه-الطلاق-من-دينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/18613.mp3","categories":["الأيمان والنذور","نواقض الإسلام"]},{"id":9411,"question":"نسمع الكثير من الحجاج وغيرهم إذا دخلوا المسجد النبوي نادى رسول الله ﷺ بقوله: يا رسول الله! أتيتك من بلاد كذا وكذا فاشف مريضي واقض حاجتي وارزقني كذا وكذا إلى آخره، فما هو توجيه سماحتكم لهؤلاء أعزكم الله؟","title":"حكم الاستغاثة بالنبي عند زيارة المسجد النبوي","answer":"الجواب: الزيارة للمسجد النبوي سنة وقربة وطاعة ويشد لها الرحال، لقوله ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام ومسجدي هذا والمسجد الأقصى فهذه الثلاثة المساجد هي أفضل مساجد الدنيا ولهذا شرع الله شد الرحال لها للعبادة، المسجد الحرام للحج والعمرة والصلاة فيه والقراءة والاعتكاف، والمسجد النبوي للصلاة فيه والقراءة والذكر والاعتكاف والتعلم والتعليم كما في المسجد الحرام، لكن يختص المسجد الحرام بالطواف؛ لأن الله شرع الطواف به ويقصد لأداء الحج والعمرة أما المسجد النبوي فيقصد لما يقصد في بقية المساجد من الصلاة فيه والقراءة فيه والذكر والاعتكاف ونحو ذلك، لقول النبي ﷺ: صلاة في مسجدي هذا خير من ألف صلاة فيما سواه إلا المسجد الحرام، وصلاة في المسجد الحرام أفضل من صلاة في مسجدي هذا بمائة صلاة فهذا فضل عظيم، والسنة للزائر إذا زار المسجد أن يسلم على النبي ﷺ وعلى صاحبيه، يقف على قبره وقبر صاحبيه ويسلم على الجميع عليه الصلاة والسلام، فيقف أمام القبر الشريف ويقول: السلام عليك يا رسول الله ورحمة الله وبركاته، أشهد أنك قد بلغت الرسالة وأديت الأمانة ونصحت الأمة وجاهدت في الله حق جهاده، فجزاك الله عن أمتك أفضل الجزاء وأحسنه. وإن اكتفى بالسلام فقط وانصرف فلا بأس، ثم يأخذ عن يمينه قليلاً فيسلم على الصديق ويقول: السلام عليك يا أبا بكر الصديق ورحمة الله وبركاته جزاك الله عن أمة محمد خيراً ورضي الله عنك فلقد نصحت وأديت الأمانة.. ونحو ذلك، وهكذا ينحرف قليلاً عن يمينه أيضاً ويسلم على عمر الفاروق  كما سلم على الصديق ويدعو له رضي الله عن الجميع، هذا السنة.\nأما أن يناديه من قريب أو من بعيد يقول: يا رسول الله! أغثني أو اشف مريضي أو جئتك من بلاد بعيدة لتشفيني أو لتعطيني كذا وكذا، هذا هو الشرك الأكبر هذا لا يجوز لا مع النبي ﷺ ولا مع غيره ولا مع الصديق ولا مع عمر ولا مع أي أحد من الناس؛ لأن العبادة حق الله وحده، والدعاء هو العبادة فلا يجوز صرفه لغير الله كائناً من كان والأموات لا يسألون ولا يدعون ولا يستغاث بهم سواء كانوا من الأنبياء أو من غير الأنبياء، فالواجب إخلاص العبادة لله وحده كما قال الله سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] وقال سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] وقال سبحانه: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] فقوله: (أحداً) نكرة في سياق النهي تعم الأنبياء وتعم الصالحين وتعم الأصنام والأشجار والملائكة وغير ذلك: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] يعني: كائناً من كان، وهكذا قوله سبحانه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتََ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: المشركين، وكل من سوى الله لا ينفع ولا يضر، فالله سبحانه هو النافع الضار وهو الذي يجعل المنفعة فيمن يشاء ويسلبها عمن يشاء ويجعل المضرة فيمن يشاء ويسلبها عمن يشاء، هو سبحانه النافع الضار المعطي المانع القوي العزيز جل وعلا، فهو الذي يسأل ويطلب ، فإذا جئت إلى رسول الله للسلام عليه أو إلى أي مقبرة للسلام على القبور والدعاء لهم فاحذر أن تدعوهم مع الله، لا تقول: يا سيدي فلان اشف مريضي أو اقض حاجتي أو أنا في حسبك أو أنا في جوارك أو قد جئتك قاصداً لك لتغفر لي أو لترحمني أو لتشفي مريضي أو لتسهل كربتي لا مع النبي ﷺ ولا مع غيره، هذا حق الله سبحانه وتعالى ولكن تسلم على الرسول ﷺ وعلى صاحبيه وتترضى عنهما وتصلي على رسول الله ﷺ وتشهد له بأنه بلغ الرسالة أدى الأمانة نصح الأمة هذا حق، أما الزيادة على هذه بأن تقول: يا رسول الله! اشفع لي أو انصرني أو اشف مريضي أو أنا في جوارك أو أنا في حسبك أو أنا مظلوم فانصرني أو أمتك قد أصابها ما أصابها فانصرها أو اشفها مما أصابها أو ما أشبه ذلك فهذا لا يجوز، هذا من الشرك بالله ، ولكن هذا يطلب من الله تطلب في صلاتك في المسجد النبوي وغيره في بيتك، تقول: يا ربي انصرني، يا ربي أصلح أمة محمد يا ربي وفقهم يا ربي اجمع كلمتهم على الحق يا ربي احمهم من شر أعدائهم يا ربي اغفر لي يا ربي اشفي مريضي، هذا بينك وبين الله سبحانه وتعالى في المساجد في الصلاة في غير ذلك، أما المخلوق وإن كان نبياً لا يملك هذا كله بيد الله ، يقول الله سبحانه لنبيه ﷺ لما قنت مدة من الزمن يدعو على أحياء من العرب أنزل الله في حقه: لَيْسَ لَكَ مِنَ الأَمْرِِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ [آل عمران:128] فالأمر لله ، هو الذي بيده الهداية والإضلال والضر والنفع والعطاء والمنع وغير ذلك، كله بيده سبحانه وتعالى هو المالك لكل شيء والشفاعة حق لله : قُلْ لِلَّهِ الشَّفَاعَةُ جَمِيعًا [الزمر:44] ملك له  يعطيه من يشاء، وقد أخبر رسوله ﷺ أن الله يشفعه يوم القيامة، ما في حاجة إلى أن تسأله أنت وهو في قبره، إذا كان يوم القيامة إن كنت من أهل الجنة دخلت في شفاعته وكذلك يشفع في أهل الموقف يقضى بينهم وأنت منهم، فلا حاجة إلى أن تسأله ...... تسألها الله، تقول: اللهم شفع في نبيك اللهم اجعلني من أهل شفاعته اللهم اجزه عنا خيراً وما أشبه ذلك أما أنتطلبها من النبي صلى الله عليه وسلم فلا، أما في حياته فلا بأس إن كان حياً بين الناس عليه الصلاة والسلام تقول: يا رسول الله! اشفع لي أن الله يهديني أن الله يرزقني، كان يشفع لأصحابه، ولما أصابهم الجدب والقحط في بعض السنوات أتى بعضهم إليه وهو يخطب يوم الجمعة فقال: يا رسول الله! هلكت الأموال وانقطعت السبل فادع الله أن يغيثنا، فرفع يديه عليه الصلاة والسلام وقال: اللهم أغثنا اللهم أغثنا اللهم أغثنا فأنشأ الله السحاب ثم أمطر، فخرج الناس في المطر كل يهم نفسه أن يصل إلى بيته ولم يزل المطر إلى الجمعة الأخرى ثم جاء ذلك الرجل أو غيره في الجمعة الأخرى وقال: يا رسول الله! هلكت الأموال وانقطعت السبل فادع الله أن يمسكه عنا،، فرفع يديه صلى الله عليه وسلم وقال: اللهم حوالينا ولا علينا، اللهم على الآكام والظراب وبطون الأودية ومنابت الشجر فانقشع السحاب ووقف المطر عن المدينة وأجاب الله دعوته في الحال في الأولى والأخرى عليه الصلاة والسلام وذلك من علامات نبوته وأنه رسول الله حقاً عليه الصلاة والسلام، ففي حياته لا مانع أن يطلب منه أن يستغيث للمسلمين أن يشفع لهم، وهكذا يوم القيامة وهو بين أظهرهم يوم القيامة يتوجه إليه المؤمنون ويسألونه أن يشفع حتى يريح الله الناس من هول موقف وحتى يقضي بينهم ثم يطلب الله أيضاً لهم للمؤمنين أن يدخلوا الجنة يشفع إلى الله سبحانه في دخول أهل الجنة الجنة، هذا حق جاءت به النصوص.\nأما وهو في قبره بعد البرزخ بعدما مات عليه الصلاة والسلام فإنه لا يطلب منه شيء بل يصلى عليه عليه الصلاة والسلام وتتبع سنته ويعظم أمره ونهيه، أما أن يسأل شفاء المرضى أو قضاء الحاجات عند قبره أو في أي بلد فهذا هو الذي لا يجوز، هذا هو الشرك الأكبر الذي حرمه الله على عباده في قوله سبحانه: إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ [لقمان:13] وفي قوله : إِنَّهُ مَنْ يُشْرِكْ بِاللَّهِ فَقَدْ حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ وَمَأْوَاهُ النَّارُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ [المائدة:72] وفي قوله سبحانه: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُواا يَعْمَلُونَ[الأنعام:88] وفي قوله : إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] فالواجب على كل مكلف وعلى كل إنسان أن ينتبه لهذا الأمر سواء كان حاجاً أو غير حاج فليحذر الاستغاثة بالأنبياء أو بالصالحين أو بالملائكة أو بالجن في أي مكان بل يجعل دعاءه لله وحده ويخص ربه بالدعاء والاستغاثة ويلجأ إليه سبحانه ويسأله قضاء حاجاته وتفريج كروبه فهو سبحانه القادر على كل شيء جل وعلا، أما الأنبياء والملائكة والجن وسائر الخلق فليس في أيديهم شيء، الملك لله وحده سبحانه وتعالى هو المالك لكل شيء جل وعلا: لِلَّهِ مُلْكُ السَّمَوَاتِ وَالأَرْضِ وَمَا فِيهِنَّ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ [المائدة:120] ، فاتق الله يا عبد الله واحذر ما حرم الله عليك وانصح من معك من إخوانك وبين لهم ما شرع الله لهم في الحج وفي غيره وحذرهم مما حرم الله عليهم وهكذا النساء يعلمن ويوجهن إلى ما يرضي الله ويقربهن إليه ويبين لهن أيضاً ما شرع الله لهن في الحج حتى يكون الجميع على بصيرة في حجهم وفي زيارتهم للمسجد النبوي على صاحبه أفضل الصلاة والسلام.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7576/حكم-الاستغاثة-بالنبي-عند-زيارة-المسجد-النبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_159/15902.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":9476,"question":"وهذا سؤال ورد في رسالة لمستمع رمز لاسمه بـ (ر. ح. ع) مصري الجنسية مقيم بالخبر، سبق أن عرضنا بعض رسالته في حلقة مضت، وسؤاله الثاني في هذه الرسالة يقول فيه: كنت جالساً مع إخوة لي من أبناء وطني من صعيد مصر، فقالوا لي: يوجد عندنا مقام لـأبي الحسن الشاذلي من طاف به سبعة أشواط كانت له عمرة، ومن طاف به عشر مرات كانت له حجة ولا يلزمه الذهاب إلى مكة، فقلت لهم: هذا الفعل كفر بل شرك نعوذ بالله، فهل أنا مصيب؟ وبماذا تنصحون من ينخدع بذلك؟","title":"حكم الطواف بقبور الأولياء والصلاة عندها","answer":"الجواب: نعم نعم قد أحسنت، لا يجوز الطواف بقبور الناس، لا بقبور أبي الحسن الشاذلي ، ولا بقبر البدوي ، ولا بقبر الحسين ، ولا الست زينب ، ولا الست نفيسة ولا غيره، الطواف يكون بالكعبة خاصة، لا يجوز الطواف بغير الكعبة أبداً، وإذا طاف بقبر أبي الحسن الشاذلي أو مقامه يتقرب إليه بالطواف صار شركاً أكبر، وليس يقوم مقام حجة ولا مقام عمرة، بل هو كفر وضلال ومنكر عظيم وفيه الإثم العظيم، فإن كان طاف يحسب أنه مشروع ويطوف لله لا لأجل أبي الحسن هذا يكون بدعة ومنكر، وإذا كان طوافه من أجل أبي الحسن من أجل التقرب إليه هو شرك أكبر نعوذ بالله، وهكذا دعاؤه والاستغاثة بـأبي الحسن الشاذلي أو النذر له، أو الذبح له كله كفر أكبر نعوذ بالله، وهكذا الحلف بـأبي الحسن أو بغيره، الحلف بالنبي أو بـالحسن أو بـالحسين أو بـفاطمة أو بالكعبة أو بالأمانة أو بحياة فلان أو شرفه كله لا يجوز، الحلف بغير الله لا يجوز، يقول النبي ﷺ: من كان حالفاً فلا يحلف إلا بالله أو ليصمت، ويقول ﷺ: من حلف بغير الله فقد كفر، وفي لفظ: فقد أشرك، وفي لفظ آخر: قد كفر أو أشرك، وقال ﷺ: من حلف بالأمانة فليس منا، وقال: لا تحلفوا بآبائكم ولا بأمهاتكم ولا بالأنداد، فالحلف يكون بالله وحده؛ لأنه تعظيم لا يليق إلا بالله وحده، فالحلف بغير الله من الشرك الأصغر، وقد يكون أكبر إذا حصل في قلبه من التعظيم للمخلوق، ما هو من جنس تعظيم الله يكون كفراً أكبر، فالدعاء والاستغاثة بالأموات والنذر لهم والذبح لهم والتوكل عليهم، أو اعتقاد أنهم يعلمون الغيب أو أنهم يتصرفون في الكون، أو يعلمون ما في نفوس أصحابهم، والداعين لهم والطائفين بالقبور كل هذا شرك أكبر نعوذ بالله، فالغيب لا يعلمه إلا الله سبحانه لا يعلمه لا الأنبياء ولا غيرهم، وإنما يعلمون من الغيب ما علمهم الله إياه، يقول سبحانه: قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ [النمل:65]، فمن زعم أن شيخه يعلم الغيب، أو أنه يعلم ما في نفس زائره وما في قلب زائره فهذا كفر أكبر نعوذ بالله، فالغيب لله وحده ، وكذلك إذا عكف على القبر يطلب فضل صاحب القبر يطلب أنه يثيبه، أو أنه يدخله الجنة بجلوسه عند قبره، أو بقراءته عند قبره، أو باستغاثته به، أو نذره له، أو صلاته عنده أو نحو ذلك هذا كفر أكبر.\nفالحاصل أن الواجب على المؤمن أن يحذر الشرك كله وأنواعه. القبور إنما تؤتى للزيارة، يزورها المؤمن للدعاء لهم والترحم عليهم، فيقول: السلام عليكم دار قوم مؤمنين وإنا إن شاء الله بكم لاحقون، يغفر الله لنا ولكم، يرحم الله المستقدمين منا والمستأخرين، نسأل الله لنا ولكم العافية، هكذا، أما أن يدعوهم مع الله أو يستغيث بهم هذا كفر أكبر، أو ينذر لهم، أو يتقرب إليهم بالذبائح به بالبقر بالإبل بالغنم بالدجاج، كل هذا كفر أكبر نعوذ بالله، فالواجب الحذر والواجب التفقه في الدين، المسلم عليه أن يتفقه في دينه حتى لا يقع في الشرك والمعاصي، وعلماء السوء علماء الضلالة يضرون الناس ويغشونهم، فالواجب على علماء الحق أن يتقوا الله، وأن يعلموا الناس، وأن يرشدوا الناس من طريق الإذاعة، من طريق الكتابة والصحافة، من طريق التلفاز، يعلموا الناس دينهم، يرشدونهم إلى الحق حتى لا يعبدوا الأموات ولا يستغيثوا بهم، حتى لا يطوفوا بقبورهم، حتى لا يتمسحوا بها، حتى لا ينذروا لها، القبور تزار للذكرى لذكر الآخرة، ذكر الموت، للدعاء للميت والترحم عليه، أما أنه يطاف بقبره، أو يدعى من دون الله، أو يستغاث به، أو يجلس عنده للصلاة أو للقراءة هذا لا، لا يجوز، والجلوس عند قبره للصلاة عنده أو القراءة عنده بدعة، وإذا كان يصلي له كان كفر أكبر، فإن صلى لله أو قرأ لله يطلب الثواب من الله، ولكن يرى أن القبور محل جلوس عندها أي بهذه العبادات صار بدعة، فالقبور ما هي بمحل جلوس للصلاة ولا للقراءة، ولكنها تزار للدعاء، لدعاء الأموات يدعى لهم، يترحم عليهم، مثلما زارهم النبي صلى الله عليه وسلم وزارهم الصحابة رضي الله عنهم، كان النبي ﷺ يقول يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين، وكان يقول إذا زار البقيع: اللهم اغفر لأهل بقيع الغرقد ويترحم عليهم هذه هي الزيارة الشرعية، فيجب الحذر مما حرم الله، مما أحدثه عباد القبور وأحدثه الجهال الذي يضر ولا ينفع، بل يوقع أصحابه في الشرك الأكبر، ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7642/حكم-الطواف-بقبور-الاولياء-والصلاة-عندها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_241/24105.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":9534,"question":"وهذه رسالة وردتنا من المرسل حاتم ظاهر من الجمهورية العراقية يقول: هل زيارة الإمام أو السيد تعتبر ذنب على الزائر إذا قبل الشباك أو باب الغرفة أو الضريح للإمام؟ وما الحكم في كلام الزائر أثناء هذه الزيارة كأن يقول للإمام: أنا دخيل عليك أن تنقذني من هذه القصة أو غير ذلك أفيدونا أفادكم الله؟","title":"حكم تقبيل الأضرحة عند زيارتها والاستغاثة بأهلها","answer":"الجواب: زيارة القبور سنة مؤكدة للرجال إذا كان المقصود منها الدعاء للميت والترحم عليه والاستغفار له، كما كان النبي يزور القبور عليه الصلاة والسلام وكان أصحابه يزورون القبور، وقال لهم ﷺ: زوروا القبور فإنها تذكركم الآخرة فالزيارة فيها خير عظيم ومصالح تذكر الإنسان الآخرة تذكره الموت يدعو لإخوانه الأموات يستغفر لهم يترحم عليهم هذه الزيارة الشرعية، كان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون نسأل الله لنا ولكم العافية وفي حديث عائشة: يرحم الله المستقدمين منا والمستأخرين.\nهذه هي الزيارة الشرعية، أما كونه يدعو الميت يقول: أنا دخيلك أو اشفني من مرضي أو خلصني من كذا هذا شرك أكبر.. هذا لا يجوز لا مع أمام ولا مع غير إمام لا مع النبي ولا مع الإمام أبي حنيفة ولا مع غيرهم لا يجوز أن يقال هذا للأموات، لا يقل للميت: أنا في جوارك أن في حسبك اغفر لي أو انصرني أو اشف مريضي أو رد غائبي أو خلصني من هذه الكربة التي أنا فيها أو ما أشبه ذلك هذا لا يقال ولا يجوز، بل هذا من خصاص الله  لا يقال للميت ولا للجماد كالصنم ولا للجن ولا للملائكة بل هذا يطلب من الله ، فالذي يتعاطى هذه الأمور مع أصحاب القبور قد فعل الشرك الأكبر الذي حذر الله منه عباده وأنزل الكتب في حقه وأرسل الرسل لأجل ذلك، قال : كِتَابٌ أُحْكِمَتْ آيَاتُهُ ثُمَّ فُصِّلَتْ مِنْ لَدُنْ حَكِيمٍ خَبِيرٍ ۝ أَلَّا تَعْبُدُوا إِلَّا الله [هود:1-2] وقال سبحانه: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] قال : وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِ اُعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ [النحل:36].\nفالعبادة حق الله سبحانه وتعالى فليس للعبد أن يطلب شفاء المرض أو رد الغائب أو التخليص من الكرب من الأموات أو من الأصنام أو من الكواكب أو من الأشجار والأحجار أو من الجن أو من الملائكة كل هذا لا يجوز بل هو شرك أكبر.\nوإنما الزيارة الشرعية مثل ما تقدم أن يزور القبور ويسلم عليهم ويقول: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لا حقون نسأل الله لنا ولكم العافية ويغفر الله لنا ولكم يرحم الله المستقدمين منا والمستأخرين وما أشبه ذلك، دعاء لهم وترحم عليهم وعلى الزائر نفسه هذا هو المشروع.\nوأما تقبيل الشباك أو تقبيل القبر أو التمسح به هذا كله لا يجوز، ولكن يقف عند القبر ويسلم فقط. ولا يجوز البناء على القبور ولا اتخاذ المساجد عليها ولا القباب كل هذا مما أحدثه الناس، الرسول ﷺ قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وقال عليه الصلاة والسلام: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك وقال جابر : نهى النبي ﷺ عن تجصيص القبور والقعود عليها والبناء عليها تجصيص القبور أو البناء عليها أو اتخاذها مساجد كله منكر كله لا يجوز، ومن أسباب الغلو فيها وعبادتها من دون الله.\nفالواجب على الزائر أن يتقيد بالأمر الشرعي وأن يبتعد عما حرم الله عليه، فيزورها كما زارها النبي ﷺوالمسلمون للدعاء للميت والترحم عليه والاستغفار له، أما دعاؤه هو دعاء الميت نفسه والاستغاثة به والنذر له أو التدخل به عن كذا وكذا هذا كله لا يجوز وكله من الشرك بالله ، وهكذا الجلوس عند القبر يدعو الله أو يصلي عند القبر هذا لا يجوز أيضاً بل يجب الحذر من ذلك؛ لأن هذا من وسائل الشرك فدعاء الميت شرك أكبر والاستغاثة به والاستشفاع به ونحو ذلك هذا من الشرك الأكبر، والجلوس عنده للدعاء والصلاة من البدع ومن وسائل الشرك، وهكذا البناء على القبور واتخاذ القباب عليها واتخاذ المساجد كله من البدع وكله من وسائل الشرك ومن ذرائعه، فالواجب على المسلمين أن يحذروا ذلك وأن يعيدوا القبور على حالها الأولى يزيلون ما عليها من مساجد ومن قباب، وعليهم أن يتركوها كما كانت في عهد النبي ﷺ وعهد أصحابه ضاحية تحت الشمس ليس عليها قبة ولا مسجد ولا غير ذلك، هذا هو المشروع وهذا هو الواجب، نسأل الله العافية والسلامة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7696/حكم-تقبيل-الاضرحة-عند-زيارتها-والاستغاثة-باهلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_245/24508.mp3","categories":["نواقض الإسلام","البدع والمحدثات"]},{"id":9553,"question":"وهذا سؤال وردنا من سوريا من بلدة الرقة من المرسل حميد سلطان يقول في رسالته: كثيراً ما تحلم بعض النساء أنه جاءها رجل وقال لها: اذبحوا لله وللخضر ذبائح وإلا فيقبل عليكم مرض، ويقولون أيضاً: إن الذي لا يذبح تنقص عائلته بالموت. أفيدونا أفادكم الله؟","title":"حكم الأحلام التي تحث على دعاء الأولياء والذبح لهم","answer":"الجواب: هذا الحلم وأشباهه من الشيطان، يقول النبي ﷺ في الحديث الصحيح: الرؤيا الصالحة من الله والحلم من الشيطان، فإذا رأى أحدكم ما يكره فلينفث عن يساره ثلاث مرات وليتعوذ بالله من الشيطان ومن شر ما رأى ثلاث مرات، ثم ينقلب على جنبه الآخر فإنها لا تضره ولا يخبر بها أحدًا هذه الرؤيا من الشيطان، فإذا رأت المرأة أو الرجل مثل هذا الحلم، أو رأى أنه يضرب أو يهدد بقتل أو في محل مخوف كل هذا من الشيطان، فعليه أن ينفث عن يساره إذا استيقظ ينفث عن يساره ثلاث مرات، يعني: يتفل عن يساره ثلاث مرات بريق خفيف ويقول: أعوذ بالله من الشيطان ومن شر ما رأيت ثلاث مرات، ثم ينقلب على جنبه الآخر فإنها لا تضره ولا يخبر بها أحداً.\nوالذبح لله عبادة في أي وقت، إذا ذبح لله عبادة وتصدق بها لا بأس، أما الذبح للخضر فهذا منكر وهو ذبح لغير الله لا يجوز، الله يقول سبحانه: قُلْ إِنَّ صَلاتِي وَنُسُكِي [الأنعام:162] يعني: ذبحي، وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَاا أَوَّلُ الْمُسْلِمِينَ[الأنعام:162-163] ويقول الله سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:1-2] ويقول النبي ﷺ: لعن الله من ذبح لغير الله خرجه مسلم في صحيحه من حديث علي ، فلا يجوز الذبح للخضر ولا للبدوي ولا للحسين ولا لغيرهم من الناس ولا للأصنام ولا للجن، الذبح يكون لله وحده، التقرب يكون بالذبائح لله وحده سبحانه كالضحايا والهدايا، أما الخضر أو البدوي أو الحسين أو ....... أو ابن عربي أو الشيخ عبد القادر أو فلان.. كل هذا لا يجوز الذبح لهم أصلاً، فالتقرب إليهم بالذبائح ليشفعوا لك أو ليشفى ولدك كل هذا من الشرك الأكبر نعوذ بالله مثل الذبح للأصنام والجن والكواكب كله شرك أكبر، فيجب الحذر من هذا أو أشباهه، يجب التواصي بترك ذلك والتناصح، فالذبح يكون لله وحده سبحانه وتعالى، هكذا الدعاء والاستغاثة لا يستغاث بـالخضر ولا بـالبدوي ولا بـالحسين ولا بالنبي ﷺ ولا بغيرهم، الاستغاثة بالله وحده، لا يستغاث بالأموات ولا بالجن ولا بالملائكة ولا بالأصنام ولا بالكواكب إنما يدعى الله وحده يستغاث به وحده سبحانه وتعالى، ولا يطلب المدد من الأموات كـالبدوي وغيره، ولا من الرسول ﷺ ولا من غيرهم، بل المدد يطلب من الله ؛ لأنه هو الذي يملك كل شيء سبحانه وتعالى، ولا بأس به من الحي القادر.. الحي القادر تقول له: يا أخي! ساعدني على كذا يسمعك أو بالمكاتبة أو بالبرقية أو بالتلفون -بالهاتف- تقول له: ساعدني على كذا وهو قادر، أقرضني كذا، هذا لا بأس، هذه أمور عادية وأسباب حسية لا حرج فيها، لكن تأتي للميت تقول: يا سيدي البدوي ! اشف مريضي أو رد غائبي أو المدد المدد أو يا سيدي الحسين أو يا سيدي يا رسول الله ﷺ أو يا سيدي ابن عربي أو يا شيخ عبد القادر أو ما أشبهها هذا هو شرك أكبر لا يجوز هذا، فيجب التنبه، يجب على كل مسلم أن يتنبه لهذا الأمر ويجب على العلماء وفقهم الله أن ينصحوا للناس وأن يعلموهم، يقول الله سبحانه: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] ويقول : ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلا يُنَبِّئُكَ مِثْلُ خَبِيرٍ [فاطر:13-14] سبحانه وتعالى، (خبير) فسمى دعاءهم شركاً، وهكذا يقول سبحانه: وَمَنْ يَدْعُُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] فسمى دعاء غير الله كفرًا وشركًا، فيجب التنبه لهذا الأمر الذي وقع فيه الكثير من العامة والجهلة، يجب على أهل العلم وعلى طلبة العلم أن ينصحوا لله ولعباده، وأن يعلموا هؤلاء الجهال حتى لا يشتغلوا بدعوة القبور وأهلها، بل يدعون الله عليهم أن يدعوا الله وحده سبحانه وتعالى ويستغيثوا به في حاجاتهم، أما الحي الحاضر القادر فلا بأس، الحي القادر من أخيك أو قريبك أو صديقك تقول: أقرضني كذا عاوني بكذا لا بأس حي يسمع كلامك، أو بالتلفون بالهاتف أو بالبرقية أو بالتلكس أو بالمكاتبة تطلب منه شيء وهو قادر لا بأس هذا ليس من العبادات، هذه أمور عادية حسية، وكان الصحابة يطلبون النبي في حياته ﷺ يطلبون منه أن يشفع لهم وأن يعينهم على كذا لا بأس بهذا في حياته ﷺ، لكن بعد الوفاة لا يسأل هو ولا غيره بعد الوفاة.\nوهكذا يوم القيامة حين يبعثه الله يسأله الناس يوم القيامة أن يشفع لهم لا بأس؛ لأنه حي حاضر بين أيديهم، أما بعدما توفاه الله وقبل يوم القيامة هذا لا يدعى ولا يستغاث به ولا يذبح له ولا ينذر له بل هذا من الشرك، وهكذا غيره كـالخضر أو نوح أو موسى أو عيسى لا يدعون مع الله ولا يستغاث بهم ولا ينذر لهم ولا يذبح لهم، وهكذا البدوي وهكذا الحسين وهكذا زينب ونفيسة وغيرهم ممن يعبدهم الجهلة، وهكذا الشيخ عبد القادر وهكذا أبو حنيفة هكذا غيرهم، كل هؤلاء وغيرهم ليس لأحد أن يدعوهم من دون الله، وليس له أن يستغيث بهم، كما أنه لا يجوز أن تدعى الأصنام التي يعبدها الجهلة أو الجن أو الكواكب أو الأشجار والأحجار كل هذا لا يجوز، العبادة حق الله وحده، يقول سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23]، إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]، وَأَنََّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينََ [يونس:106] يعني: المشركين، والآيات في هذا المعنى كثيرة، ويقول النبي ﷺ: من مات وهو يدعو لله نداً دخل النار والند: الشبيه والمثيل، يعني: يدعو ميتاً أو صنماً أو شجراً أو حجراً مع الله يقول: أغثني أو المدد المدد أو اشف مريضي أو رد غائبي أو نحو ذلك من الأدعية، كل هذا من الشرك الأكبر، كله مما نهى الله عنه ورسوله، فيجب على أهل العلم وعلى طلبة العلم وعلى كل من عنده بصيرة أن يعلم الناس وأن يحذرهم من هذا الشرك في كل مصر وفي كل مكان وفي كل زمان هذا واجب المسلمين، يقول النبي ﷺ: الدين النصيحة فالنصيحة لله ولعباده جميعاً، وهكذا يقول الرب : ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] ويقول النبي ﷺ: من دل على خير فله مثل أجر فاعله ولما بعث ﷺ علي بن أبي طالب  إلى خيبر ليدعو اليهود إلى الدخول في الإسلام قال له عليه الصلاة والسلام: فوالله لأن يهدي الله بك رجلًا واحدًا خير لك من حمر النعم يقسم ﷺ يحلف -وهو الصادق وإن لم يحلف- أن هداية واحد على يد الداعية إلى الله خير من حمر النعم، يعني: خير من جميع النوق الحمر، والمعنى خير من الدنيا وما عليها، فدل ذلك على وجوب التناصح والدعوة إلى الله وبيان حق الله لعباده تحذيرهم من الشرك حتى يكون الناس على بينة وعلى بصيرة. رزق الله الجميع التوفيق والهداية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7718/حكم-الاحلام-التي-تحث-على-دعاء-الاولياء-والذبح-لهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_270/27002.mp3","categories":["نواقض الإسلام","الرؤى والمنامات"]},{"id":9636,"question":"السائل إبراهيم من الرياض يقول: هل نواقض الإسلام محددة بعدد معين وما هي؟","title":"تحديد نواقض الإسلام","answer":"الجواب: نواقض الإسلام كثيرة وليس لها حصر؛ لأن عددها قد يحصره زيد ولا يحصره عمرو، حسب آراء العلماء واجتهادهم واستنباطهم الأحكام من الأدلة الشرعية، فقد يعدها زيد -مثلاً- أربعمائة ناقض ويعدها الآخر خمسمائة ناقض؛ لأنه استنبطها من أدلة أخرى، فهذا يخضع للأدلة الشرعية، نواقض الإسلام تخضع للأدلة الشرعية.\nوقد ذكرها العلماء في باب حكم المرتد، من أرادها وجدها في باب حكم المرتد، يراجع هذا الباب العظيم ويعتني به حتى يعرف منه نواقض الإسلام، كالشرك بالله وعبادة الأصنام والقبور من دون الله والاستغاثة بهم والنذر لهم، كل هذا من الردة عن الإسلام، كل هذا من نواقض الإسلام، كذلك سب الدين من نواقض الإسلام، سب الرسول ﷺ من نواقض الإسلام، سب الله من نواقض الإسلام، التنقص بالإسلام من نواقض الإسلام، القول: بأن الزنا ما هو بحرام من نواقض الإسلام، إذا قال: الربا ليس بحرام من نواقض الإسلام، إذا قال: الظلم للناس ليس بحرام هذا من نواقض الإسلام، إذا قال: الصلاة ما هي بواجبة هذا من نواقض الإسلام، إذا قال: الزكاة ما هي بواجبة من نواقض الإسلام، إذا قال: صوم رمضان ما هو بواجب هذا من نواقض الإسلام، إذا قال: الحج ليس بواجب مع الاستطاعة هذا من نواقض الإسلام، إذا قال: الغيبة حلال والنميمة حلال هذا من نواقض الإسلام، هكذا له أقسام كثيرة، لكن من أراد أن يعرفها على الحقيقة فعليه أن يراجع باب حكم المرتد، عليه أن يدرس هذا الباب في جميع المذاهب الأربعة الحنفي والمالكي والشافعي والحنبلي وغيرهم عليه أن يدرس هذا الباب ويتأمل وينظر الأدلة الشرعية حتى يعرف النواقض. نعم.\nالمقدم: جزاكم الله خيراً سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/7798/تحديد-نواقض-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27203.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":9640,"question":"الرسالة التالية وصلت من الأخ الذي رمز إلى اسمه بـ(ح.ع.س.) من عمان الأردن، الرسالة تحتوي على العديد من الأسئلة، والسؤال الأول يقول فيه:سب الدين أو الرب -أستغفر الله رب العالمين- هل من سب الدين وغيره هل يعتبر كافر أو مرتد وما حكمه، وما هي العقوبة المقررة عليه في الدين الإسلامي الحنيف حتى نكون على بينة من أمر شرائع الدين وهذه الظاهرة متفشية بين بعض الناس في بلادنا، أفيدونا أفادكم الله؟","title":"حكم سب الدين والرب","answer":"الجواب: سب الدين من أعظم الكبائر ومن أعظم المنكرات، وهكذا سب الرب ، وهذان الأمران من أعظم نواقض الإسلام ومن أسباب الردة عن الإسلام، فإذا كان من سب الرب سبحانه أو سب الدين ينتسب للإسلام فإنه يكون مرتدًا عن الإسلام ويكون كافرًا يستتاب، فإن تاب وإلا قتل من جهة ولي الأمر في البلد، وقال بعض أهل العلم: إنه لا يستتاب بل يقتل؛ لأن جريمته عظيمة ولكن الأرجح هو أنه يستتاب لعل الله يمن عليه بالهداية فيلتزم الحق ولكن لا مانع من تعزيره، ينبغي أن يعزر بالجلد والسجن حتى لا يعود لمثل هذا، هذا هو الصواب الذي قاله جمع من العلم تعزيره ولو استتبناه وقبلنا توبته لكن يعزر عن إجرامه العظيم وإقدامه على هذه الكبيرة العظيمة نسأل الله العافية.\nوقال آخرون: لا يستتاب بل يقتل بكل حال وهو قول قوي لكن استتابته اليوم أولى إن شاء الله مع التأديب المناسب والسجن المناسب حتى لا يعود إلى هذا المنكر، وهكذا لو سب القرآن أو سب الرسول ﷺ فإنه يستتاب فإن تاب وإلا قتل؛ لأن سب الدين وسب الرسول ﷺ وسب الرب  من نواقض الإسلام وهكذا الاستهزاء بالله أو برسوله أو بالجنة أو بالنار أو بأوامر الله كالصلاة والزكاة، فالاستهزاء بهذه الأمور من نواقض الإسلام، قال الله سبحانه: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ ۝ لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65-66] نسأل الله العافية. نعم.","link":"https://binbaz.org.sa/fatwas/7806/حكم-سب-الدين-والرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19403.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":9643,"question":"السؤال الرابع في رسالة الأخ (ح. ع. س) من الأردن يقول فيه: هل المرأة المسلمة إذا سبت زوجها أو دين زوجها أصبحت طالق في الشرع كما نسمع من أكثر الناس أفيدونا أفادكم الله؟","title":"حكم القول بطلاق المرأة إذا سبت زوجها أو دينه","answer":"الجواب: إذا سبت زوجها لا، لا تكون طالق ولكن عليها التوبة إلى الله واستسماح زوجها، فإذا سمح عنها فلا بأس، وإن سبها مثلما سبته قصاصًا لا يزيد على ذلك فلا بأس، وإن سمح عنها فهو أفضل، لأن الله يقول: وَأَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوَى [البقرة:237] والنبي ﷺ يقول: ما زاد الله عبدًا بعفو إلا عزًا.\nأما سبها لدين زوجها وهو مسلم فهذا كفر نسأل الله العافية، إذا كان مسلم وهي مسلمة وسبت دين زوجها هذا سب للإسلام نعوذ بالله، فلا يتساهل معها بل تؤدب وتضرب على هذا العمل السيئ وتستتاب، فإن تابت عن عملها السيئ وإلا وجب أن تقتل، وجب على ولي الأمر قاضي البلد وأمين البلد يستتيبوها فإن تابت وإلا قتلت؛ لأن سب الدين سب الإسلام من أعظم أنواع الكفر ومن نواقض الإسلام نسأل الله العافية، وهكذا سب الرسول ﷺ، سب القرآن. نعم.","link":"https://binbaz.org.sa/fatwas/7809/حكم-القول-بطلاق-المراة-اذا-سبت-زوجها-او-دينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19406.mp3","categories":["الطلاق","نواقض الإسلام"]},{"id":9690,"question":"يسأل أيضاً الأخ عمر من تشاد ويقول: وهل تجوز الصلاة خلف إمام يفعل البدع أثناء الليل، فإذا سأل يسأل باسم الشيخ أحمد التيجاني وإذا استعاذ يستعيذ به ويحمده؟ هل يجوز اتباعه والاقتداء به، أفيدونا أفادكم الله؟","title":"حكم الصلاة خلف من يدعو الموتى","answer":"الجواب: مثل هذا لا يصلى خلفه، من كان بهذه المثابة يدعو التيجاني ويستعيذ بـالتيجاني أو بـالحسين أو بـالبدوي أو بغيرهم من الأموات أو بالأنبياء هذا شرك أكبر، فالذي يقول: يا سيدي أحمد التيجاني أنا في حسبك أنا في جوارك، أنا مستجير بك، أو يا سيدي يا رسول الله أنا مستجير بك، أو يا سيدي الحسين أو يا سيدي البدوي، أو سيدي الست زينب، أو يا فلان أو يا فلانة، هذا من الشرك الأكبر، والله يقول سبحانه: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60] ويقول : فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] ويقول سبحانه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: المشركين.\nفالله أمر عباده أن يدعوه، قال: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60]: وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ [البقرة:186] وقال سبحانه: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18].\nوقال : ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14] فسمى دعاءهم إياهم: شركاً.\nوقال جل وعلا: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] فسماهم، كفرة؛ بدعوتهم غير الله من الأموات والملائكة والجن ونحو ذلك.\nالعبادة حق الله هو الذي يدعى : يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ [البقرة:21] ويقول سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] ويقول سبحانه: وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِ اُعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ [النحل:36] ويقول سبحانه: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ ۝ أَلا لِلَّهِ الدِّينُ الْخَالِصُ [الزمر:2-3].\nويقول سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] ونهى عن عبادة غيره فقال: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] والدعاء هنا يشمل دعاء المسألة ويشمل دعاء العبادة، فلا يدعى مع الله أحد لا بالصلاة ولا بالصوم، ولا بالضراعة إليه وسؤاله، ولا بالنذر، ولا بالسجود ولا لغير هذا بل هذه حق الله وحده .\nفالذي يدعو التيجاني أو يدعو الرسول ﷺ أو يدعو أحد الصحابة كـعلي ، أو الحسين الحسن  جميعاً، أو يدعو البدوي أو المرسي أو الشيخ عبد القادر الجيلاني أو فلان أو فلان كل هذا شرك أكبر، يجب تركه، والحذر منه، ولا يتخذ هذا إماماً، ولا يعتمد عليه في فتوى ولا غيرها؛ لأن الشرك أعظم الذنوب وأكبرها.\nفالواجب تحذيره ونصيحته ودعوته إلى الله  لعله يتوب فيتوب الله عليه، يقول سبحانه: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] ويقول سبحانه يخاطب نبيه عليه الصلاة والسلام: وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ [الزمر:65] ويقول سبحانه: إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ [لقمان:13] ويقول : إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48].\nفبين سبحانه أن الشرك لا يغفر لمن مات عليه، أما ما دونه من المعاصي فتحت مشيئة الله جل وعلا، من مات على المعاصي كالزنا أو الخمر ونحو ذلك هذا تحت مشيئة الله لا يكفر، إذا لم يستحل ذلك، لكنه تحت مشيئة الله إذا مات على ذلك، إن شاء الله سبحانه غفر له بأعماله الصالحة وتوحيده وإسلامه، وإن شاء عذبه على قدر المعاصي التي مات عليها، ثم منتهاه إلى الجنة بعد التطهير والتمحيص، إذا كان مات على التوحيد والإيمان والإسلام. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7844/حكم-الصلاة-خلف-من-يدعو-الموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_252/25204.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":9780,"question":"يسأل أيضاً ويقول: ما رأيكم فيمن يُكفِّر من يصلي ويصوم ويؤدي الفرائض ويحج لكنه يدعو غير الله أو يستعين بغير الله أو يحلف بغير الله؟","title":"حكم من يدعو غير الله ويستغيث به","answer":"الجواب: الإسلام أصله توحيد الله، وتخصيصه بالعبادة، وهذا هو معنى شهادة: أن لا إله إلا الله وأن محمداً رسول الله، هذا أصل الدين وأساس الملة، وهذا هو الركن الأول من أركان الإسلام قبل الصلاة والصيام والزكاة، الركن الأول: شهادة أن لا إله إلا الله وأن محمداً رسول الله، عن علم وعن عمل وعن صدق وعن إخلاص وعن محبة وعن قبول للحق.\nفإذا كان يعبد الله وحده صحت صلاته وصيامه وحجه وزكاته.\nوإذا كان يدعو الأموات ويستغيث بالأموات بطلت أعماله، صار مشركاً نعوذ بالله.\nفمن يدعو الأموات ويستغيث بهم وينذر لهم ويقول: المدد المدد! يا سيدي فلان! أو يا سيدي فلان! يطلب من الرسول ﷺ أو من المرغني أو من الحسين أو من البدوي أو من الشيخ عبد القادر أو من غيرهم يكون هذا شرك أكبر؛ لأن الله يقول سبحانه: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] ويقول سبحانه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: المشركين.\nويقول سبحانه: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14] سماه: شرك، سمى دعاءهم إياه شركاً بالله سبحانه وتعالى، وقال : وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] فسماهم كفرة بالدعاء، والمدعو من دون الله يسمى إله، ويسمى نداً، فالذي يدعو مع الله صنماً أو ولياً أو نبياً أو قمراً أو كوكباً أو غير ذلك أو جنياً، يكون قد اتخذه نداً لله وجعله إلهاً مع الله، فهذا العمل شرك أكبر، تبطل معه الصلاة والصوم والزكاة والحج وغير ذلك، قال الله سبحانه في كتابه العظيم: وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ [الزمر:65] يخاطب نبيه ﷺ وهو معصوم من هذا، لكن ليعلم الأمة أن هذا الأمر عظيم، وقال جل وعلا: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] وقال سبحانه: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] فالشرك لا يغفر لمن مات عليه.\nفالواجب الحذر من هذا الأمر، دعاء الأموات والاستغاثة بالأموات أو بالأصنام أو الأشجار والأحجار، وطلبهم المدد كل هذا شرك بالله، يبطل الأعمال.\nفالواجب البدار بالتوبة من هذا الأمر والحذر منه، والعزم الصادق أن لا يعود فيه من فعله، وبهذا يصح إسلامه، أما مادام يعبد القبور والأموات ويستغيث بهم وينذر لهم فقد أبطل أصل إسلامه قد أبطل الشهادة، مثل الذي يتوضأ ثم يحدث، إذا توضأ الإنسان ثم خرج منه البول أو الريح بطل وضوءه، فهكذا الذي يقول: أشهد أن لا إله إلا الله وأشهد أن محمداً رسول الله، ثم يدعو الأموات ويستغيث بالأموات أو الأصنام أو الجن وينذر لهم أبطل توحيده، مثلما أبطل طهارته بالريح أو بالبول.\nوهكذا لو قال: أشهد أن لا إله إلا الله وأن محمداً رسول الله، ثم قال -بعد ذلك-: إن مسيلمة نبي، مسيلمة الكذاب قال: إنه نبي، أو قال: إن الأسود العنسي نبي، أو قال: إن طليحة الأسدي نبي، أو قال: فلان أو فلان ممن ادعى النبوة بعد النبي ﷺ يكون كافراً ولو قال: أشهد أن لا إله إلا الله، ولو قال: أشهد أن محمداً رسول الله؛ لأنه كذب الله في قوله في محمد ﷺ (وخاتم النبيين): مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ وَلَكِنْ رَسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ [الأحزاب:40].\nوهكذا لو قال: أشهد أن لا إله إلا الله وأن محمداً رسول الله، ثم قال: الصلاة غير واجبة، كفر، ولو قال: أشهد أن لا إله إلا الله، أو ترك الصلاة عمداً على القول الصحيح كفر أيضاً، أو قال: الزكاة ما هي بواجبة، أو صوم رمضان ما هو بواجب ولو صام، أو قال: الحج ما هو بواجب مع الاستطاعة كفر ولو حج؛ لأنه كذب الله ورسوله.\nوهكذا لو أن إنساناً يقول: أشهد أن لا إله إلا الله وأن محمداً رسول الله ويصلي ويصوم ويتصدق، ولكنه يسب الرسول ﷺ أو يسب الله أو يسب الإسلام كفر بهذا السب، ولم تنفعه هذه الشهادة وهذا الصوم وهذه الصلاة؛ لأنه أتى بناقض من نواقض الإسلام.\nفلا بد في حق المسلم وبقاء الإسلام عنده أن يبتعد عن نواقض الإسلام، وعن أسباب الردة وهكذا لو أن إنساناً يشهد أن لا إله إلا الله وأن محمداً رسول الله ويصلي ويصوم ويزكي ويحج، ولكنه يستهين بالمصحف، يطؤه برجله، أو يقعد يجلس عليه إهانة له، أو يلطخه بالنجاسة كفر إجماعاً؛ بعمله مع المصحف؛ لأن هذا يدل على استخفاف بكلام الله، وسب لله بإهانة كلامه، فيكون كافراً عند جميع العلماء، ولو قال: أشهد أن لا إله إلا الله وأن محمداً رسول الله، ولو صلى ولو زكى ولو صام ولو حج.\nفينبغي للمسلم التنبه لهذه الأمور، وأن الإسلام إنما يبقى مع السلامة من نواقض الإسلام، ومع البعد عما ينقض الإسلام.\nنسأل الله للجميع الهداية والعافية.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7943/حكم-من-يدعو-غير-الله-ويستغيث-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_258/25804.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":9797,"question":"وهذا سؤال من سائل في سوريا يقول: هل الذبح لغير الله يجوز؛ لأن عندنا ناس يذبحون لرجل اسمه مجلي وعندما نقول: من هو مجلي؟ يقولون: إنه نبي من أنبياء الله أفيدونا في ذلك بارك الله فيكم؟","title":"حكم الذبح لغير الله","answer":"الجواب: الذبح لغير الله منكر عظيم وهو شرك أكبر سواء كان ذلك لنبي أو ولي أو كوكب أو جني أو صنم أو غير ذلك؛ لأن الله يقول سبحانه: قُلْ إِنَّ صَلاتِي [الأنعام:162] يعني: قل يا محمد صَلاتِي وَنُسُكِي [الأنعام:162] يعني: ذبحي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:162-163]، فأخبر سبحانه أن الذبح لله كما أن الصلاة لله فمن صرف الذبح لغير الله فهو كمن صلى لغير الله يكون شركًا بالله عز وجل وهكذا يقول سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:1-2]، فالنحر والصلاة عبادتان عظيمتان فمن صرف الذبح لأصحاب القبور أو للأنبياء أو للكواكب أو للأصنام أو للجن أو للملائكة فقد أشرك بالله كما لو صلى لهم أو استغاث بهم أو نذر لهم كل هذا شرك بالله ، والله يقول سبحانه: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] ويقول : وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] ويقول سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] فالعبادة حق الله، والذبح من العبادة، وهكذا الاستغاثة من العبادة، هكذا الصلاة من العبادة، وثبت عن رسول الله عليه الصلاة والسلام أنه قال: لعن الله من ذبح لغير الله رواه الإمام مسلم في صحيحه من حديث علي ، فعليكم أن تنكروا على هؤلاء وأن تعلموهم أن هذا شرك أكبر، وأن الواجب عليهم ترك ذلك، فليس لهم أن يذبحوا لغير الله كما أنه ليس لهم أن يصلوا لغير الله، وهذا من باب التعاون على البر والتقوى ومن باب إنكار المنكر ومن باب الدعوة إلى الله وإخلاص العبادة لله، ومن باب التوحيد الذي يجب أن يكون لله وحده ، وهذا واجب أهل العلم وواجب طلبة العلم وواجب أعيان المسلمين أن يتعاونوا على البر والتقوى وأن ينكروا في الشرك على من فعله حتى يظهر التوحيد وحتى يقضى على أسباب الشرك، نسأل الله للجميع التوفيق والهداية. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7964/حكم-الذبح-لغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_196/19613.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":9866,"question":"هذه رسالة من عبد العزيز علي حسن قناوي مصري يعمل بالعراق، يقول عبد العزيز علي حسن في رسالته: أنا أعمل بالعراق وأسكن وأعمل مع جماعة منهم من يسب دين الله، ونصحتهم ولكن ما زال بعضهم على ما هو عليه..ف ما حكم الشرع فيمن يسب الدين، وإذا كان يصلي هل صلاته صحيحة، وماذا علي تجاههم أفيدوني أفادكم الله؟","title":"حكم من يسب الدين وحكم صلاته، وواجبنا نحوه","answer":"الجواب: إذا رأيت من يسب الدين أو سمعت من يسب الدين تنصحه وتنكر عليه؛ لأن سب الدين كفر أكبر، وردة عن الإسلام إذا كان الساب مسلماً يرتد يكون كافراً، فعليك أن تنصح له وأن تنكر عليه المنكر، لقول الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] ولقوله : وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [آل عمران:104] ولقول النبي ﷺ: من رأى منكم منكراً فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه وذلك أضعف الإيمان خرجه مسلم في صحيحه.\nفالواجب عليك وعلى غيرك من المؤمنين إنكار المنكر، فإذا رأيتم من يسب الدين أو لا يصلي، أو يشرب الخمر أو يعق والديه، أو يفعل شيئاً من المنكرات الأخرى فإن عليكم الإنكار عليه، وتوجيهه إلى الخير ونصيحته، لعل الله يهديه بأسبابكم، فإذا هداه الله صار لكم مثل أجره، وإن أبى فينبغي السعي في إبعاده من العمل والقضاء عليه، وإذا كان في دولة مسلمة فينبغي الرفع عنه إلى الدولة حتى تعاقبه، فإن تاب وإلا وجب قتله مرتداً عن الإسلام، لقول النبي ﷺ: من بدل دينه فاقتلوه فإن تاب من سبه ورجع جاز عند بعض أهل العلم تركه وعدم قتله، ولكن يؤدب.\nوبعض أهل العلم يرى أنه يقتل مطلقاً ولو تاب، لكن الأرجح إن شاء الله أنه متى تاب إلى الله ورجع وندم واستقام فإنه لا يقتل ، ولكن لا مانع من تأديبه على ما أقدم عليه، وعلى ما فعله، بجلدات أو سجن أو نحو ذلك.\nوالحاصل والخلاصة: أن الواجب على من لديه من المؤمنين الإنكار عليه، الإنكار عليه وتحذيره والاجتهاد في رده إلى الصواب، فإن لم يجد ذلك ولم يتيسر ذلك، فعل المؤمن ما يستطيع من السعي في فصله وإبعاده من العمل، من رفع أمره إلى ولاة الأمور إذا كان في بلد ينكر فيها المنكر، فإن خشيت على نفسك ولم يتيسر الرفع عن هؤلاء ولا توبتهم، فابتعد عن مخالطتهم إلى عمل آخر لعلك تنجو، والله ولي التوفيق.\nالمقدم: أثابكم الله، لكن السائل يقول: إن صاحبه هذا الذي يسب الدين يصلي فيسأل ما حكم صلاته؟\nالشيخ: سب الدين يبطل الأعمال، إذا سب الدين كفر، والكفر يبطل العمل، إذا مات عليه صاحبه، إذا مات الكافر على كفره بطل عمله، أما إن تاب قبل أن يموت بقي له عمله الصالح.","link":"https://binbaz.org.sa/fatwas/8041/حكم-من-يسب-الدين-وحكم-صلاته-وواجبنا-نحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_263/26309.mp3","categories":["حكم الصلاة وأهميتها","نواقض الإسلام"]},{"id":9961,"question":"وهذا السائل مصري الجنسية يعمل في الكويت رمز لاسمه بـ (م. س. ع) يقول في رسالة طويلة الحقيقة وقد أفاض فيها، وكثير من الإخوة يحرجوننا بهذه الرسائل؛ لأنها تأخذ من وقت البرنامج، ولا نستطيع عرضها بكاملها، هذا السائل يقول في رسالته:عندنا مقبرة كبيرة بها ثلاثة أضرحة مبني عليها قباب كبيرة، يقال: أنها بنيت منذ مائتي عام، ومما يؤسف له أن هناك امرأة عجوز تذهب لهذه الأضرحة بحجة أنهم أولياء وتقوم بتنظيفها، ويذهب الناس إلى هذه الأضرحة فيذبحون لها وينذرون لها، وهناك فريق يقول: إنه يلزم هدم هذه القباب، وفريق آخر يقول: لا يجوز لنا هدمها لأنها قباب قديمة وبنيت منذ فترة فلا نعرف وضعها، سؤالي ما حكم مثل هذه الأعمال، خدمة المرأة لهذه الأضرحة، الذبح والنذر عندها، وضع الأموال، ثم أين تذهب هذه الأموال، وأين تذهب هذه الذبائح؟! وفقكم الله.","title":"حكم بناء القباب على القبور والذبح والنذر لها","answer":"الجواب: البناء على القبور أمر منكر، لا يجوز اتخاذ القباب عليها ولا اتخاذ المساجد عليها، بل نهى الرسول عن هذا عليه الصلاة والسلام، بل لعن من فعل ذلك، قال عليه الصلاة والسلام: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، وقال جابر : نهى رسول الله ﷺ عن تجصيص القبور والقعود عليها والبناء عليها خرجه مسلم في صحيحه، وهكذا روى النسائي والترمذي وغيرهما: (النهي عن الكتابة على القبور) أيضاً.\nفالحاصل: أن البناء على القبور أمر منكر، نهى عنه الرسول صلى الله عليه وسلم، واتخاذ المساجد عليها كذلك؛ لأنه وسيلة إلى الغلو فيها وعبادتها من دون الله بالدعاء، أو الطواف أو الاستغاثة بها أو الذبح لها، كل هذا يقع من بعض الجهلة، وهذا من الشرك الأكبر، الطواف على القبور تقرباً إلى الموتى بذلك، أو الدعاء للميت أو الاستغاثة بالميت، أو طلبه شفاء المريض أو قضاء الحاجة، أو رد الغائب أو ما أشبه ذلك، هذا من الشرك الأكبر، هذه لا تطلب من الأصنام ولا من الموتى، ولا من الشجر والحجر، ولا من الكواكب، هذه تطلب من الله ، هو الذي يشفي المرضى ويرد الغياب ويقضي الحاجات ويكشف الكربات .\nأما طلب هذا من الموتى أو من الأصنام أو من الأشجار والأحجار أو من الكواكب هذا كله شرك بالله عز وجل، وهكذا الطواف على القبور منكر، الطواف.. يكون بالكعبة، لا يطاف بالقبور، هذا منكر عظيم، بل شرك أكبر إذا قصد به التقرب لصاحب القبر، فهو شرك أكبر، وإذا ظن أنه قربة لله وأنه يتقرب إلى الله بهذا هذه بدعة منكرة ووسيلة إلى الشرك، فلا يطوف لا لله عند قبر ولا للميت، لا يطوف عند القبر أبداً، الطواف من خصائص البيت العتيق الكعبة، القبور لا يطاف بها أبداً، بل هذا منكر وبدعة، وإذا كان فعله لصاحب القبر صار شركاً أكبر، وهكذا دعاء الميت والاستغاثة بالميت، والنذر له، والذبح له، كله من الشرك الأكبر. فالواجب على المسلمين الحذر من ذلك، وعلى أعيان المسلمين منع هؤلاء من هذا العمل، وعلى الحكام والأمراء أن يمنعوا الجهلة من هذا الشيء، هكذا الواجب على حكام المسلمين، لأن الله جل وعلا أقامهم لمنع الأمة مما يضرها ولإلزامها بما أوجب الله عليها، وللنظر في مصالحها، هذا واجب الحكام، الحكام من الأمراء والملوك والسلاطين إنما شرعت ولايتهم ليقيموا أمر الله في أرض الله، لينفذوا أحكام الله.\nفعلى الأمير في القرية، وعلى الحاكم في أي مكان، وعلى السلطان ورئيس الجمهورية وعلى كل من له قدرة أن يساهم في هذا الخير، وذلك بإزالة هذه الأبنية والقباب والمساجد التي بنيت على القبور، وأن تبقى القبور مكشوفة، مثل القبور في البقيع في عهد النبي ﷺ وفي عهدنا الآن في المدينة، القبور تكشف ولا يكون عليها بناء لا مسجد ولا حجرة سقف ولا قبة ولا غير ذلك؛ لأن الرسول ﷺ نهى عن البناء على القبور واتخاذ المساجد عليها وتجصيصها؛ لأن هذا وسيلة إلى أن يغلى فيها، إلى أن تعبد مع الله، وهكذا لا يهدى إليها نقود ولا ذبائح ولا ملابس ولا للسدنة عندها، وهذه العجوز التي تأتي القبر هذه تمنع لا تأتي هذه المقابر، ولا تقوم بتنظيفها؛ لأن هذه دعاية للشرك، ولكن تصان القبور إذا سورت أطراف المقبرة كلها بسور حتى لا تمتهن، حتى لا تتخذ طرق أو للدواب لا بأس.\nأما البناء على القبر لتعظيمه أو لإظهار شرفه وفضله هذا كله منكر، لا يجوز البناء على القبور أبداً، ويمنع وضع السدنة عند القبور لأخذ أموال الناس، أو تغرير الناس ودعوتهم إلى الشرك، كل هذا يجب منعه، وهذا واجب الحكام وواجب الأعيان وواجب أمراء البلاد، أن يسعوا في هذا الخير وأن ينصحوا للعامة والجهال ويعلموهم، كان النبي ﷺ إذا زار القبور يقول كان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين، وكان يقول لهم إذا زار البقيع عليه الصلاة والسلام بنفسه: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، أتاكم ما توعدون، اللهم اغفر لأهل بقيع الغرقد هكذا يدعو لهم، هذا السنة، يدعى للمقبورين بالرحمة والمغفرة، يسلم عليهم ويدعو لهم ثم ينصرف، لا يدعوهم مع الله لا يستغيث بهم، لا يتمسح بقبورهم، لا يقبلها بل يدعو وينصرف، يدعو لهم بالمغفرة والرحمة ثم ينصرف؛ لأن زيارة القبور فيها ذكرى للآخرة، وذكرى للموت، أما أن يجلس عند القبور يقرأ أو يدعو أو يتمسح بالقبر، أو يقبله هذا لا يجوز أو يدعوه من دون الله أو يستغيث به أو ينذر له كل هذا من أعمال الجاهلية، من أعمال المشركين الأولين.\nفيجب الحذر منها، ويجب تعليم الناس وإرشادهم وتوجيههم إلى الخير، وتعليمهم ما ينفعهم، حتى لا يقعوا في الشرك، وحتى لا يكونوا من جنس الجاهلية الأولى، والله المستعان. نعم.\nالمقدم: وفقكم الله.","link":"https://binbaz.org.sa/fatwas/8125/حكم-بناء-القباب-على-القبور-والذبح-والنذر-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_265/26504.mp3","categories":["نواقض الإسلام","البدع والمحدثات"]},{"id":9970,"question":"وهذا السائل مصري الجنسية يعمل في الكويت رمز لاسمه بـ (م. س. ع) يقول في رسالة طويلة الحقيقة وقد أفاض فيها، وكثير من الإخوة يحرجوننا بهذه الرسائل؛ لأنها تأخذ من وقت البرنامج، ولا نستطيع عرضها بكاملها، هذا السائل يقول في رسالته:عندنا مقبرة كبيرة بها ثلاثة أضرحة مبني عليها قباب كبيرة، يقال: أنها بنيت منذ مائتي عام، ومما يؤسف له أن هناك امرأة عجوز تذهب لهذه الأضرحة بحجة أنهم أولياء وتقوم بتنظيفها، ويذهب الناس إلى هذه الأضرحة فيذبحون لها وينذرون لها، وهناك فريق يقول: إنه يلزم هدم هذه القباب، وفريق آخر يقول: لا يجوز لنا هدمها لأنها قباب قديمة وبنيت منذ فترة فلا نعرف وضعها، سؤالي ما حكم مثل هذه الأعمال، خدمة المرأة لهذه الأضرحة، الذبح والنذر عندها، وضع الأموال، ثم أين تذهب هذه الأموال، وأين تذهب هذه الذبائح؟! وفقكم الله.","title":"حكم بناء القباب على القبور والذبح والنذر لها","answer":"الجواب: البناء على القبور أمر منكر، لا يجوز اتخاذ القباب عليها ولا اتخاذ المساجد عليها، بل نهى الرسول عن هذا عليه الصلاة والسلام، بل لعن من فعل ذلك، قال عليه الصلاة والسلام: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، وقال جابر : نهى رسول الله ﷺ عن تجصيص القبور والقعود عليها والبناء عليها خرجه مسلم في صحيحه، وهكذا روى النسائي والترمذي وغيرهما: (النهي عن الكتابة على القبور) أيضاً.\nفالحاصل: أن البناء على القبور أمر منكر، نهى عنه الرسول صلى الله عليه وسلم، واتخاذ المساجد عليها كذلك؛ لأنه وسيلة إلى الغلو فيها وعبادتها من دون الله بالدعاء، أو الطواف أو الاستغاثة بها أو الذبح لها، كل هذا يقع من بعض الجهلة، وهذا من الشرك الأكبر، الطواف على القبور تقرباً إلى الموتى بذلك، أو الدعاء للميت أو الاستغاثة بالميت، أو طلبه شفاء المريض أو قضاء الحاجة، أو رد الغائب أو ما أشبه ذلك، هذا من الشرك الأكبر، هذه لا تطلب من الأصنام ولا من الموتى، ولا من الشجر والحجر، ولا من الكواكب، هذه تطلب من الله ، هو الذي يشفي المرضى ويرد الغياب ويقضي الحاجات ويكشف الكربات .\nأما طلب هذا من الموتى أو من الأصنام أو من الأشجار والأحجار أو من الكواكب هذا كله شرك بالله عز وجل، وهكذا الطواف على القبور منكر، الطواف.. يكون بالكعبة، لا يطاف بالقبور، هذا منكر عظيم، بل شرك أكبر إذا قصد به التقرب لصاحب القبر، فهو شرك أكبر، وإذا ظن أنه قربة لله وأنه يتقرب إلى الله بهذا هذه بدعة منكرة ووسيلة إلى الشرك، فلا يطوف لا لله عند قبر ولا للميت، لا يطوف عند القبر أبداً، الطواف من خصائص البيت العتيق الكعبة، القبور لا يطاف بها أبداً، بل هذا منكر وبدعة، وإذا كان فعله لصاحب القبر صار شركاً أكبر، وهكذا دعاء الميت والاستغاثة بالميت، والنذر له، والذبح له، كله من الشرك الأكبر. فالواجب على المسلمين الحذر من ذلك، وعلى أعيان المسلمين منع هؤلاء من هذا العمل، وعلى الحكام والأمراء أن يمنعوا الجهلة من هذا الشيء، هكذا الواجب على حكام المسلمين، لأن الله جل وعلا أقامهم لمنع الأمة مما يضرها ولإلزامها بما أوجب الله عليها، وللنظر في مصالحها، هذا واجب الحكام، الحكام من الأمراء والملوك والسلاطين إنما شرعت ولايتهم ليقيموا أمر الله في أرض الله، لينفذوا أحكام الله.\nفعلى الأمير في القرية، وعلى الحاكم في أي مكان، وعلى السلطان ورئيس الجمهورية وعلى كل من له قدرة أن يساهم في هذا الخير، وذلك بإزالة هذه الأبنية والقباب والمساجد التي بنيت على القبور، وأن تبقى القبور مكشوفة، مثل القبور في البقيع في عهد النبي ﷺ وفي عهدنا الآن في المدينة، القبور تكشف ولا يكون عليها بناء لا مسجد ولا حجرة سقف ولا قبة ولا غير ذلك؛ لأن الرسول ﷺ نهى عن البناء على القبور واتخاذ المساجد عليها وتجصيصها؛ لأن هذا وسيلة إلى أن يغلى فيها، إلى أن تعبد مع الله، وهكذا لا يهدى إليها نقود ولا ذبائح ولا ملابس ولا للسدنة عندها، وهذه العجوز التي تأتي القبر هذه تمنع لا تأتي هذه المقابر، ولا تقوم بتنظيفها؛ لأن هذه دعاية للشرك، ولكن تصان القبور إذا سورت أطراف المقبرة كلها بسور حتى لا تمتهن، حتى لا تتخذ طرق أو للدواب لا بأس.\nأما البناء على القبر لتعظيمه أو لإظهار شرفه وفضله هذا كله منكر، لا يجوز البناء على القبور أبداً، ويمنع وضع السدنة عند القبور لأخذ أموال الناس، أو تغرير الناس ودعوتهم إلى الشرك، كل هذا يجب منعه، وهذا واجب الحكام وواجب الأعيان وواجب أمراء البلاد، أن يسعوا في هذا الخير وأن ينصحوا للعامة والجهال ويعلموهم، كان النبي ﷺ إذا زار القبور يقول كان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين، وكان يقول لهم إذا زار البقيع عليه الصلاة والسلام بنفسه: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، أتاكم ما توعدون، اللهم اغفر لأهل بقيع الغرقد هكذا يدعو لهم، هذا السنة، يدعى للمقبورين بالرحمة والمغفرة، يسلم عليهم ويدعو لهم ثم ينصرف، لا يدعوهم مع الله لا يستغيث بهم، لا يتمسح بقبورهم، لا يقبلها بل يدعو وينصرف، يدعو لهم بالمغفرة والرحمة ثم ينصرف؛ لأن زيارة القبور فيها ذكرى للآخرة، وذكرى للموت، أما أن يجلس عند القبور يقرأ أو يدعو أو يتمسح بالقبر، أو يقبله هذا لا يجوز أو يدعوه من دون الله أو يستغيث به أو ينذر له كل هذا من أعمال الجاهلية، من أعمال المشركين الأولين.\nفيجب الحذر منها، ويجب تعليم الناس وإرشادهم وتوجيههم إلى الخير، وتعليمهم ما ينفعهم، حتى لا يقعوا في الشرك، وحتى لا يكونوا من جنس الجاهلية الأولى، والله المستعان. نعم.\nالمقدم: وفقكم الله.","link":"https://binbaz.org.sa/fatwas/8125/حكم-بناء-القباب-على-القبور-والذبح-والنذر-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_265/26504.mp3","categories":["نواقض الإسلام","البدع والمحدثات"]},{"id":9990,"question":"أخيرًا يقول هذا السائل: عندنا من مشايخ الصوفية من يهتم بصنع القباب والأضرحة، والناس يعتقدون فيهم الصلاح والبركة، فإن كان هذا الأمر غير مشروع فما هي نصيحتكم لهم وهم قدوة في نظر السواد الأعظم من الناس، أفيدونا بارك الله فيكم؟","title":"حكم الغلو في الصالحين وبناء القباب على القبور","answer":"الجواب: النصيحة لعلماء الصوفية ولغيرهم من أهل العلم أن يأخذوا بما دل عليه كتاب الله وسنة رسوله عليه الصلاة والسلام، وأن يعلموا الناس ذلك، وأن يحذروا اتباع من قبلهم فيما يخالف ذلك، فليس الدين بتقليد المشايخ ولا غيرهم، وإنما الدين ما يؤخذ عن كتاب الله وعن سنة رسول الله محمد ﷺ وعما أجمع عليه أهل العلم، وعن الصحابة ، الدين هكذا يؤخذ لا عن تقليد زيد وعمرو، وقد دلت السنة الصحيحة عن رسول الله عليه الصلاة والسلام على أنه لا يجوز البناء على القبور ولا اتخاذ المساجد عليها، ولا اتخاذ القباب ولا أي بناء، كل ذلك محرم بنص الرسول عليه الصلاة والسلام، ففي الصحيحين عن عائشة رضي الله عنها قالت: قال رسول الله ﷺ لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد قالت رضي الله عنها: يحذر ما صنعوا، وفي الصحيحين عن أم سلمة وأم حبيبة رضي الله تعالى عنهما أنهما ذكرتا للنبي صلى الله عليه وسلم كنيسة رأتاها بأرض الحبشة وما فيها من الصور، فقال: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجداً وصوروا فيه تلك الصور، أولئك شرار الخلق عند الله فأخبر عليه الصلاة والسلام أن الذين يتخذون المساجد على القبور هم شرار الخلق، وهكذا من يتخذ عليها الصور لأنها دعاية للشرك، اتخاذ المساجد والصور على القبور والقباب دعاية إلى الشرك؛ لأن العامة إذا رأوا هذا عظموا المدفونين واستغاثوا بهم ونذروا لهم، ودعوهم من دون الله، وطلبوا منهم المدد والعون، وهذا هو الشرك الأكبر، وفي حديث جندب بن عبد الله البجلي  فيما خرجه مسلم في الصحيح عن النبي ﷺ أنه قال: إن الله قد اتخذني خليلًا كما اتخذ إبراهيم خليلاً، ولو كنت متخذًا من أمتي خليلًا لاتخذت أبا بكر خليلاً، ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك هكذا رواه مسلم في الصحيح، فدل ذلك على فضل الصديق ، وأنه أفضل الصحابة وخيرهم، وأنه لو ساغ للنبي ﷺ أن يتخذ خليلاً لاتخذه خليلاً رضي الله عنه، ولكن الله جل وعلا منعه من ذلك حتى تتمحض محبته لربه سبحانه وتعالى فإن الخلة أعلى المحبة، وفي الحديث دلالة على تحريم البناء على القبور واتخاذ المساجد عليها وعلى ذم من فعل ذلك، من جهات ثلاث:\nالأولى: ذمه من فعل ذلك.\nالثانية: قوله: (فلا تتخذوا القبور مساجد).\nالثالثة: قوله: (فإني أنهاكم عن ذلك). فحذر من البناء على القبور من هذه الجهات الثلاث، يقول ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد يعني فلا تتبعوهم بهذا، لا تقتدوا بهم، ثم قال: (ألا فلا تتخذوا القبور مساجد)، يعني لا تأسوا بهم، (فإني أنهاكم عن ذلك) هذا شيء صريح، والعلة والحكمة في ذلك كما قال أهل العلم أنه وسيلة وذريعة إلى الشرك الأكبر، إلى عبادة أهل القبور، فصرف الدعاء والاستغاثة والنذور والذبائح لهم وطلب منهم المدد والعون كما هو واقع الآن في بلدان كثيرة، عند السائل في السودان، وفي مصر، وفي الشام، وفي العراق، وفي بلدان كثيرة، يأتي الرجل العامي الجاهل فيقف على صاحب القبر المعروف عندهم فيطلبه المدد والعون والغوث كما يقع عند قبر البدوي والحسين والست نفيسة وزينب وغير ذلك في مصر، وكما يقع عندكم في السودان عند قبور كثيرة، وكما يقع في بلدان أخرى، وكما يقع من بعض الحجاج الجهال عند قبر النبي ﷺ في المدينة، وعند قبور أهل البقيع، وعند قبر خديجة في مكة وقبور أخرى، يقع هذا من الجهال وهم يحتاجون إلى تبصير وإلى بيان وإلى عناية من أهل العلم.\nفالواجب على أهل العلم جميعًا سواء كانوا منسوبين للصوفية أو غيرهم، الواجب على العلماء جميعًا على علماء الشريعة أن يتقوا الله، وأن ينصحوا عباد الله، وأن يعلموهم دينهم، وأن يحذروهم من البناء على القبور واتخاذ المساجد عليها أو القباب أو غير ذلك من أنواع البناء وأن يحذروهم من دعاء الموتى والاستغاثة بالموتى، الدعاء عبادة لله وحده، الله يقول: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، ويقول سبحانه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106]، يعني المشركين، ويقول ﷺ: الدعاء هو العباد، والنبي -أيضاً- يقول ﷺ: إذا سألت فاسأل الله، وإذا استعنت فاستعن بالله، فالميت قد انقطع عمله مع الناس، فهو بحاجة إلى أن يدعى له إلى أن يستغفر له، إلى أن يترحم عليه لا يدعى من دون الله، يقول النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له فكيف يدعى من دون الله؟ وهكذا الأصنام، وهكذا الأشجار والأحجار، وهكذا القمر والشمس والكواكب كلها لا تدعى من دون الله، كلها لا تدعى ولا يستغاث بها، فهكذا أصحاب القبور وإن كانوا أنبياء، وإن كانوا صالحين، هكذا الملائكة والجن لا يدعون مع الله، والله يقول سبحانه: وَلا يَأْمُرَكُمْ أَنْ تَتَّخِذُوا الْمَلائِكَةَ وَالنَّبِيِّينَ أَرْبَابًا أَيَأْمُرُكُمْ بِالْكُفْرِ بَعْدَ إِذْ أَنْتُمْ مُسْلِمُونَ [آل عمران:80]، فجعل اتخاذ الملائكة والنبيين أربابًا بالدعاء والاستغاثة كفراً، والله لا يأمر به ، وفي حديث جابر عند مسلم يقول : نهى رسول الله ﷺ عن تجصيص القبور، وعن القعود عليها، وعنن البناء عليها، هكذا رواه مسلم في الصحيح عن جابر (أن الرسول ﷺ نهى عن تجصيص القبور، وعن القعود عليها، وعن البناء عليها) لماذا؟ لأن هذا وسيلة إلى الشرك، البناء عليها والتجصيص والكسوة والقباب كله هذا وسيلة إلى تعظيمها والغلو فيها ودعاء أهلها، أما القعود عليها هو امتهان لا يجوز، كون يقعد عليها لا هي محترمة لا تمتهن لا يقعد عليها، لا يبول عليها، لا يتغوط عليها، لا يستند إليها، لا يطؤها، هذا ممنوع احترام المسلم حياً وميت محترم لا يجوز أن يداس قبره ولا أن تكسر عظامه، ولا أن يقعد على قبره، ولا أن يبال عليه، ولا أن توضع عليه قمائم كل هذا ممنوع، فالميت لا يمتهن المسلم لا يمتهن ولا يدعى من دون الله، لا يغلى فيه ويدعى من دون الله ولا يمتهن ويداس وتوضع عليه القمائم والأبوال والقاذورات لا، لا هذا ولا هذا، الشريعة جاءت بالوسط، جاءت باحترام القبور والدعاء لأهلها بالمغفرة والرحمة وزيارتهم للدعاء لهم والاستغفار لهم، ونهت عن إيذائهم بالقمائم، بالبول، بالقعود عليهم إلى غير ذلك، ومن هذا ما جاء في الحديث الصحيح يقول ﷺ: لا تجلسوا على القبور ولا تصلوا إليها، لا تجعل قبلة ولا يقعد عليها، فجمعت الشريعة الكاملة العظيمة بين الأمرين، بين تحريم الغلو في أهل القبور ودعائهم من دون الله، والاستغاثة بهم والنذر لهم ونحو ذلك، وهذا من الشرك الأكبر، وبين النهي عن إيذائهم وامتهانهم والجلوس على قبورهم أو الوطء عليها والاستناد إليها، أو وضع القاذورات عليها كل هذا ممنوع فلا هذا ولا هذا.\nوبهذا يعلم المؤمن ويعلم طالب الحق أن الشريعة جاءت بالوسط، لا بالشرك ولا بالإيذاء، فالميت المسلم النبي أو الصالح يدعى له، يستغفر له، يسلم عليه عند زيارته، أما أنه يدعى من دون الله لا، لا يقال: يا سيدي المدد المدد، أو انصرني أو اشف مريضي، أو أعني على كذا، لا هذا يطلب من الله، ولا يمتهن يوضع ... القمامة على قبره، يوطأ عليه، يجلس عليه، يبال لا، لا هذا ولا هذا.\nأما الحي فلا بأس أن يتعاون معه لأن له عمل، الحي له عمل فلا بأس أن يتعاون معه فيما يجوز شرعاً من الأسباب الحسية، كما قال تعالى: فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15] في قصة موسى ، فإن موسى حي والمستغيث حي، فاستغاثه على عدوه، وهكذا الإنسان مع إخوانه، مع أقاربه، يتعاونون في مزارعهم، في إصلاح بيوتهم، في إصلاح سياراتهم، في أشياء أخرى من حاجاتهم يتعاونون بالأسباب الحسية المقدورة لا بأس، وهكذا من طريق الهاتف التلفون، من طريق المكاتبة، من طريق الإبراق والتلكس كل هذا تعاون حسي لا بأس به في الأمور المقدورة، لكن ما يتعلق بالعبادة لا، لا يقال للحي ولو أنه حي، لا يقال للحي: اشف مريضي، ورد غائبي من طريق سر فيه أن له سراً، ولا يقال: انصرنا على عدو بسر يعني، لا، وانصرنا بالسلاح، وانصرنا بالقرض دراهم يقرضهم إياها حتى يستعينوا بها على شئون الحرب لا بأس، كذلك يأتي الطبيب يطلب منه العلاج لا بأس، أما يقول اشفني لأنه يعتقد فيه سر، لأنه من شيوخ الصوفية أو من غيرهم، هذا كفر لأن الإنسان ما يقدر، لا، ما له سر يقدر يتصرف في الكون، إنما أمور حسية، الطبيب يتصرف بالأدوية، كذلك الإنسان القادر الحي يتصرف بالأسباب الحسية، يعينك بيده، يبني معك، يعطيك مال قرض أو مساعدة تبني به، يعطيك قطع غيار لسيارتك، يساعدك في شفاعة لدى من يعينك هذه أمور حسية لا بأس بها لا تدخل في عبادة الأموات والاستغاثة بالأموات ونحو ذلك، وكثير من دعاة الشرك يشبهون بهذه الأمور، وهي أمور واضحة بينة لا تشتبه إلا على من هو من أجهل الناس، فالتعامل مع الأحياء شيء جائز بشروطه المعروفة، وسؤال الأموات والاستغاثة بالأموات والنذر لهم أمر معروف عند أهل العلم شرك أكبر بإجماع أهل العلم، ليس فيه نزاع بين الصحابة ومن بعدهم من أهل العلم والإيمان وأهل البصيرة.\nوالبناء على القبور واتخاذ المساجد عليها والقباب كذلك منكر معلوم عند أهل العلم جاءت الشريعة بالنهي عنه فلا يجوز أن يلتبس هذا على أهل العلم.\nفالواجب على أهل العلم مرة أخرى الواجب عليهم أن يتقوا الله أينما كانوا، وأن ينصحوا لعباد الله، وأن يعلموا شريعة الله، وأن لا يجاملوا في ذلك زيداً ولا عمراً، بل يعلموا الأمير والصغير والكبير، ويحذروا الجميع مما حرم الله، ويرشدوهم إلى ما شرع الله، هذا هو الواجب على أهل العلم أينما كانوا، من طريق الكلام الشفهي، ومن طريق الكتابة، ومن طريق التأليف، ومن طريق الخطابة في الجمع وغيرها، من طريق الهاتف، من طريق التلكس، من أي الطرق التي وجدت الآن، يستعان بها على تبليغ دعوة الله وعلى نصح عباد الله، رزق الله الجميع التوفيق والهداية، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/8158/حكم-الغلو-في-الصالحين-وبناء-القباب-على-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_275/27504.mp3","categories":["نواقض الإسلام","الفرق والمذاهب"]},{"id":10066,"question":"آخر أسئلته أيضًا وكلها تدور في بحر العقيدة -سماحة الشيخ- يقول: بقرة معتقة للزار لا يحرثون بها ولا يبيعونها ولا يذبحونها لأي ضرورة أفيدونا عن حكم الشرع فيها مأجورين جزاكم الله خيرًا؟","title":"حكم تسييب المواشي تقربًا للجن والشياطين","answer":"الجواب: هذا من جنس عمل المشركين الأولين، الله أبطل هذا بقوله: مَا جَعَلَ اللَّهُ مِنْ بَحِيرَةٍ وَلا سَائِبَةٍ وَلا وَصِيلَةٍ وَلا حَامٍ [المائدة:103] فلا يسيب بقر لا للزار ولا للميت فلان ولا للجني فلان ولا لغير ذلك، فالتسييب للزار تقرب للشياطين الزار الشيطان والتقرب إلى الشياطين بتسييب البقر أو الإبل شرك بالله وتشبه بالجاهلية فلا يتقرب إلى الجن لا بتسييب ولا بذبح ولا بدعاء واستغاثة كل هذا من الشرك الأكبر فإذا قال: يا جني فلان أو يا سبعة أو يا تسعة خذوا فلان اذبحوه اقتلوه انصرونا على فلان اشفوا مرضانا من كذا، كل هذا من الشرك الأكبر، كما لو قال: يا سيدي عبدالقادر! انصرني، أو يا سيدي الحسين انصرني، أو سيدي البدوي انصرني، أو المدد المدد أو يا سيدي الحسين! أو يا سيدي سفيان الثوري! أو يا سيدي أبا حنيفة! أو ما أشبه ذلك، كل هذا من الشرك الأكبر، وهكذا لو قال: يا رسول الله! أو يا نوح! أو يا هود! أو يا عيسى! أو يا داود! انصرنا أو اشف مرضانا، أو يا عائشة! أم المؤمنين أو يا صفية! أم المؤمنين أو يا فاطمة بنت رسول الله! انصرينا أو أغيثينا، أو المدد المدد أو ما أشبه ذلك مما يفعله المشركون، كل هذا من الشرك بالله، كله كفر وشرك أكبر لا يجوز لا مع الصالحين ولا مع الطالحين لا مع الإنس ولا مع الجن، نسأل الله السلامة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8227/حكم-تسييب-المواشي-تقربا-للجن-والشياطين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_333/33303.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":10148,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين وقع في نهايتها يقول: المرسل عبدالمنعم من السودان، أخونا يسأل بعض الأسئلة في أحدها يقول: هل تجوز الصلاة خلف من يعتقد في القبور؟","title":"حكم الصلاة خلف من يعتقد في أصحاب القبور","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذا السؤال فيه إجمال، فإن الاعتقاد في القبور أنواع، فإذا كان يعتقد فيها أنها تصلح أن تعبد من دون الله وأن يستغاث بأهلها وينذر لهم ويذبح لهم ويطاف بقبورهم فهذا الشرك الأكبر، فلا يصلى خلفه؛ لأنه مشرك والصلاة لا تصح إلا خلف المسلم، فإذا كان يعتقد أن أصحاب القبور يدعون من دون الله، ويستغاث بهم، وينذر لهم، ويذبح لهم ونحو ذلك، كما يفعل بعض الجهلة عند قبر البدوي أو الحسين أو الشيخ عبد القادر الجيلاني أو غيرهم فهذا من الشرك الأكبر، فالذين يعتقدون هذه الاعتقادات في أصحاب القبور ليسوا مسلمين، بل هم كفار فعلهم فعل كفار قريش وأشباههم من جهلة العرب ومشركي العرب، لأن العرب كانت تعبد أصحاب القبور كاللات ويعبدون الأصنام والأشجار والأحجار ويستغيثون بهم وينذرون لهم ويذبحون لهم، فحكم الله عليهم بالشرك، قال جل وعلا في كتابه العظيم: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ قُلْ أَتُنَبِّئُونَ اللَّهَ بِمَا لا يَعْلَمُ فِي السَّمَوَاتِ وَلا فِي الأَرْضِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ [يونس:18]، وقال جل وعلا: مَا كَانَ لِلْمُشْرِكِينَ أَنْ يَعْمُرُوا مَسَاجِدَ اللَّهِ شَاهِدِينَ عَلَى أَنفُسِهِمْ بِالْكُفْرِ أُوْلَئِكَ حَبِطَتْ أَعْمَالُهُمْ وَفِي النَّارِ هُمْ خَالِدُونَ [التوبة:17].\nفالذي يعبد الأصنام أو الأشجار أو الأحجار أو أصحاب القبور يعتبر مشركاً في حكم الإسلام ولا يصلى خلفه، أما إن كان يعتقد في أصحاب القبور أنه يستحب زيارتهم والدعاء لهم كما شرع الله ذلك، فهذا أمر مشروع، فأصحاب القبور من المسلمين يستحب أن تزار قبورهم ويدعى لهم بالرحمة والمغفرة هذا لا حرج فيه.\nوهناك نوع ثالث يعتقد في أصحاب القبور أنهم يصلى عند قبورهم يقرأ عندها وأن هذا فيه بركة، لكن لا يعبدون ولا يدعون ولا يصلى لهم ولا يطاف لهم لكن يرى أنهم يصلى عند قبورهم للبركة، لأنها بقعة مباركة أو يرى أنه يقرأ عندها أو يتحرى عندها الدعاء يعني: دعاء الله لا دعاؤهم، فهذا من البدع ولا يكون مشركاً بذلك لكن من البدع ينكر عليه ويبين له أن هذا غلط، وأن الله ما شرع لنا أن نصلي عند القبور ولا أن نقرأ عندها ولا أن ندعو عندها ندعو الله عندها، يقول ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، فالمساجد هي التي يصلى فيها، ويدعى فيها، يقرأ فيها، أما القبور لا، تزار للدعاء لهم، تزار القبور إذا كانت قبور المسلمين ويدعى لهم بالرحمة والمغفرة، كما قال النبي ﷺ: زوروا القبور فإنها تذكركم الآخرة، وكان يعلم أصحابه عليه الصلاة والسلام ورضي الله عنهم يعلمهم إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، وفي حديث عائشة رضي الله عنها في مسلم كان يقول: يرحم الله المستقدمين منا والمستأخرين، اللهم اغفر لأهل بقيع الغرقد، وفي حديث ابن عباس أن الرسول ﷺ زار القبور قبور المدينة فقال: السلام عليكم يا أهل القبور! يغفر الله لنا ولكم، أنتم سلفنا ونحن بالأثر.\nهذه زيارة شرعية للمسلم أن يزور قبور المسلمين في بلده من غير شد رحل يزورهم بدون شد رحل ويسلم عليهم ويدعو لهم بالرحمة والمغفرة والعافية، هذه الزيارة فيها خير كثير تنفع الميت والحي، الحي يتذكر الآخرة يستعد للآخرة ويدعو لإخوانه الميتين والأموات ينتفعون بهذا الدعاء، أما إن كان الميت ليس بمسلم فإنما يزار للعبرة فقط ولا يدعى له، كما زار النبي ﷺ قبر أمه، الرسول ﷺ سأل ربه أن يستغفر لها فلم يؤذن له، فزارها للعبرة وإذا زار القبور قبور الكفار للعبرة والتذكر تذكر الآخرة فلا بأس لكن لا يدعو لهم، لأن الكافر لا يستغفر له ولا يدعى له.\nوهكذا من مات على جاهلية على حال الجاهلية على كفر الجاهلية كأم النبي ﷺ ماتت على دين الجاهلية فنهي أن يستغفر لها عليه الصلاة والسلام.\nفالحاصل أن زيارة القبور على هذا التفصيل، والاعتقاد في القبور على هذا التفصيل، من يعتقد فيها أنها تدعى من دون الله وأنها يصلح أن تتخذ آلهة تعبد من دون الله تدعى من دون الله يستغاث بها يطاف بها كما يطاف بالكعبة للتقرب إلى أصحاب القبور، يذبح لأهلها هذا شرك أكبر وهذا عمل الجاهلية ودين الجاهلية من قريش وغيرهم، فلا يصلى خلف صاحبه ولا تؤكل ذبيحته، لأنه ليس بمسلم.\nالنوع الثاني: أن يعتقد في أهل القبور أنهم يزارون وأنه يدعى لهم ويترحم عليهم من دون شد رحل، فهذه زيارة شرعية، لقوله ﷺ: زوروا القبور فإنها تذكركم الآخرة، كما تقدم، والأموات في حاجة إلى هذه الزيارة يدعى لهم ويستغفر لهم ويترحم عليهم، هذا أمر مشروع فعله النبي ﷺ وأمر به.\nالنوع الثالث: أن يعتقد في القبور أن الصلاة عندها قربة مفيدة أو القراءة عندها أو الدعاء عندها هذا لا أصل له، هذا من البدع لا أصل له، لا تزار لأجل يدعى عندها أو يصلى عندها أو يقرأ عندها لا، هذا لا أصل له، بل هذا يكون في المساجد والبيوت تصلي في المسجد يقرأ في المسجد أو في بيته يدعو في البيت أو في المسجد، هذا ليس من شأن القبور، القبور لا تزار لأجل هذا لا تزار لأجل يجلس عندها للدعاء أو الصلاة عندها أو القراءة عندها هذا ما هو مشروع بل هو من البدع ومن وسائل الشرك، نسأل الله للجميع التوفيق والهداية.\nالمقدم: اللهم آمين جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8312/حكم-الصلاة-خلف-من-يعتقد-في-اصحاب-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_306/30601.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":10400,"question":"يسأل ويقول: ما حكم من يطوف بالقبر ويدعو الله عنده وهذا ألاحظه كثيرًا في بعض الأماكن؟","title":"ما حكم من يطوف بالقبر ويدعو الله عنده؟","answer":"الجواب: الطواف عبادة لله  من أفضل العبادات، ولكنه يختص بالكعبة، لا يطاف بغير الكعبة، فمن طاف بالقبور يريد التقرب إلى أهلها فقد أشرك، مثل من يدعوها ويستغيث بها وينذر لأهلها، أما إذا طاف بالقبر يقصد التقرب إلى الله، يحسب أنه جائز فهذا بدعة ومنكر، وعليه التوبة إلى الله ؛ لأنه ما قصد صاحب القبر وإنما قصد التقرب إلى الله يظن أنه يجوز، فهذا بدعة ومنكر وعليه التوبة إلى الله سبحانه وتعالى، ولا يكون بهذا مشركًا إلا إذا قصد التقرب بالطواف للميت ليشفع له، هذا يكون مثل قوله: يا سيدي أغثني أو اشف مريضي أو المدد المدد، كل هذا من الشرك الأكبر، أو ينذر له أو يذبح له. نعم.","link":"https://binbaz.org.sa/fatwas/8573/ما-حكم-من-يطوف-بالقبر-ويدعو-الله-عنده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_340/34007.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":10401,"question":"يقول في سؤال آخر: لي جدة تدعو الله وتدعو معه النبي ﷺ وبعض الأشخاص، وإني لأغضب لذلك بشدة مع أن جدتي قليلة السمع لا تسمع إلا برفع الصوت، كيف أتصرف معها لو تكرمتم؟","title":"حكم دعاء غير الله والاستغاثة به","answer":"","link":"https://binbaz.org.sa/fatwas/8574/حكم-دعاء-غير-الله-والاستغاثة-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_340/34008.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":10448,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع عبد الله الحارثي، الأخ عبدالله له ثلاثة أسئلة في أحدها يقول: في قريتنا قبور مرتفعة عن الأرض بمقدار متر أو مترين، وقد وجدناها على هذه الحال منذ سنين طويلة ولا نعلم لمن هذه القبور، ومنطقة المقابر يوجد بها حص يستفاد منه في البناء، فهل يجوز لنا أخذ بعض هذا الحص أم لا يجوز، جزاكم الله خيراً؟الشيخ: حرث؟المقدم: حص نوع من التربة التي يستفاد منها في البناء.","title":"حكم رفع القبور عن الأرض بمقدار متر أو مترين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالواجب في هذه المسألة الرجوع إلى المحكمة لإفادتكم بما يلزم في هذا الموضوع، وفي إمكان المحكمة أن تكتب إلي حتى ندرس الموضوع مع المحكمة ونعمل ما يلزم إن شاء الله.\nالمقدم: بارك الله فيكم، حفظكم الله وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8618/حكم-رفع-القبور-عن-الارض-بمقدار-متر-او-مترين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_281/28101.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":10520,"question":"رسالة من جمهورية مصر العربية بعثها مستمع يقول إيهاب صلاح الدين، يسأل ويقول: ما هي مبطلات الإسلام؟ وإذا وقع أحد في أحد هذه المبطلات فكيف يعود إلى الإسلام مرة أخرى، جزاكم الله خيرًا؟","title":"نواقض الإسلام وكيفية التوبة لمن وقع في ذلك","answer":"الجواب: مبطلات الإسلام هي نواقض الإسلام النواقض، أسباب الردة، وهذه بينها العلماء في باب مستقل في كتب الفقه، قد سموه: باب حكم المرتد، ذكروه في كتب الفقه، في أواخر كتب الفقه، عندما ذكروا الديات والقود والحدود ذكروا هذا الباب، ففي إمكانك أن تراجع هذا الباب في كتب الحنابلة، والشافعية، والمالكية، والحنفية، وكتب أهل الحديث، حتى تستفيد من هذه الكتب العظيمة.\nالمقصود أن هذا الباب باب عظيم، ذكروا فيه نواقض الإسلام: وأعظمها: الشرك بالله ، أن يدعو الأوثان، يدعو أصحاب القبور، أو يدعو النجوم، أو يدعو الأصنام، أو يدعو الأشجار والأحجار، يستغيث بها أو ينذر لها، أو يذبح لها، هذا من الشرك بالله الأكبر.\nومن نواقض الإسلام: سب الدين، كونه يسب الدين يسب الإسلام أو يعيبه، أو يتنقص الإسلام هذا من نواقض الإسلام.\nومن نواقض الاسلام: الاستهزاء بالدين، الاستهزاء بما قاله الله ورسوله، أو الاستهزاء بالرسول ﷺ عليه أفضل الصلاة والسلام أو بالقرآن، هذا من نواقض الإسلام.\nكذلك: إذا استحل ما حرم الله، إذا قال: الزنا حلال، أو الخمر حلال، أو الربا حلال، يكون ردة عن الإسلام، بإجماع المسلمين.\nكذلك: إذا أسقط ما أوجب الله، مثل الذي يقول: الصلاة ما هي بواجبة، أو صوم رمضان ما هو بواجب على المكلفين، أو الزكاة غير واجبة، أو الحج ما هو بواجب على المستطيع، هذا كله ردة عن الإسلام، وذكروا أنواعًا كثيرة غير هذه الأشياء. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8695/نواقض-الاسلام-وكيفية-التوبة-لمن-وقع-في-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_283/28309.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":10701,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الرياض، وباعثها المستمع (حسن . م. أ) أخونا حسن له جمع من الأسئلة من بينها سؤال يقول: ما رأيكم في المسلم الذي يسب الدين، والرب والعياذ بالله، هل تجوز مقاطعته أو محاربته، وهل تبلغ عنه جهات الاختصاص؟ وجهونا حول هذه القضية جزاكم الله خيراً؟","title":"حكم من سب الله أو الدين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد نص أهل العلم -في باب: حكم المرتد من كتب الفقهاء- جميعاً: أن من سب الله أو سب الرسول صلى الله عليه وسلم أو سب الدين فقد أتى بناقض من نواقض الإسلام ويكون كافراً مرتداً عن الإسلام، فالذي يسب الدين أو يسخر به ويستهزئ أو يسب الرسول ﷺ أو يسخر به ويتنقصه كافر بإجماع المسلمين يجب أن يقاطع ويهجر، ويجب على الدولة إذا بلغها ذلك أن تستتيبه فإن تاب وإلا قتل.\nوقال جمع من أهل العلم: إنه لا يستتاب، بل يقتل مطلقاً ولو أظهر التوبة، قالوا: إن ساب الله وساب الرسول لا يستتاب لعظم الجريمة والعياذ بالله ولا حول ولا قوة إلا بالله، أما ما دام لم يرفع أمره إلى السلطان فإنه ينصح ويوجه إلى الخير ويعلم ويدعى للتوبة فإذا تاب إلى الله وأناب إليه فلا يرفع أمره، لعل الله أن يمن عليه بالاستقامة فيسلم من شر هذا البلاء الذي وقع منه.\nلكن إن استمر في السب والاستهزاء فيجب الرفع عنه إلى ولاة الأمور حتى يقام عليه حد الله، ولا يجوز التساهل في حقه، بل يرفع أمره إلى المحكمة أو إلى أمير البلد حتى ينفذ فيه حكم الله  لأن سبه للدين يسبب شراً كثيرا وفساداً عظيماً، فلا ينبغي أن يتساهل معه، لكن إن بادر بالتوبة والإصلاح والرجوع إلى الله والندم قبل أن يرفع أمره فلا حرج في ذلك، والله يتوب عن التائبين . نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8877/حكم-من-سب-الله-او-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_342/34201.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":10709,"question":"والدي سمع من العلماء: أنه لا يجوز البناء على القبور، وفي مقبرة قريبة منا توجد فيها قبور عليها بنايات من الذين يدعون بـالصوفية أنهم يقولون: إنهم يضروا وينفعوا ولا يضر ولا ينفع إلا الله ، ويزورها الناس يوم الجمعة وأيام الأعياد، هل ما فعل والدي على حق، أم ننهه عن ذلك جزاكم الله خيراً؟","title":"إزالة البناء على القبور واجب على الدولة والحكام","answer":"الجواب: البناء على القبور لا يجوز، والواجب إزالته، وعلى الدولة والحكام أن يزيلوه أما الأفراد فليس لهم أن يزيلوه، إلا بإذن حتى لا يكون اصطدام وفتنة بينهم وبين المسئولين، فعلى ولاة الأمور من الأمراء والقضاة وعلى العلماء أن ينكروا هذا المنكر وأن يزال؛ لأن الرسول ﷺ لعن من بنى المساجد على القبور، قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، ونهى عن تجصيص القبور والبناء عليها، فالواجب أن يزال البناء حتى تكون شامسة بارزة كالقبور في المدينة في عهد النبي عليه الصلاة والسلام، وحتى لا يغلى فيها، إذا بني عليها صار هذا من أسباب الغلو فيها، وعبادتها من دون الله وتعظيمها التعظيم غير الشرعي، فلا يبنى عليها لا قبة ولا مسجد ولا غير ذلك، وإذا وجد بناء يرفع الأمر إلى ولي الأمر المسلم، وإلى العلماء حتى يزال بطريقة شرعية ليس فيها فتنة ولا تعرض لمشاكل تضر المجتمع، والله المستعان. نعم.\nالمقدم: الله المستعان، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8893/ازالة-البناء-على-القبور-واجب-على-الدولة-والحكام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_343/34308.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":10758,"question":"ما هو رأي الشرع في الذين يكتبون على جنبات عرباتهم بعض العبارات، وما أكثرهم في بلدي مثل أن يقولوا: يا الشيخ التوم ودمباقا يا الشيخ الياقوت يا الشيخ المكاشفي ، علماً بأن هؤلاء كما يقولون أولياء الله وهم ميتون، وقبورهم عليها قباب وتزار للتبرك على حد زعمهم، وجهونا جزاكم الله خيراً؟","title":"حكم كتابة أسماء الأولياء على العربات والسيارات","answer":"الجواب: هذا العمل لا يجوز بل هو منكر بل هو شرك؛ لأن قصدهم التوجه إلى هؤلاء ليحفظوا سياراتهم وليحفظوا ركابهم، ولهذا يكتبون عليها: يا فلان يا فلان أو يا رسول الله أو يا علي أو ما أشبه ذلك، كل هذا لا يجوز وكله من الشرك الأكبر؛ لأنه استغاثة بغير الله ولجأ إلى غير الله، ودعاء لغير الله، يقصدون من هذا أن يمدهم بما يسبب سلامة رحلتهم وسيرهم في الداخل أو في الخارج، فلا يجوز مثل هذا العمل. نعم.\nالمقدم: جزاكم الله خيراً أرجو تعريفاً كاملاً لأولياء الله ومن هم، وهل عندهم علامات مميزة، وهل تصح زيارتهم للتبرك وقضاء الحوائج سواءً كانوا أحياءً أم أموات، جزاكم الله خيرا؟\nالشيخ: أولياء الله هم أهل التقوى والإيمان هم أهل الصلاح والاستقامة على دين الله، هم على ما جاء به رسوله عليه الصلاة والسلام، هؤلاء هم أولياء الله، وهم أهل التقوى وهم أهل الإيمان كما قال الله سبحانه: أَلا إِنَّ أَوْلِيَاءَ اللَّهِ لا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ [يونس:62] ثم فسرهم فقال: الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ [يونس:63] هؤلاء هم أولياء الله، هكذا في سورة يونس، وقال في سورة الأنفال: وَمَا كَانُوا أَوْلِيَاءَهُ إِنْ أَوْلِيَاؤُهُ إِلَّا الْمُتَّقُونَ [الأنفال:34].\nفأولياء الله هم أهل التقوى هم أهل الإيمان هم الذين أطاعوا الله ورسوله واستقاموا على دين الله، وتركوا الشرك والمعاصي هؤلاء هم أولياء الله، يجب حبهم في الله، ولكن لا يجوز دعاؤهم من دون الله ولا الاستغاثة بهم ولا البناء على قبورهم، هذا منكر، ولا البناء على قبور الأنبياء أيضاً، يقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد.\nوقال عليه الصلاة والسلام: ألا وإن من كان قبلكم -يعني: من الأمم- كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك، رواه مسلم في الصحيح، فنهر الناس عن اتخاذ المساجد على قبور الأنبياء والصالحين، وحذرهم من ذلك، ولعن من فعل هذا، وروى مسلم في الصحيح عن جابر  قال: نهى رسول الله أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه.\nفلا يبنى عليه قبة ولا غرفة ولا مسجد بل يجب الحذر من ذلك، بل تترك القبور بارزة شامسة كما كانت في عهد النبي ﷺ في البقيع، وفي غيره في الأرض الواضحة التي ليس فيها بناء يكون القبر بارزاً على الأرض قدر شبر ونحوه؛ حتى يعرف أنه قبر ولا يبنى عليه ولا يجصص، ولا يجعل عليه قبة ولا مسجد كل هذا لا يجوز، وهذه القباب والمساجد التي توضع على القبور من أسباب الشرك، إذا رآها العامي معظمة بالقباب والمساجد وربما فرشوها وربما طيبوها صار هذا من أسباب الشرك، بدعة يترتب عليها شرك أكبر نسأل الله العافية، فإن العامة إذا رأوا هذا العمل دعوها من دون الله واستغاثوا بها، وتمسحوا بها إلى غير ذلك.\nأما زيارة المؤمن ليسلم على أخيه، يعني: على قبره إذا كان ظاهراً بارزاً ليس فيه قبة ولا مسجد ولا فلا بأس بل سنة، النبي عليه السلام قال: زوروا القبور؛ فإنها تذكركم الآخرة، فإن زار القبور ليسلم عليهم ويدعو لهم فهذا مشكور وهذه سنة، أما أن يزورهم ليدعوهم من دون الله أو يستغيث بهم أو يطلبهم المدد فهذا شرك أكبر لا يجوز، كالذي يقول لصاحب القبر: المدد المدد، أو يا سيدي فلان أغثني أو انصرني، أو اشف مريضي، أو أنا في جوارك، أو أنا في حسبك، هذا دعاء لغير الله وشرك بالله ، فهذا من جنس عمل الجاهلية الأولى، أبي جهل وأشباهه.\nفالواجب على المسلمين أن يحذروا هذه الأمور وأن يتواصوا ويتناصحوا بتركها أينما كانوا، وأما الأحياء منهم إذا زارهم يسلم عليهم لحبهم في الله، فلا بأس يزورهم لحبهم في الله، لا للتبرك بهم، ولكن يزورهم .. يسلم عليهم ويعرف أحوالهم ويتذاكر معهم في الخير أو في العلم كل هذا طيب، أو ليدعوا له ليستغفروا له لا بأس أيضاً ... قال: استغفروا لي أو ادعوا لي لا بأس، أما أن يزوره لأجل الاعتقاد فيه أنه يدعى من دون الله، أو أنه يصلح أن يعبد من دون الله حياً وميتاً؛ لأنه ينفع أو يضر أو لأنه يتصرف في الكون أو ما أشبه ذلك من اعتقاد الجهلة فهذا لا يجوز، يقول الله جل وعلا لنبيه ﷺ: قُلْ لا أَمْلِكُ لِنَفْسِي نَفْعًا وَلا ضَرًّا إِلَّا مَا شَاءَ اللَّهُ وَلَوْ كُنتُ أَعْلَمُ الْغَيْبَ لاسْتَكْثَرْتُ مِنَ الْخَيْرِ وَمَا مَسَّنِيَ السُّوءُ إِنْ أَنَا إِلَّا نَذِيرٌ وَبَشِيرٌ لِقَوْمٍ يُؤْمِنُونَ [الأعراف:188].\nفإذا كان ﷺ وهو سيد الخلق وأفضل الخلق لا يملك لغيره نفعاً ولا ضرا ولا يعلم الغيب فكيف بغيره من الناس، فعلم الغيب إلى الله  وهو النافع الضار المعطي المانع جل وعلا، فليس لأحد أن يدعو غير الله بالأموات أو الغائبين أو الأشجار والأحجار أو الجن أو الملائكة، بل هذا من الشرك بالله .\nوليس له أن يعتقد في أحد من المخلوقات أنه ينفع ويضر دون الله، أو أنه يصلح أن يعبد من دون الله ويدعى من دون الله، كل هذا اعتقاد باطل وكفر نسأل الله العافية، أما الحي الحاضر القادر يقول: يا أخي أعني على كذا لا بأس، حي حاضر تقول له: ساعدني على إصلاح سيارتي، على عمارة بيتي، على مزرعتي وهو قادر يسمعك ويستطيع أن يساعدك بما يسر الله لا بأس، هذه أمور جائزة فيما بين الناس، قال تعالى في قصة موسى: فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15]؛ لأنه حي يسمع كلامه وموسى يقدر أن يغيثه، فلا بأس بهذا.\nأما دعاء الأموات والاستغاثة بالأموات أو الغائبين، يعني: يعتقد فيهم أنهم يسمعون دعاءه وينفعون أو يضرون، هذا هو الشرك الأكبر، هذا عمل الجاهلية الأولى نسأل الله العافية، ولو قال: إني ما قصدت أنهم ينفعون أو يضرون، ولو قال: أقصد أنهم شفعاء عند الله، هذا شرك المشركين المشركون ما قصدوا أنهم ينفعون ويضرون، بل أرادوهم شفعاء عند الله، وأرادوهم أن يقربوهم إلى الله كما قال تعالى: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18] قال الله سبحانه: قُلْ أَتُنَبِّئُونَ اللَّهَ بِمَا لا يَعْلَمُ فِي السَّمَوَاتِ وَلا فِي الأَرْضِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ [يونس:18] فسماه: شركاً، وقال  في سورة الزمر: وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:3] ما قالوا: إلا أنهم ينفعون أو يضرون لا قالوا: ليقربونا إلى الله زلفى هذه عقيدتهم يعلمون أن النافع والضار هو الله وحده، ولكنهم يطلبون من الأولياء أو من الأنبياء أو من الملائكة الشفاعة إلى الله ليعطيهم مطالبهم، ويزعمون أنهم شفعاء وأنهم يقربون إلى الله ولا يعتقدون أنهم يتصرفون في الكون أو ينفعون أو يضرون لا، ليس هذا من اعتقاد الجاهلية، ومع هذا كفرهم الله وقاتلهم الرسول ﷺ على شركهم هذا.\nفالواجب على كل من يدعي الإسلام أن يتبصر ويتفقه في دينه، وأن يحذر التعلق بأهل القبور، ودعاءهم من دون الله، والاستغاثة بهم والنذر لهم والذبح لهم، وأن هذا هو شرك الجاهلية، كما يفعل هذا بعض الناس عند قبر السيد البدوي أو السيد الحسين أو الشيخ عبد القادر في العراق أو غيرهم، كل هذا شرك بالله لا يجوز، لا مع الحسين ولا مع البدوي ، ولا مع الشيخ عبد القادر الجيلاني ولا مع غيرهم من الناس، ولا مع ابن عربي في الشام ولا مع غيرهم.\nالواجب الإخلاص لله في العبادة؛ لأنه حقه سبحانه وتعالى.\nقال تعالى: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] وقال سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] يعني: أمر وأوصى أن لا تعبدوا إلا إياه، وقال سبحانه: يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ [البقرة:21]، وقال جل وعلا: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] هذا أصل الدين وأساس الملة، وهذا أعظم واجب وأهم واجب أن تعبد الله وحده، بدعائك ونذرك وذبحك وصلاتك وصومك وغير ذلك.\nوقال تعالى: قُلْ إِنَّ صَلاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ [الأنعام:162-163] والنسك: يطلق على الذبح وعلى العبادة، فكما أن الصلاة لله، هكذا الذبح لله، فالذي يذبح للجن أو يتقرب لأصحاب القبور أو الأشجار والأصنام بالذبائح هذا شرك بالله عز وجل، وهكذا دعاؤهم والاستغاثة بهم وطلب المدد مثل يقف على قبره: المدد المدد، أو يدعوه من قريب: يا سيدي البدوي أو يا سيدي الحسين المدد المدد ، أو يا سيدي عبد القادر المدد المدد هذا الشرك الأكبر، هذا شرك بالله عز وجل وعبادة لغيره، قال سبحانه وتعالى: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] أحداً عام يعم الأنبياء وغيرهم، نكرة في سياق النهي تعم الأنبياء والملائكة والجن والإنس.\nوقال سبحانه وتعالى: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: المشركين، وقال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] فسمى دعاة غير الله: كفاراً، ولو قالوا: ما نسميه إله، ولو قالوا: نسميهم: سادة أو نسميهم أولياء متى دعوهم واستغاثوا بهم فقد جعلوهم آلهة وإن لم يسموهم آلهة، فلا عبرة بالأسماء العبرة بالحقائق، فالذي يعبده من دون الله ويستغيث به قد جعله إلهاً وإن لم يسمه إلهاً، وإن قال: هو السيد أو هو الولي أو هو كذا أو كذا بأسماء أخرى، والاعتبار في الأمور بالحقائق والمعاني لا بالألفاظ.\nنسأل الله أن يهدي إخواننا .. جميع المسلمين، نسأل الله أن يرشد الجاهل الحق والهدى وأن يكثر في المسلمين علماء الحق وعلماء الهدى؛ حتى يبصروا الناس وحتى يرشدوهم إلى توحيد الله، وإلى الحق الذي بعث الله به نبيه محمد عليه الصلاة والسلام.\nونسأل الله أن يهدي الجاهل إلى أن يتعلم ويسأل ويتبصر ولا يرضى بالتقليد الأعمى، نصيحتي لجميع من يتصل بالقبور أو يدعو القبور أو يجهل أحكام الله، نصيحتي للجميع أن يسألوا العلماء علماء الحق علماء السنة أهل البصيرة يسألوهم مثل: أنصار السنة في مصر، مثل: شيخ الأزهر، مثل: علماء السنة في الشام في الأردن في أي مكان، علماء الحق المعروفين بالسنة والتوحيد والإخلاص والبصيرة، وهكذا في كل مكان في أفريقيا وفي أوروبا وفي أمريكا في كل مكان.\nالواجب على من جهل الحكم أن يسأل ولا يقدم على شيء على غير بصيرة، الله يقول سبحانه في كتابه العظيم: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43] ويروى عنه عليه السلام أنه قال لقوم أفتوا بغير علم: ألا سألوا إذ لم يعلموا، إنما شفاء العي السؤال، وكان الصحابة يسألونه عليه الصلاة والسلام، ويعلمهم ويجيبهم حتى النساء يسألونه ويجيبهم، وقال له بعض النساء: يا رسول الله! ذهب الرجال بحديثك فاجعل لنا يوماً نسألك ونتحدث إليك فوعدهم وجمعهم في مكان وأتاهم وسألوه عن حاجاتهم عليه الصلاة والسلام فالواجب على العلماء أن ينبسطوا للجهلة حتى يعلموهم، وأن يعتنوا بالكتاب والسنة وأن تكون الفتاوى من الكتاب والسنة لا من التقليد الأعمى، بل من كتاب الله العظيم وسنة رسوله الأمين، على العالم أن يتبصر من طريق الكتاب والسنة، وأن يعلم الناس على ضوء الكتاب والسنة، وأن يرشدهم إلى أحكام الله التي دل عليها كتابه العظيم وسنة رسوله الأمين عليه الصلاة والسلام، وأن يحذر التساهل في هذه الأمور.\nرزق الله الجميع الهداية والتوفيق.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8932/حكم-كتابة-اسماء-الاولياء-على-العربات-والسيارات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_347/34702.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":10760,"question":"ما هو رأي الشرع في الذين يكتبون على جنبات عرباتهم بعض العبارات، وما أكثرهم في بلدي مثل أن يقولوا: يا الشيخ التوم ودمباقا يا الشيخ الياقوت يا الشيخ المكاشفي ، علماً بأن هؤلاء كما يقولون أولياء الله وهم ميتون، وقبورهم عليها قباب وتزار للتبرك على حد زعمهم، وجهونا جزاكم الله خيراً؟","title":"حكم كتابة أسماء الأولياء على العربات والسيارات","answer":"الجواب: هذا العمل لا يجوز بل هو منكر بل هو شرك؛ لأن قصدهم التوجه إلى هؤلاء ليحفظوا سياراتهم وليحفظوا ركابهم، ولهذا يكتبون عليها: يا فلان يا فلان أو يا رسول الله أو يا علي أو ما أشبه ذلك، كل هذا لا يجوز وكله من الشرك الأكبر؛ لأنه استغاثة بغير الله ولجأ إلى غير الله، ودعاء لغير الله، يقصدون من هذا أن يمدهم بما يسبب سلامة رحلتهم وسيرهم في الداخل أو في الخارج، فلا يجوز مثل هذا العمل. نعم.\nالمقدم: جزاكم الله خيراً أرجو تعريفاً كاملاً لأولياء الله ومن هم، وهل عندهم علامات مميزة، وهل تصح زيارتهم للتبرك وقضاء الحوائج سواءً كانوا أحياءً أم أموات، جزاكم الله خيرا؟\nالشيخ: أولياء الله هم أهل التقوى والإيمان هم أهل الصلاح والاستقامة على دين الله، هم على ما جاء به رسوله عليه الصلاة والسلام، هؤلاء هم أولياء الله، وهم أهل التقوى وهم أهل الإيمان كما قال الله سبحانه: أَلا إِنَّ أَوْلِيَاءَ اللَّهِ لا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ [يونس:62] ثم فسرهم فقال: الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ [يونس:63] هؤلاء هم أولياء الله، هكذا في سورة يونس، وقال في سورة الأنفال: وَمَا كَانُوا أَوْلِيَاءَهُ إِنْ أَوْلِيَاؤُهُ إِلَّا الْمُتَّقُونَ [الأنفال:34].\nفأولياء الله هم أهل التقوى هم أهل الإيمان هم الذين أطاعوا الله ورسوله واستقاموا على دين الله، وتركوا الشرك والمعاصي هؤلاء هم أولياء الله، يجب حبهم في الله، ولكن لا يجوز دعاؤهم من دون الله ولا الاستغاثة بهم ولا البناء على قبورهم، هذا منكر، ولا البناء على قبور الأنبياء أيضاً، يقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد.\nوقال عليه الصلاة والسلام: ألا وإن من كان قبلكم -يعني: من الأمم- كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك، رواه مسلم في الصحيح، فنهر الناس عن اتخاذ المساجد على قبور الأنبياء والصالحين، وحذرهم من ذلك، ولعن من فعل هذا، وروى مسلم في الصحيح عن جابر  قال: نهى رسول الله أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه.\nفلا يبنى عليه قبة ولا غرفة ولا مسجد بل يجب الحذر من ذلك، بل تترك القبور بارزة شامسة كما كانت في عهد النبي ﷺ في البقيع، وفي غيره في الأرض الواضحة التي ليس فيها بناء يكون القبر بارزاً على الأرض قدر شبر ونحوه؛ حتى يعرف أنه قبر ولا يبنى عليه ولا يجصص، ولا يجعل عليه قبة ولا مسجد كل هذا لا يجوز، وهذه القباب والمساجد التي توضع على القبور من أسباب الشرك، إذا رآها العامي معظمة بالقباب والمساجد وربما فرشوها وربما طيبوها صار هذا من أسباب الشرك، بدعة يترتب عليها شرك أكبر نسأل الله العافية، فإن العامة إذا رأوا هذا العمل دعوها من دون الله واستغاثوا بها، وتمسحوا بها إلى غير ذلك.\nأما زيارة المؤمن ليسلم على أخيه، يعني: على قبره إذا كان ظاهراً بارزاً ليس فيه قبة ولا مسجد ولا فلا بأس بل سنة، النبي عليه السلام قال: زوروا القبور؛ فإنها تذكركم الآخرة، فإن زار القبور ليسلم عليهم ويدعو لهم فهذا مشكور وهذه سنة، أما أن يزورهم ليدعوهم من دون الله أو يستغيث بهم أو يطلبهم المدد فهذا شرك أكبر لا يجوز، كالذي يقول لصاحب القبر: المدد المدد، أو يا سيدي فلان أغثني أو انصرني، أو اشف مريضي، أو أنا في جوارك، أو أنا في حسبك، هذا دعاء لغير الله وشرك بالله ، فهذا من جنس عمل الجاهلية الأولى، أبي جهل وأشباهه.\nفالواجب على المسلمين أن يحذروا هذه الأمور وأن يتواصوا ويتناصحوا بتركها أينما كانوا، وأما الأحياء منهم إذا زارهم يسلم عليهم لحبهم في الله، فلا بأس يزورهم لحبهم في الله، لا للتبرك بهم، ولكن يزورهم .. يسلم عليهم ويعرف أحوالهم ويتذاكر معهم في الخير أو في العلم كل هذا طيب، أو ليدعوا له ليستغفروا له لا بأس أيضاً ... قال: استغفروا لي أو ادعوا لي لا بأس، أما أن يزوره لأجل الاعتقاد فيه أنه يدعى من دون الله، أو أنه يصلح أن يعبد من دون الله حياً وميتاً؛ لأنه ينفع أو يضر أو لأنه يتصرف في الكون أو ما أشبه ذلك من اعتقاد الجهلة فهذا لا يجوز، يقول الله جل وعلا لنبيه ﷺ: قُلْ لا أَمْلِكُ لِنَفْسِي نَفْعًا وَلا ضَرًّا إِلَّا مَا شَاءَ اللَّهُ وَلَوْ كُنتُ أَعْلَمُ الْغَيْبَ لاسْتَكْثَرْتُ مِنَ الْخَيْرِ وَمَا مَسَّنِيَ السُّوءُ إِنْ أَنَا إِلَّا نَذِيرٌ وَبَشِيرٌ لِقَوْمٍ يُؤْمِنُونَ [الأعراف:188].\nفإذا كان ﷺ وهو سيد الخلق وأفضل الخلق لا يملك لغيره نفعاً ولا ضرا ولا يعلم الغيب فكيف بغيره من الناس، فعلم الغيب إلى الله  وهو النافع الضار المعطي المانع جل وعلا، فليس لأحد أن يدعو غير الله بالأموات أو الغائبين أو الأشجار والأحجار أو الجن أو الملائكة، بل هذا من الشرك بالله .\nوليس له أن يعتقد في أحد من المخلوقات أنه ينفع ويضر دون الله، أو أنه يصلح أن يعبد من دون الله ويدعى من دون الله، كل هذا اعتقاد باطل وكفر نسأل الله العافية، أما الحي الحاضر القادر يقول: يا أخي أعني على كذا لا بأس، حي حاضر تقول له: ساعدني على إصلاح سيارتي، على عمارة بيتي، على مزرعتي وهو قادر يسمعك ويستطيع أن يساعدك بما يسر الله لا بأس، هذه أمور جائزة فيما بين الناس، قال تعالى في قصة موسى: فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15]؛ لأنه حي يسمع كلامه وموسى يقدر أن يغيثه، فلا بأس بهذا.\nأما دعاء الأموات والاستغاثة بالأموات أو الغائبين، يعني: يعتقد فيهم أنهم يسمعون دعاءه وينفعون أو يضرون، هذا هو الشرك الأكبر، هذا عمل الجاهلية الأولى نسأل الله العافية، ولو قال: إني ما قصدت أنهم ينفعون أو يضرون، ولو قال: أقصد أنهم شفعاء عند الله، هذا شرك المشركين المشركون ما قصدوا أنهم ينفعون ويضرون، بل أرادوهم شفعاء عند الله، وأرادوهم أن يقربوهم إلى الله كما قال تعالى: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18] قال الله سبحانه: قُلْ أَتُنَبِّئُونَ اللَّهَ بِمَا لا يَعْلَمُ فِي السَّمَوَاتِ وَلا فِي الأَرْضِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ [يونس:18] فسماه: شركاً، وقال  في سورة الزمر: وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:3] ما قالوا: إلا أنهم ينفعون أو يضرون لا قالوا: ليقربونا إلى الله زلفى هذه عقيدتهم يعلمون أن النافع والضار هو الله وحده، ولكنهم يطلبون من الأولياء أو من الأنبياء أو من الملائكة الشفاعة إلى الله ليعطيهم مطالبهم، ويزعمون أنهم شفعاء وأنهم يقربون إلى الله ولا يعتقدون أنهم يتصرفون في الكون أو ينفعون أو يضرون لا، ليس هذا من اعتقاد الجاهلية، ومع هذا كفرهم الله وقاتلهم الرسول ﷺ على شركهم هذا.\nفالواجب على كل من يدعي الإسلام أن يتبصر ويتفقه في دينه، وأن يحذر التعلق بأهل القبور، ودعاءهم من دون الله، والاستغاثة بهم والنذر لهم والذبح لهم، وأن هذا هو شرك الجاهلية، كما يفعل هذا بعض الناس عند قبر السيد البدوي أو السيد الحسين أو الشيخ عبد القادر في العراق أو غيرهم، كل هذا شرك بالله لا يجوز، لا مع الحسين ولا مع البدوي ، ولا مع الشيخ عبد القادر الجيلاني ولا مع غيرهم من الناس، ولا مع ابن عربي في الشام ولا مع غيرهم.\nالواجب الإخلاص لله في العبادة؛ لأنه حقه سبحانه وتعالى.\nقال تعالى: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] وقال سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] يعني: أمر وأوصى أن لا تعبدوا إلا إياه، وقال سبحانه: يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ [البقرة:21]، وقال جل وعلا: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] هذا أصل الدين وأساس الملة، وهذا أعظم واجب وأهم واجب أن تعبد الله وحده، بدعائك ونذرك وذبحك وصلاتك وصومك وغير ذلك.\nوقال تعالى: قُلْ إِنَّ صَلاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ [الأنعام:162-163] والنسك: يطلق على الذبح وعلى العبادة، فكما أن الصلاة لله، هكذا الذبح لله، فالذي يذبح للجن أو يتقرب لأصحاب القبور أو الأشجار والأصنام بالذبائح هذا شرك بالله عز وجل، وهكذا دعاؤهم والاستغاثة بهم وطلب المدد مثل يقف على قبره: المدد المدد، أو يدعوه من قريب: يا سيدي البدوي أو يا سيدي الحسين المدد المدد ، أو يا سيدي عبد القادر المدد المدد هذا الشرك الأكبر، هذا شرك بالله عز وجل وعبادة لغيره، قال سبحانه وتعالى: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] أحداً عام يعم الأنبياء وغيرهم، نكرة في سياق النهي تعم الأنبياء والملائكة والجن والإنس.\nوقال سبحانه وتعالى: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: المشركين، وقال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] فسمى دعاة غير الله: كفاراً، ولو قالوا: ما نسميه إله، ولو قالوا: نسميهم: سادة أو نسميهم أولياء متى دعوهم واستغاثوا بهم فقد جعلوهم آلهة وإن لم يسموهم آلهة، فلا عبرة بالأسماء العبرة بالحقائق، فالذي يعبده من دون الله ويستغيث به قد جعله إلهاً وإن لم يسمه إلهاً، وإن قال: هو السيد أو هو الولي أو هو كذا أو كذا بأسماء أخرى، والاعتبار في الأمور بالحقائق والمعاني لا بالألفاظ.\nنسأل الله أن يهدي إخواننا .. جميع المسلمين، نسأل الله أن يرشد الجاهل الحق والهدى وأن يكثر في المسلمين علماء الحق وعلماء الهدى؛ حتى يبصروا الناس وحتى يرشدوهم إلى توحيد الله، وإلى الحق الذي بعث الله به نبيه محمد عليه الصلاة والسلام.\nونسأل الله أن يهدي الجاهل إلى أن يتعلم ويسأل ويتبصر ولا يرضى بالتقليد الأعمى، نصيحتي لجميع من يتصل بالقبور أو يدعو القبور أو يجهل أحكام الله، نصيحتي للجميع أن يسألوا العلماء علماء الحق علماء السنة أهل البصيرة يسألوهم مثل: أنصار السنة في مصر، مثل: شيخ الأزهر، مثل: علماء السنة في الشام في الأردن في أي مكان، علماء الحق المعروفين بالسنة والتوحيد والإخلاص والبصيرة، وهكذا في كل مكان في أفريقيا وفي أوروبا وفي أمريكا في كل مكان.\nالواجب على من جهل الحكم أن يسأل ولا يقدم على شيء على غير بصيرة، الله يقول سبحانه في كتابه العظيم: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43] ويروى عنه عليه السلام أنه قال لقوم أفتوا بغير علم: ألا سألوا إذ لم يعلموا، إنما شفاء العي السؤال، وكان الصحابة يسألونه عليه الصلاة والسلام، ويعلمهم ويجيبهم حتى النساء يسألونه ويجيبهم، وقال له بعض النساء: يا رسول الله! ذهب الرجال بحديثك فاجعل لنا يوماً نسألك ونتحدث إليك فوعدهم وجمعهم في مكان وأتاهم وسألوه عن حاجاتهم عليه الصلاة والسلام فالواجب على العلماء أن ينبسطوا للجهلة حتى يعلموهم، وأن يعتنوا بالكتاب والسنة وأن تكون الفتاوى من الكتاب والسنة لا من التقليد الأعمى، بل من كتاب الله العظيم وسنة رسوله الأمين، على العالم أن يتبصر من طريق الكتاب والسنة، وأن يعلم الناس على ضوء الكتاب والسنة، وأن يرشدهم إلى أحكام الله التي دل عليها كتابه العظيم وسنة رسوله الأمين عليه الصلاة والسلام، وأن يحذر التساهل في هذه الأمور.\nرزق الله الجميع الهداية والتوفيق.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8932/حكم-كتابة-اسماء-الاولياء-على-العربات-والسيارات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_347/34702.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":10796,"question":"السؤال الأخير الذي نعرضه لأخينا في هذه الحلقة يقول: تقوم بعض النساء عندنا بزيارة القبور والمساجد، ومن خلال الزيارة يقمن بجمع الأطفال داخل المسجد، أو على القبور، ويفرقن عليهم خبزًا، وبعض الأشياء، ويقلن: لوجه الله، ثم يقمن بدعاء الولي الذي زرن لأجله، ويقلن: يا ولي عافني، واحفظ أولادي، وكثيرًا من الدعاء، فما رأيكم -يا سماحة الشيخ- في هذا العمل؟","title":"حكم زيارة المرأة للمشاهد والقبور ودعائها الأولياء","answer":"الجواب:  هذا عمل خطير، يجب الحذر منه، النساء ممنوعات من زيارة القبور، وإنما الإذن للرجال، يقول ﷺ: زوروا القبور فإنها تذكركم الآخرة ولعن زائرات القبور من النساء؛ لأنهن فتنة، وصبرهن قليل، أما إذا كان مع ذلك دعوة الموتى، والاستغاثة بالموتى صار شركًا أكبر، صار الشرك الأكبر، هكذا الذبح لهم، طلبهم المدد، هذا شرك أكبر من الرجال والنساء جميعًا، فالذي يأتي القبور ليدعوها من دون الله، ويطلبها النصر والمدد والعون، هذا أتى شركًا عظيمًا من الرجال والنساء جميعًا، وهذا شرك المشركين، هذا شرك عباد القبور، كـأبي جهل، وأصحابه من عباد القبور، وهكذا توزيع الصدقات إذا كان يقصد بهذا التقرب إلى الموتى بذلك، وأنه يتصدق، ينوي التقرب بالصدقة لهم، يعتقد أنهم ينفعونه، يتصدق عند قبورهم، وأنهم بهذه الصدقة التي يتقرب بها إليهم ينفعونه؛ مثل لو صلى لهم. وأما إن كان لا، صدقة يطلب من الله ثوابها، ولكن يظن ويعتقد أنها عند القبور أفضل، هذه بدعة، ما هي عند القبور أفضل، الصدقة يتصدق في بيته في أي محل، وإذا كانت عن طريق السر كان أفضل إلا إذا دعت الحاجة إلى الجهر، ولكن ليس محلها القبور؛ في الأسواق.. البيت.. في أي مكان في المسجد لمن سأل لا بأس. والخلاصة أن زيارة النساء للقبور لا تجوز، وكونهن يذبحن للأموات، أو يطلبن منهم المدد، أو الغوث، أو شفاء المرضى، هذا شرك أكبر، سواء وقع من امرأة، أو من الرجل، حتى ولو فعله في بيته، ما هو بعند القبور، يا سيدي فلان! يا عبدالقادر! يا حسين! يا علي! يا رسول الله! ولو في بيته، ولو في أي مكان بعيد عن المدن والقبور فهو شرك أكبر، ولو أنه في الصحراء ما عنده أحد، إذا قال: يا رسول الله! انصرني، أو يا رسول الله! اشف مريضي، أو ما أشبه ذلك فقد عبده من دون الله بهذا الدعاء، أو قال: يا سيدي الحسين! أو يا سيدي الحسن! أو يا سيدي علي! أو يا سيدي عبدالقادر! أو أحمد البدوي، أو ما أشبه ذلك، يطلبه المدد والعون، والغوث، هذا من الشرك الأكبر. وهكذا إذا تقرب له بالذبائح، سواء عند قبره، أو بعيدًا عن قبره، يذبح من أجل التقرب إليه، يرى أنه إذا ذبح له يمده بأشياء، أو يعطيه أشياء، أو يحصل له أشياء، فالذبح لغير الله شرك أكبر، قال تعالى: قُلْ إِنَّ صَلاتِي وَنُسُكِي يعني: ذبحي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ [الأنعام:162] لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:163] قال سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:2] فأمر بالصلاة والنحر لله . وقال -عليه الصلاة والسلام-: لعن الله من ذبح لغير الله فالذبح عبادة عظيمة كالصلاة، فإذا ذبح لأصحاب القبور، وتقرب إليهم بذلك يرجو شفاعتهم، ويرجو أنهم يقربونه من الله زلفى، أو تصدق يطلب الأجر منهم، والثواب منهم، أو حج لقبورهم، أو ما أشبه ذلك من المقاصد التي يفعلها، يتقرب بها إلى أصحاب القبور، هو يكون بهذا قد عبدهم، وجعلهم آلهة يعبدهم مع الله بصلاته لهم، أو دعائه لهم، أو ذبحه لهم، أو نذره لهم، أو غير ذلك، ولا حول ولا قوة إلا بالله، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/8977/حكم-زيارة-المراة-للمشاهد-والقبور-ودعاىها-الاولياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_352/35207.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":10816,"question":"من بغداد الأعظمية حي تونس رسالة وصلت إلى البرنامج من المستمع: (ع. خ. م) عرضنا سؤالًا له في حلقة مضت، وفي هذه الحلقة يقول: ما رأي سماحة الشيخ في العائلة التي عندما يولد لها مولود تقوم بذبح شاة لأحد الأئمة دون الله، وذلك لنذر كانوا قد نذروه، علمًا أنهم يذبحون للذكر فقط، ولا يذبحون للأنثى، وهل على المولود بعد بلوغه من ذنب؟ ماذا عليه أن يفعل؟ جزاكم الله خيرًا.","title":"حكم الذبح للولي إذا رزق العبد مولوداً","answer":"الجواب:  هذا من الشرك الأكبر، والواجب على من فعله التوبة إلى الله، ثم الندم، وعدم العود إلى ذلك، كونه ينذر ذبيحة للولي فلان، إذا جاءه ولد هذا شرك أكبر -نعوذ بالله- فالنذر عبادة لله  فالذي يفعل هذا عليه التوبة إلى الله، وعدم العودة إلى مثل هذا، وأما الطفل فليس عليه شيء؛ لأنه ليس من عمله والله يقول سبحانه: وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164] لكن الذي فعل من رجل أو امرأة عليه التوبة، والرجوع إلى الله، والندم على ما مضى، وألا يعود إلى ذلك، والله يقول سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا [التحريم:8]، فدعاء غير الله، والاستغاثة بغير الله من الأولياء والأنبياء من أصحاب القبور، أو الاستغاثة بالجن أو بالملائكة أو بالنجوم والكواكب كل هذا من الشرك الأكبر، كل هذا من عبادة غير الله . وهكذا النذر لهم والذبح لهم، كونه ينذر للأموات، أو للملائكة أو للجن، أو للكواكب، ليشفعوا له، أو يخلصوه من النار، أو يشفوا مريضه، أو يردوا غائبه، أو ما أشبه ذلك، كل هذا من الشرك الأكبر. يقول الله سبحانه: قُلْ إِنَّ صَلاتِي وَنُسُكِي( يعني: ذبحي )وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:162-163] ويقول سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:2] ويقول : وَمَا أَنفَقْتُمْ مِنْ نَفَقَةٍ أَوْ نَذَرْتُمْ مِنْ نَذْرٍ فَإِنَّ اللَّهَ يَعْلَمُهُ [البقرة:270]. فالنذر عبادة التزام بعبادة الله من صدقة، أو صلاة، أو غير ذلك لا تجوز إلا لله وحده  فالذي ينذر ذبيحة إن رزقه الله مولودًا ذكرًا للبدوي، أو للشيخ عبدالقادر، أو للنبي ﷺ أو للحسن أو الحسين، أو علي بن أبي طالب  أو لغيرهم، هذا يعتبر من الشرك الأكبر. وهكذا لو قال: يا علي انصرني، أو اشف مريضي، أو يا سيدي الحسين أو الحسن، أو يا رسول الله، أو يا سيدي عبدالقادر، أو ما أشبه ذلك، انصرني، أو اشف مريضي، أو أنا في جوارك وحسبك، أو المدد المدد، كل هذا من الشرك الأكبر.. كل هذا من عبادة غير الله  والله يقول -جل وعلا-: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] ويقول سبحانه: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] ويقول : فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ [غافر:14] ويقول : وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] ويقول سبحانه: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] ويقول : وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: من المشركين، والآيات في هذا كثيرة. ويقول النبي ﷺ: الدعاء هو العبادة والله يقول سبحانه: وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60] فالواجب على جميع المسلمين، وعلى جميع المكلفين الحذر من ذلك، وأن تكون العبادة لله وحده، كما قال : وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ [البينة:5] وقال: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، فهو الذي يدعى، وهو الذي يرجى  هو الذي يتقرب إليه بالذبائح والنذور دون غيره . نسأل الله للجميع الهداية والتوفيق، ونسأل الله أن يصلح أحوال المسلمين، وأن يمنحهم الفقه في الدين، وأن يعيذهم من كل ما يخالف شرعه، الله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9002/حكم-الذبح-للولي-اذا-رزق-العبد-مولودا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_354/35413.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":10822,"question":"من بغداد الأعظمية حي تونس رسالة وصلت إلى البرنامج من المستمع: (ع. خ. م) عرضنا سؤالًا له في حلقة مضت، وفي هذه الحلقة يقول: ما رأي سماحة الشيخ في العائلة التي عندما يولد لها مولود تقوم بذبح شاة لأحد الأئمة دون الله، وذلك لنذر كانوا قد نذروه، علمًا أنهم يذبحون للذكر فقط، ولا يذبحون للأنثى، وهل على المولود بعد بلوغه من ذنب؟ ماذا عليه أن يفعل؟ جزاكم الله خيرًا.","title":"حكم الذبح للولي إذا رزق العبد مولوداً","answer":"الجواب:  هذا من الشرك الأكبر، والواجب على من فعله التوبة إلى الله، ثم الندم، وعدم العود إلى ذلك، كونه ينذر ذبيحة للولي فلان، إذا جاءه ولد هذا شرك أكبر -نعوذ بالله- فالنذر عبادة لله  فالذي يفعل هذا عليه التوبة إلى الله، وعدم العودة إلى مثل هذا، وأما الطفل فليس عليه شيء؛ لأنه ليس من عمله والله يقول سبحانه: وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164] لكن الذي فعل من رجل أو امرأة عليه التوبة، والرجوع إلى الله، والندم على ما مضى، وألا يعود إلى ذلك، والله يقول سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا [التحريم:8]، فدعاء غير الله، والاستغاثة بغير الله من الأولياء والأنبياء من أصحاب القبور، أو الاستغاثة بالجن أو بالملائكة أو بالنجوم والكواكب كل هذا من الشرك الأكبر، كل هذا من عبادة غير الله . وهكذا النذر لهم والذبح لهم، كونه ينذر للأموات، أو للملائكة أو للجن، أو للكواكب، ليشفعوا له، أو يخلصوه من النار، أو يشفوا مريضه، أو يردوا غائبه، أو ما أشبه ذلك، كل هذا من الشرك الأكبر. يقول الله سبحانه: قُلْ إِنَّ صَلاتِي وَنُسُكِي( يعني: ذبحي )وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:162-163] ويقول سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:2] ويقول : وَمَا أَنفَقْتُمْ مِنْ نَفَقَةٍ أَوْ نَذَرْتُمْ مِنْ نَذْرٍ فَإِنَّ اللَّهَ يَعْلَمُهُ [البقرة:270]. فالنذر عبادة التزام بعبادة الله من صدقة، أو صلاة، أو غير ذلك لا تجوز إلا لله وحده  فالذي ينذر ذبيحة إن رزقه الله مولودًا ذكرًا للبدوي، أو للشيخ عبدالقادر، أو للنبي ﷺ أو للحسن أو الحسين، أو علي بن أبي طالب  أو لغيرهم، هذا يعتبر من الشرك الأكبر. وهكذا لو قال: يا علي انصرني، أو اشف مريضي، أو يا سيدي الحسين أو الحسن، أو يا رسول الله، أو يا سيدي عبدالقادر، أو ما أشبه ذلك، انصرني، أو اشف مريضي، أو أنا في جوارك وحسبك، أو المدد المدد، كل هذا من الشرك الأكبر.. كل هذا من عبادة غير الله  والله يقول -جل وعلا-: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] ويقول سبحانه: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] ويقول : فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ [غافر:14] ويقول : وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] ويقول سبحانه: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] ويقول : وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: من المشركين، والآيات في هذا كثيرة. ويقول النبي ﷺ: الدعاء هو العبادة والله يقول سبحانه: وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60] فالواجب على جميع المسلمين، وعلى جميع المكلفين الحذر من ذلك، وأن تكون العبادة لله وحده، كما قال : وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ [البينة:5] وقال: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، فهو الذي يدعى، وهو الذي يرجى  هو الذي يتقرب إليه بالذبائح والنذور دون غيره . نسأل الله للجميع الهداية والتوفيق، ونسأل الله أن يصلح أحوال المسلمين، وأن يمنحهم الفقه في الدين، وأن يعيذهم من كل ما يخالف شرعه، الله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9002/حكم-الذبح-للولي-اذا-رزق-العبد-مولودا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_354/35413.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":10855,"question":"يسأل سؤالًا آخر ويقول: البعض يذكر أن القبر يرفع عن الأرض بمقدار شبر، فهل هذا صحيح، أم لا؟ وما دليله؟ وإن زيد على شبر فما حكمه؟ وكيف نوفق بين ذلك وبين ما ورد عن علي  كما ورد في مسلم: \"هل أبعثك على ما بعثني عليه رسول الله ﷺ ألا تدع صورة إلا طمستها، ولا قبرًا مشرفًا إلا سويته\"؟","title":"مقدار ارتفاع القبر عن الأرض","answer":"الجواب:  نعم القبور لا بأس أن ترفع قدر شبر كما ثبت من حديث سعد بن أبي وقاص: \"أنه رفع قبره قدر شبر، وأن قبر النبي ﷺ كان كذلك\" والسر في ذلك لتعرف أنها قبور حتى لا تمتهن، وحتى لا توطأ، وحتى لا يجلس عليها، فإنها إذا سويت بالأرض قد تخفى معالمها، فإذا رفعت قدر شبر وما يقاربه فهذا يعفى عنه ومشروع؛ لتعرف أنها قبور، ولتصان ولا تداس. أما حديث علي وما جاء في معناه فالمراد به الإشراف الزائد على هذا، كأن يُبنى عليها مساجد، أو قباب، أو بنية هذه تزال، وإنما ترفع بترابها نفس التراب الذي أخرج من اللحد، هذا يجعل فوقه؛ لأنه إذا دفن بقي بعض التراب الذي إلى اللحد، وبعض التراب الآخر؛ لأنه لو كان مرصوصًا أولًا .... عظيمًا، ثم بعد ما أخرج يتراكم بعضه على بعض، ويبقى منه بقية إذا دفن الميت، فهذه البقية تجعل على القبر علامة على أنه قبر، وقد نهى النبي ﷺ أن يزاد على ترابه، فالتراب الذي بقي من الميت يكون هو المرفوع على محله علامة، على أنه قبر، ولا يؤتى بزيادة أخرى من تراب، أو لبن، أو حصى، أو غير ذلك، لا بل يكفي التراب، وتوضع النصايب علامة على أنه قبر في طرفيه علامة أنه قبر، ولا بأس أن يوضع عليه شيء من الحصباء لحفظ التراب ويرش بالماء لا بأس كل هذا لا بأس به. نعم. المقدم: الحمد لله الحمد لله جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9023/مقدار-ارتفاع-القبر-عن-الارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_356/35604.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":10916,"question":"إذا كان الإمام الذي يؤم المصلين ممن يعتقدون في الأولياء والصالحين، ويجوزون الاستغاثة بهم، فهل يصلى خلفه؟","title":"حكم الصلاة خلف من يعتقد في الأولياء ويستغيث بهم","answer":"الجواب:  لا يصلى خلفه؛ هذا كافر لا يصلي، إذا كان يجوز الاستغاثة بغير الله، ودعاء الأموات، والاستغاثة بالأموات، أو الطواف بالقبور هذا لا يصلى خلفه ولا كرامة؛ لأنه كافر، والكافر لا يصلى خلفه، نسأل الله العافية، ولكن ينصح ويعلم ولا ييئس منه، لعل الله يهديه، ويمن عليه بالتوبة، نعم.","link":"https://binbaz.org.sa/fatwas/9097/حكم-الصلاة-خلف-من-يعتقد-في-الاولياء-ويستغيث-بهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_361/36107.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":10919,"question":"هل تجوز الاستغاثة بالرسول ﷺ؟","title":"حكم الاستغاثة بالرسول صلى الله عليه وسلم","answer":"الجواب:  أما في حياته فيما يقدر عليه فلا بأس، كأن يقال: يا رسول الله! أغثنا من هذا الأمير الذي ظلمنا، أو من هذا الشخص الذي ظلمنا، فالرسول يستطيع أن يأمر بعض الصحابة أن يزيل الشر، وأن يغيثهم من ذلك، أما بعد الوفاة فلا، لا يستغاث بأحد لا الرسول، ولا غيره، بعد الوفاة لا يستغاث بالأموات، لا الرسول ولا غيره -عليه الصلاة والسلام- ومن هذا الباب من باب الجواز قوله سبحانه: فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15]، استغاث الإسرائيلي موسى على القبطي؛ لأن موسى حي يسمع كلامه، ويستطيع إغاثته، ومن هذا استغاثة الإنسان بإخوانه في الحرب على في قتال الأعداء، هذا لا بأس به، أما طلب الأموات والاستغاثة بالأموات، أو بالأصنام، أو بالجمادات، أو بالأشجار، والأحجار، أو بالنجوم هذا كفر بالله، شرك أكبر، وهكذا الاستغاثة بالحي فيما لا يقدر عليه، كأن يستغيث به في أن يصلح قلبه بأمر سري في نفسه .............. أو بأن ينقذه من النار بسر فيه، أو يدخله الجنة في سر فيه هذا كفر بالله. أما إذا قال: أعني على أسباب دخول الجنة يعلمه، يتفقه في الدين، أو على إصلاح قلبه بالتذكير والوعظ والتوجيه إلى الخير هذا أمر مطلوب، يعظه ويذكره وينصحه، أما أن يعتقد أن هذا الولي -وهو وإن كان حيًا- يعتقد أنه يستطيع إدخال الجنة، وإنجاء الناس من النار، وشفاء المرضى بسره بشيء فيه هذا كفر بالله، نعوذ بالله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9098/حكم-الاستغاثة-بالرسول-صلى-الله-عليه-وسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_361/36108.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":11386,"question":"من أسئلتها -سماحة الشيخ- تقول: ما حكم وضع الأشجار على القبر وذلك بقصد تماسك التربة وعدم انجراف القبر من شدة الريح وكذلك رشه بالماء أيضًا للحفاظ عليه من الانجراف؟","title":"حكم رش القبر بالماء ووضع الأشجار عليه لئلا ينجرف","answer":"الجواب:  لا بأس برشه ووضع الحصباء عليه، يوضع عليه حصباء تمسكه، أما الشجر فلا، لا حاجة إلى ذلك؛ لأنه قد يعتقد فيه شيء، أما نصب الجريدة الذي فعلها النبي ﷺ فكان في قبرين اطلع على عذابهما -عليه الصلاة والسلام- أما نحن فلا نعرف المعذب من غير المعذب، فلا يشرع لنا أن نجعل عليه جريد ولا شجر، ولكن إذا جعل عليه حصباء ورش بالماء فهذا حسن لأجل ضبط التراب.","link":"https://binbaz.org.sa/fatwas/9555/حكم-رش-القبر-بالماء-ووضع-الاشجار-عليه-لىلا-ينجرف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29312.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":11417,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من جمهورية مصر العربية، محافظة قنا، وباعثها المستمع إيهاب صلاح الدين، يقول: ما هي مبطلات الإسلام؟ وإذا وقع أحد في أحد هذه المبطلات، فكيف يرجع إلى الإسلام مرة أخرى؟ جزاكم الله خيرًا.","title":"نواقض الإسلام وخطرها على الفرد والمجتمع","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فهذا سؤال عظيم، يجب على كل مؤمن أن يفهمه، وأن يعتني به؛ لأن نواقض الإسلام اليوم كثيرة، وخطرها عظيم، وهذا السؤال فيه فائدة كبيرة لكل مسلم، قد ألف العلماء في نواقض الإسلام مؤلفات، وذكروا في كتب الفقه بابًا مستقلًا في هذا الباب، في هذه المسألة سموه: باب حكم المرتد، باب، سموا هذا المقام، مسائل هذا الباب جعلوها تحت باب وهو باب حكم المرتد، وهو الذي يكفر بعد إسلامه، ثم ذكروا النواقض التي يحصل بها الردةن يقال لها: نواقض الإسلام، مبطلات الإسلام، أسباب الردة، وهي كثيرة ذكرها العلماء في هذا الباب، في مذهب الحنابلة، والشافعية، والمالكية، والحنبلية وغيرهم، وذكرها أيضًا جماعة في مؤلفات خاصة مستقلة. فيجب على المؤمن والمؤمنة الحذر من ذلك، والتفقه في ذلك؛ حتى لا يقع فيه، ومنها: الشرك بالله  منها: الشرك وهو أعظمها، كدعاء أصحاب القبور، كـالبدوي، أو الحسين، أو غيرهم، والاستغاثة بهم، والنذر لهم، والذبح لهم، وكسؤال الأصنام، أو الضراعة إلى الجن، والاستغاثة بالجن، أو بالملائكة، أو بالنجوم، كل هذا من الشرك بالله ناقض من نواقض الإسلامن ومن أسباب بطلان الإسلام. كذلك: سب الله، أو سب الرسول -عليه الصلاة والسلام- أو الاستهزاء بدين الله، أو الاستهزاء بالقرآن، أو بالرسول ﷺ قال الله تعالى: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ * لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة: 65-66]. من ذلك: ترك الصلاة؛ لأن الصلاة عمود الإسلام، وهي أعظم الأركان بعد الشهادتين، وإذا جحد وجوبها؛ كفر إجماعًا، إذا قال: ما هي بواجبة؛ كفر إجماعًا، وإن تركها تساهلًا وتكاسلًا؛ كفر في الصحيح من قولي العلماء. وهكذا لو جحد وجوب الزكاة قال: ما هي بواجبة الزكاة على الناس، أو قال: صيام رمضان ليس بواجب على الناس؛ كفر عند الجميع، أو قال: إن الحج مع الاستطاعة لا يجب على المكلفين، كفر إجماعُا؛ لأن الله أوجب الحج مع الاستطاعة، أو قال: إن الزنا حلال، استحل ما حرم الله، قال: الزنا حلال؛ كفر عند الجميع، ردة ... من نواقض الإسلام.  أو قال: إن الخمر المسكرات حلال؛ كفر عند الجميع، أو قال: إن الربا حلال، ما فيه ربا، كل الربا حلال، هذا كفر عند الجميع، أو قال: اللواط حلال، إتيان الذكور، هذا ردة عند الجميع، والعياذ بالله. أو قال: إن الحكم بغير الشريعة جائز، لا بأس بتحكيم القوانين الوضعية، وترك الكتاب والسنة، من أجاز هذا، وأباحه؛ كفر إجماعًا، وهي نواقض كثيرة حتى بلغ بعضهم أربعمائة ناقض، نعم، إذا تدبرها الإنسان، وتقصاها فهي كثيرة. فالواجب على المؤمن الحذر، وأن يتفقه في دين الله، ويتبصر، وكذلك يراجع هذا الباب، باب حكم المرتد، طالب العلم يراجع هذا الباب، ويتأمل؛ حتى يستفيد، أو يفيد، نسأل الله للجميع العافية، والسلامة، لا حول ولا قوة إلا بالله، لا حول ولا قوة إلا بالله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9598/نواقض-الاسلام-وخطرها-على-الفرد-والمجتمع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_294/29401.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":11420,"question":"الشق الآخر من سؤاله: كيف يرجع إلى الإسلام مرة أخرى من وقع في ناقض من نواقض الإسلام؟","title":"كيفية الرجوع إلى الإسلام لمن وقع في مبطلاته","answer":"الجواب:  التوبة، باب التوبة مفتوح، إذا وقع في ناقض؛ فعليه أن يرجع إلى الإسلام بالتوبة، يندم على الماضي، ويعزم ألا يعود، ويترك هذا الناقض، فإذا كان كفره بدعاء الأموات، والاستغاثة بالأموات والأصنام؛ ترك ذلك، وتاب إلى الله من ذلك، وبهذا يرجع إلى الإسلام، إلا إذا كان كفره بأنه جحد وجوب الصلاة؛ يقر، يقول: لا، أنا غلطان، الصلاة فرض على المكلفين، وأتوب إلى الله من ذلك، ويندم، ويقلع، ويعزم ألا يعود، يتوب الله عليه، أو كان يترك الصلاة لا يصلي، التوبة أن يفعل الصلاة، ويندم على الماضي، ويستغفر مما مضى، ويعزم ألا يعود فيه وهذه التوبة، كذلك إذا كان كفره؛ لأنه يقول: الزنا حلال، إذا تاب وقال: لا. الزنا حرام، وأنا أتوب إلى الله، وأستغفر الله، وقد أخطأت، والله يعلم من قلبه أنه صادق؛ يتوب الله عليه، وهكذا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9603/كيفية-الرجوع-الى-الاسلام-لمن-وقع-في-مبطلاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_294/29402.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":11448,"question":"يسأل أخونا ويقول: هل يجوز التبرك بالتراب الموجود على ضريح الولي المتوفى، وهل هذا التراب يفيد شيئًا، وما هو رأي سماحتكم في هذا؟ جزاكم الله خيرًا.","title":"حكم التبرك بتراب قبور الأولياء","answer":"الجواب:  التبرك بتراب القبور هو منكر، وهو من المحرمات الشركية، لا يجوز التبرك بتراب الولي، ولا غير الولي، البركة من الله  إنما التبرك بالشيء الذي شرعه الله، مثل التبرك بماء زمزم، كونه يشرب منه؛ لأن الله جعل فيه بركة، وأخبر النبي ﷺ أنه مبارك، أو كونه مثلًا: يسأل ربه أن الله يجعل هذا المال مباركًا، يدعو ربه أن الله يبارك فيه له، أو أن الله يبارك له في هذا الولد، فالبركة من الله  ولم يكن الصحابة يتبركون لا بـالصديق، ولا بـعمر، ولا بـعثمان، ولا بـعلي، إنما هذا خاص بالنبي ﷺ كانوا يتبركون بعرقه وريقه -عليه الصلاة والسلام- أما بعده فلا، جميع الأولياء لا يتبرك بهم، إنما هذا خاص بالنبي، عليه الصلاة والسلام. فالتبرك بالأشخاص، أو بالتراب ترابهم، أو آثارهم كله منكر، لا يجوز، بل من وسائل الشرك الأكبر. المقدم: نعوذ بالله، جزاكم الله خيرًا، وأحسن إليكم، إذًا تنصحون المسلمين بالإقلاع عن هذا سماحة الشيخ؟! الشيخ: يجب الحذر من هذا، يجب الحذر، أما دعاؤهم، والاستغاثة بهم هذا الشرك الأكبر، نسأل الله العافية، نعم. المقدم: نسأل الله العافية، نعم.","link":"https://binbaz.org.sa/fatwas/9629/حكم-التبرك-بتراب-قبور-الاولياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38104.mp3","categories":["نواقض الإسلام","التبرك وأنواعه"]},{"id":11610,"question":"سماحة الشيخ! ألاحظ في رسالة أخينا أنه يكثر من قوله: إن هذا لم يرد في القرآن، إن هذا لم يرد في القرآن، هل من تعليق على هذا؟ جزاكم الله خيرًا.","title":"حكم من يحتج بالقرآن فقط وينكر السنة","answer":"الجواب:  نعم، هذا قول طائفة من الناس ترى أنه لا يحتج بالسنة، وإنما يحتج بالقرآن فقط، وأن السنة فيها الضعيف وفيها الصحيح، وأنها عندهم ملتبسة لا يحتج بها، وهذا معناه عصيان قوله -جل وعلا-: أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ [النساء:59] فمعناه: أطيعوا الله فقط، ولا يطاع الرسول،، فالسنة هي أمر الرسول ونهيه -عليه الصلاة والسلام- والله يقول: فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ [النور:63] ويقول -جل وعلا-: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7] ويقول ﷺ: إني أوتيت القرآن ومثله معه.  فهذه الطائفة التي ترى أن السنة لا يحتج بها جميعها طائفة كافرة ضالة، فالواجب على من يعرفهم أن يهجرهم، وأن يعرفهم أنهم على باطل، وأنهم كفار بهذا العمل، بإنكارهم السنة يكفرون، ويخرجون من دائرة الإسلام، بل يجب على كل مسلم أن يقبل السنة، وأن يعمل بما صح منها، وأن يحذر إنكارها، فإنكارها بالكلية، وأنه لا يحتج إلا بالقرآن هذا من أبطل الباطل، وأعظم الكفر، نسأل الله العافية. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9796/حكم-من-يحتج-بالقران-فقط-وينكر-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38807.mp3","categories":["نواقض الإسلام","الفرق والمذاهب"]},{"id":11897,"question":"هل تجوز الصلاة خلف إنسان يعتقد بأنه يوجد في البشر من يعلم الغيب، وهل يؤكل ذبحه؟ جزاكم الله خيرًا.","title":"حكم الصلاة خلف من يعتقد أن من البشر من يعلم الغيب","answer":"الجواب:  من يعتقد أنه يوجد في الدنيا من يعلم الغيب هذا كافر، لا تؤكل ذبيحته، ولا يصلى خلفه، ولا يجوز أن يكون إمامًا. علم الغيب لا يعلمه إلا الله، ليس في الدنيا من يعلم الغيب أحد، لا يعلم الغيب إلا الله، قال الله سبحانه: قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ [النمل: 65]، فعلم الغيب إليه  فلا يعلمه الأنبياء، ولا غيرهم، فالذي يعتقد أنه يوجد في الدنيا من يعلم الغيب من جن أو إنس هو كاذب وكافر -نسأل الله العافية- وعليه أن يتوب إلى الله -جل وعلا- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10081/حكم-الصلاة-خلف-من-يعتقد-ان-من-البشر-من-يعلم-الغيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42518.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":11977,"question":"من يتلفظ بكلمة الكفر من المسلمين -والعياذ بالله- هل تكفيه التوبة والاستغفار، أم يجب عليه الغسل بعد ذلك، جزاكم الله خيرًا؟","title":"حكم توبة من تلفظ بالكفر وقبولها منه في الدنيا","answer":"الجواب:  من تكلم بما يوجب ردته؛ عليه التوبة، ويستحب له الغسل، وقال بعض أهل العلم: يجب الغسل، القول بالوجوب فيه خلاف بين العلماء، والأولى والأقرب أنه مسنون مشروع، وإنما الواجب التوبة والرجوع إلى الله، والإنابة إليه، والندم على ما مضى منه، والإقلاع من معصيته وكفره، والتوبة إلى الله من ذلك بالعزم الصادق ألا يعود في ذلك، وبذلك يتوب الله عليه، قال تعالى: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] وقال النبي ﷺ: التائب من الذنب كمن لا ذنب له فإذا تكلم بالكفر، بأن سب الدين، أو تنقص بالدين، أو سب الصحابة، أو ما أشبه ذلك؛ يجب البدار بالتوبة، وإذا علم ولي الأمر، وثبت لدى ولي الأمر ذلك؛ وجب أن يعزر ويؤدب ولو تاب، فإن أصر، ولم يتب؛ وجب قتله مرتدًا، نسأل الله العافية.  المقصود: إذا أتى بناقض من نواقض الإسلام، ثم تاب إلى الله توبة صادقة؛ تاب الله عليه، كفى، جميع الذنوب، الله يتوب عليه، لكن بعضها فيه خلاف من جهة قبولها في الحكم الشرعي هل يقتل، أو ما يقتل، أما فيما بينه وبين الله فكل من تاب إلى الله؛ تاب عليه، إذا استوفى الشروط، وأخلص في التوبة، وصدق فيها، فالله يتوب عليه من كل ذنب حتى الشرك، لكن هناك أمور قد توجب قتله، وإن تاب كسب الله، وسب الرسول ﷺ والسحر، فإن جمعًا من أهل العلم قالوا: لا يستتاب في هذا، بل يقتل؛ لأن شره عظيم وفتنته كبيرة، لكن توبته فيما بينه وبين الله صحيحة إذا كان صادقًا فيما بينه وبين الله، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10162/حكم-توبة-من-تلفظ-بالكفر-وقبولها-منه-في-الدنيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_429/42918.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":12182,"question":"تقول: ما حكم من سب الدين، أو سب الرب في إحدى الساعات، ولما حان وقت الصلاة توضأ وصلى الفريضة، فهل أداء الفريضة في ذلك الوقت يعتبر بمثابة إعلان التوبة؟","title":"حكم سب الله أو الدين والتوبة من ذلك","answer":"الجواب:  سب الدين، وسب الرب ردة عظمى أقول: ردة عظمى عن الإسلام -نعوذ بالله- فالواجب على من فعل ذلك أن يبادر بالتوبة والندم والإقلاع، ولا تكفي الصلاة؛ لأن الصلاة ما يكفي، بل لابد من توبة صادقة، وندم على ما وقع منه، وعزم صادق ألا يعود في ذلك؛ لأن الجريمة عظيمة، فلا يجوز له أن يتساهل في هذا الأمر، بل يجب أن يبادر بالتوبة، وحقيقتها الندم على الماضي منه، الندم الحقيقي، والحزن على ما وقع منه، والعزم الصادق ألا يعود في ذلك، وقبل أن يفعل هذا صلاته غير صحيحة؛ لأنها صلاة كافر، فلابد من توبة قبل الصلاة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10368/حكم-سب-الله-او-الدين-والتوبة-من-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_443/44309.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":12222,"question":"يقول في سؤالى آخر: مرضت وأنا صغير، فنذرت أمي إن شفيت، وكبرت أن تذبح ماعزًا عند قبر الولي، ويجتمع عليها الناس، وعندما كبرت؛ أحضرت ماعزًا لتفي بنذرها؛ فأخذت الماعز، وبعتها في السوق، وقلت لها: إن هذا شرك بالله، هل ما قمت به صحيح، أم لا؟ أرجو الإفادة جزاكم الله خيرًا.","title":"حكم الذبح لولي من الأولياء وفاءً بنذر","answer":"الجواب:  قد أحسنت هذا هو الصواب، ليس لها أن تذبح عند قبر الولي، لا عن نذر، ولا عن غير نذر، إذا كان الذبح للولي؛ كان شركًا أكبر، إذا كان القصد التقرب للولي، لفلان أو فلان عند قبر البدوي أو فلان، أو الشيخ عبدالقادر الجيلاني، أو ابن عربي، أو فلان أو فلان، كل هؤلاء لا يجوز التقرب إليهم بالذبائح، ولا يدعى أحد من دون الله، ولا يستغاث به، ولا ينذر له، كل ذلك من الشرك الأكبر. وهكذا الأنبياء -عليهم الصلاة والسلام- لا يجوز للمسلم أن يذبح للنبي، يتقرب إليه، أو يسأله أن يغيثه، أو ينصره، أو يشفي مريضه، لا نبينا محمد ﷺ ولا غيره، هذا حق الله  الله يقول: يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ [البقرة:21] ويقول -جل وعلا-: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُُ [الإسراء:23] ويقول سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ [البينة:5]، ويقول : فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، والنبي  يقول: الدعاء هو العبادة فلا يدعى أحد مع الله، لا نبيًا، ولا ملكًا، ولا جنًا، ولا إنسًا، ولا وليًا، ولا غير ذلك. وهكذا الذبح لا يذبح للأنبياء، ولا للملائكة، ولا للأولياء، ولا يتقرب إليهم بالنذور، ولا غير هذا من العبادات، يقول الله سبحانه: قُلْ إِنَّ صَلاتِي [الأنعام:162] يعني: قل: يا محمد! للناس إِنَّ صَلاتِي وَنُسُكِي [الأنعام:162] يعني: ذبحي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:162-163]، ويقول سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكََ وَانْحَرْ [الكوثر:1-2]، ويقول النبي ﷺ: لعن الله من ذبح لغير الله،. فالتقرب للأولياء بالذبيحة من الشرك الأكبر كونه يذبح عند قبره، أو في غير قبره؛ حتى ولو كان في مكان بعيد، ولو في بيت الإنسان كونه يذبح، ينوي للولي فلان، أو فلان هذا شرك أكبر، مثل لو صلى له، لو صلى له، وسجد له؛ فهو شرك؛ فهكذا إذا ذبح له، أو دعاه، أو استغاث به، أو نذر له، أو قال: يا سيدي! اشفي مريضي، أو انصرني، أو دلني على كذا، أو ما أشبه ذلك، سواء عند قبره، وإلا بعيد عن قبره، هذا كله لا يجوز، هذا حق الله، هو الذي يدعى  هو الذي يسأل، أما الحي الحاضر كونه يذبح له ذبيحة كرامة له؛ لأنه ضيف جاي من سفر، أو لأنه قريب له زاره وذبح له من أجل كرامة ضيف؛ هذا لا بأس به. وهكذا لو قال لأخيه الذي عنده: ساعدني على كذا الحي الحاضر، ساعدني على إصلاح سيارتي، على إصلاح مزرعتي، يتعاون هو وإياه في المزرعة؛ لا بأس، أما الأموات أو الغائبون أو الملائكة أو الأنبياء أو الجن يدعوهم مع الله، أو يستغيث بهم، أو ينذر لهم؛ هذا لا يجوز، هذا من الشرك الأكبر، لا يدعى الغياب، ولا الموتى، ولا الجمادات كالأشجار والأحجار والأصنام، ولا الملائكة كلهم لا يدعون مع الله، ولا يستغاث بهم، ولا ينذر لهم، بل هذا من الشرك الأكبر، نعوذ بالله من ذلك. أما إذا كان بالطرق الحسية مع الأحياء، مثل برقية، يكتب برقية، يقول: أقرضني كذا، أو يكلمه بالهاتف -بالتلفون- أقرضني كذا، أو ساعدني على كذا، مع إنسان حي يكلمه، أو يكتب له رسالة، هذا مثل الحي الحاضر، مثل المشاهد، لا حرج في ذلك، كما قال الله  في قصة موسى: فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15]، فالناس يتعاونون، والأحياء يتعاونون؛ لا حرج في ذلك، لكن دعاء الميت أو الغائب؛ لأنه يعتقد أن فيه سر، أنه يسمع ولو بعد، أو دعاء الجمادات كالأصنام والكواكب هذا كله شرك أكبر، أو دعاء الملائكة أو الجن؛ هذا شرك أكبر؛ لأنهم غائبون عنك، مشغولون بشؤونهم، ليس من جنس الحاضر بين يديك الذي تخاطبه، وتسأله أن يعينك على كذا أو كذا.  وبهذا ينبغي للمؤمن أن يحتاط، ويبتعد عن أسباب الشرك، وعن ذرائعه، وعن أعماله، وقد أحسنت أيها السائل في إخبار أمك، وإيضاح الحق لها، فقد أحسنت في ذلك -بارك الله فيك- نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/10410/حكم-الذبح-لولي-من-الاولياء-وفاء-بنذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_446/44610.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":12284,"question":"ما نوع العلاقة مع جار لا يصلي ولا يصوم، وهو موالٍ للشيوعيين ويتناول المسكرات، وعاق لوالديه، ومؤذٍ لجيرانه، ويسب الرب والدين والعياذ بالله؟ ثم كيف يتم التعامل مع زوجته التي تصلي، ومع أولاده الصغار؟","title":"حكم معاملة الزوجة والجيران لتارك الصلاة والساب للدين","answer":"الجواب:  إذا كان الواقع هو ما ذكره السائل؛ فالواجب مقاطعته وهجره، ورفع أمره إلى ولاة الأمور، كالمحكمة والهيئة؛ حتى ينظر في أمره، وحتى يقام عليه حكم الله؛ لأن هذا ضرره عظيم، وخطره كبير. فالواجب أن يرفع أمره إلى ولي الأمر؛ حتى ينفذ فيه حكم الله، ولا يجوز لجيرانه زيارته، ولا صحبته، ولا أن يدعوه إلى وليمة، أو غيرها، بل يجب هجره ومقاطعته. والواجب على زوجته أيضًا المسلمة أن تبتعد عنه، وأن تذهب إلى أهلها، ولا يجوز لها البقاء معه، ما دام بهذه الحالة؛ لأن لديه مكفرات سبه الله؛ ردة، وتركه الصلاة؛ ردة، وموالاته الشيوعيين، واعتقاده أنهم مصيبون، أو أن أمرهم جائز، أو لا حرج فيه؛ كل هذه ردة عن الإسلام، نسأل الله العافية. فالحاصل\" أن مثل هذا الشخص يجب أن يرفع أمره إلى ولي الأمر إذا كان في بلاد إسلامية، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا تسأل عن العلاقة بزوجته التي تصلي، وعن العلاقة بأولاده؟ الشيخ: بينا أن الواجب عليها أن تبتعد عنه؛ فلا يحل لها البقاء عنده. المقدم: هذه الزوجة؟ الشيخ: الزوجة، بل يجب أن تذهب إلى أهلها؛ لأنه لا يجوز أن تكون زوجة لكافر، وهي مسلمة، بل يجب أن تبتعد عنه، ولا يحل لها البقاء عنده، ولا تمكينه منها لا بقبلة، ولا جماع، ولا غير ذلك، بل يجب أن تنتقل عنه؛ لأن الله حرم على المسلمة أن تنكح الكافر، قال تعالى: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10] قال -جل وعلا-: وَلا تُنكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا [البقرة:221] يعني: لا تزوجوهم حتى يؤمنوا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10484/حكم-معاملة-الزوجة-والجيران-لتارك-الصلاة-والساب-للدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_452/45204.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":12294,"question":"المستمع (ع. ب. ز) من اليمن الجنوبي بعث برسالة يقول فيها: يوجد لدينا مقابر أولياء توفوا من قديم الزمان، ويعتقد الكثير من الناس عندنا بأن لهم كرامات، فهم يأتون بالحلوى والأرز والقهوة والتمر من بلد آخر، ويقولون: إن هذه من كرامات هؤلاء الأولياء، ويؤكدون بأنما كانت معجزة النبي كانت معجزة لولي، فهل هذا الاعتقاد صحيح؟ وهل من المعقول أن يحصل من هؤلاء الأولياء مثل هذه الأشياء؟ نرجو الإفادة والتوجيه جزاكم الله خيرًا.","title":"حكم اعتقاد أن الأولياء يأتون بالحلوى وغيرها","answer":"الجواب:  كونهم يعتقدون أن الأولياء يأتونهم بكذا وكذا من الحلوى، أو غيرها هذا باطل، وهذا من لعب الشياطين، أما كونهم يتقربون للأولياء بالحلوى إلى قبورهم، أو بالذبائح، أو بغير هذا يرجون بركتهم، أو شفاعتهم؛ هذا من الشرك الأكبر، نسأل الله العافية. فالواجب على المؤمن أن يحذر هذه الخرافات التي يفعلها كثير من الناس، فلا يجوز له أن يعتقد في المقبورين سواء سموا أولياء، أم لم يسموا أولياء، لا يجوز أن يعتقد فيهم أنهم يشفعون لمن ذبح لهم، أو دعاهم من دون الله، بل هم يشفعون لأولياء المؤمنين، المؤمن يوم القيامة يشفع للمؤمن، لا للمشرك، فالأنبياء يشفعون، والملائكة يشفعون، والمؤمنون يشفعون، والأفراط يشفعون، لكن لمن رضي الله قوله وعمله كما قال تعالى: وَلا يَشْفَعُونَ إِلَّا لِمَنِ ارْتَضَى [الأنبياء:28]. فالشفاعة إنما تكون لأهل التوحيد والإيمان، لا لأهل الشرك، فالذي يظن أن الأولياء أو الأنبياء يشفعون للمشركين الذين يعبدونهم مع الله، ويدعونهم مع الله؛ هذا غالط، واعتقاده باطل، فلا يجوز أن يدعوا مع الله، ولا أن يسألوا الشفاعة، ولا أن يستغاث بهم، ولا أن ينذر لهم، ولا أن يذبح لهم، كل هذا من الشرك بالله . وإذا أردت شفاعة الأنبياء والمؤمنين؛ فعليك بطاعة الله وتوحيده، واتباع شريعته، والاستقامة على دينه، فالأنبياء والأولياء والمؤمنون يشفعون لأهل التوحيد والإيمان، كما أن الملائكة تشفع والأفراط تشفع أيضًا، لكن لمن رضي الله قوله، وعمله لأهل التوحيد، لا لأهل الشرك بالله  ولكن الشياطين تلاعبوا بكثير من الناس، وتزين لهم أن هؤلاء الأولياء يتصرفون في الكون، وأنهم ينفعون ويضرون ويشفون مرضى الناس، إذا تقربوا إليهم بالذبائح، أو بالنذور، وهذا من الشرك الأكبر، وهذا من لعب الشيطان، وهذا من فعل الجاهلية، قال تعالى: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18] ويتقربون لقبورهم وللأصنام التي صورت على صورهم بالقرابين من السجود والذبح وغير ذلك، يزعمون أنهم بهذا يشفعون لهم عند الله، وهذا عين الكفر، وهكذا قوله سبحانه: وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:3] يعني: عبدوهم مع الله معتقدين أنهم يقربونهم إلى الله زلفى، بذبحهم لهم، وسجودهم لهم، ودعائهم إياهم، واستغاثتهم بهم، وهذا هو الشرك الأكبر. فيجب الحذر من هذه الخرافات والضلالات التي هي من أعمال الشياطين، ومن أعمال المشركين، فلا يدعى مع الله أحد لا ولي ولا غيره ولا نبي ولا غيره، ولا ملك ولا غيره، بل يدعى الله وحده، ويسأل ويطلب منه قضاء الحاجات، وتفريج الكروب  أما المؤمن الميت يدعى له بالمغفرة والرحمة، والحي يدعى له بالثبات على الحق، والأنبياء يصلى عليهم - عليهم الصلاة والسلام- ويدعى الله لهم أن يجزيهم عما قاموا به خيرًا، ولا يعبدون مع الله  العبادة حق الله، قال تعالى: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] قال تعالى: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] قال سبحانه: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونََ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ[فاطر:13-14] سماه: شركًا، فالواجب الحذر وقال تعالى: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] ومن زعم أن الولي يأتيه بحلوى، أو يأتيه بكسوة، أو يأتيه بذبيحة، أو يأتيه بلحم؛ فهو غلطان، هذا من عمل الشيطان، الشياطين هي التي تأتيهم بهذه الأمور حتى تشجعهم على الشرك، وعبادة غير الله  نسأل الله العافية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10494/حكم-اعتقاد-ان-الاولياء-ياتون-بالحلوى-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_452/45214.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":12488,"question":"تقول: ما حكم من ينتسب إلى مذهب يؤمن بأن القرآن مخلوق، وأن الناس لن يروا الله يوم القيامة، مع العلم أن من ينتسبون إلى هذا المذهب أغلبهم لا يقرون بخلق القرآن، ولا يؤمنون به، ويقولون: نحن لا نؤمن بأن القرآن مخلوق، لكننا ننتسب إلى هذا المذهب؛ لأن آباءنا كانوا ينتسبون إليه فقط، وما حكم من يؤمن بخلق القرآن، أيعتبر خارجًا عن ملة الإسلام، وجهونا في هذا، جزاكم الله خيرًا.","title":"حكم من يقول بخلق القرآن وينكر رؤية الله يوم القيامة","answer":"الجواب:  نعم، الذين يقولون: إن القرآن مخلوق معناه إنكار أنه كلام الله؛ فهذا كفر أكبر، وهكذا من قال: إن الله لا يرى، من أنكر رؤية الله في الآخرة، رؤيته في الجنة؛ هذا كفر أكبر؛ لأنه قد كذب الله، وكذب رسوله، عليه الصلاة والسلام. فكل طائفة، أو شخص يقول: إن القرآن مخلوق، فمعناه أنه ليس كلام الله، بل هو كلام المخلوق الذي تكلم به، والله صرح بأنه كلامه  في قوله -جل وعلا-: وَإِنْ أَحَدٌ مِنَ الْمُشْرِكِينَ اسْتَجَارَكَ فَأَجِرْهُ حَتَّى يَسْمَعَ كَلامَ اللَّهِ [التوبة:6] وقال سبحانه: يُرِيدُونَ أَنْ يُبَدِّلُوا كَلامَ اللَّهِ [الفتح:15] والرسول ﷺ كان يقول للناس: ألا رجل يؤويني حتى أبلغ كلام ربي يطوف عليهم في مكة قبل الهجرة، فيقول لهم، يطلب منهم أن يجيروه، وأن يؤوه؛ حتى يبلغ كلام الله. المقصود: أن الرسول ﷺ والصحابة كلهم صرحوا بأن القرآن كلام الله، والقرآن دل على أنه كلام الله، فمن زعم أن القرآن مخلوق؛ فقد زعم أنه ليس كلام الله؛ فيكون كافرًا بذلك، مكذبًا لله ولرسوله ولإجماع المسلمين. وهكذا من أنكر صفات الله، أو أنكر رؤيته، من قال: إنه ليس بحليم، ولا حكيم، ولا عزيز، ولا قدير، ولا ولا؛ فهو كافر كـالجهمية ، وكذلك من أنكر رؤية الله، وأن المؤمنين لا يرونه في الآخرة، ولا في الجنة؛ فهذا كافر كفرًا أكبر -أعوذ بالله نسأل الله العافية- لأنه قد كذب الله ورسوله، الله يقول -جل وعلا- في حق الكفرة: كَلَّا إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ [المطففين:15] فإذا حجب الله الكفار؛ معناه أن المؤمنين يرون ربهم  قال تعالى: وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ ۝ إِلَى رَبِّهَا نَاظِرَةٌ [القيامة:22-23] ناضرة: يعني: بهية جميلة إلى ربها ناظرة تنظر إليه  وقال -جل وعلا-: لِلَّذِينَ أَحْسَنُوا الْحُسْنَى وَزِيَادَةٌ [يونس:26] جاء في الحديث الصحيح عن رسول الله ﷺ أنه قال: الحسنى الجنة، والزيادة النظر إلى وجه الله وجاء في الأحاديث الصحيحة المتواترة عن النبي ﷺ أنه قال: إنكم ترون ربكم كما ترون القمر ليلة تمامه، ليلة البدر، لا تضامون في رؤيته وقال في اللفظ الآخر: كما ترون الشمس صحوة، ليس دونها سحاب، وكما ترون القمر ليلة البدر، لا تضامون في رؤيته يعني: رؤية واضحة ظاهرة بارزة ليس فيها شبهة ولا شك. فالمقصود: أن المؤمنين يوم القيامة يرون ربهم رؤية ظاهرة، كما ترى الشمس صحوة، ليس دونها سحاب، يعني: رؤية بارزة، وهكذا في الجنة يرون ربهم -جل وعلا- فمن أنكر هذا وقال: إنه لا يرى؛ فقد كذب الله ورسوله، فيكون كافرًا، نسأل الله العافية. المقدم: جزاكم الله خيرًا. الشيخ: نسأل الله العافية. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/10705/حكم-من-يقول-بخلق-القران-وينكر-روية-الله-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_406/40616.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":12576,"question":"أخونا أيضًا يسرد قضايا كثيرة حول مثل هؤلاء، ويسأل أيضًا عن حكم الصلاة خلفهم، هل تجوز، أو لا؟","title":"حكم الصلاة خلف من يدعي علم الغيب ويعبد الجن","answer":"الجواب:  مثل ما تقدم، إذا كان ممن يدعي علم الغيب، أو يعرف بعبادة الجن؛ هذا لا يصلى خلفه؛ لأنه كافر، ويجب على أهل الإيمان هجره، والتحذير منه، ورفع أمره إلى ولاة الأمور، إذا كان في بلاد يمكن أن يحكم عليه ويمنع، عليهم أن يجتهدوا في القضاء عليه من طريق ولاة الأمور، ويحذروا الناس منه، ولا يصلى خلفه. أما إذا كان دواؤه بالدواء المعتاد، بالعلاج المعتاد بين الناس، الذي ليس فيه عبادة للجن، وليس فيه دعوى علم الغيب، وإنما هي أمور معروفة، معتادة بين الناس، يستعملها في علاج المرضى؛ فينفع الله به، فهذا لا حرج عليه، وإذا كان أهلًا للإمامة؛ صلي خلفه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10788/حكم-الصلاة-خلف-من-يدعي-علم-الغيب-ويعبد-الجن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_412/41205.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":12609,"question":"هل نذكر السادة المستمعين بالأشياء التي تخرج الإنسان من الملة، تخرجه من كونه مسلمًا إلى كونه كافرًا؟","title":"نواقض الإسلام","answer":"الجواب:  نعم، الإسلام له نواقض، يجب على المسلم أن يحذرها، وقد ذكرها العلماء في باب حكم المرتد، قالوا: هو المسلم يكفر بعد إسلامه، وذكروا أشياء كثيرة تنقض الإسلام، مثل: دعوة الأموات، والاستغاثة بالأموات، مثل سب الدين، سب الرسول ﷺ وسب القرآن، الاستهزاء بالقرآن، الاستهزاء بالدين، ترك الصلاة، جحد وجوبها، جحد وجوب الزكاة، جحد وجوب صوم رمضان، جحد وجوب الحج مع الاستطاعة إذا جحد وجوب ذلك؛ كفر، كذلك إذا استحل الزنا؛ كفر، إذا استحل اللواط كفر، إذا قال: الخمر حلال؛ كفر، إذا قال: الربا حلال؛ كفر، وهكذا، أشياء ذكروها كثيرة سموها: نواقض الإسلام، يعني: الموجبة للردة -نسأل الله العافية- نعم.  المقدم: جزاكم الله خيرًا، ونفع بعلمكم، الواقع المسلم في حالة خطيرة، ولا سيما في هذا العصر ...؟  الشيخ: نعم، نعم هو عصر خطير، ولا سيما في كثير من الدول التي لا تحكم الشريعة، فإن دعاة الباطل فيها كثيرون، ونواقض الإسلام فيها منتشرة، ولا حول ولا قوة إلا بالله، نعم.","link":"https://binbaz.org.sa/fatwas/10816/نواقض-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41404.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":12624,"question":"هل نذكر السادة المستمعين بالأشياء التي تخرج الإنسان من الملة، تخرجه من كونه مسلمًا إلى كونه كافرًا؟","title":"نواقض الإسلام","answer":"الجواب:  نعم، الإسلام له نواقض، يجب على المسلم أن يحذرها، وقد ذكرها العلماء في باب حكم المرتد، قالوا: هو المسلم يكفر بعد إسلامه، وذكروا أشياء كثيرة تنقض الإسلام، مثل: دعوة الأموات، والاستغاثة بالأموات، مثل سب الدين، سب الرسول ﷺ وسب القرآن، الاستهزاء بالقرآن، الاستهزاء بالدين، ترك الصلاة، جحد وجوبها، جحد وجوب الزكاة، جحد وجوب صوم رمضان، جحد وجوب الحج مع الاستطاعة إذا جحد وجوب ذلك؛ كفر، كذلك إذا استحل الزنا؛ كفر، إذا استحل اللواط كفر، إذا قال: الخمر حلال؛ كفر، إذا قال: الربا حلال؛ كفر، وهكذا، أشياء ذكروها كثيرة سموها: نواقض الإسلام، يعني: الموجبة للردة -نسأل الله العافية- نعم.  المقدم: جزاكم الله خيرًا، ونفع بعلمكم، الواقع المسلم في حالة خطيرة، ولا سيما في هذا العصر ...؟  الشيخ: نعم، نعم هو عصر خطير، ولا سيما في كثير من الدول التي لا تحكم الشريعة، فإن دعاة الباطل فيها كثيرون، ونواقض الإسلام فيها منتشرة، ولا حول ولا قوة إلا بالله، نعم.","link":"https://binbaz.org.sa/fatwas/10816/نواقض-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41404.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":12680,"question":"يقول: في قريتنا مقبرة تقع على طريق الناس، فما هي نصيحتكم؟","title":"واجب المسلمين تجاه المقبرة الموجودة في طريق الناس","answer":"الجواب:  الواجب تسويرها حتى لا يطأها الناس، حتى لا يمتهنوها، تسور ويجعل لها باب للحاجة حتى لا يطأها الناس، وحتى لا يمتهنها الناس، وفي الإمكان الاتصال بالمحكمة حتى تقوم باللازم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10890/واجب-المسلمين-تجاه-المقبرة-الموجودة-في-طريق-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45819.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":12705,"question":"يقول في أيام العيد نضع على قبور الموتى جريدًا أخضر، هل لهذا أصل؟","title":"حكم وضع الجريد الأخضر على القبر","answer":"الجواب:  ليس له أصل، النبي ﷺ وضع الجريد على قبرين معذبين، وأطلعه الله على عذابها، قال: أما أحدهما فكان يمشي بالنميمة والعياذ بالله وأما الآخر فكان لا يستتر من بوله يعني: لا يتنزه من البول، ولم يضع على قبور الصحابة في البقيع، ولا في أحد، فدل ذلك على أن هذا خاص بالقبرين، فليس للإنسان أن يضع على القبور جريدًا، ولا زهورًا، ولا غير ذلك، لا في أيام عيد، ولا في غيرها، بل هذا منكر وبدعة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10915/حكم-وضع-الجريد-الاخضر-على-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_459/45910.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":13083,"question":"في سؤاله الثاني يقول: ما هي الأسباب التي تؤدي إلى نشر الخرافات، ونشوء الوثنيات بين الناس، وجهونا في هذا السؤال؟","title":"أسباب انتشار الخرافات والوثنيات بين الناس","answer":"الجواب:  الأسباب: قلة العلم، وكثرة الجهال، وقلة الناصحين لله ولعباده، والطمع في المال والشهرة، وما يقع من الحسد والبغضاء بين الناس، كلها أسباب للشر، فالإنسان إذا لم يكن عنده تقوى لله، ودين يحميه؛ فعل ما تهواه نفسه من ظلم وعدوان، ودعوة إلى الباطل، ونشر البدع والخرافات؛ لأنه ليس عنده تقوى تمنعه، وخوف من الله يحجزه، نسأل الله العافية، نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/11300/اسباب-انتشار-الخرافات-والوثنيات-بين-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50715.mp3","categories":["البدع والمحدثات","نواقض الإسلام"]},{"id":13101,"question":"السائل في آخر أسئلته يقول: سماحة الشيخ! من نواقض الإسلام مظاهرة المشركين، ومعاونتهم على المسلمين، نرجو أن توضحوا لنا ذلك، وهل كل الطوائف غير المسلمة تدخل في ذلك؟","title":"حكم مظاهرة المشركين على المسلمين","answer":"الجواب:  نعم، مظاهرة المشركين على المسلمين ردة عن الإسلام؛ لقوله -جل وعلا-: وَمَنْ يَتَوَلَّهُمْ مِنْكُمْ فَإِنَّهُ مِنْهُمْ [المائدة:51] كونه يظاهر الكفار من النصارى، أو اليهود، أو الشيوعيين، أو غيرهم ضد المسلمين، وينصرهم على المسلمين، هذا تول للكفار، وردة عن الإسلام -نعوذ بالله- كما نص على ذلك أهل العلم في باب حكم المرتد، نسأل الله العافية. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11318/حكم-مظاهرة-المشركين-على-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50811.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":13114,"question":"بعد ذلك ننتقل إلى رسالة بعث بها أحد الإخوة المستمعين يقول في هذا  ما هي ظواهر الشرك القولية والعملية الموجودة في أي مجتمع، نرجو منكم إفادة؟","title":"مظاهر الشرك القولية والعملية","answer":"الجواب: ظواهر الشرك تارة تكون بالكلام، وتارة تكون بالفعال، فإذا كان في محل تدعى فيه القبور من دون الله، ويجتمع الناس لدعوة الأموات، والاستغاثة بالأموات، هذه مظاهر الشرك. وإذا كان الناس يجهرون بدعاء الأموات، أو بدعاء الأنبياء، أو الأولياء، أو الأصنام، أو الجن هذه مظاهر الشرك، يستغيثون بهم، ينذرون لهم، ويذبحون لهم، هذه مظاهر الشرك، فالواجب الحذر من ذلك. المقصود: أن الشرك له مظاهر، تارة بدعاء الأموات، والاستغاثة بالأموات عند القبور .. تارة بعبادة أشجار، أو أحجار .. تارة بأصنام مصورة توضع في محلات معينة يدعونها من دون الله، تارة بدعاء الجن، والاستغاثة بالجن إلى غير ذلك، تارة بدعاء الأموات، وإن كان في بيته، أو كان في السيارة، أو كان في الطائرة، يقول: يا سيدي فلان، يا رسول الله! انصرني، أو يا سيدي البدوي انصرني، أو يا حسين، أو يا حسن انصرني، أو اشف مريضي، أو يا شيخ عبدالقادر الجيلاني، أو يا فلان، أو يا فلان .. كل هذا شرك أكبر، ولو في السيارة، ولو في الطريق، ولو في الطائرة، وإذا كان عند القبر كذلك -نسأل الله العافية- نعم.","link":"https://binbaz.org.sa/fatwas/11331/مظاهر-الشرك-القولية-والعملية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50820.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":13191,"question":"من المملكة الأردنية الهاشمية رسالة وصلت إلى البرنامج من المستمع (م. أ. م) يقول: هل تجوز الصلاة خلف إمام واقع في بعض الشركيات، وإن كان جاهلًا بحكم ما وقع فيه؟","title":"حكم الصلاة خلف من وقع في بعض الشركيات","answer":"الجواب:  لا تجوز الصلاة خلف من يتعاطى بعض الشركيات بعد التأكد من ذلك؛ لأن بعض الناس قد يظن أن هذا الشيء شرك، وليس بشرك، فإذا علم أن هذا الإمام يتعاطى بعض الأعمال الشركية؛ لم تجز الصلاة خلفه، فإذا علم أنه يدعو غير الله، كـالبدوي، أو الحسين، أو الحسن ابني علي بن أبي طالب  أو الشيخ عبدالقادر، أو غير ذلك من الناس، أو يدعو الرسول ﷺ أو غيره من الأنبياء، هذا لا يصلى خلفه، هذا كافر، لا يصلى خلفه. أما إذا كان حلف بغير الله؛ فهذا ليس بشرك أكبر، بل هو شرك أصغر، كالذي يقول: بالكعبة، أو بالنبي ﷺ أو بالأمانة، هذا الصلاة خلفه صحيحة؛ لأن هذا شرك أصغر، لا يخرجه من الإسلام، ولا ينبغي أن يبقى إمامًا، هذا ينبغي أن يزال من الإمامة، إلا أن يتوب، ويعرف الحكم الشرعي، فإذا تاب؛ تاب الله عليه، لكن ما دام مصرًا على الحلف بغير الله، أو على المعاصي الظاهرة؛ فإنه لا ينبغي أن يبقى إمامًا، وهو يتعاطى بعض المعاصي الظاهرة، أو بعض الشركيات من الشرك الأصغر، ينبغي أن يزال، ويستبدل بمن هو أصلح منه. أما إذا تعاطى ما هو شرك أكبر، كدعاء الأموات، والاستغاثة بالأموات، أو بالأصنام، أو بالأنبياء، أو بالجن، أو بالملائكة هذا شرك أكبر؛ لأن الله يقول سبحانه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: المشركين، الظلم إذا أطلق فهو الشرك، كما قال تعالى: وَالْكَافِرُونَ هُمُ الظَّالِمُونَ [البقرة:254]. وقال تعالى: إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ [لقمان:13] وقال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] فسماهم كفرة بدعائهم غير الله -جل وعلا- بدعاء الأموات من صالح، أو نبي، أو غيره، أو دعاء الملائكة، ولو أنهم أحياء مشغولون بشأنهم، لا يستطيعون أن يجيبوك، أو الجن كذلك، قال الله تعالى: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ [فاطر:13] القطمير: اللفافة التي على نواة التمر وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ [فاطر:13] إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلا يُنَبِّئُكَ مِثْلُ خَبِيرٍ  [فاطر:14]  فسمى دعاءهم شركًا، فعلم بذلك أن دعاء الأموات، أو الملائكة، أو الجن كله شرك أكبر يجب الحذر منه. وقال تعالى: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] أحدًا هذا عام، يعم الأنبياء والملائكة والجن والصالحين وغيرهم، نكرة في سياق النهي تعم كل أحد، والله يقول سبحانه: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] ويقول : وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ [الزمر:65]. فالشرك الذي عليه كفار قريش هو هذا، كانوا يعبدون الأصنام، ويدعون هبل واللات والعزى وغيرها من الأصنام والأموات، يستغيثون بهم، ينذرون لهم، فبعث الله النبي محمد ﷺ يدعوهم إلى توحيد الله، ويحذرهم من هذا الشرك، فلما أصروا، واستكبروا؛ هاجر من بينهم إلى المدينة المنورة، وأقام الله به دينه هناك، وصارت العاصمة الإسلامية هناك، ثم جرى بينه وبينهم من الحروب ما هو معروف، من حرب بدر وأحد والخندق، ونصره الله عليهم في بدر والخندق، وابتلي المسلمون في أحد بما يجعله الله طهورًا لهم، ثم فتح الله عليه مكة، ودخل الناس في دين الله أفواجًا. فالحاصل: أن هذا الشرك الذي يفعله الناس اليوم عند البدوي، أو عند الشيخ عبدالقادر الجيلاني، أو عند غيرهم، كل ذلك هو الشرك الذي فعلته الجاهلية، كله شرك قريش وأشباههم من دعاء الأموات، والاستغاثة بالأموات، والطواف بالقبور، وغير هذا من أنواع الشرك، نسأل الله السلامة والعافية. والواجب على العلماء أن ينصحوا الناس، على العلماء في كل بلد أن يتقوا الله، وأن يعلنوا النصيحة بالكتابة، وبالخطب في الجمع، وزيارة المقابر؛ حتى يدعوا من كان حول المقابر، يعلمونهم، ويرشدونهم إلى الزيارة الشرعية، الزيارة الشرعية أن تزور القبور للدعاء لهم، والترحم عليهم، هذه الزيارة الشرعية، يقول النبي ﷺ: زوروا القبور؛ فإنها تذكركم الآخرة وكان ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار، من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين. وكان إذا زار البقيع -عليه الصلاة والسلام- يقول: السلام عليكم دار قوم مؤمنين، وإنا -إن شاء الله- بكم لاحقون، غدًا مؤجلون، أتاكم ما توعدون، ثم يقول: اللهم اغفر لأهل بقيع الغرقد ما كان يدعوهم، ولا يستغيث بهم، ولا الصحابة -رضي الله عنهم وأرضاهم- ولا أهل العلم والإيمان. لا يجوز لأحد أن يطمئن إلى رأيه، وإلى هواه، بل يسأل ويتفقه في الدين، ويقرأ القرآن، ويقرأ السنة، وينظر في سيرة الصحابة، سيرة النبي ﷺ والصحابة، ينظر في السيرة سيرة النبي ﷺ مع أهل مكة، لما كان في مكة حين دعاهم إلى التوحيد، وينظر سيرته مع أهل المدينة، وينظر سيرة الصحابة، وما كانوا عليه، حتى يكون على بصيرة، هذا هو الدين، الدين ما كان عليه النبي ﷺ وأصحابه، هذا هو الدين، أما ما أحدثه الناس بعد ذلك مما يخالفه فليس هو الدين، نسأل الله للجميع الهداية والبصيرة والفقه في الدين، ولا حول ولا قوة إلا بالله، نعم.","link":"https://binbaz.org.sa/fatwas/11446/حكم-الصلاة-خلف-من-وقع-في-بعض-الشركيات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_475/47508.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":13218,"question":"هذا السائل يسأل ويقول: ما حكم الشرع في القبور التي تعلو سطح الأرض، كالقبور التي تتكون من دورين، وهذا يكون بسبب ضيق المساحة المخصصة للقبور سماحة الشيخ؟","title":"حكم رفع القبور","answer":"الجواب:  الواجب أن تكون القبور في داخل الأرض، يحفروا يحفر في قبر نصف قامة ويدفن، هذا إذا استطاع، إذا تيسر ذلك، إما إذا كانوا في أرض جبلية ما يستطيعون فإنه يكوم حصى من هنا ومن هنا، ويدفن بينها، يوضع على الشق الذي دفنوا فيه شيء من الحجارة؛ حتى يغطى، وهذا جهدهم فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. أما إذا أمكن الحفر؛ فإن السنة أن يحفر له في الأرض، وأن يدفن في الأرض، وألا يرفع عن الأرض إلا قدر شبر، وما حوله؛ حتى يعرف أنه قبر، وأما وضع أحجار، أو بناء على القبر من دون موجب؛ هذا لا يجوز. الرسول ﷺ نهى أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه، لكن إذا دعت الضرورة يجمع الحصى، ويكون مثل القبر، ويجعل الميت في وسطه، ويجعل فوقه الحجارة تغطيه، هذا إذا ما وجد مكانًا، كان في بلدهم -يعني- حجرية، ما يمكن الحفر، هذا فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] هذا جائز لهم؛ لأن الله -جل وعلا- يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. فإذا فرضنا ناسًا نزلوا في أرض حجرية ما فيها محل للدفن، ما فيها محل للحفر؛ فلهم أن يدفنوا بين الأحجار، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11495/حكم-رفع-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51217.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":13275,"question":"ما حكم من قال: بأن الذين يدعون الأولياء والصالحين هم مسلمون؟","title":"حكم من قال بأن الذين يدعون الأولياء مسلمون؟","answer":"الجواب: حكمه أنه يبين له أن هذا كفر وضلال، فإذا أصر؛ صار كافرًا مثلهم، يبين له كفرهم وضلالهم، والأدلة على ذلك، يقول الله -جل وعلا-: فًلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] ويقول سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] فسماهم كفرة، وقال سبحانه: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ  ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ[فاطر:14] سمى دعاءهم شركًا. يبين له أن دعوتهم، واستغاثتهم بالأموات هذا شرك المشركين، هذا شرك قريش مع اللات، ومع غيرها من الصالحين، ومع الملائكة، نسأل الله العافية والسلامة، نعم. المقدم: اللهم آمين، بارك الله فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11560/حكم-من-قال-بان-الذين-يدعون-الاولياء-مسلمون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_509/50912.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":13321,"question":"هذا السائل من اليمن يقول في هذا  أهل مسجدنا يخرجون جميعًا بعد كل صلاة عيد إلى زيارة القبور جماعة، ما الحكم في هذا مأجورين؟","title":"حكم زيارة القبور بعد صلاة العيد","answer":"الجواب: ليس لهذا أصل، الخروج للقبور صلاة العيد إنما هي عادة لبعض الناس، فإذا زاروا القبور يوم العيد، أو يوم الجمعة، أو في أي يوم ما في يوم مخصوص، تخصيص يوم العيد، أو تخصيص الجمعة، أو تخصيص يوم آخر لا، ليس له أصل، ولكن السنة أن يزوروا القبور دائمًا بين وقت وآخر على حسب التيسير، إذا كان وقتهم يسمح في يوم الجمعة، في يوم العيد، في أوقات أخرى؛ يفعلون، أما أن يظنوا أن لهذا اليوم خصوصية؛ فلا، لكن السنة أن يزوروا القبور عندما يتيسر ذلك؛ لقوله ﷺ: زوروا القبور؛ فإنها تذكركم الآخرة. وكان يزورها -عليه الصلاة والسلام- ويدعو لأهلها، فلا فرق بين يوم العيد، أو الجمعة، أو الخميس، أو غير ذلك، ليس لهذا وقت معروف فيما نعلم، ولكن المؤمن يتحرى الأوقات التي يحصل له فيها فرصة؛ لأن الإنسان قد تشغله المشاغل، فإذا تيسر له فرصة في الجمعة، أو في يوم العيد، أو في غير ذلك؛ فعل ذلك، زار القبور، وسلم عليها. وكان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين هذا تعليمه لأصحابه -عليه الصلاة والسلام- سواء كانت في الليل، أو في النهار، إذا زرتهم في الليل، أو في النهار، في أول النهار، في وسط النهار، في آخر النهار، في الليل، في أوله، في وسطه، في آخره حسب التيسير، نعم.  أما النساء لا، ليس لهن زيارة القبور، والرسول ﷺ لعن زائرات القبور، لكن يصلين على الميت في المساجد، في المصلى، لا بأس، يصلين مع الرجال على الموتى لا بأس، أما زيارة القبور فقد زجرهن عن ذلك -عليه الصلاة والسلام- ولعن زائرات القبور. والحكمة في ذلك -والله أعلم- لأنهن قليلات الصبر، ولأنهن فتنة، كما قال ﷺ: ما تركت بعدي فتنة أضر على الرجال من النساء. فالواجب عليهن طاعة الله ورسوله، وعدم الزيارة للقبور، لكن الدعاء مطلوب من الجميع، من الرجال والنساء، الدعاء لأموات المسلمين، الدعاء لأقاربهم، وأمواتهم: اللهم اغفر لهم، اللهم ارحمهم، اللهم أنجهم من النار، اللهم ارفع درجاتهم في الجنة.. إلى غير هذا من الدعوات الطيبة، اللهم كفر سيئاتهم، اللهم تقبل حسناتهم، اللهم لا تحرمنا أجرهم، ولا تفتنا بعدهم، الدعاء مطلوب في البيت.. في الطريق.. عند القبر.. كله طيب عند الزيارة. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11607/حكم-زيارة-القبور-بعد-صلاة-العيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_541/54103.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":13338,"question":"يسأل أخونا في قضية القبور التي فتن بها كثير من الناس، يقول: يوجد لدينا في القطر عادة ذلك أنهم يصلون إلى قبر، ويزورونه، ويتبركون به، ويقولون: إنه من قبور الصحابة، نرجو أن توجهوا الناس، جزاكم الله خيرًا.","title":"توجيه لمن يصلون إلى القبور ويتبركون بها","answer":"الجواب: القبور فتن بها كثير من الناس، فيما مضى وفي هذه الأمة، وكانت اليهود والنصارى فتنت بذلك، وعبدوا القبور، واتخذوها أوثانًا كما قال النبي ﷺ: لعن الله اليهود والنصارى؛ اتخذوا قبور أنبيائهم مساجد وقال -عليه الصلاة والسلام- لما أخبرته اثنتان من نسائه في الحبشة أنهما رأتا كنيسة في الحبشة، وما فيها من الصور قال: أولئك إذا مات فيهم الرجل الصالح؛ بنوا على قبره مسجدًا، وصوروا فيه تلك الصور، أولئك شرار الخلق عند الله فجعلهم بهذا العمل شرار الخلق؛ لأنهم يعظمونهم بالتصوير والبناء، ويسألونهم قضاء الحاجات، وتفريج الكروب، ويتبركون بتراب قبورهم، إلى غير هذا من أعمالهم القبيحة، ولهذا استحقوا اللعنة على ذلك. وقال -عليه الصلاة والسلام- في حديث جندب فيما رواه مسلم في الصحيح: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك وقال في حديث ابن مسعود: إن من شرار الناس من تدركهم الساعة وهم أحياء، والذين يتخذون القبور مساجد. فالواجب الحذر من هذه الخصلة الذميمة التي سار عليها اليهود والنصارى وهي تعظيم القبور بالبناء عليها، واتخاذ المساجد عليها، والقباب والتبرك بها، ودعاء أهلها، والاستغاثة بهم، والذبح لهم، والنذر لهم، وطلبهم المدد، وهذا بلاء عظيم، بعضه بدعة وبعضه شرك. فاتخاذ المساجد على القبور بدعة، اتخاذ القباب، وتجصيصها كل ذلك من البدع، ومن أسباب الشرك، ووسائله، ولهذا ثبت في صحيح مسلم عن جابر بن عبدالله الأنصاري -رضي الله تعالى عنهما-: أن النبي ﷺ نهى أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه لأن التجصيص والبناء عليه وسيلة للشرك والتعظيم، وهكذا اتخاذ القبة فوقه، والمسجد فوقه، كل هذا من أسباب الشرك، وهكذا القراءة عنده، والصلاة عنده من البدع. أما سؤال المدد، وطلبه الغوث هذا الشرك الأكبر، هذه عبادة لغير الله  فالواجب على الأمة الحذر من ذلك، والواجب على العلماء بيان ذلك للأمة، وتحذيرهم من هذا الشرك، وهذه البدع؛ لعلهم يسلمون منها، وهكذا كل من لديه علم يبثه في الناس، ويعلمه الناس يقول الله سبحانه: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33]. والرسول  يقول: بلغوا عني ولو آية ويقول ﷺ: نضر الله امرءًا سمع مقالتي فوعاها، ثم أداها كما سمعها، فرب حامل فقه غير فقيه، ورب حامل فقه إلى من هو أفقه منه وكان إذا خطب -عليه الصلاة والسلام- يقول للناس: ليبلغ الشاهد الغائب، فرب مبلغ أوعى من سامع. وهذه البلية انتشرت في العالم في البلاد الإسلامية وغيرها، وهي التعلق على القبور، والبناء عليها، والتمسح بها، وسؤالها الحاجات، وتفريج الكروب، والمدد، وهذا بلاء عظيم، وشر كبير، يجب الحذر منه.  والبدعة دائمًا تكون وسيلة للشرك، فأسباب هذا الشرك تعظيم القبور بالبناء عليها، واتخاذ المساجد عليها، والصلاة عندها، والقراءة عندها، فلما وجد هذه البدع؛ جرت الناس إلى الشرك، والغلو في القبور، وعبادتها من دون الله، بالدعاء، والاستغاثة، والذبح لها، والنذر لها، وطلبها المدد، وهذا هو الشرك الأكبر. فيجب الحذر من ذلك، والتوبة إلى الله من ذلك، ويجب هدم البناء الذي على القبور من مساجد وغيرها، وأن تكون القبور بارزة، ليس عليها بناء، كما كان هذا في عهد النبي ﷺ في البقيع، وهكذا في البلاد الإسلامية السليمة من هذه الفتنة، وعلى العلماء، وعلى الأمراء، أمراء المسلمين أن يعالجوا هذه الأوضاع، وأن يزيلوها من بينهم، وأن يحذروا الناس منها، وأن تكون القبور بارزة، ليس عليها بناء، لا قبة، ولا مسجد، ولا غير ذلك، رزق الله الجميع الهداية والبصيرة. المقدم: اللهم آمين، اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11624/توجيه-لمن-يصلون-الى-القبور-ويتبركون-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_476/47613.mp3","categories":["نواقض الإسلام","التبرك وأنواعه"]},{"id":13388,"question":"من السودان السائلان جعفر إبراهيم وإبراهيم عبدالقادر لهما هذا  لدينا أناس يعظمون القبور، ويرجون من أهلها النفع والضر، هل يكون هؤلاء كفارًا مع أنهم يصلون، ويقومون بباقي العبادات؟ وجهونا في ضوء هذا السؤال سماحة الشيخ.","title":"حكم تعظيم القبور ودعاء أصحابها","answer":"الجواب: التعلق بالقبور، ورجاء نفعها، ودفع الضرر منها بدعائها، أو التمسح بها، أو الاستغاثة بها ،أو الطواف بها كله كفر أكبر، هذا شرك المشركين، هذا ضلال الأولين. لا يجوز التعلق بالقبور، لا بقبور الصالحين، ولا بقبور الأنبياء، ولا غيرهم، فالذي يتعلق بها، يطوف بها، يرجو نفعها، أو يستغيث بأهلها، أو ينذر لهم، أو يتمسح بقبورهم، يرجو منهم النفع، أو يستعين بهم، أو يذبح لهم، أو يسجد لهم، كل هذا من الكفر بإجماع أهل السنة والجماعة، بإجماع أهل العلم، وهذا شرك المشركين الأولين. الله يقول -جل وعلا-: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] سماهم كفارًا، وقال -جل وعلا-: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا[الجن:18] وقال سبحانه: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ  ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:13-14]، سموه شركًا، دعاهم. قال النبي ﷺ: الدعاء هو العبادة فالذي يدعوهم قد عبدهم، فإذا قال: يا سيدي! انصرني، أو اشف مريضي، أو اشفع لي، أو أنا في جوارك، أو أنا في حسبك، أنا متوكل عليك، أنا أرجوك، أنا أخافك، هذا شرك أكبر، هذا ما يفعل إلا مع الله -جل وعلا- يخاطب الله، يا رب! انصرني .. اشف مريضي .. أنا أخاف..... مع الله سبحانه، أما مع المخلوق هذا الشرك الأكبر، أو مع النجوم، أو مع الجن، أو مع الأصنام، كل هذا كفر أكبر، هذا شرك المشركين. وهكذا ما يفعله عباد الحسين، أو عباد الشيخ عبدالقادر الجيلاني، أو غيرهما، أو عباد العيدروس، أو .... زينب، أو غير ذلك، كل هذا كفر أكبر إذا دعاه، دعا العيدروس، أو دعا الحسين، أو الحسن، أو استغاث بعلي  أو بالنبي ﷺ أو استعان به، أو قال: يا رسول الله! انصرني، أو اشفع لي، أو اشف مريضي، أو ثبتني على الدين، هذا كله كفر أكبر. الشفاعة تطلب منه يوم القيامة بعد البعث والنشور، وفي حياته قبل الموت يقال: اشفع لي يا رسول الله، لا بأس، أما بعد الموت لا، لا يطلب منه لا شفاعة، ولا غيرها، لكن حين كان حيًا يقول الصحابي: يا رسول الله! اشفع لنا، استغث لنا، لا بأس؛ لأنه قادر، ويوم القيامة كذلك بعدما يبعث الله الناس، وعند شدة الهول يذهب المؤمنون إلى آدم يقولون: اشفع لنا إلى ربك حتى يريحنا من كرب الموقف، يقضي بيننا، فيتعذر آدم ويحيلهم إلى نوح، ويتعذر نوح، ويحيلهم إلى إبراهيم، ويتعذر إبراهيم، ويحيلهم إلى موسى، فيتعذر موسى ويحليهم إلى عيسى، فيتعذر عيسى ويقول: اذهبوا إلى محمد، عبد غفر الله له ما تقدم من ذنبه وما تأخر، قال ﷺ: فيأتوني -يأتيه الناس- فأقول: أنا لها أنا لها ثم يذهب -عليه الصلاة والسلام- فيسجد بين يدي ربه، يسجد بين يدي الله تحت العرش، ويحمد الله بمحامد يفتحها عليه، يثني عليه كثيرًا حتى يقال له: يا محمد! ارفع رأسك، وقل يسمع، وسل تعط، واشفع تشفع  لا يشفع إلا بعد الإذن؛ لأن الله يقول: مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ [البقرة:255] فإذا أذن له شفع في الناس أن يقضى بينهم، ويشفع في أهل الجنة أن يدخلوا الجنة، ويشفع في أناس من العصاة دخلوا النار أن يخرجوا منها شفاعات كثيرة، عليه الصلاة والسلام. وهكذا يشفع المؤمنون في العصاة.. تشفع الملائكة.. يشفع الأفراط، هذا جاءت به النصوص عن النبي ﷺ. نعم.","link":"https://binbaz.org.sa/fatwas/11682/حكم-تعظيم-القبور-ودعاء-اصحابها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_515/51511.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":13393,"question":"على بركة الله نبدأ هذا اللقاء برسالة من السائلة (ح. ح) من بني مالك تقول: سماحة الشيخ! أريد أن أسأل سؤالًا يدور في ذهني، وهو: ما حكم من مات مشركًا بالله -أعاذنا الله من الشرك- ولكنه لم يعرف خطورة ذلك الأمر، وهو من جهل أهل القرى في ذلك الوقت، ولا يعرفون أن الشرك من أكبر الكبائر، ومات على ذلك الحال، سؤالي: هل يجب علينا أن ندعو لهم بالرحمة والمغفرة، وأداء الحج والعمرة؟ وهل ينفعهم ذلك العمل؟ أفتونا بالتفصيل سماحة الشيخ عبدالعزيز.","title":"حكم الدعاء لمن مات على الشرك جاهلًا","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فالشرك هو أعظم الذنوب... هو أكبر الكبائر، كما قال النبي الكريم -عليه الصلاة والسلام- في الحديث الصحيح: ألا أنبئكم بأكبر الكبائر؟ ألا أنبئكم بأكبر الكبائر؟ ألا أنبئكم بأكبر الكبائر؟ قلنا: بلى يا رسول الله، قال: الإشراك بالله ويدل على هذا قوله سبحانه: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]. فالشرك هو أعظم الذنوب، وأقبح السيئات، فمن مات عليه؛ لن يغفر له، وهو من أهل النار المخلدين فيها، ولا يحج عنه، ولا يصلى عنه، ولا يدعى له، ولا يصدق عنه؛ لقول الله -جل وعلا-: وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ [الزمر:65] وقوله سبحانه: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] وقال في المشركين: كَذَلِكَ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْ حَسَرَاتٍ عَلَيْهِمْ وَمَا هُمْ بِخَارِجِينَ مِنَ النَّارِ [البقرة:167]. والشرك: هو صرف العبادة لغير الله، أو شيء منها، كالذي يدعو الأموات، أو النجوم، أو الأنبياء، أو الملائكة يستغيث بهم، وينذر لهم، يذبح لهم، هذا الشرك. وهكذا من جحد شيئًا مما أوجبه الله مما هو معلوم من الدين بالضرورة، مما أجمع عليه المسلمون، كالذي يجحد وجوب الصلاة، أو يجحد وجوب الزكاة، أو يجحد وجوب صوم رمضان، أو يجحد وجوب الحج مع الاستطاعة، أو يستحل ما حرم الله من الأمور المعروفة من الدين بالضرورة، مما أجمع المسلمون على تحريمه كالزنا، والخمر، فيقول: الزنا حلال، أو الخمر حلال، أو يقول: عقوق الوالدين حلال، هذا كفر أكبر، لا يصلى عليه، ولا يستغفر له، ولا يحج عنه، ولا يتصدق عنه؛ لأنه مات على غير الإسلام. ما دام بين المسلمين قد سمع القرآن، ورأى المسلمين، ورأى أعمالهم، هذا غير معذور، قد قامت عليه الحجة؛ لأن الله يقول سبحانه: وَأُوحِيَ إِلَيَّ هَذَا الْقُرْآنُ لِأُنذِرَكُمْ بِهِ وَمَنْ بَلَغَ [الأنعام:19] من بلغه القرآن فقد قامت عليه الحجة، قال الله سبحانه: هَذَا بَلاغٌ لِلنَّاسِ [إبراهيم:52] ولأنه معرض، ما تعلم، ولا سأل، وأمره إلى الله، لكن هذا حكمه في الدنيا، مثل: عامة كفار قريش الذين قتلوا في يوم بدر، وفي غيره، أو ماتوا في مكة عامة الكفار اليوم، عامة الكفار النصارى، كفار اليهود، كلهم جهال، لكن لما رضوا بما هم عليه، ولم ينقادوا لما بعث الله به محمد ﷺ ولم يلتفتوا إليه؛ صاروا كفارًا، فنسأل الله العافية والسلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11685/حكم-الدعاء-لمن-مات-على-الشرك-جاهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_516/51601.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":13422,"question":"في فقرة له يقول: سماحة الشيخ! هل تصح الصلاة خلف من عرف بدعاء، أو بأنه يدعو غير الله، وما حكم من يصلي خلفه؟","title":"حكم الصلاة خلف من يدعو غير الله","answer":"الجواب: من صلى خلف من يشرك بالله؛ لا تصح صلاته مادام يدعو غير الله، يستغيث بغير الله، أو ينذر لغير الله؛ لا يصلى خلفه، عند أهل العلم لا يصلى خلف كافر، ولا تصح الصلاة خلف كافر، نعم، إنما الخلاف في الفاسق، أما الكافر لا. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11715/حكم-الصلاة-خلف-من-يدعو-غير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52702.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":13461,"question":"بعد ذلك ننتقل إلى رسالة جمهورية مصر العربية، والسائل (م. م. م) يقول: سماحة الشيخ! لدينا أشخاص يحافظون على الصلوات في أوقاتها، ويتصدقون ويصومون، ولكنهم يتبركون بأناس يدعون بأنهم أولياء، ويذبحون عند قبورهم، ما الحكم في هؤلاء؟ جزاكم الله خيرًا.","title":"حكم من يذبح للقبور ويتبرك بأصحابها","answer":"الجواب: الذي يتعاطى الشرك تبطل أعماله، ولو صلى وصام، فالذي يتصل بأهل القبور يدعوهم من دون الله، أو يذبح لهم، أو يتبرك بقبورهم، يتمسح بها، ويقبلها يرجو بركتها، هذا كفر أكبر -والعياذ بالله- وهكذا من يتمسح بأناس يظنهم يقول: إنهم صالحون .. يعتقد فيهم البركة، وأنه إذا تمسح بهم؛ جاءت البركة من عندهم، أو أنهم يشفعوا له عند الله، أو يقربونه إلى الله، مثل فعل الكفار، هذا لا يجوز، قال الله -جل وعلا- عن الكفرة: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18] قال سبحانه: وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:3] يعني: يقولون: ما نعبدهم إلا ليقربونا إلى الله زلفى: إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ [الزمر:3] سماهم الله كذبة كفرة، فالواجب الحذر من هذا، فلا يذبح عند القبور، ولا يتمسح بالقبور. أما إذا أراد بالذابح الذبح لله، ولكن يحسب أن الذبح عند القبور طيب، وأنه أراده لله، هذه بدعة تصير بدعة، ما يصير كفرًا، أما إذا ذبح يتقرب إلى أصحاب القبور، يريد أنهم يشفعون له، أو ينفعونه يوم القيامة بهذه الذبيحة، هذا هو شغل المشركين، والله يقول: فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:2] ويقول سبحانه: قُلْ إِنَّ صَلاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ [الأنعام:162-163] والنسك: الذبح، ويقول النبي ﷺ: لعن الله من ذبح لغير الله. فالخلاصة: أن الواجب إخلاص العبادة لله وحده في الدعاء، والخوف، والرجاء، والتوكل، والذبح، والنذر، وغير ذلك، يكون لله وحده، فلا يذبح لصاحب القبر، ولا للصنم، ولا للنجوم، ولا للجن، ولا يستغيث بهم، ولا ينذر لهم، ولا يستغيث بهم عند الملمات، بل يستغيث بالله وحده، وينذر لله وحده  هو المستحق؛ لأن يعبد الله -جل وعلا- وهكذا لا يتبرك بالقبور، ويتمسح بها، يرجو بركتها، ولا بالناس، بفلان وفلان يرجو بركته، كل هذا لا يجوز. وإذا ظن أن هذا الرجل بنفسه يحصل له البركة منه صار شركًا أكبر، أما إذا ظن أن هذا مناسب، وأنه مستحب يكون بدعة ما كان يفعل هذا إلا مع النبي ﷺ، هذا لا يجوز إلا مع النبي ﷺ خاصة؛ لأنه أقرهم على التبرك بوضوئه، وبشعره، وبعرقه -عليه الصلاة والسلام- لأن الله جعله مباركًا. أما غيره فلا؛ ولهذا لم يفعله الصحابة مع الصديق، ولا مع عمر، ولا مع عثمان، ولا مع علي، ولا مع غيرهم؛ لعلمهم أن هذا خاص بالرسول ﷺ دون غيره، التبرك بشعره، التبرك بعرقه، بوضوئه هذا خاص به ﷺ أما غيره بدعة لا يجوز، وإذا اعتقد أنه يحصل له البركة من هذا الشخص؛ صار كفرًا أكبر -نسأل الله العافية- نعم.  المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11764/حكم-من-يذبح-للقبور-ويتبرك-باصحابها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51709.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":13499,"question":"يقول هذا السائل من الجزائر: ما حكم تزيين القبور؟","title":"حكم تزيين القبور والبناء عليها","answer":"الجواب: التزيين يختلف، إن كان المقصود كونه يجمع التراب عليها، ويجعل عليها النصائب هذا لا بأس، ما يسمى تزيين هذا هو المشروع، إذا دفن الميت يرفع قبره قدر شبر، بقية التراب توزع على قبره حتى يعرف أنه قبر، ويجعل النصائب على أطرافيه من اللبن؛ حتى يعرف أنه قبر؛ حتى لا يوطأ، ولا يمتهن. أما تزيينه بالجص، أو بالطيب يكب عليه، أو بالبناء عليه هذا منكر لا يجوز \"الرسول ﷺ نهى عن تجصيص القبور، ونهى عن القعود عليها، ونهى عن البناء عليها\" رواه مسلم في الصحيح، ونهى أن يكتب عليها أيضًا، فلا يكتب عليها، ولا تجصص، ولا يبنى عليها، لا مسجدًا ولا غيره ولا قبة، كل هذا بدعة. والذي يفعل في بعض الدول من البناء على القبور، واتخاذ القباب عليها، والمساجد هذا من البدع، من وسائل الشرك، لا يجوز هذا، والواجب على المسلمين ترك ذلك، والواجب على أمراء المسلمين أن يمنعوا هذا، وأن يزيلوا هذه الأشياء، يجب على جميع الدول الإسلامية أن تمنع هذا، تمنع البناء على القبور، وتزيل المساجد التي على القبور، أو الأبنية التي عليها، والقباب يجب أن تزال، وإذا كانت مساجد قديمة، ولكن دفن فيها ميتًا ينبش، إذا كانت المساجد هي القديمة، ولكن دفن فيها؛ ينبش، ويخرج منها إلى المقابر، يوضع في حفرة في المقابر، ويسوى عليه التراب كسائر القبور، ولا يجوز أن يبقى في المساجد قبور. أما إن كانت قبورًا قديمة، ولكن بني عليها؛ فالواجب هدم البناء، قبة أو مسجدًا يهدم ويزال، ولا يجوز؛ لأن هذا من وسائل الشرك، يقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وقالت له بعض أزواجه: يا رسول الله! إنا رأينا كنيسة في أرض الحبشة وفيها صور، قال -عليه الصلاة والسلام-: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجدًا، وصوروا فيه تلك الصور، أولئك شرار الخلق عند الله أخبر أنهم شرار الخلق ببنائهم على القبور، واتخاذ المساجد عليها والصور، وقال ﷺ: لا تصلوا إلى القبور، ولا تجلسوا عليها وروى مسلم في صحيحه عن جابر  قال: نهى رسول الله أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه. فالواجب على علماء المسلمين في كل مكان، وعلى أمراء المسلمين في كل مكان إزالة هذا الشيء، ووعظ الناس، وتذكيرهم وتحذيرهم، وعلى ولاة الأمور أن يزيلوه بالقوة، يهدموا المسجد الذي على القبر، ويهدموا القبة التي على القبر، تكون القبور بارزة، ليس عليها قباب، ولا مساجد كما كانت في عهد النبي ﷺ في البقيع. وهكذا الآن في عهد الدولة السعودية، في البقيع، وفي غير البقيع مكشوفة، ليس عليها بناء، ولا مساجد، وهكذا كان الحال في عهد النبي ﷺ كانت القبور في البقيع، وفي غير البقيع، في مكة والمدينة وغيرها مكشوفة، وهكذا في عهد الصحابة -رضي الله عنهم وأرضاهم- حتى جاءت الرافضة، وغلت في القبور، وهكذا من شابههم من غير الرافضة. فالواجب الحذر، الواجب هدم المساجد التي على القبور، وهدم الأبنية والقباب التي على القبور، وأن تكون القبور مكشوفة، ليس عليها شيء، يزورها الناس للسلام عليهم، يزورها المسلمون للسلام فقط، يقول النبي ﷺ: زوروا القبور؛ فإنها تذكركم الآخرة وكان ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين هذه السنة. المسلمون يزورون القبور، ويسلمون عليهم فقط، لا يسألونهم، ولا يدعونهم، ولا يتمسحون بالقبور، كل هذا من المنكر، من الشرك، دعاء الميت، والاستغاثة بالميت هذا من الشرك الأكبر، تقول: يا فلان اشفع لي أو انصرني أو اشف مريضي، سواء كان هذا عند النبي ﷺ أو عند البدوي أو عند الحسين أو عند فلان كل هذا شرك أكبر، فلا يجوز هذا أبدًا عند جميع المسلمين، لا يجوز أن تأتي القبر تقول: انصرني، أو اشف مريضي، أو أنا في جوارك، أو أنا في حسبك، لا قبور الأنبياء ولا غيرها، ولا يجوز أن تدعوه تقول: يا سيدي فلان! أو يا أبا فلان، أو يا رسول الله! انصرني، أو اشف مريضي. هذا من الشرك الأكبر، سواء كان ذلك مع الأنبياء، أو مع أهل البيت، أو مع غيرهم، ولا يجوز التمسح بالقبور، والتبرك بها، وإنما تزار فقط، يزورهم، يسلم عليهم فقط، تقول: السلام عليكم أهل الديار، من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين، هكذا علم النبي أصحابه -عليه الصلاة والسلام- كان يعلمهم إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار، من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية هكذا روى مسلم في الصحيح، هكذا ذكر العلماء في بلوغ المرام، وفي منتقى الأخبار، وهكذا ذكر أهل العلم في كتب الحديث، وكتب الفقه بينوا هذا. فالواجب على علماء المسلمين نشر ذلك، وبيان ذلك للناس، يجب على العلماء أن يبينوا في المساجد، وفي خطب الجمعة، وفي غيرها، وفي المحاضرات، وفي المدارس، يعلموا الناس، يعلمونهم هذه الأمور حتى يكونوا على بصيرة، حتى يدعوا الغلو في القبور، حتى لا يبنوا عليها، حتى لا يتخذوا عليها المساجد، حتى لا يدعوها من دون الله .. لا يستغيثوا بها وبأهلها، المصيبة عظيمة الآن بهذه المسألة، في كثير من البلدان الإسلامية يبنى على القبور مساجد وقباب، ويدعى أهلها من دون الله، ويستغاث بهم، وينذر لهم، هذا هو الشرك، دعاؤهم من دون الله، والاستغاثة بهم، والنذر لهم هذا هو الشرك الأكبر، واتخاذ المساجد وسيلة لذلك، واتخاذ القباب وسيلة لذلك. فالواجب على الأمراء، أمراء المسلمين في كل مكان، يجب عليهم أن يزيلوا هذه القباب، وهذه المساجد التي على القبور، ويجب على العلماء أن ينبهوهم، وينصحوهم، ويذكروهم، إذا كانوا مسلمين؛ فعليهم أن يزيلوا ما حرم الله، إذا كان الوالي مسلمًا؛ فليتق الله، وليزل ما حرم الله من القباب والمساجد التي على القبور، وليمنع الناس من دعاء الموتى، والاستغاثة بهم، والنذر لهم، هذا لله وحده، هو الذي يدعى .. هو الذي ينذر له .. هو الذي يستغاث به، يقول: يا رب! اغفر لي، يا رب! انصرني، يا رب! اشف مريضي، يا رب! ارحم ضعفي، يا رب! ارزقني، يدعو ربه. أما الميت لا يدعى، لا الميت ولا الصنم ولا الكوكب ولا الجن، لا يدعون من دون الله، فالله هو الذي يدعى  فلا يجوز دعاء الأنبياء، ولا دعاء المؤمنين، ولا دعاء غيرهم، ولا دعاء الكواكب والنجوم، ولا دعاء الأصنام، ولا دعاء الجن، كل هذا لا يجوز، بل يجب إخلاص العبادة لله وحده يقول: يا رب! اغفر لي، يا رب! ارحمني، يا رب! انصرني، يا الله .. يا ذا الجلال والإكرام! اغفر لي وارحمني .. اشف مريضي .. ارزقني من فضلك. أما أن يأتي الميت يقول: ارزقني أو اشف مريضي! حتى ولو كان النبي محمد -عليه الصلاة والسلام- من جاء إلى قبره، أو بعيدًا عنه يقول: ارزقني يا محمد، أو انصرني، هذا الشرك الأكبر، أو يقول: يا سيدي! عبد القادر، أو يا سيدي الحسين، أو يا سيدي البدوي، أو يا سيدي فلان! انصرني، أو اشف مريضي، أو أنا في جوارك، أو أنا في حسبك، هذا هو الشرك الأكبر. يجب الحذر من هذه الأمور، ويجب على العلماء أن يبينوا للناس، وأن ينصحوهم، ويجب على الأمراء أمراء المسلمين أن يمنعوا هذا، وأن يزيلوا الأبنية التي على القبور، وأن تكون مكشوفة، ليس عليها مساجد، ولا قباب، هذا هو الواجب على المسلم؛ حماية لجناب التوحيد، وحرصًا على سلامة عقيدة المسلمين، ودعوة لهم إلى الحق، وأداءً لواجب الدعوة. نسأل الله أن يوفق ولاة أمر المسلمين لما يرضيه، ونسأل الله أن يعين العلماء على البلاغ والبيان، ونسأل الله أن ينصر بالجميع الحق، وأن يعيذ الجميع من مضلات الفتن، ولا حول ولا قوة إلا بالله! المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ، على هذا التوجية الطيب المبارك.","link":"https://binbaz.org.sa/fatwas/11810/حكم-تزيين-القبور-والبناء-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53102.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":13505,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية اليمنية حضرموت، وباعثها المستمع عبد الحافظ عبدالرحمن باعباد، أخونا باعباد له سؤال يقول فيه: يوجد عندنا قبور يقال: إنها قبور بعض الصالحين، ويقوم بعض الناس بزيارتها لكي تبعد عنهم الشر، وتجلب لهم الخير، وتشفي مرضهم بزعمهم، ويقولون: إن هذا الصالح له شأن في هذا الشيء، وعند نهاية زيارتهم يضعون بعض النقود على هذا القبر، ما حكم عملهم هذا؟","title":"حكم الاستغاثة بأهل القبور","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه. أما بعد.  فإن الله  شرع لعباده زيارة القبور للذكرى والاستغفار للميتين، والدعاء لهم، كما قال ﷺ: زوروا القبور فإنها تذكركم الآخرة ويقول لأصحابه -عليه الصلاة والسلام- كان يعلمهم إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار، من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين، ويقول -عليه الصلاة والسلام- إذا زار البقيع: اللهم اغفر لأهل بقيع الغرقد ويقول: السلام عليكم دار قوم مؤمنين، وإنا -إن شاء الله- بكم لاحقون ثم يقول: اللهم اغفر لأهل بقيع الغرقد هذه هي السنة أن يدعى لهم عند الزيارة، ويترحم عليهم؛ لأنهم في حاجة إلى الدعاء. أما زيارتهم لطلب الشفاء، للمرضى، أو لطلب المدد، والنصر على الأعداء، أو ما أشبه ذلك، فهذا من الشرك الأكبر، هذا كفر بالله، هذا لا يجوز، هذه حال عباد الأوثان يرجون الموتى والأصنام والأشجار والأحجار والكواكب، ويسألونهم قضاء الحاجات، تفريج الكروب، شفاء المرضى، ويسألونهم المدد لكل ما يعينهم، هذا كله من الشرك الأكبر، فالواجب الحذر من هذا العمل السيئ. قبور الصالحين تزار للدعاء لهم، والترحم عليهم، لا لدعائهم من دون الله، ولا فرق بين العيدروس، أو ابن علوان، أو غيرهما، جميع القبور حتى قبور الأنبياء حتى قبر النبي ﷺ وقبر الصديق وعمر وأهل البقيع كلهم لا يدعون مع الله، لا يستغاث بهم، لا ينذر لهم حتى النبي ﷺ يقول: (السلام عليك يا رسول الله! ورحمة الله وبركاته، جزاك الله عن أمتك أفضل الجزاء وأحسنه) ولا يدعى من دون الله، ولا يقال له المدد، ولا اشف مرضانا، ولا انصرنا، هذا شرك أكبر. وهكذا عند الصديق، وهكذا عند عمر، هكذا عند عثمان، هكذا عند علي، هكذا عند قبور أهل البيت جميعًا، لا يدعون مع الله، لا يقال: انصرونا، أو اشفوا مرضانا، أو أنتم تعلمون حاجاتنا هذا كله من الكفر الأكبر، والغيب لا يعلمه إلا الله  قال الله : قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ [النمل:65] فهو الذي يعلم الغيب -جل وعلا-. ولما سقط عقد لعائشة في بعض الأسفار؛ أناخ النبي الناس -عليه الصلاة والسلام- وطلب العقد، وأرسل من يطلبه ويلتمسه، ولم يعرف أين مكانه -عليه الصلاة والسلام- وهو سيد الخلق، وأفضلهم، لم يعرف أين العق، طلب أن يلتمسوه؛ فلم يجدوه، فلما أقاموا البعير الذي عليه عائشة؛ وجدوه تحته. فلو كان يعلم الغيب؛ لقال: انظروه تحت البعير، ولم يحتج إلى أن يرسل من يطلبه. ولما قذف المنافقون عائشة، وبعض الناس قلدهم وقذفها لم يعلم الحقيقة، وتوقف حتى جاءه الوحي بسلامتها وبراءتها، رضي الله عنها وأرضاها. فالغيب لا يعلمه إلا الله، لا يعلمه نبي، ولا ملك، ولا غيرهما إلا ما علم الله عباده، إلا ما أوحى الله به إلى أنبيائه، وعلمهم إياه. هكذا لا يدعون مع الله، ولا يستغاث بهم، وهم أنبياء قال الله تعالى: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] هذا (أحدًا) هذا عام، نكرة في سياق النهي يعم الأنبياء وغيرهم، قال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117]. فسمى دعاة غير الله كفره، يعني: دعاة الأموات والأنبياء، ودعاء الأشجار والأصنام، ونحو ذلك، وقال الله لنبيه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: المشركين. والمقصود: تحذيره ﷺ وتحذير الأمة فهو ﷺ لا يشرك، قد عصمه الله من هذا، لكن المقصود تحذير الأمة، وبيان أن هذا الأمر خطير، وأنه لا يجوز لأحد أن يفعله.  وهكذا قوله سبحانه: وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ [الزمر:65] أوحى الله إليه هذا الأمر؛ ليعلم الناس أن الشرك محرم، وأنه أعظم الذنوب، وأنه محرم على الأنبياء، وعلى غيرهم. وقال سبحانه: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلا يُنَبِّئُكَ مِثْلُ خَبِيرٍ [فاطر:13-14]  فجعل دعاء غير الله كائنًا من كان من الشرك، وقد أخبر أن المدعوين لا يسمعون دعاء الداعين، وأنهم لو سمعوا ما استجابوا. فالواجب الحذر من هذا الشرك الوخيم، وتحذير الناس من ذلك، والواجب على العلماء في كل مكان أن يبينوا للناس هذا الأمر العظيم، وأن يحذروهم من التعلق على القبور، والتعلق على الأموات، والاستغاثة بهم، والنذر لهم، وطلب منهم المدد، والعون، كل هذا من المحرمات الشنيعة، بل من الشرك الأكبر، وإذا كان هذا لا يجوز مع النبي ﷺ ولا مع الخلفاء الراشدين، فكيف يجوز مع العيدروس، أو مع ابن علوان، أو مع الشيخ عبدالقادر، أو مع علي، أو مع الحسن، أو فاطمة، أو غيرهم، لا يجوز أبدًا مع أحد، العبادة حق الله وحده قال سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] وقال: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60] وقال: يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ [البقرة:21] وقال سبحانه: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] فهو المعبود بالحق وهو المستعان -جل وعلا- فلا يدعى معه أحد، لا ملك، ولا نبي، ولا صنم، ولا شجر، ولا حجر، ولا ميت، العبادة حق الله وحده -سبحانه وتعالى- قال تعالى: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] وقال سبحانه: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ [الزمر:2] وقال -جل وعلا-: فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ [غافر:14]. أما الحي فلا بأس يقال له: يا عبدالله! أعني على كذا الحي الحاضر، تقول: أعني على إصلاح سيارتي، أقرضني كذا وكذا حي يسمعك ويقدر، تقول له: أعني على كذا، أعني على تعمير بيتي، على إمساك دابتي، على إصلاح سيارتي، هذا لا بأس، كما قال الله في قصة موسى : فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15] لأنه حي قادر، أما الأموات فلا يدعون مع الله، وهكذا الأصنام، هكذا الأشجار والأحجار، هكذا النجوم، كل ذلك من الشرك الأكبر، نسأل الله العافية. فنصيحتي لكل مسلم أن يحذر هذا، وعلى العلماء أن يحذروا الناس من هذا الشرك الوخيم، على العلماء في كل مكان أن يتقوا الله، وأن يعنوا بهذا الأمر، بالكتابة، وفي خطب الجمعة، وفي غير ذلك، وهكذا زيارة القبور حتى ينبه الناس القبر الذي يدعى من دون الله، يزار حتى ينبه أهله، يزوره العالم يقول: يا ناس هذا لا يجوز، سلموا وادعوا له بالمغفرة والرحمة، أما أن تدعوه من دون الله المدد المدد يا سيدي فلان اشفع لنا، انصرنا هذا .... هذا الشرك الأكبر، نعوذ بالله، فيجب الحذر. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11818/حكم-الاستغاثة-باهل-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_479/47901.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":13578,"question":"السائل (صبري . أ. أ) من جمهورية مصر العربية يقول: ما هو الكفر المخرج من الملة؟","title":"أنواع الكفر المخرج من الملة","answer":"الجواب: أنواع الكفر كثيرة المخرجة من الملة منها: دعاء الأموات، والاستغاثة بالأموات، ومنها: ترك الصلاة، كونه يترك الصلاة ولا يصلي، هذا من الكفر الأكبر، نسأل الله العافية، ومنها سب الدين .. سب الرسول ﷺ.. سب القرآن .. سب الله، هذه ردة عن الإسلام، ومنها: الاستهزاء بالدين، أو الاستهزاء بالله، وبالرسول ﷺ هذه ردة عن الإسلام، وهذا مبسوط في باب حكم المرتد، من أراد أن يعرف هذا يطالع باب حكم المرتد في جميع المذاهب الأربعة، بوبوا بابًا سموه: \"باب حكم المرتد\" ذكروا فيه أنواع المرتدين، وأسباب ردتهم، نسأل الله العافية. نعم.  المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/11943/انواع-الكفر-المخرج-من-الملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_533/53317.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":13586,"question":"السائل (صبري . أ. أ) من جمهورية مصر العربية يقول: ما هو الكفر المخرج من الملة؟","title":"أنواع الكفر المخرج من الملة","answer":"الجواب: أنواع الكفر كثيرة المخرجة من الملة منها: دعاء الأموات، والاستغاثة بالأموات، ومنها: ترك الصلاة، كونه يترك الصلاة ولا يصلي، هذا من الكفر الأكبر، نسأل الله العافية، ومنها سب الدين .. سب الرسول ﷺ.. سب القرآن .. سب الله، هذه ردة عن الإسلام، ومنها: الاستهزاء بالدين، أو الاستهزاء بالله، وبالرسول ﷺ هذه ردة عن الإسلام، وهذا مبسوط في باب حكم المرتد، من أراد أن يعرف هذا يطالع باب حكم المرتد في جميع المذاهب الأربعة، بوبوا بابًا سموه: \"باب حكم المرتد\" ذكروا فيه أنواع المرتدين، وأسباب ردتهم، نسأل الله العافية. نعم.  المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/11943/انواع-الكفر-المخرج-من-الملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_533/53317.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":13610,"question":"السائل أخوكم في الله أبو علي له مجموعة من الأسئلة يقول في هذا  عندنا الأرض ترابية، فنقوم بحفرها لتسوية القبور، ونبنيها بطوب محروق، ما رأيكم سماحة الشيخ عبدالعزيز؟","title":"الأرض ترابية، فنحفرها لتسوية القبر، ونبنيها بطوب محروق فما الحكم؟","answer":"الجواب: الواجب أن تحفروا فقط، أما البناء لا تبنوا شيئًا؛ لأن الرسول ﷺ نهى أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه ولكن تحفرون حفرًا إلى نصف القامة مثلًا، ثم تجعل فيها لحد، ثم يدفن الميت يجعل في اللحد، وينصب عليه اللبن، ثم يهال عليه التراب، ويرفع عن الأرض قدر شبر بالطين حتى يعرف أنه قبر، ويجعل عليه النصايب في أطرافه لحفظ ترابه.  أما أن يبنى عليه شيء، لا يبنى عليه شيء، إنما يجعل التراب فوقه إذا نصب عليه اللبن، ينصب عليه اللبن نصبًا، ويسدد ما بين اللبن بالطين، وقصار اللبن، ثم يهال عليه التراب، ويرفع قدر شبر، التراب -تراب القبر- حتى يعرف أنه قبر.  أما أنه يبنى عليه شيء من داخل، أو من خارج؛ فلا يجوز، الرسول نهى عن تجصيص القبور، ونهى عن القعود عليها، ونهى عن البناء عليها -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11950/الارض-ترابية-فنحفرها-لتسوية-القبر-ونبنيها-بطوب-محروق-فما-الحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52804.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":13869,"question":"هذا السائل حسين عوض من اليمن يقول في هذا  توفي والدي رحمه الله، فعند زيارتي لقبر والدي أشاهد بعض القبور عليها حجارة كبيرة وعليها اسم المتوفى، وليس على قبر والدي سوى التراب المركوم وحجارة صغيرة ليس عليها الاسم، فهل يجب علي أن أفعل مثل ما في هذه القبور من كتابة الاسم، ووضع التراب عليها؟","title":"حكم رفع القبور وكتابة اسم الميت عليها","answer":"الجواب: الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفالسنة في القبور أن لا ترفع قدر أكثر من الشبر، شبر فما يكون قربه، تمييزاً لها عن غيرها حتى يعرف أنها قبور، أما رفعها أكثر من ذلك فلا يجوز، وهكذا لا يجوز الكتابة عليها لا اسم صاحبها ولا غيره؛ لما ثبت عن النبي ﷺ: أنه نهى عن تجصيص القبور، وعن البناء عليها، وعن الكتابة عليها. فالبناء عليها لا يجوز، وهكذا تجصيصها؛ لأن هذا من وسائل الشرك؛ من وسائل الغلو فيها، وهكذا بناء المساجد عليها والقباب كله لا يجوز؛ لأنه من وسائل الشرك، وهكذا لا تجوز الكتابة؛ لأن الرسول نهى عنها عليه الصلاة والسلام، فلا يكتب عليها اسم الميت ولا غيره، وإذا وضع حجرًا للعلامة لا بأس، إنما توضع النصائب التي تحفظ التراب على أطراف القبر، أو يوضع عليه حصباء ويرش بالماء لحفظ التراب لا بأس، أما الحصى الكبار فلا حاجة إليه، إنما توضع حصاة للعلامة لا بأس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12253/حكم-رفع-القبور-وكتابة-اسم-الميت-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53801.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":14153,"question":"سماحة الشيخ! هذا السائل من أديس أبابا- أرتيريا يقول في هذا  التعلق بقبور الصالحين وتعظيمها وزيارتها ما حكمه في الشرع؟ جزاكم الله خيرًا.","title":"حكم التعلق بالقبور وتعظيمها وزيارتها","answer":"الجواب: هذا فيه تفصيل: أما الزيارة مشروعة زيارة القبور، للدعاء لأهلها والترحم عليهم والاستغفار لهم، النبي  قال: زوروا القبور فإنها تذكركم الآخرة فزيارة قبور الصالحين والأخيار والأقارب والدعاء لهم والاستغفار لهم هذا قربة وطاعة.\nأما التعلق بالقبور ودعاء أهلها والاستغاثة بها هذا شركًا أكبر، كونه يدعوهم: يا سيدي أغثني انصرني، أنا في جوارك، أنا في حسبك، اقض ديني أو أصلح ذريتي، أو اشف مريضي كل هذا من الشرك الأكبر هذا من دعاء غير الله، فإذا فعل هذا مع قبور الصالحين أو مع الجن أو مع الغائبين أو مع الملائكة كان شركًا أكبر نسأل الله العافية؛ لقوله جل وعلا: لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ [الزمر:65]، وقوله جل وعلا: إِنَّهُ مَنْ يُشْرِكْ بِاللَّهِ فَقَدْ حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ وَمَأْوَاهُ النَّارُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ [المائدة:72]، وقوله سبحانه: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ [فاطر:13]، إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14]، فسمى دعاءهم شركًا، وقال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117]. هذا محل إجماع بين أهل السنة والجماعة ليس فيه نزاع، الذي يدعو الأموات أو يستغيث بالأموات أو بالجن أو بالملائكة أو بالأنبياء أو ما أشبه ذلك هذا كله شرك أكبر؛ لأن الأنبياء كلهم قد ماتوا ولم يبق منهم إلا عيسى مرفوع غائب في السماء. والملائكة غائبون فلا يجوز دعاؤهم ولا الاستغاثة بهم، وهكذا الغائبون من الناس لا يدعون ولا يستغاث بهم إلا من طريق حسي كالمكاتبة، أو التلفون، يكلمه بالتلفون وهو في بلد أخرى، تقول: أقرضني كذا أو أرسل لي كذا لا بأس، مثل الحاضر إذا كلمه بالتلفون أو بالمكاتبة لا بأس كالحاضر، أما يعتقد أن هذا الغائب له سر وأنه يعلم الغيب فيخاطبه من بعيد يقول: اقض حاجتي انصرني يعتقد فيه أنه يعلم الغيب ويسمع دعاءه أو يدعو الملائكة، أو يدعو الأموات ويستغيث بالأموات، كل هذا شرك أكبر. نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/12594/حكم-التعلق-بالقبور-وتعظيمها-وزيارتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54618.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":14218,"question":"في ثاني أسئلة هذا السائل يقول: ما حكم وضع جرائد النخيل أو الأراك على القبر في وقتنا الحاضر؛ لأن البعض -يا سماحة الشيخ- يحتج بأن وضع الجريد على القبر -أي: جريد النخل- على القبر هو خاص بالرسول ﷺ؛ لأنه علم بالعذاب الذي كان يعذب به صاحبا القبر؟ وجهونا في ضوء ذلك.","title":"حكم وضع جرائد النخيل على القبور","answer":"الجواب: هذا هو الصواب، ليس لأحد أن يضع الجريد ولا غيره على القبور؛ لأن الرسول ﷺ ما كان يضع على القبور شيئًا، قبور البقيع وغيرها ما كان يضع عليها شيئًا، إنما وضع الجريدة على قبرين أطلعه الله على عذابهما فوضع الجريدتين قال: لعله يخفف عنهما ما لم ييبسا ولم يضع الجريد على القبور الأخرى، فدل ذلك على أنه لا يشرع وضع الجريد ولا غير الجريد على القبور الأخرى؛ لأننا لا نعلم عذابهم، والله أطلع نبيه على عذاب القبرين فوضع الجريد لعله يخفف عنهما ما لم ييبسا، فليس لنا أن نشرع شيئًا جديدًا. نعم.","link":"https://binbaz.org.sa/fatwas/12669/حكم-وضع-جراىد-النخيل-على-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54819.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":14241,"question":"في آخر أسئلته يقول هذا السائل من اليمن: هل يجوز الذبح وقراءة القرآن على الموتى؟","title":"حكم الذبح وقراءة القرآن على الموتى","answer":"الجواب: هذا فيه تفصيل: الذبح إن كان قصده الضحية عن الميت يضحي عنه فالضحية مشروعة للحي والميت، كونه يضحي عنه أو يذبح ذبيحة يتصدق بها يعطيها الفقراء عنه لا بأس. أما الذبح له يتقرب إليه وهو للميت هذا شرك، ... يذبح له يتقرب إليه كما يذبح عباد الأصنام لأصنامهم هذا شرك أكبر، أما أن يذبح يتقرب إلى الله أضحية عن الميت أو صدقة يعطيها الفقراء عن الميت، أو يتصدق بدراهم أو بطعام عن الميت فهذا لا بأس به، بل فيه نفع للميت، يقول ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له. قال رجل: يا رسول الله! إن أمي ماتت ولم توص أفلها أجر إن تصدقت عنها؟ قال النبي ﷺ: نعم، فهذا فيه خير عظيم.\nأما القراءة عند القبور فبدعة لا يشرع القراءة عند القبور، ولا الصلاة عند القبور، بل هذا من البدع، بل هو من وسائل الشرك، ولهذا يقول ﷺ: اجعلوا من صلاتكم في بيوتكم ولا تتخذوها قبورًا دل على أن القبور ما يصلى فيها ولا يقرأ عندها، اجعلوا من صلاتكم في بيوتكم ولا تتخذوها قبورًا، فإن الشيطان يفر من البيت الذي تقرأ فيه سورة البقرة، هذا يدل على أن البيوت هي محل الصلاة والقراءة، أما القبور لا ليست محل الصلاة والقراءة، فالبيت تصلى فيه النافلة، يصلي فيه المريض إذا عجز عن المسجد، يقرأ في البيت كل هذا طيب، أما القبور فإنما تزار للدعاء لهم والترحم عليهم والإحسان إليهم بالدعاء، أما أن يتخذها للصلاة عندها أو للذبح عندها أو للقراءة عندها فهذا بدعة. نعم.","link":"https://binbaz.org.sa/fatwas/12697/حكم-الذبح-وقراءة-القران-على-الموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53013.mp3","categories":["إهداء القرب للميت","نواقض الإسلام"]},{"id":14369,"question":"يقول السائل: ما الفرق بين الشرك والكفر؟","title":"الفرق بين الشرك والكفر","answer":"الجواب: كل شرك يسمى كفرًا، كل شرك؛ دعوة غير الله، والاستغاثة بغير الله، وصرف العبادة لغير الله، تسمى شركًا، ويسمى كفرًا، وقد يسمى الكفر شركًا أيضًا، كمن جحد وجوب الصلاة، أو قال: الزنا حلال، يسمى كافرًا، ويسمى مشركًا، ولكن الغالب على ما كان جحدًا لواجب، أو جحدًا لمحرم يسمى: كفرًا، والغالب على من كانت الدعوة لغير الله، الاستغاثة بغير الله، نذر لغير الله يسمى شركًا، وإلا فكل شرك يسمى كفرًا، وكل كفر أكبر يسمى شركًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12850/الفرق-بين-الشرك-والكفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_551/55111.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":14466,"question":"من أسئلة هذه السائلة من اليمن تقول: سماحة الشيخ جرت عندنا سيول عظيمة، مما أدى إلى جرف الأراضي، وأضرت ببعض عظام الموتى، وقامت بعض من النساء بجمع العظام ودفنها في الأرض، فهل على هؤلاء النسوة شيء؟","title":"حكم دفن النساء لعظام الموتى التي جرفها السيل","answer":"الجواب: إذا جرفت السيول المقبرة فعلى ولي الأمر والجهات المختصة أن ينظروا في ذلك، وأن يعيدوا العظام إلى مدافنها، ويسووها ويسوروا المقبرة حتى لا تصاب مرة أخرى، على ولي الأمر أو على المحسنين الذين يطلبون الأجر يعيدون العظام في محلها، كل عظام قبر في محلها، وإذا لم يعرفوا ذلك دفنوها في أي محل من المقبرة، وسووه بظاهر القبور على حالها حتى تعرف أنها قبور وتسور المقبرة بشبك أو ببناء حتى لا تمتهن، وحتى لا تدخلها السيول، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12945/حكم-دفن-النساء-لعظام-الموتى-التي-جرفها-السيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55418.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":14468,"question":"تقول في ثاني أسئلتها هذه السائلة من اليمن: البعض من الناس يزعمون بأنهم يشاهدون الموتى، وما آلوا إليه، وما آلوا إلى مصيرهم، ويقومون بإخبار أهل الميت أين مصير أبناءهم أو ميتهم؟ ويخبرونهم بأن الميت يقول لهم: إن يفعلوا أشياء يذكرونهم بها، فهل هذا العمل صحيح؟ وما نصيحتكم يا سماحة الشيخ؟","title":"ما حكم من يدعي معرفة أحوال الموتى ومصيرهم؟","answer":"الجواب: هذا باطل، وهؤلاء كذابون ودجالون، ومن ادعى هذا فهو كافر، من يدعي أنه يعلم الغيب هذا ما يجوز، هذا باطل، ولا يصدقون ،والعياذ بالله، فلا يعلم حال الموتى، وما منازلهم عند الله إلا الله ، لكن المؤمن يرجى له الخير، والكافر إلى النار، نسأل الله العافية، والمؤمن مشهود له بالخير، ومصيره إلى الجنة، لكن أخبارهم في البرزخ، ويقول: إنه جرى عليهم كذا، وأنهم جرى عليهم كذا، وأن منازلهم في الجنة كذا، هذا لا يقوله عاقل، هذا كذاب، ولكن المؤمنين موعودون بالجنة، ومنازلهم في الجنة، وأرواحهم في الجنة في شكل طير، أرواحهم تكون طيور في الجنة، كما جاء في الحديث، والشهداء تكون في أجواف طير خضر، تسرح في الجنة حيث شاءت، ثم تأوي إلى قناديل معلقة تحت العرش، فمن يقول: إنه يعلم أحوال الموتى وما شؤونهم ومنازلهم بأنه يشاهد ذلك فهذا كذاب دجال، يجب أن يستتاب فإن تاب وإلا قتل، نسأل الله العافية. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12950/ما-حكم-من-يدعي-معرفة-احوال-الموتى-ومصيرهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55419.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":14474,"question":"ما حكم دراستنا على الشيخ الذي يستغيث بغير الله، ويتوسل بالصالحين، وإذا قام من مكانه قال: يا فلان؟","title":"حكم الدراسة على من يستغيث بغير الله ويتوسل بالصالحين","answer":"الجواب: مثل هذا لا يقرأ عليه، ولا ينقل عنه العلم لشركه، ولا يؤمن أن يشبه على الطلبة فيوافقوه على ما هو عليه من الباطل، بل الواجب أن ينصح ويبيّن له أغلاطه من أهل العلم، حتى ولو من الطلبة بالأسلوب الحسن، بالكلام الطيب، فالمؤمن لا يحقر نفسه عن بيان العلم، كان النبي ﷺ ذات يوم بين أصحابه فقال: حدثوني عن شجرة لا يسقط ورقها هي مثل المؤمن قال ابن عمر: فوقع الناس في شجر البوادي، ووقع في نفسي أنها النخلة فاستحييت؛ لأنه كان أصغر القوم، فقال النبي ﷺ: إنها النخلة قال عبدالله: فقلت لأبي عمر: إنه وقع في نفسي أنها النخلة فاستحييت، فقال عمر: «لأن تكون قلتها أحب إلي من كذا وكذا» فأرشده عمر  إلى أنه يقول العلم، يتبين يتكلم يتقدم بالعلم ولو كان صغيرًا. وكان عمر  يدني ابن عباس مع الكبار في المشورة؛ لما أظهر له من علمه، كان يدنيه معهم ويستشيره معهم لما أعطاه الله من العلم والفقه في الدين.\nفالطالب إذا عرف من أستاذه غلطًا فلا مانع، بل يجب أن ينبهه بالأسلوب الحسن، بالسؤال: ما حكم كذا؟ ما الدليل على كذا أيها الأستاذ؟ يا أبا فلان، يا شيخنا، يأتي بالعبارات المناسبة، أو يطلب من العلماء الآخرين أن يرشدوا هذا العالم لعله يقبل منهم، أو يجتمع هو والطلبة ويكونون جميعًا، ويأتون الشيخ في بيته ليس عند الناس، فيقولون له: إنا سمعنا منك كذا وكذا، وقد ظهر لنا أن هذا الشيء حكمه كذا وكذا، من الدليل الفلاني،.... الدليل الفلاني، فأحببنا أن نبحث معك الموضوع، من باب النصيحة، ومن باب التعاون على البر والتقوى، لعله يقبل منهم، ولعله يستفيد، ولا يضرهم ذلك لو تكلم عليهم أو احتقرهم أو زعل عليهم، لا يضرهم ذلك، هم عليهم أن يحاولوا النصيحة، وبذل المستطاع في إرشاده وتنبيهه، والله ولي التوفيق ، لَيْسَ عَلَيْكَ هُدَاهُمْ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [البقرة:272]، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12985/حكم-الدراسة-على-من-يستغيث-بغير-الله-ويتوسل-بالصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_625/62511.mp3","categories":["نواقض الإسلام","التوسل والشفاعة"]},{"id":14484,"question":"السؤال الآخر: ما حكم الصلاة وراء رجل يستغيث بغير الله، ويتوسل بالصالحين؟","title":"حكم الصلاة خلف من يتوسل بالصالحين ويستغيث بغير الله","answer":"الجواب: الصلاة خلف المشرك لا تجوز، ولا يجوز أن يقتدى به؛ لأن من استغاث بغير الله يعتبر مشركًا، فلا يصلى خلفه سواءً استغاث بالنبي ﷺ، أو بـالبدوي أو بـالحسين ، أو بالشيخ عبدالقادر، أو بغيرهم من الناس، فالذي يستغيث بالأموات، ويسألهم الحاجات والمدد يعتبر مشركًا، عليه أن يتوب إلى الله، وأن يبادر بذلك، ومن تاب صادقًا تاب الله عليه؛ لكن لا يتخذ إمامًا ولا مؤذنًا، بل يجب أن يكون المؤذن من أهل التوحيد، وهكذا الإمام، وإذا وجد في المسجد إمام مشرك يجب أن يزال، يجب على ولاة الأمور أن يزيلوه، وأن يعينوا مكانه عالمًا موحدًا بعيدًا عن الشرك؛ لأن ذلك هو الواجب على أئمة الإسلام، وعلى حكام المسلمين ألا يقدموا في المساجد من هو مشرك بالله، فإن إمامته باطلة، وهكذا المؤذنون يجب أن يكونوا مسلمين؛ لأنهم يخبروا الناس بالأوقات، ويعتمد عليهم، فلا بد أن يكون المؤذن أمينًا مسلمًا موحدًا، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12982/حكم-الصلاة-خلف-من-يتوسل-بالصالحين-ويستغيث-بغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_625/62509.mp3","categories":["نواقض الإسلام","التوسل والشفاعة","نصائح وتوجيهات"]},{"id":14622,"question":"إيهاب عبدالحميد مصري، ومقيم بالمملكة، له مجموعة من الأسئلة، يقول سماحة الشيخ في السؤال الأول: تجصيص القبر هل يجوز بناء القبر بالطوب الأحمر أو الإسمنت إذا كانت الأرض رخوة أو بها بلل، عندنا في بلادنا يكثر مثل هذا؟ أفتونا، مأجورين.","title":"حكم بناء القبور إذا كانت الأرض رخوة","answer":"الجواب: تجصيص القبور لا يجوز، والبناء عليها لا يجوز؛ لأن الرسول ﷺ نهى عن ذلك، نهى عن تجصيصها، والبناء عليها، ولا يجوز اتخاذ مساجد عليها؛ لأنه وسيلة الشرك، لكن إذا كانت الأرض رديئة غير متماسكة لا بأس أن تضبط بشيء مما يمسكها من ألواح أو خشب أو حجر شيء يضبط الأرض حتى يوضع فيها الميت، نعم.","link":"https://binbaz.org.sa/fatwas/13114/حكم-بناء-القبور-اذا-كانت-الارض-رخوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55910.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":14677,"question":"المستمع موسى كريم الأسود، من جمهورية مصر العربية، بعث يسأل ويقول: ما كفارة سب الدين؟أعاذنا الله وإياكم من ذلك.","title":"ما حكم من سب الدين؟","answer":"الجواب: سب الدين الواجب فيه القتل؛ هي ردة عظيمة، ردة غليظة، فمن سب الدين وثبت عليه ذلك وجب أن يقتل نصرة لدين الله، وحماية له من سب السابين، وإلحاد الملحدين.  فإن ثبت لدى الحاكم الشرعي وجب عليه الحكم بقتله غيرة لله، وحمأة لدينه، ولا تقبل توبته في الحكم الشرعي، أما فيما بينه وبين الله فإن كان صادقًا توبته تقبل عند الله  إذا تاب توبة صادقة.  وأما في الحكم الشرعي فلا تقبل، بل يجب قتله إذا ثبت لدى القاضي بالبينة الشرعية أنه سب الدين سبًا واضحًا، أو سب الرسول ﷺ فإنه يقتل قتل ردة من بدل دينه فاقتلوه هكذا قال النبي ﷺ: من بدل دينه فاقتلوه ولا سيما بالسب لله ولرسوله. أما لو تاب فيما بينه وبين الله، وندم فيما بينه وبين الله، فهذا إلى الله ، لكن لو تاب قبل القدرة عليه، لو تاب ورجع إلى الله قبل أن نقدر عليه لا يجوز قتله حينئذٍ، إذا جاءنا تائبًا نادمًا مستغفرًا يقول: بعد جرى مني كذا وكذا، فإنه لا يقتل، أما توبته بعد إمساكه وبعد إقامة الحجة عليه، والبينة عليه قد تبت فإنها لا تقبل، بل يجب قتله إذا ثبت لدى الحاكم الشرعي أنه سب الدين، أو سب الرسول ﷺ، فإنه يقتل ويحكم بردته، ولا تقبل منه التوبة بعد القدرة عليه، كما قال الله  في حق المحاربين: إِلَّا الَّذِينَ تَابُوا مِنْ قَبْلِ أَنْ تَقْدِرُوا عَلَيْهِمْ فَاعْلَمُوا أَنَّ اللَّهَ غَفُورٌ رَحِيمٌ [المائدة:34] أول الآية يقول سبحانه: إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللَّهَ وَرَسُولَهُ وَيَسْعَوْنَ فِي الأَرْضِ فَسَادًا أَنْ يُقَتَّلُوا أَوْ يُصَلَّبُوا أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُمْ مِنْ خِلافٍ أَوْ يُنفَوْا مِنَ الأَرْضِ ذَلِكَ لَهُمْ خِزْيٌ فِي الدُّنيَا وَلَهُمْ فِي الآخِرَةِ عَذَابٌ عَظِيمٌ ۝ إِلَّا الَّذِينَ تَابُوا مِنْ قَبْلِ أَنْ تَقْدِرُوا عَلَيْهِمْ فَاعْلَمُوا أَنَّ اللَّهَ غَفُورٌ رَحِيمٌ [المائدة:34]. والذي يسب الدين أو يسب الرسول ﷺ من أعظم الناس محاربة لله ولرسوله، ومن أعظم الناس فسادًا في الأرض فلا تقبل توبته بعد القدرة عليه، بل يجب تنفيذ حكم الله فيه وهو القتل، حتى لا يتجرأ الناس على سب الدين أو سب الرسول ﷺ. وقد صنف أبو العباس شيخ الإسلام ابن تيمية -رحمه الله- كتابًا جليلًا في هذا المعنى سماه: الصارم المسلول على شاتم الرسول -عليه الصلاة والسلام-، وذكر الأدلة في ذلك، وكلام أهل العلم، وذكر حكم ساب الله ورسوله، فينبغي أن يراجع، فإنه مفيد جداً، نعم. المقدم: جزاكم الله خيرًا.\nإذًا: نخلص إلى...\nالشيخ: نخلص إلى أن من سب الله ورسوله، ثم قدر عليه، وقامت الحجة عليه، فإن الحاكم الشرعي يحكم بردته وقتله، أما لو تاب قبل ذلك قبل أن نعلم، وجاء إلينا تائبًا نادمًا يخبر عن توبته فإن الصحيح أنه تقبل توبته، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13170/ما-حكم-من-سب-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_628/nour_62803.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":14731,"question":"الأخت صالحة محمد رزق الله، من ليبيا، بعثت برسالة ضمنتها جمعًا من الأسئلة، تسأل عن حكم الذي يسب الدين والعياذ بالله؟وترجو توجيه النصيحة، جزاكم الله خيرًا شيخ عبدالعزيز.","title":"ما حكم من يسب الدين؟","answer":"الجواب: حكم الذي يسب الدين عند أهل العلم أنه كافر، فالذي يسب الإسلام، أو يسب الله، أو يسب الرسول محمد ﷺ أو يتنقصه ويعيبه ويطعن فيه، أو يسب الجنة، أو يقول: إنها غير حقيقة، أو ينكر النار ويقول: إنها غير حقيقة، كل هؤلاء كفار عند أهل العلم بإجماع المسلمين.  فالذي يسب الرسول، ويشتم الرسول، أو يقول: إنه ما بلغ الرسالة، أو يقول: إنه يجهل بعض الأمور، ما يعرف كل شيء جاهل، أو عنده جهل، أو مقصر في حق الله، أو مقصر في البلاغ، أو ما أشبه ذلك من الاستهزاء كله كفر أكبر، وردة عن الإسلام، نعوذ بالله، أو يسب الله، ويتنقص الله، أو يقول: إنه يجهل، أو يقول: إنه ظالم، أو يقول: إن شرعه ناقص، أو يقول: إن الإسلام غير صحيح، أو إنه دين خرافة، أو لا يجوز التزامه، أو لا يجوز الدخول فيه، أو لا يلزم كل ذلك كفر أكبر، نسأل الله العافية. والخلاصة: أن سب الإسلام، أو سب الله، أو سب الرسل أو تنقصهم أو الطعن فيهم أو الاستهزاء بهم كله كفر أكبر عند جميع أهل العلم، نسأل الله العافية، يوجب القتل، يوجب على ولي الأمر ولي أمر المسلمين أن يأخذ هذا الشاذ، وهذا المتنقص ويقتله على ردته عن الإسلام.  أما إذا تاب فتوبته فيها تفصيل بين أنواع الكفر، والساب لله ولرسوله لا يستتاب عند جمع من أهل العلم؛ لعظم جريمته نعوذ بالله، بل يقتل حدًا.  أما أنواع الكفر الأخرى كدعاء الأموات والاستغاثة بالأموات والنذر للأموات وترك الصلاة هؤلاء يستتابون، فإن تابوا وإلا قتلوا، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13223/ما-حكم-من-يسب-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_637/nour_63712.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":14798,"question":"رسالة وصلت إلى البرنامج من سلطنة عمان، المنطقة الجنوبية، باعثها المستمع علي بن مبخوت بن سالم الراشدي. أخونا يقول: عندنا وخاصة في المنطقة الجنوبية يوجد مسجد وقبر في الجبل، أي: جبل ظفار، يدعي أهل ظفار بأنه قبر النبي أيوب، ومما لفت انتباهي بأنهم يزاورونه ويتوافدون إليه، وكذلك قبر مماثل يوجد في صلالة يدعون أنه قبر عمران، ويتجهون إليهم مثل الذي في الجبل. أرجو من سماحتكم التكرم بالإجابة على هذا السؤال، ونشره في الإذاعة. جزاكم الله خيرًا.","title":"هل يعرف قبرا أيوب وعمران عليهما السلام؟ وحكم زيارتهما","answer":"الجواب: هذا شيء لا صحة له، فجميع قبور الأنبياء لا تعرف ما عدا قبر نبينا محمد ﷺ في المدينة، وقبر إبراهيم في الخليل، وما سوى ذلك فهو غير معروف عند أهل العلم، ولا يصدق من قال ذلك، لا قبر أيوب، ولا غير أيوب -عليه الصلاة والسلام-.  ثم لو فرضنا أنه موجود قبر أيوب أو غير أيوب أو عمران أو غير عمران لم يجز لأحد أن يعبده من دون الله، ولا أن يدعوه من دون الله، حتى الرسول محمد ﷺ وهو أفضل الخلق لا يجوز لأحد أن يدعوه من دون الله، أو يستغيث به، أو ينذر له، أو يذبح له يتقرب إليه بالذبائح؛ لأن هذا من الشرك الأكبر، فالواجب الحذر من ذلك. فالقبور لا يجوز عبادة أهلها من دون الله، فلا تدعى من دون الله، ولا يستغاث بأهلها، ولا ينذر لهم، ولا يذبح لهم، ولا يطلب منهم المدد، كل هذا لا يجوز، بل هو من الشرك الأكبر، فالواجب الحذر من ذلك، قال الله : وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ[الإسراء:23] وقال سبحانه: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ[الفاتحة:5] وقال سبحانه: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا[الجن:18] وقال : وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ106] وقال : ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلا يُنَبِّئُكَ مِثْلُ خَبِيرٍ[فاطر:13-14]،  فبيَّن سبحانه أن دعاء غير الله من الأموات والأصنام والأشجار والأحجار كله شرك بالله ؛ ولهذا قال: وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ يعني: يتبرؤون منكم، وينكرون عليكم ما فعلتم، وقال : وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ[المؤمنون:117] فسمى دعاة غير الله من الأصنام والأموات سماهم كافرين. فالواجب الحذر من هذه الشركيات، والواجب التواصي بإنكارها، وإبلاغ الجهلة ذلك، حتى يكونوا على بينة، وعلى بصيرة؛ لأن الله  أوجب على عباده التواصي بالحق، والدعوة إلى الله  قال سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ[العصر:1-3] وقال سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ[النحل:125] رزق الله الجميع التوفيق والهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13300/هل-يعرف-قبرا-ايوب-وعمران-عليهما-السلام-وحكم-زيارتهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63813.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":14806,"question":"يذهب الناس عندنا في يوم العيد إلى المقابر، وينادون الشيوخ -كما يطلقون عليهم- لقضاء حوائجهم، فهل يجوز هذا أم لا؟","title":"حكم الذهاب إلى المقابر لدعاء أصحابها","answer":"الجواب: الذهاب إلى القبور لدعاء الأموات، والاستغاثة بالأموات؛ هذا من الشرك الأكبر، هذا لا يجوز، بل هو من عمل الجاهلية، من عمل أهل الشرك، فلا يجوز دعاء الأموات، لا عند قبورهم، ولا بعيدًا من ذلك، ولا طلبهم المدد، كأن يقول: يا سيدي البدوي اقض حاجتي، اشف مريضي، المدد المدد، أو يا سيدي عبدالقادر، أو يا شيخ عبدالقادر ، أو يا رسول الله اشف مريضي، أو المدد المدد، أو غير هذا من الأساليب، بل هذا من الشرك الأكبر، ومن عمل الجاهلية.  وإنما تزار القبور للسلام عليهم، والدعاء لهم، إذا كانوا مسلمين، يزورهم، ويقول: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يغفر الله لنا ولكم. فالميت المسلم في حاجة إلى الدعاء، إلى أن يدعى له، ويترحم عليه، أما أنه يدعى من دون الله؛ فهذا من الجرائم العظيمة، هو لا يستطيع أن ينفع نفسه، فكيف ينفع غيره، ليس له إلا ما قدم من عملٍ صالح، والله يقول -جل وعلا-: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] ويقول : وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] ويقول ﷺ: الدعاء هو العبادة والله يقول سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء: 23]، إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] ويقول -جل وعلا- لنبيه ﷺ: قُلْ إِنَّ صَلاتِي [الأنعام:162] يعني: قل يا محمد للناس: إِنَّ صَلاتِي وَنُسُكِي [الأنعام:162] يعني: عبادتي، وفسر أيضًا: بالذبح، بذبحي، وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ [الأنعام:163]. فالواجب على جميع العباد أن يخصوا الله بالعبادة، من دعاء، وخوف، ورجاء، وتوكل، وذبح، ونذر، وغير هذا من أنواع العبادة، هذا حق الله، وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]، وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] والدعاء من العبادة، طلب الشفاء، أو الشفاعة، أو المدد، أو قضاء الدين، أو سلامة الأولاد، أو سلامة الدواب والمزرعة، كل هذا شرك بالله، إذا طلبه من الأموات، أو من الأصنام والأشجار والأحجار، صار شركًا بالله ، فالواجب الحذر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13301/حكم-الذهاب-الى-المقابر-لدعاء-اصحابها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64202.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":14807,"question":"المستمع: (س. ع. ب) مصري يعمل في العراق، بعث برسالة يقول فيها: في حالة غضب رجل سب الدين، والعياذ بالله، هل تطلق زوجته؟ وهل عليه كفارة؟ وما هي؟","title":"هل تطلق زوجة من سب الدين في حالة الغضب؟","answer":"الجواب: سب الدين ردة عن الإسلام، فإن تاب ورجع إلى الله، وأناب إليه قبل خروج زوجته من العدة؛ فهي زوجته، وإن خرجت من العدة قبل أن يتوب؛ لم تحل له إلا بنكاحٍ جديد، إذا تاب إلى الله ، ورجع إلى الحق. أما إن استمر على كفره وضلاله؛ فإنها لا تحل له حتى يتوب إلى الله، وحتى يجدد عقده عليها، بعد خروجها من العدة، إذا كانت قد خرجت من العدة، أما إذا تاب في العدة؛ فهي زوجته، ومن تاب، تاب الله عليه. أما إذا رفع إلى ولي الأمر، فولي الأمر يحيله إلى المحكمة، والمحكمة تحكم فيه بما يقتضي به الشرع المطهر، في ساب الدين، أو ساب الرسول -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13307/هل-تطلق-زوجة-من-سب-الدين-في-حالة-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64208.mp3","categories":["الطلاق","نواقض الإسلام"]},{"id":14818,"question":"يسأل ويقول: لدى كثير من الناس عادة، وهو أنه عندما يعطس أحد فيقول الشخص الذي يتكلم بعطسة: حلال، هل هذا الكلام صحيح؟","title":"حكم قول المتكلم عندما يعطس شخص: بعطسة حلال","answer":"الجواب: لا أصل لهذا، هذا كلام العامة لا أصل له، ولكن المشروع للمؤمن إذا عطس أن يقول: الحمد لله، ومن سمعه يقول له: يرحمك الله، وهو يقول: يهديكم الله ويصلح بالك، هذا السنة، إذا عطس يقول: الحمد لله، أو الحمد لله رب العالمين، أو الحمد لله على كل حال، ومن سمعه يقول: يرحمك الله، هذا السنة، وهو يقول لمن قال: يرحمك الله، يقول له: يهديكم الله، ويصلح بالكم، هكذا جاءت السنة عن النبي -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13329/حكم-قول-المتكلم-عندما-يعطس-شخص-بعطسة-حلال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_643/nour_64310.mp3","categories":["نواقض الإسلام","البدع والمحدثات","الآداب والأخلاق المحمودة"]},{"id":14846,"question":"عندما يحدث نزاع بين قبيلتين على أمر ما من مصالح الدنيا، فإن المتنازعين لا يتحاكمون إلى الشرع، حتى ولو على حكم الشرع، بل يتحاكمون -وهذا سائد بين كل أفراد القبيلتين- لما يسمى المرضي، وهو شخص من قبيلة غير قبيلتي المتنازعين، فيحكم هذا الشخص بما وجد عليه الآباء والأجداد، وقد يحكم بيمين تؤدى في ضريح، فمثلًا: إذا اتهم شخص بسرقة، وأنكر فإنه يقسم بالشيخ فلان أنه ما سرق، ويحلف معه خمسة أو عشرة من أهله أو قبيلته تختارهم القبيلة التي لها اليمين، وبالفعل يحلفون بأن صاحبهم صادق، حتى ولو لم يروا شيئًا، فما رأي سماحتكم؟ وما هو موقفنا كدعاة إلى الله؟ وإذا كان والدي من هؤلاء الذين يحكمون الناس بما سبق، وأن وصفته فما هو وجه النصح له، رغم أني نصحته أكثر من مرة، فبرر عمله بأنه طالما أنه يحلف الناس من بعضهم فلا شيء في ذلك، هل أقاطعه؟ وإذا ما قاطعته هل أكون عاقًا؟أفيدونا، جزاكم الله خيرًا.","title":"حكم التحاكم إلى غير شرع الله والحلف بغير الله","answer":"الجواب: لا يجوز التحاكم إلى غير شريعة الله، بل يجب الحكم بشريعة الله، والتحاكم إليها، كما قال الله سبحانه: فَلا وَرَبِّكَ لا يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ [النساء:65] يعني: النبي ﷺ، فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لا يَجِدُوا فِي أَنفُسِهِمْ حَرَجًا مِمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْلِيمًا [النساء:65] ويقول سبحانه: أَفَحُكْمَ الْجَاهِلِيَّةِ يَبْغُونَ وَمَنْ أَحْسَنُ مِنَ اللَّهِ حُكْمًا لِقَوْمٍ يُوقِنُونَ [المائدة:50] ويقول سبحانه: وَمَنْ لَمْ يَحْكُمْ بِمَا أَنزَلَ اللَّهُ فَأُوْلَئِكَ هُمُ الْكَافِرُونَ [المائدة:44] . فَأُوْلَئِكَ هُمُ الظَّالِمُونَ [المائدة:45].. فَأُوْلَئِكَ هُمُ الْفَاسِقُونَ [المائدة:47]. فالواجب التحاكم إلى شرع الله، ولا يجوز لأي أحد أن يحكم بين القبيلة بحكم الطاغوت والأجداد والأسلاف، ولا يجوز الحلف بغير الله، بالسيد فلان، ولا بأبي فلان، ولا بالنبي فلان، الحلف لا يجوز إلا بالله وحده ، قال النبي ﷺ: من كان حالفًا فليحلف بالله أو ليصمت وقال -عليه الصلاة والسلام-: من حلف بشيء دون الله فقد أشرك فالحلف بغير الله لا يجوز، لا بالأنبياء ولا بالأولياء ولا بغيرهم. ولا يجوز تحكيم شيوخ القبائل، ولا أشخاص معينين من أي قبيلة، كل هذا منكر، وكل هذا لا يجوز وباطل، والذي يراه جائزًا، ويراه أمرًا معتبرًا، يكون كافرًا، نسأل الله العافية من ذلك، كل من أجاز حكم غير الله، فإنه يكون كافرًا، ولو قال: إن حكم الشرعة أحسن، إذا قال: إنه يجوز تحكيم القوانين، أو آراء الأجداد، وأنها جائزة، فهذا كله شرك أكبر، ولو قال: إن الشريعة أحسن وأفضل، فالأحوال ثلاثة:\n- تارة يحكم بغير ما أنزل الله ويقول: إنه أحسن من حكم الله.\n- وتارة يقول: إنه مثل حكم الله.\n- وتارة يقول: لا، حكم الله أحسن، ولكن هذا جائز.\nففي الأحوال الثلاثة كلها يكون كافرًا، نسأل الله العافية؛ لأنه استجاز أمرًا محرمًا بالإجماع مخالفًا للشريعة المطهرة، ولنص الكتاب والسنة، ومن استحل ما حرمه الله، وأجمع عليه المسلمون فهو كافر. نعم يجوز الإصلاح بين الناس بما لا يخالف الشرع، فإذا تنازع اثنان في سرقة، أو مضاربة، وأصلح بينهما وتراضوا، أصلح بينهما شخص على أن هذا السارق يعطي فلان كذا وكذا، ولا يترافعون للمحكمة يعطيه سرقته، أو يزيده كذا وكذا، ولا يترافعون فلا بأس، أو يطلب منه سموحة وسمح، فلا بأس، أما أن يلزمه بحكم أحد فلا، لا يجوز الإلزام بحكم أحد من الناس أبدًا إلا بحكم الشرع، أما الإصلاح بين الناس بأن يطلب منه السماح فيسمح، أو يرضيه بماله الذي أخذه منه، أو نهب منه، أو عن ضربة ضربه إياها، يرضيه بمال أو بوجاهة فلا بأس، على سبيل الرضا فقط من دون إلزام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13352/حكم-التحاكم-الى-غير-شرع-الله-والحلف-بغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_644/nour_64408.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":14852,"question":"المستمع (م. ش. ع) من محافظة مطروح -برج العرب، بعث برسالة مطولة، ضمنها عددًا من الأسئلة، من بينها سؤال يقول فيه: بجوارنا الكثير من الأضرحة والقبور المرتفعة التي أوقدت عليها السرج، وتذبح له النذور من دون الله، ويحلف بأصحابها، والعياذ بالله، فإذا ما تحدثنا للناس، وبينا لهم بأن هذا شرك، وأن عليهم أن يتوبوا إلى الله، قالوا: بأنهم وجدوا آباءهم على هذه الحالة التي وصفت، فماذا نفعل إزاءهم؟ وجهونا ووجهوهم، جزاكم الله خيرًا.","title":"ما الواجب تجاه الأضرحة والقبور المرتفعة؟","answer":"الجواب: الواجب عليكم وعليهم إزالة الأبنية التي على القبور، وبقرها، وتركها ضاحية شامسة، كما كانت القبور في عهد النبي ﷺ في البقيع وفي غيره، وكما كانت القبور في بلاد أهل السنة والجماعة من قديم الزمان، ولا يجوز البناء عليها، ولا اتخاذ المساجد عليها؛ لأن الرسول نهى عن ذلك -عليه الصلاة والسلام-، وقال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وقال جابر بن عبدالله الأنصاري : \"نهى رسول الله ﷺ عن تجصيص القبور، والقعود عليها، والبناء عليها\" ولا يجوز لأحد من الناس أن يدعوها من دون الله، أو يستغيث بأهلها، أو ينذر لهم، أو يذبح لهم، أو يطلبهم المدد، أو يتبرك بتراب قبورهم، كل ذلك منكر، ومن الشرك الأكبر، نعوذ بالله. فالواجب تنبيههم، وليس لهم حجة في تقليد آبائهم، هذه حجة المشركين، قال الله -جل وعلا- عن المشركين لما نهاهم الرسول ﷺ عن عبادة الأصنام قالوا: إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِمْ مُهْتَدُونَ [الزخرف:22] فهذه حجة باطلة، حجة ملعونة خبيثة، فلا يجوز الاحتجاج بها، هذه حجة الكفرة، إذا وجدت أباك على باطل لا تتبع أباك، أما إذا كان على حق؛ فالواجب الأخذ بالحق، سواءً كان عليه أبوك أو غير أبيك. وأما ما يفعله الناس اليوم عند القبور من الدعاء، والاستغاثة بأهلها، والذبح لهم، والطواف بقبورهم، كل هذا منكر عظيم، كل هذا من عمل أهل الشرك من عباد الأوثان. فالواجب على المسلم أن يحذر ذلك، وأن يحذره إخوانه، وينذرهم، والواجب على العلماء في كل مكان أن يحذروا الناس، وأن يرشدوهم، وأن يوضحوا لهم حقيقة التوحيد، وحقيقة الشرك، وأنه لا يجوز لأحد أن يدعو الميت من دون الله، ولا أن يستغيث به، ولا أن يذبح له، ولا أن يطلبه المدد، ولا أن يطوف بقبره، كل ذلك من الشرك الأكبر، كونه يطوف يتقرب إلى الميت بالطواف هذا شرك أكبر، أو يقول: يا سيدي، المدد المدد، أو الغوث الغوث، هذا من الشرك الأكبر، هذا من جنس عمل أبي جهل وأشباهه من عباد القبور، عباد الأصنام. فالواجب عليكم -أيها السائل- أن تستمروا في النصيحة والإنكار، وأن تطلبوا من العلماء أن ينبهوهم ويوضحوا لهم، ويرشدوهم، حتى يتركوا هذا الشرك، وحتى يزيلوا هذه الأبنية التي على القبور، وتبقى القبور ضاحية شامسة ليس عليها بناء، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/13349/ما-الواجب-تجاه-الاضرحة-والقبور-المرتفعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_644/nour_64406.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":14861,"question":"هل يصح زيارة الولي في المسجد للرجل أو للمرأة وحينئذٍ يكون هناك شرك بالله؟الشيخ: أعد.المقدم: يقول: هل يصح زيارة الولي في المسجد للرجل أو للمرأة، وحينئذٍ يكون هناك شرك بالله إذا وضعت أو حملت له في مرة قادمة خروفًا لهذا الولي ومبلغ معين من المال؟","title":"حكم زيارة الأولياء والتقرب لهم","answer":"الجواب: الولي علمه عند الله ، والمؤمنون كلهم أولياء الله، وما يظنه بعض الخرافيين بأن الولي يكون له صفة أخرى زائدة على صفات أهل الإيمان، من بعض الخرافات، وخرق العادات، ونحو ذلك، فهذا ليس بصحيح، فكثير من الأولياء لا يجري على أيديهم خرق للعادات، فأولياء الله هم أهل الإيمان، وإن لم توجد لهم كرامات خاصة، قال الله -جل وعلا-: أَلا إِنَّ أَوْلِيَاءَ اللَّهِ لا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ ۝ الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ[يونس:63] قال سبحانه: وَمَا كَانُوا أَوْلِيَاءَهُ إِنْ أَوْلِيَاؤُهُ إِلَّا الْمُتَّقُونَ[الأنفال:34]. فالمؤمن ولي لله سواء كان عربيًا أو أعجميًا، ذكرًا أو أنثى، عالمًا أو غير عالم، فأولياء الله هم أهل الإيمان والتقوى، فزيارتهم في الله للمحبة في الله في المسجد، أو في بيوتهم، التزاور بين المؤمنين سنة، قربة وطاعة، جاء في الحديث الصحيح عن النبي ﷺ أنه قال: يقول الله : وجبت محبتي للمتزاورين فيَّ، والمتجالسين فيَّ، والمتحابين فيَّ، والمتباذلين فيَّ ويقول ﷺ: يقول الله -جل وعلا- يوم القيامة: أين المتحابون بجلالي؟ اليوم أظلهم في ظلي، يوم لا ظل إلا ظلي. فالمؤمن يزوره أخوه في الله في بيته، أو في المسجد، وتزوره أخته في الله إذا كانت الزيارة ليس فيها ريبة، كأن تزور أخاها، أو عمها، أو خالها، أو قريبًا لها، أو جارًا لها مريضًا تعوده أو تسأله عن علم مع التحجب، ومع عدم الخلوة لا بأس بذلك، فالمؤمن يزوره إخوانه المؤمنون، وتزوره أخته المؤمنة على وجه شرعي ليس فيه ريبة، ولا فتنة مع التستر، والحجاب، وعدم الخلوة لمصلحة شرعية من عيادة المريض، أو سؤال أهل العلم، أو غير هذا من المقاصد الشرعية. أما أن يذبح له من دون الله، أو يدعى من دون الله لظن بعض الخرافيين أنه يتصرف في الكون هذا باطل، هذا من الشرك الأكبر، سواء كان حيًا أو ميتًا، فالذي يتقرب لقبور الأولياء يزعم أنهم يقضون حوائجه، أو أنهم يعلمون الغيب، أو أنهم يتصرفون في الكون، هذا شرك أكبر، حتى ولو ما تقرب لهم، هذا الاعتقاد نفسه شرك أكبر، نسأل الله العافية. فإذا ذبح لهم إبلًا أو بقرًا أو غنمًا أو دجاجًا، أو غير ذلك هذا شرك أكبر أيضًا، وإذا استغاث بهم، وقال: يا سيدي فلان المدد، أو اشفع لي، أو اقض حاجتي، أو أغثني، يقولها عند قبره، أو بعيدًا عنه، كل هذا من الشرك الأكبر، أما إذا كان يقوله لحي حاضر قادر يقول: ساعدني على كذا، اشفع لي عند فلان، أو ساعدني على قضاء ديني، أو ساعدني على كف شر فلان بن فلان، حتى يشفع له حتى يتصل به، ويقول له: دع فلانًا، لا تؤذ فلانًا، هذه أمور عادية لا بأس، كما قال الله -جل وعلا- في قصة موسى: فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ[القصص:15]. فالناس ما داموا أحياء فيما بينهم يطلب بعضهم من بعض الرفد، أو العون أو المساعدة بالمشافهة، أو بالمكاتبة، أو من طريق الهاتف، أو من طريق البرق برقية، أو ما أشبهه لا بأس بهذا، أما أن يدعوه من دون الله يعتقد أنه ولي لله، وأنه يتصرف في الكون يدعوه من بعيد، أو يدعوه عند قبره، أو يقدم له ذبائح، أو يستغيث به، أو ينذر له وهو ميت أو غائب هذا شرك أكبر. فيجب الحذر من هذه الأمور التي يقع فيها العامة لجهلهم، أما الأمور الحسية العادية التي يفعلها الناس فيما بينهم، كأن تقول لأخيك الحاضر: يا فلان أقرضني كذا، أو ساعدني على كذا، أو عاوني في إصلاح سيارتي، أو في بناء بيتي، وهو حاضر يسمع كلامك، أو من طريق المكاتبة، أو من طريق الهاتف، يعني: التلفون، أو من طريق البرق إلى البرق، أو من طريق حسي، وطريق أخرى تكلمه منه هذا كله لا بأس به؛ لأنها أمور عادية، وقد جرى للناس الآن اتصالات هاتفية، واتصالات رسمية كانت لم تكن قبل ذلك، وقد وقعت الآن، فإذا كان الاتصال بالشيء الحسي المعروف، سواء سمي هاتفًا، أو سمي باسم آخر تلكس، أو غير ذلك كل ذلك من الأمور الحسية فيما يقدر عليه الإنسان. أما أن يعتقد فيه أنه يتصرف في الكون، أو أنه يعلم الغيب، فهذا كفر وشرك أكبر، أو يتقرب لقبر، للميت يتقرب إليه بالذبائح، أو يستغيث به، أو ينذر له، أو يذبح له قرابين كل هذا شرك أكبر، فيجب التفريق بين ما جاز شرعًا، وما حرم الله شرعًا، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13380/حكم-زيارة-الاولياء-والتقرب-لهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_639/nour_63903.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":14975,"question":"سؤال فلاح السويد من قرية الكوز التالي طويل ومتشعب أيضًا، لكن لا بد من قراءته، يقول فيه: أسألكم عن زيارة قبور الصالحين، وتقبيل الحجر، أي: النصائب، هل هذا يجوز أم لا؟ وعن مديح المشايخ هل يجوز أم لا؟ وعن المدد أو استمداد من غير الله مثل: مدد يا شيخ الفلاني مثلًا، هل هو من قبره يمدني أم لا؟أفيدونا، إننا غشماء عن هذه، ولا ندري إننا نسب عباد الله الصالحين، يقول أحد الناس: إن من عباد الله الصالحين يغني قسم من هذه الدنيا بكلمة واحدة، هل هذا يجوز القول أم لا حرام؟نرجو أن تجعلونا لله نهتدي إلى الخير بمشيئة الله.الجواب: أعد السؤال. يقول في سؤاله، نأخذه نقطة نقطة، يقول في سؤاله: نسألكم عن زيارة قبور الصالحين، وتقبيل الحجر، أي: النصائب، هل هذا يجوز أم لا؟","title":"حكم زيارة قبور الصالحين وتقبيل النصائب وطلب المدد","answer":"الجواب: زيارة القبور للصالحين للمسلمين أيضًا عمومًا سنة، قربة، الرسول ﷺ أمر بزيارة القبور، وحث عليها، وقال: إنها تذكر الآخرة، وتزهد في الدنيا، وتذكر الموت قال -عليه الصلاة والسلام-: زوروا القبور، فإنها تذكركم الآخرة وكان يعلم أصحابه -عليه الصلاة والسلام- إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية وفي حديث عائشة يقول: يرحم الله المستقدمين منا والمستأخرين. فعلينا معشر المسلمين أن نعلم هذا الحكم، ويشرع لنا أن نفعل ذلك؛ أن نزور القبور للذكرى والرغبة في الآخرة والزهد في الدنيا، والإحسان للموتى بالدعاء لهم، الإنسان يزورهم ليدعو لهم بالمغفرة والرحمة والعافية؛ وليتذكر الآخرة، وأنه صائر إلى ما صاروا إليه من هذا الموت حتى يستعد للآخرة. أما تقبيل القبور فلا، لا يقبل النصائب ولا التراب، ولا الجدران إن كان عليها جدران ولا القضبان إن كان هناك قضبان، كل هذا منكر لا يجوز، هذا من الغلو، ولا يجوز البناء على القبور، بل يجب أن تكون مكشوفة ليس عليها بناء، واتخاذ القباب عليها من البدع، وهكذا بناء المساجد عليها من البدع التي أنكرها الرسول ﷺ ونهى عنها، قال: لعن الله اليهود والنصارى، اتخذوا قبور أنبيائهم مساجد وقال جابر : \"نهى النبي ﷺ عن تجصيص القبور، والقعود عليها، والبناء عليها، والكتابة عليها\". فليس لأحد أن يبني على القبور لا قبابًا ولا مساجد ولا غير ذلك، وليس له أن يقبلها، ولا أن يتبرك بترابها، ولا أن يطلب الشيخ المدد كما يأتي، لا يجوز يقول: يا رسول الله، مدد مدد، ولا يا فلان كالشيخ عبدالقادر، أو يا شيخ البدوي السيد البدوي، أو يا الحسن أو يا سيدي الحسن أو الحسين، أو يا فلان أو يا أبا حنيفة، أو يا أبا فلان، كل هذا لا يجوز، المدد لا يطلب من الميت يطلب من الله -جل وعلا-: يا رب أغثني، يا رب ارحمني، يا رب اشف مريضي، يا رب ارزقني، أما طلب المدد من الموتى فهو من الشرك بالله  من الشرك الأكبر من عمل الجاهلية. فلا يقبل الحجارة، ولا النصائب ولا التراب، ولا يأخذ التراب للبركة، ولا يطلب مدد من المخلوق من الميت، أما الحي الحاضر تقول: يا أخي! ساعدني بكذا، أعني على كذا، وهو حي حاضر قادر لا بأس، الحي الحاضر القادر لا بأس، لكن الميت لا، لا تقل: المدد المدد، ولا تقل: اشف مريضي وانصرني على عدوي انصرنا على المشركين لا يقل هذا للميت، الميت انقطع عمله، وليس له التصرف في الكون، بل التصرف لله وحده  هو المالك لكل شيء، وهو القاهر فوق عباده، وهو النافع الضار، المعطي المانع، المدبر للكون ، وأما الميت فهو مرتهن بعمله ليس له تصرف، قال النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية مثل الأوقاف التي يوقفها في حياته أو علم ينتفع به كتب ألفها أو طلبة علمهم له أجر ذلك  أو ولد صالح يدعو له. أما كونه يتصرف في الكون، أو يمد هذا، أو ينصر هذا، هذا منكر لا حقيقة له ولا صحة له، بل الاستغاثة بالأموات والنذر لهم، والتقرب إليهم، بالذبائح، وطلبهم المدد والغوث كل هذا من فعل الجاهلية من عمل أهل الشرك، وهو شرك أكبر يجب الحذر منه، ويجب عليك -أيها السائل- أن تبلغ من يفعل هذا أن هذا منكر، وأنه شرك يجب ترك ذلك والتوبة إلى الله من ذلك؛ لأن هذا من عمل الجاهلية، نعم.","link":"https://binbaz.org.sa/fatwas/13482/حكم-زيارة-قبور-الصالحين-وتقبيل-النصاىب-وطلب-المدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_661/nour_66102.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":14977,"question":"لديه أيضًا السؤال الذي يقول فيه: يقول لنا أحد الناس بعد أن قال: إننا غشماء وكذا وكذا، يقول: يقول لنا أحد الناس: إن من عباد الله الصالحين يغني قسم من هذه الدنيا بكلمة واحدة، هل هذا يجوز القول أم لا؟","title":"حكم قول: إن بعض الصالحين يُغني بكلمة واحدة","answer":"الجواب: هذا باطل، التصرف في الكون لله وحده، والعبد لا يملك، ولو كان أصلح الصالحين، ولو كان من الرسل، لا يملك التصرف في الكون، ولا إغناء الناس، ولا إفقارهم، بل هذا بيد الله ، هو الذي يغني ويفقر -جل وعلا-، وهو المتصرف في الأمور سبحانه، ومدبر الأمر -جل وعلا-، وهو خالق كل شيء : إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ[يس:82] ، أما العباد وإن كانوا أصلح الناس، فليس لهم التصرف في الكون، ولا يملكون تدبير الكون.  نعم، قد يدعو المؤمن دعوة مباركة فتستجاب له، قد يدعو لأخيه أن الله يشفيه فيشفى، قد يدعو له بالمغفرة فيغفر له، هذا من باب استجابة الدعاء من فضل الله ، قد يجيب دعوة المؤمن والمؤمنة لأخيهما فلا بأس هذا وقع.  لكن ليس لأحد من الصالحين أو غيرهم التصرف في الكون، أو تدبير الكون، هذا لله وحده ، وما قد يقع لبعض الصوفية أو غيرهم من اعتقاد هذا في بعض مشايخهم، وأنه يقول للشيء: كن، فيكون، وأنه يدبر الأمور، هذا كله غلو، كله إطراء زائد، وكله كفر وضلال، لا يجوز هذا، بل هذا من الكفر بالله ، نعم.","link":"https://binbaz.org.sa/fatwas/13488/حكم-قول-ان-بعض-الصالحين-يغني-بكلمة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_661/nour_66104.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":15155,"question":"نعود مع بداية هذه الحلقة إلى رسالة المستمع أحمد عبدالله محمد علي جمعة من السودان، الأخ أحمد عرضنا بعض أسئلة له في حلقة مضت، وفي هذه الحلقة يسأل، ويقول: رأيت بعض الناس يزورون القبب التي فيها مقابر الأولياء، ويطلبون منهم الرحمة والخير والعافية، ما حكم الإسلام في هؤلاء؟جزاكم الله خيرًا.","title":"حكم دعاء أهل القبور والاستغاثة بهم","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فإن الله -جل وعلا- شرع لعباده ما فيه صلاحهم، وما فيه نجاتهم في الدنيا والآخرة، ونهاهم عن كل ما يضرهم في الدنيا والآخرة، وبعث الرسل مبشرين ومنذرين -عليهم الصلاة والسلام-، مبشرين من أطاعهم واستقام على ما دعوا إليه؛ بالجنة والسعادة، والنصر في الدنيا والنجاة من الآخرة، ومنذرين من عصاهم بالذل في الدنيا والشقاء في الآخرة. وأعظم ما بعث الله به الرسل وأهمه وأفرضه: توحيد الله، والإخلاص له، وصرف العبادة له -جل وعلا-، هذا أهم دعوة الرسل، وهذا زبدتها، إخلاص العبادة لله وحده، كما قال -جل وعلا-: وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَسُولٍ إِلَّا نُوحِي إِلَيْهِ أَنَّهُ لا إِلَهَ إِلَّا أَنَا فَاعْبُدُونِ[الأنبياء:25] وقال سبحانه: وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِ اُعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ [النحل:36] فهذه أعظم دعوة الرسل وأهمها، وهذا أساسها، توحيد الله، والإخلاص له، وألا يعبد معه سواه، لا نبي ولا ملك ولا شجر، ولا حجر، ولا صنم، ولا غير ذلك. واتخاذ القباب على القبور، والمشاهد على القبور من وسائل الشرك؛ لأن هذا من تعظيم القبور، فإذا بني عليها القباب، وجعل عليها المساجد، عظمها العامة، ودعوها من دون الله، واستغاثوا بها، ونذروا لها، وهذا هو الشرك الأكبر، فدعاء الأموات، والاستغاثة بالأموات، والنذر لهم، هذا هو الشرك الأكبر، هذا ضد دعوة الرسل، ضد التوحيد الذي بعث الله به الرسل. ولما بعث الله نبيه محمد ﷺ، قال لقومه يا قوم قولوا: لا إله إلا الله تفلحوا ونهاهم أن يعبدوا مع الله سواه، نهاهم أن يعبدوا مع الله العزى، أو مناة، أو اللات، أو غير ذلك، وأمرهم بإخلاص العبادة لله وحده، وأنزل الله عليه في ذلك: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ ۝  أَلا لِلَّهِ الدِّينُ الْخَالِصُ [الزمر:2-3]، وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]. فالواجب عبادة الله وحده، ولا يجوز اتخاذ القباب على القبور، ولا المساجد عليها، بل يدفن الميت، ويرفع قبره قدر شبر من الأرض حتى يعلم أنه ميت حتى لا يمتهن، ولا يجوز أن يدعى من دون الله، ولا أن يبنى عليه قبة، ولا مسجد، ولكن يترك ضاحيًا بارزًا كما كانت قبور الصحابة في المدينة في عهد النبي ﷺ وبعده. ولا يجوز أن يدعى الميت مع الله، ولا أن يستغاث به، ولا يقال: يا سيدي، يا فلان أغثني، أو انصرني، أو أنا في حسبك أو جوارك، أو يطلب منه الرحمة، أو المغفرة، أو شيء من أمور الخير، كالرزق، أو الزواج، أو النجاة من النار، أو دخول الجنة، أو ما أشبه ذلك، كل هذا كفرٌ بالله، كله شرك أكبر، قال الله -جل وعلا-: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] معنى: ليعبدون: ليوحدوني بالعبادة، يقصدوني بالعبادة، وحده ، وقال سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] يعني: أمر ألا تعبدوا إلا إياه، وقال سبحانه: وَاعْبُدُوا اللَّهَ وَلا تُشْرِكُوا بِهِ شَيْئًا [النساء:36] وقال سبحانه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: المشركين، وقال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] فسماهم كفارًا، وقال : فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ ۝ أَلا لِلَّهِ الدِّينُ الْخَالِصُ وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ [الزمر:2-3]. فأمر سبحانه بعبادته وحده -جل وعلا-، وإخلاص العبادة له ، وأخبر أن المشركين اتخذوا من دونه أولياء، يقولون: مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى[الزمر:3] فهم يعبدون اللات والعزى والأصنام، ويدعونها، ويستغيثون بها، ويقولون:ما نقصد إلا أنهم يقربونا إلى الله زلفى، يشفعون لنا عند الله، كما في آية يونس، يقول سبحانه: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ[يونس:18] فكذبهم سبحانه بقوله: قُلْ أَتُنَبِّئُونَ اللَّهَ بِمَا لا يَعْلَمُ فِي السَّمَوَاتِ وَلا فِي الأَرْضِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ [يونس:18] وفي آية الزمر، يقول -جل وعلا-: وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ [الزمر:3] يعني: يقولون: ما نعبدهم إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:3] فكذبهم سبحانه بقوله: إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ [الزمر:3]. فبين أنهم لا يقربونهم إلى الله، بل هم كفار بهذا كاذبون، فالقرب من الله بدعوته سبحانه، وعبادته وحده، وسؤاله، هذا هو الذي يقربهم إلى الله، وينجيهم بفضله سبحانه، يا رب أغثني، يا رب انصرني، يا رب يسر لي الزواج من المرأة الصالحة، يا رب اقض ديني، يا رب أدخلني الجنة، يا رب اغفر لي، يا رب ارحمني، هذا هو الذي شرعه الله، وهذا هو العبادة لله وهذا هو التوحيد. أما أن تقول: يا سيدي البدوي ارحمني، أو أنا في جوارك، أو أغثني، هذا هو الشرك الأكبر، أو يا سيدي الحسين، أو يا سيدي علي بن أبي طالب، أو يا سيدي الحسن، أو يا فاطمة، أو ما أشبه ذلك، هذا هو الشرك الأكبر، هذا عبادة غير الله، التي أنكرها الرسل، وأنكرها نبينا محمد -عليه الصلاة والسلام-، ولما خطبهم ﷺ في مكة، في بعض الأيام، قال: يا بني عبد المطلب أنقذوا أنفسكم من الله، لا أغني عنكم من الله شيئًا، يا بني عبد مناف أنقذوا أنفسكم من الله لا أغني عنكم من الله شيئًا، يا عباس بن عبد المطلب اشتر نفسك من الله، لا أغني عنك من الله شيئًا، يا صفية عمة رسول الله لا أغني عنك من الله شيئًا، يا فاطمة بنت محمد سليني من مالي ما شئت، لا أغني عنك من الله شيئًا فأخبرهم -عليه الصلاة والسلام-: أنه لا يغني عنهم من الله، بل لا بد من شرائهم أنفسهم من الله بالتوحيد، والإيمان، والطاعة. هؤلاء أقرب الناس إليه، بنته، وعمه، وعمته، أخبرهم أنه لا يخلصهم من الله، ولا ينجيهم من عذاب الله، ولا يغني عنهم من الله شيئًا، إلا أن يوحدوا الله، ويعبدوه وحده، حتى فاطمة بنته، قال: سليني من مالي ما شئت، لا أغني عنك من الله شيئًا. فالواجب على الجميع عبادة الله وحده، وسؤاله وحده سبحانه، والاستغاثة به وحده، وأداء حقه من صلاة، وزكاة، وصيام، وحج، وبر والدين، وصلة رحم، وصدق الحديث، وترك ما حرم الله من سائر المعاصي، كالزنا، وشرب الخمر، واللواط، والعقوق للوالدين، القطيعة للرحم، وشهادة الزور، إلى غير هذا من المعاصي، يجب تركها طاعة لله، وتعظيمًا لله، وتقربًا إليه . هذا هو الدين، وهذا الذي بعث الله به الرسل، وأنزل به الكتب، وبعث به خاتم الرسل محمدًا -عليه الصلاة والسلام-، بعثه الله يدعو الناس إلى توحيد الله، والإخلاص له، وإلى طاعة أوامره، التي أمر بها عباده، من صلاة، وصوم، وزكاة، وحج، وغير ذلك، وبعثه ينهاهم عما حرم الله عليهم؛ ولهذا صح عنه -عليه الصلاة والسلام- أنه قال: كل أمتي يدخلون الجنة إلا من أبى قيل: يا رسول الله من يأبى؟ قال: من أطاعني دخل الجنة، ومن عصاني فقد أبى فمن أطاع الرسول، واتبع الشريعة، فله الجنة، ومن عصاه فله النار، نسأل الله العافية. فنصيحتي لكل من يخاف الله، لكل من يرجو الله، أن يعبد الله وحده، وأن يخصه بدعائه، واستغاثته، ونذره، وذبحه، وغير ذلك، كما يخصه بصلاته، وصومه، وسائر عباداته، لله وحده. هذا هو التوحيد، وهذا هو الإيمان، وهذا معنى قوله -جل وعلا-: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] ومعنى قوله سبحانه: يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ [البقرة:21] يعني: وحدوه، خصوه بالعبادة، بدعائكم، وخوفكم، ورجائكم، وذبحكم، ونذركم، وصلاتكم، وصومكم. أما من يأتي أصحاب القباب، يدعوهم مع الله، هذا هو الشرك الأكبر، سواء كانوا أنبياء، أو غيرهم، من يقول: يا رسول الله أغثني، هذا شرك أكبر، بعد وفاته ﷺ، أما في حياته، يقول: أعطني كذا، أعطني من مال الله الذي عندك، ساعدني من كذا، لا بأس في حياته ﷺ، كما يقال للملوك وغيرهم، ساعدونا في حياتهم، لكن بعد وفاته يقال: أغثنا يا رسول الله، أو انصرنا، أو اشفع لنا لا، يطلب من الله، يقول: يا رب، شفع في نبيك، يا رب، أغثني، يا رب! أنجني من النار. وهكذا لا يدعى عمر ، ولا الصديق، ولا عثمان، ولا علي ولا غيرهم، وهكذا من بعد الصحابة من باب أولى لا يدعون مع الله ولا يستغاث بهم هذا حق الله، الأموات يترضى عنهم، ويدعى لهم، والأنبياء يتبعون، ويدعى لهم، لا يدعون مع الله، العبادة حق الله، وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ لا إِلَهَ إِلَّا هُوَ الرَّحْمَنُ الرَّحِيمُ [البقرة:163]، إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]، وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّاا إِيَّاهُ[الإسراء:23]، وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5]. يقول النبي ﷺ: من مات وهو يدعو لله ندًا دخل النار يعني: شبيهًا أو نظيرًا، يدعوه مع الله، يستغيث به، ينذر له، ويقول ﷺ: من لقي الله لا يشرك به شيئًا دخل الجنة، ومن لقيه يشرك به شيئًا دخل النار. فالواجب الحذر من هذا الشرك، والواجب البصيرة والتفقه في الدين، هذا واجب على جميع المسلمين، في كل مكان، وعلى جميع المكلفين في كل مكان، في البلاد العربية وغيرها، في أوروبا، في أمريكا، في أفريقيا، في آسيا في كل مكان، يجب على المكلفين أن يعبدوا الله وحده، يجب أن يخصوه بدعائهم، ونذرهم، واستغاثتهم ونحو ذلك؛ لأنهم لهذا خلقوا، خلقهم الله ليعبدوه، ليعظموه، ليخصوه بالعبادة وبه أمروا. وبهذا تعرف -أيها السائل- أن اتخاذ القباب منكر، ومن وسائل الشرك، وهكذا بناء المساجد على القبور، يقول النبي ﷺ: لعن الله اليهود والنصارى، اتخذوا قبور أنبيائهم مساجد قالت عائشة: \"يحذر ما صنعوا\" متفق على صحته، وقال -عليه الصلاة والسلام- في حديث جندب بن عبدالله البجلي، يقول : ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم، وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك رواه مسلم في الصحيح، فبين ﷺ أن الناس السابقين، يتخذون قبور أنبيائهم وصالحيهم مساجد، يعظمونها يصلون عندها، يدعون عندها يقرؤون عندها، فنهاهم عن هذا، نهاهم أن يفعلوا هذا الفعل، فوجب على العباد أن يتركوا هذا الفعل؛ لأنه وسيلة للشرك، إذا بني عليها المسجد أو القبة، جاء الجاهل والعامي، وقال: هذا ولي، وهذا ينفع، وهذا يشفع، فجعل يدعوه من دون الله، ويستغيث به، وهذا هو الشرك الأكبر، نعوذ بالله. وهكذا البناء على القبور حتى غير المساجد، يقول جابر : \"نهى رسول الله ﷺ؛ أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه\" رواه مسلم في الصحيح، زاد الترمذي وغيره: \"وأن يكتب عليه\". فالرسول ﷺ نهى عن تجصيص القبور، وعن البناء عليها، وهذا يشمل القباب وغير القباب، لا يبنى عليها شيء، ونهى أن يجلس عليه أيضًا؛ لأنه امتهانًا له، فلا يجلس عليه؛ لأنه امتهان، ولا يبنى عليه، ولا يجصص؛ لأن تجصيصه والبناء عليه من وسائل التعظيم، فإذا جصص أو بني عليه عظمه الناس حتى يقع الشرك، يدعونه من دون الله، ويعظمونه. فالواجب أن يكون مكشوفًا كسائر القبور، ولو كان قبر نبي أو صالح، حتى لا يدعى من دون الله، وحتى لا يخص بشيء من العبادة، لكن لما خاف الصحابة على النبي ﷺ أن يدعى وأن يعبد دفنوه في حجرة عائشة في بيت عائشة، حمايةً له لئلا يعبد من دون الله، ولكن أهل الغلو ما تركوا ذلك عبدوه خارج الحجرة، وفي كل مكان، يستغيثون به، وينذرون له، وهذا هو الشرك الأكبر الذي نهى عنه -عليه الصلاة والسلام-، وحذر منه، وقال: لا تطروني كما أطرت النصارى ابن مريم، إنما أنا عبد فقولوا: عبدالله ورسوله. فلا يجوز لأحد أن يغلو فيه بالدعاء، فيدعوه يدعوه من دون الله، أو ينذر له، أو يستغيث به، أو يذبح له، كل هذا شرك أكبر.\nوهكذا غيره من الأنبياء والصالحين، لا يدعون مع الله، ولا يستغاث بهم؛ لأن ذلك مما حرمه الله . فينبغي لك -يا عبد الله- أن تكون على غاية من الحذر من هذا الشرك، دقيقه وجليله، وقد عمت به البلوى في بلدان كثيرة، في البلاد العربية وغيرها، كما لا يخفى على من له أدنى دراية بأحوال الناس، ما يقع عند قبر البدوي، والحسين، والست زينب، ونفيسة في مصر، وعند العيدروس في الجنوب اليمني، وعند قبر ابن علوان، وعند غيرها من القبور، وعند قبور كثيرة، عند قبر ابن عربي في الشام، وعند قبورٍ كثيرة في العراق، وفي غيرها، تدعى من دون الله، ويستغاث بها. فيجب الحذر، وهكذا من يأتي من بعض الحجاج عند قبر النبي ﷺ، أو عند قبور البقيع من الصحابة، يدعوهم من دون الله هذا منكر وشرك أكبر يجب الحذر من ذلك، ويجب على أهل العلم أن يبينوا، يجب على العلماء في كل مكان -وفقهم الله- أن يبينوا للناس؛ لأن الناس قد يغلب عليهم الجهل يحسبونه دين. فوجب على العلماء -وفقهم الله- أن يوضحوا للناس أن الواجب عبادة الله وحده، وإخلاص العبادة لله وحده، وأن أصحاب القبور لا يدعون مع الله، ولا يستغاث بهم، ولا ينذر لهم، ولا يذبح لهم، ولا يبنى على قبورهم، ولا يتخذ عليها مساجد، فالناس في ذمة العلماء، فيجب على العلماء أن يبينوا، وأن يوضحوا للناس شرع الله، ولا سيما ما يتعلق بالتوحيد، فهو أعظم الأمور وأهمها، كما أن الشرك أعظم الذنوب، وليس عليهم إلا البلاغ على العلماء البلاغ مثلما على الرسل، والله يهدي من يشاء، وعلى ولاة الأمور التنفيذ على الحكام الرؤساء، الملوك، رؤساء الجمهوريات، ومن له قدرة على التنفيذ، أن يمنع العامة من الشرك بالله، ويدعوهم إلى توحيد الله، والإخلاص له، ويبين لهم أن هذا لا يجوز، وأن الواجب عبادة الله وحده، الذبح يكون لله، الاستغاثة بالله وحده، لا بالقبور، والنذر يكون لله وحده، لا لأهل القبور، القبور يزارون للدعاء لهم، والترحم عليهم، هم محتاجين للدعاء لهم، يزورهم، يقول: السلام عليكم أهل الديار من المؤمنين والمسلمين، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين يدعو لهم، كما كان النبي ﷺ يزور القبور، ويدعو لهم -عليه الصلاة والسلام-، وكان يعلم أصحابه إذا زاروا القبور، يقولوا: السلام عليكم دار قوم مؤمنين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين وذكر ابن عباس -رضي الله عنهما- أن النبي ﷺ لما زار قبور المدينة، قال: السلام عليكم يا أهل القبور، يغفر الله لنا ولكم، أنتم سلفنا ونحن بالأثر وكان يعلم أصحابه هذا، -عليه الصلاة والسلام-، كما رواه مسلم في الصحيح، كان يعلمهم إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية وفي الحديث الآخر: يرحم الله المستقدمين منا والمستأخرين. فالواجب على أهل الإسلام التمسك بما كان عليه النبي ﷺ وأصحابه، والسير عليه، في زيارة القبور، وفي غيرها في جميع الأمور، كما قال الله سبحانه: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7] قال سبحانه: قُلْ أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِنْ تَوَلَّوا فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُمْ مَا حُمِّلْتُمْ وَإِنْ تُطِيعُوهُ تَهْتَدُوا [النور:54] فالهداية في طاعته -عليه الصلاة والسلام-، وَمَا عَلَى الرَّسُولِ إِلَّا الْبَلاغُ الْمُبِينُ [النور:54] وقال سبحانه: مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ [النساء:80] قال : فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ [النور:63] فالخير كله في طاعة المصطفى ﷺ، واتباع شريعته، وتعظيم أمره ونهيه؛ وذلك بتعظيم كتاب الله -القرآن- والتمسك به، والأخذ بما فيه، وتعظيم السنة، التي جاء بها ﷺ، فإن الله أعطاه القرآن ومثله معه، وهي السنة. فالواجب على أهل الإسلام التفقه في كتاب الله، والتفقه في سنة رسول الله ﷺ، والعمل بهما، في جميع الأحوال، ولا سيما في أصل التوحيد، وأصل الدين وأساسه، وهو أعظم الأمور، وهو رأس المال، نسأل الله لجميع المسلمين ولنا التوفيق والهداية والفقه في الدين، ولا حول ولا قوة إلا بالله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13668/حكم-دعاء-اهل-القبور-والاستغاثة-بهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_496/49601.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":15351,"question":"في آخر أسئلة هذه السائلة تقول سماحة الشيخ: سمعت من إحدى صديقاتي بأنه عند المرور على القبور أنه يستحب للمسلم أن يقرأ سورة الإخلاص إحدى عشر مرة، وآية الكرسي في هذا اليوم، فيرفع عنهم العذاب، وعلى قدر عددهم يغفر الله لهم، هل هذا بدعة؟","title":"حكم قراءة الإخلاص وآية الكرسي عند المرور على القبور","answer":"الجواب: كل هذا باطل، لا أصل له، هذا باطل ليس له أصل، بدعة، بدعة ظاهرة، ليس له أصل، ولكن إذا مر عليهم يسلم عليهم، يقول: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين هذا الرجل، أما المرأة لا تزور القبور، لكن الرجل إذا مر عليها يسلم، أما قراءة قُلْ هُوَ اللَّهُ أَحَدٌ  [الإخلاص: 1] أو آية الكرسي كل هذا لا أصل له، نعم.","link":"https://binbaz.org.sa/fatwas/13854/حكم-قراءة-الاخلاص-واية-الكرسي-عند-المرور-على-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56624.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":15355,"question":"رسالة من أحد الإخوة المستمعين، وقع في نهايتها بقوله: أخوكم في الله (خ. م. س)، يسأل ويقول: ما حكم الإسلام فيمن يشهد: أن لا إله إلا الله، وأن محمدًا رسول الله، ويصوم ويصلي، ولكنه يقرب الذبائح لغير الله، ويحلف بغير الله، ويشد الرحال إلى قبور الصالحين ويدعوهم، ويستغيث بهم؟المطلوب بيان هوية فيمن يفعل ذلك هل هو مسلم؟ وهل صلاته صحيحة، أم غير ذلك؟جزاكم الله خيرًا.","title":"حكم من يصرف بعض العبادات لأهل القبور","answer":"الجواب: هذه المسألة قد وقع فيها جم غفير ممن ينتسب إلى الإسلام جهلًا منهم، وتقليدًا لآبائهم وأسلافهم، فالذي يشهد أن لا إله إلا الله، وأن محمدًا رسول الله، ويصلي ويصوم، ولكنه مع ذلك يتقرب إلى أصحاب القبور بالذبائح، ويستغيث بهم، وينذر لهم، أو للجن أو إلى الأصنام هذا مشرك، وصلاته باطلة، وشهادته باطلة؛ لأنه نقضها بأفعاله الشركية، مثل المنافقين الذين يصلون مع الناس، ويصومون، ويشهدون أن لا إله إلا الله، وأن محمدًا رسول الله، ولكن يقولون: محمد ما هو صادق في باطنهم، وينكرون البعث والنشور في الباطن، هؤلاء في الدرك الأسفل من النار، كما قال الله -جل وعلا-: إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الأَسْفَلِ مِنَ النَّارِ [النساء:145] وقال عنهم سبحانه: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ وَلا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا ۝ مُذَبْذَبِينَ بَيْنَ ذَلِكَ لا إِلَى هَؤُلاءِ وَلا إِلَى هَؤُلاءِ [النساء:142-143] لا مع المسلمين، ولا مع الكفار، وقال في الآية الأخرى: وَمَا مَنَعَهُمْ يعني: المنافقين، أَنْ تُقْبَلَ مِنْهُمْ نَفَقَاتُهُمْ إِلَّا أَنَّهُمْ كَفَرُوا بِاللَّهِ وَبِرَسُولِهِ وَلا يَأْتُونَ الصَّلاةَ إِلَّا وَهُمْ كُسَالَى وَلا يُنفِقُونَ إِلَّا وَهُمْ كَارِهُونَ ۝ فَلا تُعْجِبْكَ أَمْوَالُهُمْ وَلا أَوْلادُهُمْ إِنَّمَا يُرِيدُ اللَّهُ لِيُعَذِّبَهُمْ بِهَا فِي الْحَيَاةِ الدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَافِرُونَ [التوبة: 54-55] فسماهم كفرة، ولم يقبل منهم أعمالهم، مع أنهم يصلون لماذا؟ لأنهم في الداخل والباطن قد كذبوا الرسول ﷺ، وأنكروا البعث والنشور، فلهذا صاروا كفارًا باعتقادهم الباطن، فلا ينفعهم صلواتهم وشهاداتهم الظاهرة؛ لأن باطنهم يخالف ذلك. فهكذا الذي يتقرب للقبور بالذبائح والنذور، ويستغيث بهم، ويذبح لهم، هذا ليس بمسلم يكون كافرًا، وإن صلى وصام، وإن شهد أن لا إله إلا الله، وأن محمدًا رسول الله عند أهل العلم، عند جميع أهل السنة والجماعة ليس في هذا خلاف بحمد لله؛ لأن نواقض الإسلام متى وجد منها ناقض بطلت أعمال العبد، ومن ذلك لما يبين هذا الأمر، لو أن إنسانًا يشهد أن لا إله إلا الله، وأن محمدًا رسول الله ويصلي ويصوم، ولكنه يسب الله، ويلعن الله، ويلعن الرسول ﷺ فهذا كافر عند جميع العلماء، ولو شهد، لو لعن الله، أو لعن الرسول ﷺ كفر بإجماع المسلمين، أو قال: إن الرسول ﷺ بخيل، ذمه قال: بخيل، أو قال: جبان، كفر عند جميع العلماء، ولو شهد أن محمدًا رسول الله، وهكذا لو سب الله كفر إجماعًا، أو قال كما قالت اليهود: (إن الله بخيل) كفر إجماعًا، أو قال: (يداه مغلولتان) كفر بإجماع المسلمين، ولو صلى وصام، أو قال في باطن الأمر: إن ما هناك جنة، ولا نار كذب، كما يقول المنافقون كفر بالإجماع، ولو شهد أن لا إله إلا الله، وأن محمدًا رسول الله، هذه مسألة مهمة عظيمة، وهكذا لو أن إنسانًا يصلي ويصوم، ويشهد أن لا إله الله، وأن محمدًا رسول الله، ويقول: إن الزنا حلال، ما في حرج أن الإنسان يزني، أو ما في حرج أنه يشرب الخمر، أو ما في حرج أنه يعق والديه، ما في بأس، ما في حرج صار كافرًا بإجماع المسلمين.\nفينبغي للعاقل أن ينتبه لهذا، ينبغي له أن ينتبه لهذا، وهكذا كل مسلم ومسلمة يجب الانتباه لهذا الأمر، فالتقرب للقبور بالذبائح والنذور والاستغاثة بأهل القبور شرك أكبر، كما يفعله بعض الناس عند قبر ابن علوان في اليمن، أو عند العيدروس في اليمن، أو عند ابن عربي في الشام، أو عند الشيخ عبدالقادر الجيلاني في العراق، أو عند قبر أبي حنيفة في العراق، أو يفعله مع البدوي في مصر، أو مع الحسين في مصر، أو مع غيرهم، كل هذا كفر أكبر شرك أكبر، الذي يستغيث بهؤلاء، وينذر لهم، ويذبح لهم، ويسألهم الغوث والنصر والشفاء، كافر عند جميع أهل السنة والجماعة، ولا تنفعه صلاته، ولا صومه، ولا شهادة أن لا إله إلا الله، وأن محمدًا رسول الله، كالمنافقين الذين يقولونها وهم يسبون الرسول، ويكذبون الله في الباطن. فهذه المسائل العظيمة يجب التنبه لها من جميع المسلمين، ويجب على العلماء في أي قطر وفي أي مكان أن ينبهوا الناس على هذا الأمر، حتى يتبصر المسلمون، وحتى يتبصر عباد القبور وغيرهم، وحتى يكونوا على بينة، وحتى يقلعوا من هذا العمل السيئ، وحتى يتوبوا إلى الله من ذلك. هذا هو واجب العلماء أينما كانوا في هذه المملكة وفي الشام وفي مصر وفي أفريقيا وفي العراق، وفي كل مكان، يجب على علماء الشريعة علماء السنة أن يبينوا للناس أحكام هذه الأمور، وأن يرشدوهم إلى توحيد الله والإخلاص له، كما قال سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] وقال سبحانه: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] وقال : وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] وقال عن الكفار من قريش وغيرهم: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18] جعل شفاعتهم، طلبهم الشفاعة من آلهتهم جعلها كفرًا، شركًا أكبر، جعلها كفرًا وشركًا أكبر، فكيف بالذي يذبح لهم، وينذر لهم، ويستغيث بهم أعظم وأعظم. فالواجب على جميع المسلمين وعلى جميع من وقع في هذه الأمور أن ينتبه، وأن يتوب إلى الله، وأن يخلص العبادة لله وحده، وألا يذبح إلا لله، وألا يستغيث إلا بالله، وألا ينذر إلا لله، يقول سبحانه في سورة الأنعام في آخرها: قُلْ إِنَّ يعني: قل: يا محمد! قُلْ إِنَّ صَلاتِي يعني: قل يا محمد! للناس، إِنَّ صَلاتِي وَنُسُكِي يعني: ذبحي، وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:162-163] ويقول سبحانه يخاطب نبيه ﷺ: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:1-2] فالصلاة لله والذبح لله -جل وعلا-، ويقول -جل وعلا-: فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ [غافر:14] قال -جل وعلا-: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] فهذا يعم الأنبياء وغيرهم، وقال سبحانه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: المشركين، والآيات في هذا المعنى كثيرة. ويقول النبي ﷺ: حق الله على العباد أن يعبدوه، ولا يشركوا به شيئًا، ويقول لـابن عباس: إذا سألت فاسأل الله، وإذا استعنت فاستعن بالله فالعبادة حق الله وحده، هو الذي يستعان به، ويستغاث به. أما المخلوق إذا كان حيًا فلا بأس أن يستعان به في الحي الحاضر، تقول له: أعني على إصلاح سيارتي، لا بأس، أعني على تعمير بيتي، لا بأس، حاضر يسمع كلامك، ويعينك. أما سؤال الأموات والاستغاثة بالأموات، أو بالأحجار أو بالأصنام أو بالأشجار أو بالجن هذا كفر أكبر، وشرك أعظم، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13858/حكم-من-يصرف-بعض-العبادات-لاهل-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_498/49805.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":15378,"question":"السائل صبري جعفر، مقيم بأبها، يقول: هل يجوز بناء المقابر فوق سطح الأرض، إذا كانت الأرض التي بها المقابر طينية أو زراعية؟ علمًا بأنه لو تم حفر حوالي نصف المتر، أو ربع المتر، سوف يظهر الماء، وليس هناك سوى المكان في هذه البلدة.","title":"ما حكم بناء القبور فوق سطح الأرض لأن الأرض طينية؟","answer":"الجواب: إذا كانت هكذا يجعل خشب أو ألواح، تحفر، ويجعل خشب، أو ألواح، يحول بين الماء وبين الميت، ويدفن في الأرض، ولا يبنى عليه؛ لأن الرسول ﷺ نهى أن يبنى على القبور، لكن يحفر القدر الذي لا يصل إلى الماء، يحفر ثم يجعل لوح تحته، أو أخشاب، أو شبه ذلك تمنع الماء، ثم يدفن الميت، ويهال عليه التراب، يوضع عليه اللبن، وعليه التراب، ولا يبنى عليه بناية، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13881/ما-حكم-بناء-القبور-فوق-سطح-الارض-لان-الارض-طينية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56709.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":15442,"question":"هذا السائل يقول في هذا  يوجد مقابر بجوارها مقام يذبح عند هذا المقام ذبائح نذرت لله، ولكن لا تذبح إلا في هذا المكان، وإذا نهاهم أحد قالوا: إنما نذبح لله، ولكن بجوار الأولياء. علمًا بأنهم يأتون من أماكن متفرقة، وأماكن بعيدة للذبح في هذا المكان، ثم يجلسون لتناول الطعام في نفس المكان، فهل هذا حلال أم حرام؟أفيدونا بذلك.","title":"حكم الذبح عند الأضرحة والمقامات","answer":"الجواب: هذا بدعة، ووسيلة للشرك، مجيئهم للذبح عند القبور بدعة، ولو قالوا: إنها لله، أما إن كان لأصحاب القبور فهو شرك أكبر، والعياذ بالله، قال الله تعالى: قُلْ إِنَّ صَلاتِي وَنُسُكِي [الأنعام:162] يعني: ذبحي، وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:162-163] وقال سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ( [الكوثر:1-2] وقال النبي ﷺ: لعن الله من ذبح لغير الله. فإن ذبحوا للأموات يتقربوا للأموات صار شركًا أكبر، كمن يذبح للأولياء يرجو شفاعتهم، أو شفاء المرضى، أو ما أشبه ذلك، أو يدعونهم، أو يستغيثون بهم، أو ينذرون لهم، أو يطوفون بالقبور، كل هذا شرك أكبر، أما إن كان الذبح لله، ولكن يرون أن هذا محل مناسب، وأنه محل مبارك، هذا غلط، هذا بدعة، لا يجوز؛ لأنه وسيلة للشرك، وبدعة في الدين، نعم.\nالمقدم: جزاكم الله خيرًا، سماحة الشيخ عبدالعزيز كثيرًا ما تردنا مثل هذه الأسئلة، فهل من توجيه من كلمة للدعاة إلى الله  في نصح مثل هؤلاء؟ الشيخ: نعم، نوصي الدعاة إلى الله والعلماء أن يوجهوهم إلى الخير، وأن يعلموهم ويرشدوهم، حتى يكونوا على بينة على بصيرة، يقول الله -جل وعلا- في كتابه العظيم: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] ويقول -جل وعلا-: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33] وقال سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ أَنَا وَمَنِ اتَّبَعَنِي [يوسف:108] هكذا أتباع النبي ﷺ يدعون إلى الله على بصيرة، يعلمون الناس، يرشدون الناس لا يغفلون، ويقول ﷺ في حديث علي: لأن يهدي الله بك رجلًا واحدًا خير لك من حمر النعم ويقول ﷺ: من دل على خير فله مثل أجر فاعله نعم. المقدم: جزاكم الله خيرًا فضيلة الشيخ.","link":"https://binbaz.org.sa/fatwas/13957/حكم-الذبح-عند-الاضرحة-والمقامات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_500/50013.mp3","categories":["البدع والمحدثات","نواقض الإسلام"]},{"id":15472,"question":"سؤالها الآخر تقول: منذ مدة صادفتني مشكلة فنذرت نذرًا لأحد الأئمة إن انحلت هذه المشكلة، وقد علمت أنه لا يجوز النذر لغير الله. علمًا أن المكان الذي فيه الإمام بعيد عني، فهل يجوز أن أدفع هذا النذر للفقراء أو أكفر عنه؟أفيدوني، حفظكم الله.","title":"ما يجب على من نذر للأولياء؟","answer":"الجواب: هذا النذر باطل؛ لأنه عبادة لغير الله، وعليك التوبة إلى الله من ذلك، والرجوع إليه والإنابة والاستغفار والندم.\nفالنذر عبادة، قال الله تعالى: وَمَا أَنفَقْتُمْ مِنْ نَفَقَةٍ أَوْ نَذَرْتُمْ مِنْ نَذْرٍ فَإِنَّ اللَّهَ يَعْلَمُهُ[البقرة:270] يعني: فيجازيكم عليه، وقال النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه فهذا النذر باطل، الذي نذرت لأحد الأئمة الأموات لعلي أو الحسين، أو الشيخ عبد القادر أو غيرهم نذر باطل، وهكذا النذور لغير هؤلاء كالنذر للبدوي أو للسيدة زينب أو السيدة نفيسة، أو غير ذلك، كله باطل، وهكذا النذر لرسول الله ﷺ باطل أيضًا. النذر لا يجوز إلا لله وحده؛ لأنه عبادة، فالصلاة، والذبح، والنذر، والصيام، والدعاء كله لله وحده  كما قال الله سبحانه: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ[الفاتحة:5] قال سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ[الإسراء:23] يعني: أمر ألا تعبدوا إلا إياه، قال سبحانه: فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ[غافر:14] قال : فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا[الجن:18]. فالعبادة حق الله، والنذر عبادة، والصوم عبادة، والصلاة عبادة، والدعاء عبادة، والذبح عبادة، فيجب إخلاصها لله وحده. فهذا النذر باطل ليس عليك منه شيء لا للفقراء ولا غيرهم، بل عليك التوبة والاستغفار، وليس عليك الوفاء بهذا النذر؛ لكونه باطلًا وشركًا، وعليك بالتوبة الصادقة، والعمل الصالح، وفقك الله، وهداك لما فيه رضاه، ومنَّ عليك بالتوبة النصوح، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/14002/ما-يجب-على-من-نذر-للاولياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_688/nour_68804.mp3","categories":["الأيمان والنذور","نواقض الإسلام"]},{"id":15586,"question":"هذا السائل: محمد أحمد علي من الأردن، عمان، بعث بسؤالين، قد أجيب على سؤاله الأول في الحلقة الماضية، وهذا سؤاله الثاني نعرضه على فضيلتكم يقول فيه:إذا غضب الشخص، واشتد به الغضب، فحصل منه سب للدين، فما حكمه؟ وإن كان متزوجًا فهل يلحق زوجته شيء كأن تفارقه مثلًا إذا كان الحكم بخروجه عن الإسلام؟","title":"حكم من سب الدين عند الغضب","answer":"الجواب: هذه مسألة عظيمة، ولها شأن خطير؛ سب الدين من أعظم الكبائر والنواقض للإسلام، فإن سب الدين ردة عند جميع أهل العلم، وهو شر من الاستهزاء، قال الله تعالى: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ ۝ لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ[التوبة:66] وكانت جارية في عهد النبي ﷺ تسب النبي ﷺ فقتلها سيدها لما لم تتب، فقال النبي ﷺ: ألا اشهدوا إن دمها هدر. سب الدين يوجب الردة عن الإسلام، وسب الرسول ﷺ كذلك يوجب الردة عن الإسلام، ويكون صاحبه مهدر الدم، وماله لبيت المال؛ لكونه مرتدًا أتى بناقض من نواقض الإسلام، لكن إذا كان عن شدة غضب واختلال عقل فله حكم آخر، والغضب عند أهل العلم له ثلاث مراتب: المرتبة الأولى: أن يشتد غضبه حتى يفقد عقله، وحتى لا يبقى معه تمييز من شدة الغضب، فهذا حكمه حكم المجانين والمعاتيه لا يترتب على كلامه حكم لا طلاقه ولا سبه، ولا غير ذلك، يكون كالمجنون لا يترتب عليه حكم.\nالقسم الثاني: دون ذلك، اشتد معه الغضب وغلب عليه الغضب جدًا حتى غيَّر فكره، وحتى لم يضبط نفسه، واستولى عليه استيلاء كاملًا حتى صار كالمكره والمدفوع الذي لا يستطيع التخلص مما في نفسه؛ لكنه دون الأول، لم يزل شعوره بالكلية، ولم يفقد عقله بالكلية، لكن معه شدة غضب بأسباب المسابة والمخاصمة والنزاع الذي بينه وبين بعض الناس، بينه وبين أهله، أو زوجته، أو أبيه أو أميره، أو غير ذلك، فهذا اختلف فيه العلماء:\nفمنهم من قال: حكمه حكم الصاحي وحكم العاقل...، تجري فيه أحكام، يقع طلاقه، ويرتد بسبه الدين، ويحكم بقتله وردته، ويفرق بينه وبين أهله بين زوجته.  ومنهم من قال: يلحق بالأول الذي فقد عقله؛ لأنه أقرب إليه؛ ولأن مثله مدفوع مكره إلى النطق، لا يستطيع التخلص من ذلك لشدة الغضب، وهذا القول أظهر وأقرب، وأن حكمه حكم من فقد عقله في هذا المعنى في عدم وقوع طلاقه، وفي عدم ردته؛ لأنه يشبه فاقد الشعور بسبب شدة غضبه، واستيلاء سلطان الغضب عليه، حتى لم يتمكن من التخلص من ذلك، واحتجوا على هذا بقصة موسى -عليه الصلاة والسلام-، فإنه لما وجد قومه على عبادة العجل اشتد غضبه عليهم، وجاء وألقى الألواح، وأخذ برأس أخيه يجره إليه، مع شدة غضب فلم يؤاخذه الله لا بإلقاء الألواح، ولا بجر أخيه، وهو نبي مثله هارون، من أجل شدة الغضب، ولو ألقاها تهاونًا بها وهو يعقل الإنسان لكان هذا عظيمًا، ولو جر النبي بلحيته أو رأسه وآذاه صار كفرًا، لو جره إنسان، لكن لما كان موسى في شدة الغضب العظيم غضبًا لله  على ما جرى من قومه سامحه الله، ولم يؤاخذ بإلقاء الألواح، ولا بجر أخيه، هذه من حجج الذين قالوا: إن طلاق هذا -الذي اشتد به الغضب- لا يقع، وهكذا سبه لا تقع به الردة، وهو قول قوي ظاهر، وله حجج أخرى كثيرة بسطها شيخ الإسلام ابن تيمية -رحمه الله-، والعلامة ابن القيم، واختارا هذا القول. وهذا القول أرجح عندي، وهو الذي أفتي به؛ لأن من اشتد غضبه ينغلق عليه قصده، ويشبه المجنون بتصرفاته، وكلامه القبيح، فهو أقرب إلى المجنون والمعتوه منه إلى العاقل السليم، فهذا القول أظهر وأقوى، ولكن لا مانع من كونه يؤدب بعض الأدب إذا فعل شيئًا من أسباب الردة من وجوه الردة من باب الحيطة، ومن باب الحذر من التساهل بهذا الأمر، أو وقوعه منه مرة أخرى إذا أدب.\nالمقدم: تعزير مثلًا يعني.\nالشيخ: من باب الضرب أو السجن أو نحو ذلك، هذا قد يكون فيه مصلحة كبيرة، لكن لا يحكم عليه بحكم المرتدين من أجل ما أصابه من شدة الغضب التي تشبه حال الجنون، والله المستعان. أما المرتبة الثالثة، القسم الثالث: فهو الغضب العادي الذي لا يزال معه العقل، ولا يكون معه شدة تضيق عليه الخناق، وتفقده ضبط نفسه، بل هو دون ذلك، غضب عادي يتكدر ويغضب، لكنه سليم العقل، سليم التصرف، فهذا عند جميع أهل العلم تقع تصرفاته، يقع بيعه وشراؤه وطلاقه وغير ذلك؛ لأن غضبه خفيف، لا يغير عليه قصده، ولا قلبه، والله أعلم، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/14129/حكم-من-سب-الدين-عند-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_693/nour_69302.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":15807,"question":"يسأل أخونا سماحتكم فيقول: نرجو من سماحتكم أن تتفضلوا بتوضيح أنواع الشرك؟ وهل الحلف بغير الله شرك يخرج صاحبه من الملة أم لا؟","title":"بيان أنواع الشرك","answer":"الجواب: الشرك نوعان: شرك أكبر، وأصغر؛ فالشرك الأكبر صرف العبادة لغير الله، أو بعضها، كدعاء الأموات، والاستغاثة بالأموات، والنذر لهم، أو للجن أو للملائكة أو غيرهم من الأموات والغائبين، هذا يقال له: شرك أكبر، كما كانت قريش وغيرها من العرب يفعلون ذلك عند أصنامهم وأوثانهم.  ومن ذلك أيضًا إذا جحد الإنسان أمرًا معلومًا من الدين بالضرورة وجوبًا أو تحريمًا، من جحده كان كافرًا ومشركًا شركًا أكبر، كمن قال: إن الصلاة لا تجب على المكلفين من المسلمين، أو قال: إن الزكاة لا تجب على من عنده أموال الزكاة، أو قال: صوم رمضان لا يجب على المسلم المكلف، فهذا يكون كافرًا ومشركًا شركًا أكبر. أو أحل ما حرمه الله مما هو معلوم من الدين بالضرورة، مما أجمع عليه المسلمون، كأن يقول: الزنا حلال، أو شرب المسكر حلال، أو العقوق للوالدين حلال، أو السحر حلال، أو ما أشبه ذلك، فهذا يكون كافرًا ومشركًا شركًا أكبر. والقاعدة: أن من صرف العبادة أو بعضها لغير الله من أصنام أو أشجار أو أموات أو جن أو غيرهم من الغائبين فهذا شرك أكبر، وهكذا من جحد ما أوجب الله أو ما حرم الله مما هو معلوم من الدين بالضرورة، قد أجمع عليه المسلمون، فهذا يكون كافرًا كفرًا أكبر ومشركًا شركًا أكبر، كل من أتى ناقضًا من نواقض الإسلام يكون مشركًا شركًا أكبر كما مثلنا. أما الشرك الأصغر فهو أنواع أيضًا، مثل الحلف بغير الله، بالنبي، بالأمانة، برأس فلان، هذا شرك أصغر؛ لقوله ﷺ: من حلف بشيء دون الله فقد أشرك وهكذا الرياء كونه يقرأ يرائي، أو يتصدق يرائي هذا من الشرك الأصغر؛ لقوله ﷺ: أخوف ما أخاف عليكم الشرك الأصغر فسئل عنه، فقال: الرياء وهكذا قول: ما شاء الله وشاء فلان بالواو، أو لولا الله وفلان، أو هذا من الله ومن فلان، فهذا من الشرك الأصغر؛ لقوله ﷺ: لا تقولوا: ما شاء الله وشاء فلان، ولكن قولوا: ما شاء الله، ثم شاء فلان ولما قال رجل: «يا رسول الله، ما شاء الله وشئت، قال: أجعلتني لله نداً؟ ما شاء الله وحده. وقد يكون الشرك الأصغر شركًا أكبر إذا اعتقد صاحبه أن من حلف به بغير الله، أو قال فيه ما شاء الله وشاء فلان، أنه له التصرف في الكون، وأن له إرادة تخرج عن إرادة الله، وعن مشيئة الله، وأن له قدرة يضر وينفع دون الله، أو اعتقد أنه يصلح أن يعبد من دون الله، وأن يستغاث به، يكون شركًا أكبر لهذا الاعتقاد، أما إذا كان مجرد حلف بغير الله من غير اعتقاد آخر، لكن جرى على لسانه الحلف بغير الله تعظيمًا لهذا الشخص، يرى أنه أهل لأنه نبي أو صالح، أو لأنه أبوه أو أمه أو ما أشبه ذلك، فهذا من الشرك الأصغر لا من الشرك الأكبر عند أهل العلم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14401/بيان-انواع-الشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_743/nour_74315.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":15852,"question":"السائلة من الإمارات -في آخر أسئلتها في رسالتها لنور على الدرب- تقول:أرجو بيان صحة هذه الصيغة الصلاة على الرسول ﷺ، وهو كما يلي:(اللهم صل وسلم على سيدنا محمد، قد ضاقت حيلتي؛ أدركني يا رسول الله، اللهم صل على سيدنا محمد الحبيب المحبوب شافي العلل، ومفرج الكروب، وعلى آله وصحبه وسلم، اللهم صل على محمد الصلاة الكاملة، وسلم السلام التام على محمد النبي ﷺ)؟","title":"حكم الصلاة على النبي ﷺ بألفاظ تقدح في التوحيد","answer":"الجواب: هذا منكر، هذه صلاة منكر، لا تجوز؛ لأن قوله: (أدركني يا محمد) هذا دعاء غير الله، هذا شرك بالله، شرك بالله، ولا يجوز.\nالشيخ: وما الكلام الذي بعده؟ المقدم: تقول: (اللهم صل على سيدنا محمد، قد ضاقت حيلتي؛ أدركني يا رسول الله).\nالشيخ: هذا من الشرك الأكبر، نعم، أعوذ بالله، نعم. المقدم: (..اللهم صل على سيدنا محمد النبي الحبيب المحبوب شافي العلل).\nالشيخ: كذلك هذا، لا، ما هو بشافي العلل، الذي يشفي العلل هو الله وحده، هو المعافي المشافي -جل وعلا-، نعم. المقدم: (ومفرج الكروب).\nالشيخ: كذلك هذا شرك أكبر، ليس هو مفرج الكروب، الذي يفرجها هو الله وحده ، ولكن اتباع النبي ﷺ وطاعته، واتباع شريعته من أسباب تفريج الكروب، ومن أسباب تيسير الأمور. وأما الشافي للعلل، ومفرج الكروب، والذي يدرك الناس برحمته هو الله -جل وعلا-، ولكن السنة في هذا أن يقول:\nاللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم؛ إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم؛ إنك حميد مجيد هذه الصلاة التي علمها أصحابه -عليه الصلاة والسلام- لما قالوا: «يا رسول الله، أمرنا الله أن نصلي، فكيف نصلي عليك؟ قال: قولوا: اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم؛ إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم، إنك حميد مجيد. وقال لهم في وقت آخر أيضًا: اللهم! صل على محمد وعلى أزواجه وذريته كما صليت على آل إبراهيم، وبارك على محمد وعلى أزواجه وذريته، كما باركت على آل إبراهيم؛ إنك حميد مجيد وفي لفظ آخر قال: قولوا: اللهم صل على محمد وعلى آل محمد كما صليت على آل إبراهيم، وبارك على محمد وعلى آل محمد كما باركت على آل إبراهيم في العالمين إنك حميد مجيد، والسلام كما علمتم السلام يقول: (السلام عليك -أيها النبي- ورحمة الله وبركاته).\nهذه الصلاة المشروعة، أما هذه الصلاة -التي ذكرها السائل- هذه منكرة وشركية، نعوذ بالله، نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ.\nهذه العبارات التي يوجد بها هذه الشركيات، أقول: كيف يحقق المسلم التوحيد يا شيخ؟\nالشيخ: تحقيق التوحيد: بإخلاص العبادة لله وحده، وألا يدعو إلا الله، ولا يستغيث إلا بالله، ولا يتوكل إلا عليه، ولا ينذر إلا له، ولا يذبح إلا له، ولا يصلي إلا له، العبادة لله وحده، كما قال تعالى: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] قال سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] هذا حقيقة التوحيد: أن يخص الله بالعبادة، ويخص نبيه بالاتباع والطاعة -عليه الصلاة والسلام-، أما العبادة فهي حق الله يجب أن يخص بها -جل وعلا-: فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ [غافر:14]، إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]، وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] فلا يصلي إلا لله، ولا يذبح إلا لله، ولا ينذر إلا لله، ولا يصوم إلا لله، وهكذا جميع العبادات، نعم. المقدم: سماحة الشيخ، ما توجيهكم لأصحاب المكتبات والتي قد توجد فيها بعض هذه الشركيات في بعض الكتب الموجودة؟\nالشيخ: الواجب على أهل المكتبات أن يتخيروا الكتب النافعة، وأن يحذروا، والواجب على القائمين على المكتبات أن يتقوا الله، وألا يبيعوا الكتب التي فيها الدعوة إلى الشرك أو البدع، يجب على المسلمين التعاون على البر والتقوى، بل كل مؤمن يجب أن يتقي الله، وأن يراقب الله، فإذا رأى شيئًا يخالف الشرع رفع إلى من له الأمر حتى يزال ذلك الشيء. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14443/حكم-الصلاة-على-النبي-ﷺ-بالفاظ-تقدح-في-التوحيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_576/57614.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":15876,"question":"سماحة الشيخ، يقول السائل من الجزائر: تعلق بعض الناس بالصالحين، وهم موتى، فترى هذا الإنسان يذهب إلى هؤلاء الموتى، يطلب منهم قضاء الحاجات، وتفريج الكربات، مع أنّ هؤلاء ماتوا، ويزعم بأنهم صالحين، ما حكم عمل هؤلاء؟ مأجورين.","title":"حكم دعاء الأموات","answer":"الجواب: ما يفعله بعض الناس من الذهاب إلى قبور الصالحين، أو قبر النبي ﷺ يدعو، ويستغيث هذا من الشرك الأكبر، هذا شرك المشركين، هذا شرك الجاهلية، نعوذ بالله، كان أهل الجاهلية يطلبون من الموتى، كانوا يسألون اللات، ويتقربون إليه، وهو رجل صالح، يزعمون أنه كان يلت السويق للحاج، فمات فعكفوا على قبره، وصاروا يسألونه من دون الله، ويستغيثون به؛ ولهذا قال النبي ﷺ: لعن الله اليهود والنصارى، اتخذوا قبور أنبيائهم مساجد وقال ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد؛ فإني أنهاكم عن ذلك. فالواجب على كل مكلف أن يتقي الله، وأن يراقب الله، وأن يخص الله بالعبادة، فلا يدعو إلا الله، ولا يستغيث إلا به، ولا يستجير إلا به، هو سبحانه الذي يدعى ويرجى -جل وعلا-، قال تعالى: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] قال سبحانه: ادْعُونِي أَسْتَجِبْ لَكُمْ[غافر:60] قال تعالى: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] قال تعالى: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: المشركين. فالذي يقصد أصحاب القبور وإن كانوا صالحين، ويسألهم الغوث أو الشفاعة أو غفران الذنوب أو السلامة من شر الأعداء كل هذا شرك بالله شرك أكبر، وهكذا دعاء الجن والاستغاثة بالجن أو بالأصنام والأوثان، كل هذا من الشرك الأكبر نسأل الله العافية، فالواجب الحذر من ذلك، هذا هو دين المشركين، دعاء الأموات والاستغاثة بالأموات وبالأصنام وبالجن وبالنجوم هذا شرك المشركين، هذا دينهم الباطل، نسأل الله العافية، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14463/حكم-دعاء-الاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57702.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":16397,"question":"لها سؤال آخر تقول فيه: يوجد عندنا مقام، ويدعي الناس أنه موجود فيه قبر الخضر  فيأتون إلى هذا المقام، ويأخذون معهم الشموع والحلوى، وعندما يدخلون فيه؛ يضيئون الشموع، ويبدؤون بالدعاء، والنذر عند هذا القبر، فهل هذا بدعة؟ وجهونا مأجورين.","title":"حكم دعاء أصحاب القبور والنذر لهم والاستغاثة بهم","answer":"الجواب: الخضر مات من دهر طويل، والصواب أنه مات قبل بعثة النبي -عليه الصلاة والسلام- وهو رجل صالح، وذهب جماعة من أهل العلم إلى أنه نبي، وهو الأرجح بظاهر القرآن الكريم، ولكن لا يعرف قبره، والذي يقال عندكم إنه قبره كذب لا صحة له، ولو عرف ما جاز أن يغلى فيه، ولا أن ينذر له، ولا أن يدعى من دون الله، ولا أن يتبرك به، ولا يبنى عليه، بل هذا منكر عظيم، بل النذر للخضر، أو دعاؤه من دون الله من الشرك الأكبر، كدعاء الأنبياء والصالحين، والاستغاثة بهم، كله شرك أكبر، الله يقول سبحانه: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، ويقول سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117]. فلا يجوز للرجل، ولا للمرأة دعاء الخضر، ولا الاستغاثة به، ولا النذر له، ولا الطواف بما يدعى أنه قبر له، كل هذا لا يجوز، بل من الشرك الأكبر، دعاؤه، والنذر له، والاستغاثة به من الشرك الأكبر، والطواف بقبر يدعى أنه قبر الخضر، أو غيره، الطواف بالقبور؛ طلبًا للكرم من أهلها، والفائدة من أهلها شرك أكبر. فالواجب على جميع من يأتي هذا القبر أن يترك ذلك، وأن يحذره، والواجب على الدولة إذا كانت مسلمة أن تهدم هذا، وتزيله؛ لأنه كذب لا صحة له، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15100/حكم-دعاء-اصحاب-القبور-والنذر-لهم-والاستغاثة-بهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_811/nour_81107.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":16441,"question":"ما حكم نصب القباب على قبور الصالحين بقصد تشريفهم وتكريمهم؟ وما حكم التبرك بها، والاستشفاء بها، والصلاة عندها، وخاصة صلاة الأعياد؟ وبماذا تنصحون الناس جزاكم الله خيرًا؟","title":"حرمة نصب القباب على القبور","answer":"الجواب: نصب القباب على القبور منكر، ومن وسائل الشرك، وهكذا البناء عليها بناء مساجد، كله منكر من عمل اليهود والنصارى، يقول النبي ﷺ: لعن الله اليهود والنصارى؛ اتخذوا قبور أنبيائهم مساجد. فالواجب الحذر من ذلك، وعدم التشبه بهم؛ لأنهم فعلوا ما يسبب الشرك، والرسول ذمهم على هذا، ولعنهم عليه، والواجب هدمها، الواجب على ولاة الأمور -إذا كانوا مسلمين- أن يهدموها، ويزيلوها، وأن تبقى القبور مكشوفة، ليس عليها قباب ولا مساجد، كما كان في عهد النبي ﷺ وعهد الصحابة، وكما كانت عند أهل السنة في مقابرهم، وكما في المملكة العربية السعودية -بحمد الله- فإنها مكشوفة، وليس عليها بناء. ولا يجوز التبرك بها، ولا دعاء أهلها، ولا الاستغاثة بهم، ولا النذر لهم، بل هذا من الشرك الأكبر، دعاؤهم، والاستغاثة بهم، والنذر لهم، وطلب البركة منهم، كله من الشرك الأكبر، نعوذ بالله، وهكذا الذبح لهم. فيجب على المسلم أن يحذر هذه الأمور، وأن يحذرها غيره، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15145/حرمة-نصب-القباب-على-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_755/nour_75512.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":16738,"question":"هناك جماعة من الناس يستعينون بالأموات، والمشايخ، وهناك بعض الإخوة يقولون لهم: إنكم مشركون بهذا العمل، ويقاطعونهم، فما هو توجيهكم؟ جزاكم الله خيرًا.","title":"حكم الاستغاثة بالأموات","answer":"الجواب: نعم، الاستعانة بالأموات، والاستغاثة بالأموات، أو بالأشجار، والأحجار، أو بالأصنام، أو بالجن، أو بالملائكة، كله شرك أكبر، أو بالرسل، كله شرك أكبر، كله من الشرك بالله .  وهكذا المشايخ إذا كانوا أمواتًا، أو غائبين، يعتقد فيهم أنهم ينفعونه، ويشفعون له، يدعوهم من دون الله، يستغيث بهم، كل هذا من الشرك الأكبر، وقد أنزل الله في ذلك كتابه العظيم، وبعث به رسله الكرام -عليهم الصلاة والسلام- قال  في كتابه العظيم: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] وقال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] وقال -جل وعلا-: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:13-14] سمى دعاءهم شركًا.  فلا يجوز لمسلم أن يدعو الأموات، أو يستغيث بهم، أو ينذر لهم، أو يذبح لهم، يتقرب إليهم بالذبائح، أو يستغيث بهم عند الشدائد، كل هذا من الشرك الأكبر، وهذا عمل كفار قريش وغيرهم، هذه أعمال الكفار عند قبور الأموات، وعند أصنامهم، وأشيائهم التي يعبدونها من دون الله. والغائب مثل الميت، الغائب عنك مثل الميت، يدعو غائبًا يعتقد أنه يسمع دعاءه، وأنه له سر، يدعوه مثلًا هو في مصر، أو في مكة، أو في أي مكان يدعوه من بعيد، هذا مثل دعاء الميت، شرك أكبر. أما الحاضر الذي يسمع كلامك، تقول: يا عبدالله، أعني على كذا، أقرضني كذا، ساعدني على إصلاح السيارة، عاوني على رفع هذا الحجر، على رفع هذا الباب، على رفع هذه الخشبة، لا بأس، إذا كان حاضرًا يسمع كلامك، ويقدر على أن يعينك، لا بأس بهذا، كما قال الله في قصة موسى: فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15] لأن موسى يسمع الكلام، ويستطيع؛ فلا بأس. وهكذا خوفك من العدو، تغلق الباب، أو تهرب من بلد إلى بلد؛ خوفًا من العدو، لا بأس، كما قال الله -جل وعلا- في قصة موسى: فَخَرَجَ مِنْهَا خَائِفًا يَتَرَقَّبُ [القصص:21] يعني خرج من مصر خائفًا من حاشية آل فرعون، لما قتل القتيل، فالشيء الذي يفعله الإنسان مع الحاضر، أو مع الجماعة الحاضرين، أو خوفًا من العدو الحاضر، يتباعد عنه؛ لئلا يعاقبه، ويهرب إلى جهة بعيدة حتى يكون ذلك أسلم له، كل هذا لا بأس به، هذه أمور عادية، وأمور متعلقة بالأسباب، حسية معروفة لا حرج فيها. أما دعاء الأموات، والغائبين عنك، والأصنام، والأشجار، والأحجار، هذا هو الشرك الأكبر، هذا عمل المشركين الأولين من عباد اللات والعزى ومناة، وعمل قوم نوح، وقوم هود، وقوم صالح، وغيرهم من الكفرة، هذه أعمالهم. فالواجب على العاقل أن يميز بين الأمرين، وأن يكون على بصيرة، فإذا قلت لأخيك: يا أخي، ناولني هذه السجادة، أو ناولني هذا الإناء، أو أقرضني كذا، هذا حاضر يسمع كلامك؛ لا بأس بإجماع المسلمين، لا حرج في ذلك، أو في البناء، أو في الحرب، والجهاد تستعين به، تقول: أعطني السلاح، تقدم إلى المحل الفلاني، امش في المحل الفلاني، احرس المحل الفلاني، كل هذا لا بأس به، هذه أمور عادية مشروعة، مأمور بها، ليس صاحبها عابدًا لغير الله، بل هي أمور حسية، مقدورة يتعامل بها الناس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15495/حكم-الاستغاثة-بالاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_821/nour_82106.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":16781,"question":"المستمع حسين ولد ميمني تاجي من الجمهورية الإسلامية الموريتانية، بعث برسالة إلى البرنامج، وضمنها سؤالين في أحد أسئلته، يقول: هل يجوز البناء على الميت كالبيت مثلًا؟ ولعله يقصد القبر سماحة الشيخ، جزاكم الله خيرًا.","title":"هل يجوز البناء على الميت مثل البيت؟","answer":"الجواب: البناء على القبور لا يجوز مطلقًا، بل ذلك من أسباب الشرك، ومن ذرائع الشرك، وقد قال -عليه الصلاة والسلام- في الحديث الصحيح: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وثبت في الصحيح من حديث جابر  قال: \"نهى رسول الله ﷺ أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه\". فلا يجوز البناء عليه لا قبة، ولا حجرة، ولا مسجدًا، ولا غير ذلك، ولا أن يقعد عليه، ولا أن يجصص، ولا أن يجعل عليه الستور والأطياب، كل هذا منكر، ومن وسائل الشرك، فالواجب الحذر من ذلك، والواجب على المسلمين في كل مكان أن يحذروا هذا العمل السيئ الذي انتشر في بلدان كثيرة، ودول كثيرة. فالواجب هدم المساجد التي على القبور إذا كانت بنيت عليها، والقباب التي على القبور تهدم وتزال، هذا الواجب على الدول الإسلامية أن يزيلوها، وتكون القبور مكشوفة ليس عليها شيء.  أما إن كان القبر جديدًا هو الذي دفن في المسجد، والمسجد قبله، المسجد قديم؛ فإنه ينبش القبر، ويخرج إلى المقابر، يجعل مع المقابر، ولا يكون في المسجد، بل يجب أن ينبش، وأن ينقل رفاته إلى المقابر العامة، ويبقى المسجد سليمًا يصلى فيه.  أما إن كان القبر هو القديم، وبني المسجد عليه؛ فإنه يهدم المسجد، ولا يجوز بقاؤه، يجب على رؤساء الدول الإسلامية، المسؤولين أن يقوموا بهذا الواجب، وأن يمنعوا الناس من الشرك، وذرائعه، فإن دعاء الأموات، والاستغاثة بالأموات شرك أكبر.  وبناء المساجد على القبور بدعة، ومن أسباب الشرك، ولهذا قال ﷺ في الحديث الصحيح الذي رواه مسلم في الصحيح عن جندب بن عبدالله البجلي قال ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد؛ فإني أنهاكم عن ذلك. ويقول ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد ولما قالت له أم سلمة، وأم حبيبة -رضي الله عنهما-: «إنهما رأتا في أرض الحبشة صورًا في بعض الكنائس، قال ﷺ في حق النصارى: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجدًا، وصوروا فيه تلك الصور ثم قال: أولئك شرار الخلق عند الله فأخبر أنهم شرار الخلق بسبب أعمالهم، وهي البناء على القبور، واتخاذ الصور عليها. فالواجب على الحكومات الإسلامية، وعلى جميع العلماء أن يسعوا في إزالة هذه الأبنية التي على القبور: من مساجد، وقباب، وغيرها، وأن تكون القبور بارزة مكشوفة، ليس عليها بناء، ولا مانع من رفع القبر قدر شبر، يرفع ترابه؛ حتى يعرف أنه قبر، يكون لحدًا، يكون له لحد، ويكون التراب الباقي يجمع على القبر؛ حتى يكون فوقه علامة على أنه قبر، وعليه نصايب، ويكون قدر شبر، ونحوه؛ حتى يعرف أنه قبر. أما البناء فلا يبنى عليه، لا مسجدًا، ولا غيره، ولا قبة، ولا غيرها، ولا يجوز أن يدعى صاحب القبر يقول: يا سيدي، أو يا فلان، يا أبا عبدالله، أو يا محمد، أو يا فلان! اغفر لي، أو انصرني، أو اشف مريضي، أو أنا في جوارك، ولا يقال: يا رسول الله، ولا يا أبا بكر، ولا يا سيدي البدوي، ولا يا سيدي الحسين، ولا يا سيدي عبدالقادر، ولا غيرهم، لا يجوز هذا كله، بل هو من الشرك الأكبر، دعاء الأموات، والاستغاثة بالأموات من الشرك الأكبر.  فلا يدعى الرسول ﷺ ولا غيره من الصحابة،  ولا من العلماء، بل هذا من الشرك الأكبر عند جميع أهل العلم من أهل السنة، والجماعة .. كانت الجاهلية يعظمون القبور، ويدعونها من دون الله، ويستغيثون بأهلها، فنهى الله عن ذلك، وحرم ذلك على المسلمين، قال : فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] وقال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] وقال : ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ[فاطر:13-14]، فسماه شركًا . فدعاء الأموات، وسؤالهم الشفاعة، أو النصر على الأعداء، أو شفاء المرضى، أو النذر لهم، أو الذبح لهم، كل هذا من الشرك الأكبر، ومن عبادة غير الله، والله سبحانه يقول: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23].. وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] ويقول النبي ﷺ: الدعاء هو العبادة دعاء الميت عبادة، وشرك به بالله  نسأل الله السلامة والعافية، ونسأل الله أن يصلح أحوال المسلمين، وأن يمنحهم الفقه في الدين، وأن يصلح ولاة أمرهم، حتى يزيلوا ما وقع من الشرك، وذرائعه، ووسائله. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15534/هل-يجوز-البناء-على-الميت-مثل-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_762/nour_76213.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":16816,"question":"يقول السائل: هل النذر للأولياء، والصالحين محرم؟ وكيف يكون حلالًا، وكيف يكون حرامًا؟ وما حكمه مأجورين؟","title":"حرمة النذر للأولياء والصالحين","answer":"الجواب: النذر للصالحين، والتقرب إليهم بالذبائح، أو بالنذور، أو بالدعاء شرك أكبر، من الشرك الأكبر، فالذي ينذر الصلاة، أو الذبيحة للصالحين؛ للنبي ﷺ أو لعبد القادر الجيلاني، أو للصديق، أو لعلي بن أبي طالب، أو يستغيث بهم، أو يذبح لهم، أو ينذر، أو يسجد لهم؛ يكفر بالله، يكون كفرًا أكبر، أو يستغيث بهم يا سيدي علي، أو يا نبي الله، أو يا رسول الله، اغفر لي، أو انصرني، أو يا سيدي البدوي، اغفر لي، أو انصرني، أو يا علي، أو يا أبا بكر، أو يا عمر، أو يا فلان، كل هذا من الشرك الأكبر. فدعاء الأموات، والاستغاثة بالأموات، والنذر لهم، والذبح لهم، والاستنصار بهم، كل هذا من الشرك الأكبر، هذا دين المشركين، هذا دين المشركين، نعوذ بالله من ذلك. وهكذا السجود لهم، وهكذا الذبح لهم، وهكذا طلب الغوث منهم، وهكذا للغائبين، ولو كانوا أحياء، إن كانوا غائبين يعتقد أنهم يسمعونه، ويجيبونه، وهو في البلاد البعيدة، يستغيث بهم، يستعين بهم، يسألهم قضاء الحاجات؛ لأنه يعتقد فيهم أنهم يعلمون الغيب، أو أنهم يغيثون من بعيد، هذا من الشرك الأكبر، كالاستغاثة بالأموات، نسأل الله العافية. أما من طريق الكتابة كونه يكتب كتابًا، يقول لفلان: اشتر لي كذا، أو أعطني كذا، أو أقرضني كذا، يكتب له كتابًا، لا بأس وهو حي، أو بالتلفون، يكلمه بالتلفون، هذا لا بأس، أما يعتقد في الغائب في بلد بعيد، لا يسمع كلامه، ويعتقد فيه أنه يسمعه، أو يعلم الغيب، أو يسمع كلامه من بعد لاعتقاده السر فيه، فيستغيث به، أو يطلبه قضاء الحاجة، أو العون على كذا هذا شرك أكبر كالميت، كسؤال الميت، نسأل الله العافية. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/15554/حرمة-النذر-للاولياء-والصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_585/58513.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":16944,"question":"يسألن السائلات سماحة الشيخ عن وضع الأحجار فوق القبر، وتسمى النصاير، وهي وضع حجر فوق قبر الرجل واحدة، ووضع حجرين فوق قبر المرأة.","title":"حكم وضع حجر على قبر الرجل وحجرين على قبر المرأة","answer":"الجواب: يُوضع أحجارٌ تحفظ التراب، حجر أو حجرين الرجل والمرأة واحد سواء ما فيه تخصيص، ما في فرق بين المرأة والرجل، ما في ..... طرف القبر من فوق، ومن أعلى، ومن أسفل، لبنة أو حجر يحفظ التراب، أو علامة يعرف بها القبر، لا بأس. وأما تخصيص المرأة بحجرين، والرجل بحجر هذا لا أصل له، ولكن القبور واحدة، إذا جعل عليها حجرًا في أعلاها، أو في أسفلها لحفظ التراب، أو كب عليها حصباء تحفظ التراب كل هذا طيب.","link":"https://binbaz.org.sa/fatwas/15729/حكم-وضع-حجر-على-قبر-الرجل-وحجرين-على-قبر-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58617.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":17174,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من المستمع: رقيب محمود محمد علي، أخونا يبدو أنه سوداني، وقد عرضنا بعض أسئلة له في حلقة مضت من حلقات هذا البرنامج، أما في هذه الحلقة، فيسأل سماحتكم، فيقول: يوجد لدينا بعض الإخوان يقعون في بعض الشرك، ويقول: بأن الولي، أو الرجل الصالح هذا الذي يميل إليه أنه يعلم الغيب، أو أن لديه بعض الغيبيات، هل يجوز أن نجلس مع أمثال هؤلاء؟ جزاكم الله خيرًا.","title":"حكم الجلوس مع من يعتقد علم الغيب في الأولياء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فهذا وأشباهه لا يجوز الجلوس إليهم إلا على سبيل الدعوة، والتعليم، والإرشاد، والنصيحة؛ لأن دعاء الأولياء، والاستغاثة بالأولياء -وهم أصحاب القبور أو الغائبون- من الشرك الأكبر، الذي جاءت الرسل -عليهم الصلاة والسلام- بالنهي عنه، ودل القرآن الكريم على النهي عنه، وأنه من الشرك الأكبر. فدعاؤهم، والاستغاثة بهم، والنذر لهم، والذبح لهم، كل هذا من الشرك الأكبر، الطواف بقبورهم، كل هذا من الشرك الأكبر، واعتقاد أنهم يعلمون الغيب، هذا كفر أكبر، فليس يعلم الغيب إلا الله وحده سبحانه، فالرسل، وغيرهم لا يعلمون الغيب، إنما يعلمه الله، إلا ما علمهم الله إياه، كما قد علمهم أشياء من أمر الآخرة، وأمر آخر الزمان، وما مضى من الزمان فليس لهم من علم الغيب إلا ما علمهم الله إياه، كما قال الله  في كتابه العظيم: قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ [النمل:65] ويقول : وَعِنْدَهُ مَفَاتِحُ الْغَيْبِ لا يَعْلَمُهَا إِلَّا هُوَ [الأنعام:59] ويقول لنبيه ﷺ يقول للناس: قُلْ لا أَمْلِكُ لِنَفْسِي نَفْعًا وَلا ضَرًّا إِلَّا مَا شَاءَ اللَّهُ وَلَوْ كُنتُ أَعْلَمُ الْغَيْبَ لاسْتَكْثَرْتُ مِنَ الْخَيْرِ وَمَا مَسَّنِيَ السُّوءُ إِنْ أَنَا إِلَّا نَذِيرٌ وَبَشِيرٌ لِقَوْمٍ يُؤْمِنُونَ [الأعراف:188] هكذا يقول ﷺ يخبرهم أنه نذير وبشير، ليس عالمًا بالغيب، ويقول -جل وعلا- يأمر نبيه أن يعلم الناس: قُلْ لا أَقُولُ لَكُمْ عِندِي خَزَائِنُ اللَّهِ وَلا أَعْلَمُ الْغَيْبَ وَلا أَقُولُ لَكُمْ إِنِّي مَلَكٌ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَى إِلَيَّ [الأنعام:50]. فعلم الغيب إلى الله سبحانه، ومن قال: إن هذا الولي الفلاني ابن عربي، أو الحسين  أو علي  أو الشيخ: عبدالقادر الجيلاني، أو غيرهم، من قال: إن هؤلاء، أو غيرهم يعلمون الغيب؛ فقد كفر، وأشرك، وكذب الله  وهكذا من زار قبور هؤلاء؛ ليدعوهم، أو يستغيث بهم، أو دعاهم من بعيد عن قبورهم في أي مكان، دعاهم، واستغاث بهم، ونذر لهم، أو اعتقد أنهم ينفعون، أو يضرون، أو أنهم يعلمون الغيب، أو أنهم يستجيبون لمن دعاهم بكشف الضر، وجلب النفع، أو ما أشبه ذلك، هذا هو الشرك الأكبر، هذا دين الجاهلية، دين قريش في حال جهلها، وكفرها، هذا دين أبي جهل، وأشباهه. فدعاء الأموات، والاستغاثة بالأموات، والذبح للأموات، وطلبهم الشفاء، وهكذا طلب الغائبين من الجن، أو الملائكة، أو غيرهم كله من الشرك الأكبر، فالواجب الحذر من ذلك غاية الحذر. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16030/حكم-الجلوس-مع-من-يعتقد-علم-الغيب-في-الاولياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72301.mp3","categories":["الدعوة والدعاة","نواقض الإسلام"]},{"id":17304,"question":"بعد هذا ننتقل إلى إريتريا، أسمرة عبر رسالة بعث بها مستمع من هناك يقول: من مجيب الرحمن صالح أمان، يسأل مجموعة من الأسئلة سماحة الشيخ في أحدها يقول: في بلدنا بعض الناس يذبح عند قبور الأولياء، وإذا سألتهم: أليس الذبح يجب أن يكون لله، وأن يكون خالصًا لله، وأن هذا العمل من الشرك، لا يستمعون إليك، وجهوهم لعلهم يستمعون، وفقكم الله، وجزاكم خيرًا.","title":"ما حكم الذبح لغير الله؟","answer":"الجواب: الذبح لغير الله من الشرك بالله، سواءً كان عند القبور، أو بعيدًا عن القبور، إذا نوى بالذبيحة التقرب إلى المخلوقين، أو إلى النجوم، أو إلى الأصنام، أو إلى الجن، أو الأولياء، أو الملائكة؛ صار شركًا بالله، يقول الله سبحانه في كتابه العظيم: قُلْ إِنَّ صَلاتِي وَنُسُكِي يعني: ذبحي، وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:162-163].  ويقول سبحانه في كتابه العظيم مخاطبًا نبيه محمد -عليه الصلاة والسلام-: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:1-2]، النحر عبادة مثل الصلاة، فالذي يذبح لغير الله كالذي يصلي لغير الله، فمن صلى للمخلوقين، أو سجد لهم أشرك، فهكذا إذا ذبح للأولياء، يتقرب إليهم، أو للأصنام، أو للجن، أو للملائكة، أو للنجوم، أو غير هذا من المخلوقين، فذبح لهم، أو صلى لهم، وسجد لهم، أو نذر لهم القرابين، ينذرون للولي الفلاني، أنه يذبح كذا.. أو يتصدق بكذا .. أو يسجد، أو يصلي، أو يصوم. المقصود: النذر لغير الله من الأولياء، أو من الجن، أو للأصنام كأن يقول: نذر علي للقبر الفلاني، أو للولي الفلاني، أن أتصدق بكذا، أو أن نصوم كذا، أو نصلي كذا، أو نذبح كذا، كل هذا من النذور الشركية. فالصلاة لغير الله، والسجود لغير الله، والذبح لغير الله، والنذر لغير الله كله من الشرك بالله، فإن صلى عند القبر لله، ما قصد صاحب القبر، يصلي لله، لكن يظن أن الصلاة عند القبر فيها فائدة، وأنها أفضل، وإلا ما قصده يصلي للمخلوقين، ولا قصده الذبح لهم، قصده الذبح لله، والصلاة لله، ولكن يظن أنها عند هذا القبر فيها فائدة، فيها ثواب أكثر، هذه بدعة، ولا تجوز ووسيلة للشرك، ولكن لا تكون شركًا إذا كان قصد به وجه الله، والتقرب إلى الله، لكن تكون بدعة؛ لأنه فعلها في محل ما يجوز التعبد فيه بالصلاة، والذبح، بل هذا يفضي إلى الشرك، ووسيلة إلى أن يذبحها للمخلوق صاحب القبر . نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16147/ما-حكم-الذبح-لغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_724/nour_72404.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":17345,"question":"سماحة الشيخ من أسئلة هذا السائل يقول: ما هو النفاق، وكيف الخلاص منه؟","title":"أقسام النفاق وحقيقته","answer":"الجواب: النفاق نفاقان: نفاق أكبر، ونفاق أصغر، النفاق الأكبر: كون الإنسان يتعاطى الدين، ويتظاهر بالدين وهو يكذب، لا يؤمن بالله، ولا باليوم الآخر، ولا يؤمن بالدين، ولكن يصلي مع الناس، أو يذكر الله مع الناس رياءً، كفعل المنافقين في عهد النبي ﷺ وإلا لا يؤمن بالدين ولا يؤمن بالجنة، ولا بالنار، ولا بتوحيد الله؛ هذا كافر كفرًا أكبر، أعظم من الكفار، من اليهود والنصارى، قال الله في حقهم: إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الأَسْفَلِ مِنَ النَّارِ [النساء:145] نسأل الله العافية. وهناك نفاق أصغر، وهو من صفات المنافقين، قاله النبي ﷺ: آية المنافق ثلاث: إذا حدث كذب، وإذا وعد أخلف، وإذا ائتمن خان هذه من صفات المنافقين، وقال ﷺ: أربع من كن فيه كان منافقًا خالصًا -نفاقًا عمليًا يعني-: إذا حدث كذب، وإذا وعد أخلف، وإذا خاصم فجر، وإذا عاهد غدر هذه من أعمالهم التي تجعله نفاقًا أصغر، كذلك: التكاسل عن الصلاة، وعدم الإكثار من ذكر الله، من خصال المنافقين، كما قال تعالى: إنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ وَلا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا [النساء:142] هذه من خصالهم. لكن هذا يسمى النفاق الأصغر، ما يخرج من الإسلام، مسلم لكن ناقص الإيمان، ناقص التوحيد، فهو مسلم، لكن يعتبر بهذه الخصال منافقًا نفاقًا أصغر، نسأل الله العافية، ويخشى عليه من النفاق الأكبر. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16185/اقسام-النفاق-وحقيقته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59323.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":17363,"question":"هذا سائل للبرنامج يقول في هذا  هل يجوز لي يا سماحة الشيخ الاستغفار لشخص من أحد أقاربي مات، وأنا لا أدري أهو مات على حسن الخاتمة، أم لا؟ علمًا بأنه كان يجلل، أو يقدس الأولياء، وأصحاب القبور، والأضرحة، ويعتقد بأن هذا من الدين، وجهوني في سؤالي.","title":"حكم الاستغفار لمن كان يعظم أصحاب القبور","answer":"الجواب: إذا كان ظاهره الشرك، والغلو في الأموات، ودعاء الأموات، والاستغاثة بالأموات لا، لا يدعى له، ولكن إذا كان ظاهره الإسلام، ولا تعلم عنه إلا الإسلام؛ فلا بأس تدعو له، وتستغفر لأخيك، هذا مشروع، المؤمن يدعو لإخوانه، ويستغفر لهم، كما قال أتباع المهاجرين والأنصار بإحسان: رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالإِيمَانِ [الحشر:10]، فأنت تستغفر لإخوانك، تدعو لهم بالرحمة إذا كان ظاهره الإسلام. أما من كان ظاهره الشرك -وهو الغلو في القبور ودعاء الأموات والاستغاثة بالأموات- فهذا لا يدعى له؛ لأن دعاء الأموات، والاستغاثة بالأموات، وطلب الحوائج منهم هذا من الشرك الأكبر، هذا دين المشركين، نسأل الله العافية. وهكذا دعاء الجن .. دعاء الأصنام .. دعاء الكواكب، كل هذا من الشرك الأكبر، يقول الله -جل وعلا-: مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُوْلِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ [التوبة:113]. ولما مات أبو طالب على دين قومه قال النبي ﷺ: لأستغفرن لك ما لم أُنْهَ عنك فأنزل الله في ذلك هذه الآية: مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُوْلِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ [التوبة:113] من مات على الشرك فهو من أصحاب الجحيم. فالمقصود: أن من كان معروفًا بدعاء الأموات، والاستغاثة بأهل القبور أو بالأصنام أو بالجن أو بالكواكب، أو بالملائكة، أو بالأنبياء، هذا كله شرك أكبر داخل في قوله -جل وعلا-: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ [النساء:48] وداخل في قوله سبحانه: إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ [لقمان:13] وداخل في قوله سبحانه: إِنَّهُ مَنْ يُشْرِكْ بِاللَّهِ فَقَدْ حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ وَمَأْوَاهُ النَّارُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ [المائدة:72] وفي قوله سبحانه: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] وقال سبحانه: وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ ۝ بَلِ اللَّهَ فَاعْبُدْ وَكُنْ مِنَ الشَّاكِرِينَ [الزمر:66]، وقال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] وقال -جل وعلا-: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ[فاطر:13].  القطمير: اللفافة التي على النواة وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14] هذا يعم الجميع، يعم الغائبين، ويعم الموتى من الأنبياء، وغيرهم إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا [فاطر:14] ولو قدرنا أنهم سمعوا لم يستجيبوا وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14] يعني: ينكرون ويتبرؤون إلى الله يقول سبحانه: تَبَرَّأْنَا إِلَيْكَ مَا كَانُوا إِيَّانَا يَعْبُدُونَ [القصص:63] نعم، نسأل الله العافية. المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16208/حكم-الاستغفار-لمن-كان-يعظم-اصحاب-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77004.mp3","categories":["إهداء القرب للميت","نواقض الإسلام","البدع والمحدثات"]},{"id":17584,"question":"ما حكم من يستهزئ بالمؤمنين المتمسكين بالسنة وخاصة موضوع اللحية؟ ويقول أيضًا: أولئك الذين يرفعون الثوب إلى أعلى الكعبين؟","title":"حكم الاستهزاء بأوامر الدين","answer":"الجواب: الاستهزاء من أقبح الكبائر ومن أقبح الشرور، لا يجوز الاستهزاء بالمسلم فيما فعله من الشرع، وإذا استهزأ بالدين قصده أن هذا الشرع ليس بشيء أو أنه هزء صار كافرًا نعوذ بالله، يقول الله جل وعلا: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ ۝ لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65-66]، فالاستهزاء بالصلاة أو باللحى أو ..... أو بالصيام أو بالحج يكون كفر ردة عن الإسلام، إذا كان قصده الاستهزاء بالشرع. أما إذا كان قصده الإنسان نفسه وليس قصده اللحية بل الاستهزاء به في مشيته أو سوء تصرفه هذا لا يجوز، لكن ما يكون كفرًا، أما إذا كان قصده استنكار اللحية واستقباح عمله أو استقباح الإسبال هذا كفر؛ لأنه استهزاء بالشرع، فالواجب الحذر من هذا الأمر العظيم، لأنه خطير يجب الحذر منه، فلا يجوز الاستهزاء بشيء من الشرع لا باللحى ولا بمنع الإسبال ولا بالصلاة ولا بالصوم ولا بغير ذلك، يجب على المؤمن أن يخضع لشرع الله وأن يؤمن به وأن يعظمه وأن لا يستهزئ به. نعم، نسأل الله العافية.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16537/حكم-الاستهزاء-باوامر-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84118.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":17624,"question":"من المستمع الشيخ محمد مسعود أبو العباس من محافظة كفر الشيخ في جمهورية مصر العربية رسالة يقول فيها: يوجد عندنا مدافن على جبلٍ من الرمل، وكان المعتاد شق أخدود ووضع الميت فيه في تابوت من الخشب فجاء بعض الناس وأراد البناء ليجمع العائلة كلها، فقال البعض: إن هذا محرم غير شرعي، واستند لحديث عن النبي ﷺ ونهيه عن البناء على القبور وتجصيصها وقام الخلاف في ذلك، لكنا في انتظار ما نسمع من سماحتكم، جزاكم الله خيرًا.","title":"حكم البناء على القبور والدفن في أرض رملية","answer":"الجواب: البناء على القبور واتخاذ المساجد عليها والقباب أمر لا يجوز بنص النبي عليه الصلاة والسلام، ثبت في الصحيحين عن النبي ﷺ أنه قال: لعن الله اليهود و النصارى اتخذوا قبور أنبيائهم مساجد، وقالت له أم سلمة وأم حبيبة أنهما رأتا في أرض الحبشة كنيسة ورأتا فيها صورًا كثيرة، قال أولئك -قال لهم النبي ﷺ-: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجدًا وصوروه في تلك الصور ، ثم قال ﷺ: أولئك شرار الخلق عند الله فسماهم شرار الخلق.\nوفي الصحيح عن جابر  -صحيح مسلم، عن جابر - قال: \"نهى رسول الله ﷺ أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه\".  فالقبور لا تجصص ولا يبنى عليها، ولا يبنى عليها مساجد، ولا يتخذ عليها قباب، بل هذا من وسائل الشرك، وهذا من عمل اليهود والنصارى، فالواجب الحذر منه. لكن إذا كانت الأرض رديئة يحفر فيها ويجعل فيها ما يمسك التراب من صندوق أو ألواح حتى لا تنهار على الميت أو حجارة حتى لا ينهار ويوضع الميت بينها، وإذا تيسر أرض صلبة جيدة يحفر فيها القبور ويكون فيها ألحاد من جهة القبلة، يوضع الميت في اللحد في جهة القبلة يكون هذا أفضل؛ لأن هذا هو الذي فعل بالنبي ﷺ، حفروا له وألحدوا له وجعلوه في اللحد، وهذا هو الأفضل. فإن لم يتيسر لأنها أرض رديئة يشق شق في الأرض ويجعل على جانبي الشق ما يحفظ التراب من ألواح أو حجارة من دون بناء، ثم يوضع الميت، ثم يوضع فوقه ألواح أو حجارة، ثم يرجم عليه التراب ويجعل عليه النصائب حتى يعرف أنه قبر، وتلتمس الأرض الطيبة ما هو بالأرض الرملية، إذا تيسر أرض طيبة يوضع فيها الميت حتى يحصر فيها، فإذا ما تيسر إلا أرض رديئة رملية يجتهدون في جعله في محل مناسب ثم يجعل فيه حجارة أو ألواح تحفظه عن التراب ثم يوضع الميت ثم يوضع فوقه حجارة تقيه التراب أو ألواح يقيه التراب، ثم يهال عليه التراب، إذا لم يتيسر أرض طيبة جيدة يحفر فيها ويكون فيها لحد ويوضع عليه اللبن، إذا تيسر هذا فهو السنة. أما إذا ما تيسر يكون شق في الأرض، يشق في الأرض ويوضع فيه الميت وتوضع على جانبيه وأطرافه الحجارة حتى تقيه التراب ثم يوضع فوقها حجارة كبيرة فوق الحجارة، تستره وتمنعه من التراب أو ألواح، وهذا هو المشروع في هذه الحالة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16553/حكم-البناء-على-القبور-والدفن-في-ارض-رملية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_843/nour_84306.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":18125,"question":"من جمهورية مصر العربية محافظة سوهاد هذه رسالة الأخ إبراهيم محمود إبراهيم أخونا يقول في رسالته: إنني من صعيد مصر، وأقيم في قرية صغيرة تكثر فيها المعتقدات الفاسدة في أصحاب القبور والأضرحة والمقامات ويهتفون بأسمائهم عند الشدائد ويلجئون إليهم عند الملمات وينذرون لهم النذور ويعتقدون فيهم النفع والضر ويحلفون بأسمائهم، فهل تصح الصلاة خلف إمام مسجد يعتقد في تلك القبور ويعتقد النفع والضر في أصحابها، ويهتف بأسمائهم؟وهو أيضًا يحلف بغير الله، وهل تصح صلاة الجمعة خلفه، ولو لم يوجد من يصلي خلفه غيره إلا منه هو مثله، فهل صلاة الفرد تكون في هذه الحالة أفضل أم الصلاة خلفه؟وهل يعذر أولئك القبوريون بجهلهم، أم لا يعذرون؟ فالجاهل منهم يحكم عليه بالإسلام أم يحكم عليه بالكفر؟ وهل يصلى على ميتهم ويدفن في مقابر المسلمين أم لا؟ أجيبوني عن هذه القضايا جزاكم الله خيرًا.","title":"حكم الصلاة خلف القبوريين","answer":"الجواب: هذا سؤال عظيم وله شأن كبير؛ لأنه يتعلق بالكفر والإيمان والإسلام والشرك، فهؤلاء الذين ذكرت -أيها السائل- عقيدتهم وأعمالهم، هؤلاء يعتبرون كفارًا مشركين وثنيين مثل كفار قريش وأشباههم لا يصلى عليهم ولا يصلى خلفهم؛ لكونهم يستنجدون بأهل القبور، ويسألونهم قضاء الحاجات وتفريج الكروب هذا شرك أكبر، فليس لأحد أن يصلي خلفهم أو يصلي عليهم إذا ماتوا، بل حكمهم حكم أهل الشرك. وإذا كان بعض الناس يعتقد فيهم، يعتقد في الأولياء النفع والضر صار شركًا آخر، كونه يدعوهم ويسألهم ويستغيث بهم هذا شرك أكبر، وكونه يعتقد فيهم النفع والضر والتصرف في العباد شرك آخر زائد على شرك المشركين الأولين، فإن قريشًا وأشباههم في جاهليتهم، لا يعتقدون النفع والضر في الأموات ولا في الأصنام، وإنما يعتقدون أنهم شفعاء عند الله، وأنهم يقربونهم إلى الله زلفى فقط، كما قال الله : وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ فرد الله عليهم بقوله: قُلْ أَتُنَبِّئُونَ اللَّهَ بِمَا لا يَعْلَمُ فِي السَّمَوَاتِ وَلا فِي الأَرْضِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ [يونس:18]، فسماهم مشركين بهذا مع أنهم قالوا: هؤلاء شفعاؤنا عند الله، فدل ذلك على أنهم لم يعتقدوا فيهم النفع والضر، وإنما اعتقدوا أنهم وسطاء. وقال سبحانه في سورة الزمر: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ ۝ أَلا لِلَّهِ الدِّينُ الْخَالِصُ وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ [الزمر:2-3]، فبين سبحانه أنهم ما عبدوهم؛ لأنهم يضرون وينفعون، وإنما عبدوهم ليقربوهم إلى الله زلفى. قال سبحانه عنهم أنهم يقولون مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:3]، فعلم بذلك: أن كفار قريش وغيرهم من كفار العرب في عهده ﷺ لم يعتقدوا أن أصحاب القبور أو أن الأصنام أو الأشجار أو الأحجار أو الأنبياء والصالحين ينفعونهم أو يضرونهم، وإنما اعتقدوا أنهم وسطاء ينفعونهم بالوساطة، ويقربونهم إلى الله زلفى، فلهذا عبدوهم وسألوهم واستغاثوا بهم وذبحوا لهم.. ونحو ذلك. فهؤلاء كفار ما داموا على هذه الحال، وليس لك أن تصلي خلف أحد منهم، ولو صليت وحدك، فالجمعة تصلي ظهرًا وحدك، إلا أن تجد من الموحدين من يصلي معك جمعة في مسجد إن تيسر في المسجد أو في بيت أحدكم إذا لم يتيسر في المسجد، أما أن تصلي خلف هؤلاء فلا؛ لأن هؤلاء شركهم ظاهر وكفرهم ظاهر، نسأل الله العافية. والواجب على الدعاة إلى الله أن يدعوهم إلى الله، وأن يوضحوا لهم الحق وأن يرشدوهم، والواجب عليهم أن يتعلموا ويسألوا ويستفيدوا وألا يصروا على باطلهم. فالواجب على من كان في هذه المثابة أن يسأل أهل العلم في بلاده أو في غير بلاده بالمكاتبة أو بالهاتف التلفون أو بغير ذلك من الوسائل، يسأل، الله يقول: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43]، فالحريص على دينه يسأل ولو بالسفر ولو يرتحل من مكان إلى مكان، كما فعل السلف الصالح يرتحلون من بلد إلى بلد لطلب العلم. وهذه المسألة أعظم مسألة، مسألة التوحيد والكفر هي أعظم مسألة وأكبر مسألة، فالواجب على كل مكلف أن يسعى في خلاصه ونجاته، وأن يسأل أهل العلم عما أشكل عليه، وألا يرضى بالعوائد التي درج عليها أسلافه، كما قال الله عن الكفرة: إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِمْ مُقْتَدُونَ [الزخرف:23]، ما يصلح، هذا ما يصلح، بل يجب التعلم والتبصر والتفقه في الدين والسؤال عما أشكل حتى تعبد ربك على بصيرة: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108]، فنسأل الله لك -أيها السائل- ولمن ذكرت عنهم هذه الأعمال، نسأل الله للجميع الهداية والتوفيق للعلم النافع والعمل الصالح، إنه سبحانه جواد كريم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17172/حكم-الصلاة-خلف-القبوريين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_852/nour_85202.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":18191,"question":"السائلة أختنا من جمهورية مصر العربية من ضمن أسئلتها سؤال في العقيدة، وتذكر سماحة الشيخ، وتقول: هل هناك فرق بين شرك الاعتقاد وشرك العبادة، وما هو الشرك وما هي أنواعه؟","title":"الفرق بين شرك العبادة وشرك الاعتقاد","answer":"الجواب: شرك الاعتقاد هو شرك العبادة، لكن الاعتقاد قد يكون بالقلب، وقد يكون شرك العبادة بإحداث بدعة، يعني: عبادة يعبد بها غير الله، فالاعتقاد كأن يعتقد في أهل القبور أو في الأنبياء أو في غيرهم أنهم يتصرفون في الكون، وأنهم يعلمون الغيب، هذه بدعة في الاعتقاد، وهذا شرك أكبر، كفر أكبر، وقد يفعل ما هو كفر أكبر لكن ليس من جنس هذا بل يدعو الميت، يستغيث به، يسجد له، يذبح له، هذه أيضًا كفر أكبر، وشرك أكبر؛ نسأل الله العافية. وهكذا اعتقاده أن الميت يعلم الغيب، أو أنه يشفي من المرض ولو ما دعاه، إذا اعتقد أن فلان يعلم الغيب الحي والميت، أو الأنبياء يعلمون الغيب، أو أن فلانًا يعلم الغيب أو فلانة، أو يشفي المرضى أو ما أشبه ذلك، هذا كفر أكبر، نسأل الله العافية. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17254/الفرق-بين-شرك-العبادة-وشرك-الاعتقاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78205.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":18206,"question":"من السودان هذه رسالة بعث بها أحد الإخوة المستمعين يقول فيها المرسل سيد جعفر أخونا له مجموعة من الأسئلة في أحد أسئلته يقول: ورد في بعض المجلات الناطقة باسم الإسلام مقالًا جاء فيه: إن بعض المسلمين ينذرون إن حصل لهم كذا وكذا، فسيقدمون بعض الأموال لصناديق النذور الموضوعة في المساجد المقامة على أضرحة الأولياء والصالحين، وهذه الأموال تجرد كل عام وتقسم على العاملين بهذه المساجد كالإمام وغيره، ويرجو من سماحتكم التوجيه في هذا الموضوع.","title":"حكم وضع النذور في صناديق المساجد التي بها أضرحة","answer":"الجواب: هذه النذور التي يتقرب بها الناس إلى أصحاب القبور والسدنة التي على القبور كلها باطلة وكلها شرك بالله ؛ لأن النذر عبادة، فلا يجوز أن يصرف لغير الله ، فلا يجوز أن ينذر لقبر البدوي أو الحسين أو فلان أو فلان أو فلان لا دراهم ولا شمعًا ولا خبزًا.. ولا غير ذلك، كل ذلك منكر لا يجوز، كما أن دعاء الأموات والاستغاثة بهم منكر وهكذا الذبح لهم والتقرب إليهم بالذبائح منكر. فهكذا النذر قال الله  لنبيه ﷺ: قُلْ إِنَّ صَلاتِي وَنُسُكِي [الأنعام:162] والنسك: العبادة يعم النذر وغيره قُلْ إِنَّ صَلاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:162-163] قال : إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:1-2] قال سبحانه: وَمَا أَنفَقْتُمْ مِنْ نَفَقَةٍ أَوْ نَذَرْتُمْ مِنْ نَذْرٍ فَإِنَّ اللَّهَ يَعْلَمُهُ [البقرة:270] يعني: فيجازيكم عليه، فالنذور قرب وطاعات فإن كانت لله فلصاحبها ثوابها، مع أن الرسول ﷺ نهى عن النذر وقال: إنه لا يأتي بخير فلا ينبغي النذر. لكن لو فعل النذر طاعة لله وجب عليه أن يفعل الطاعة كما قال النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه خرجه البخاري في الصحيح عن عائشة رضي الله عنها، فإذا نذر طاعة لزمه الوفاء وأجره على الله ، ولكن ينصح ألا يعود إلى ذلك، فإذا قال: لله علي أن أصلي ركعتين هذه الليلة، أو لله علي أن أصوم يوم الإثنين أو يوم الخميس، أو لله علي أن أتصدق بكذا وكذا على الفقراء، أو لله علي أن أحج هذا العام، أو عام كذا أو عام كذا، هذه كلها نذور عبادة وطاعة، فعليه أن يوفي بها. أما إذا نذر أن يتصدق بكذا وكذا للشيخ البدوي أو للسيد حسين أو للشيخ عبد القادر الجيلاني أو لفلان أو لفلان فهذه نذور باطلة نذور شركية باطلة، وهذا المال الذي يجمع في الصناديق يجب أن يفرق على الفقراء، ولا يعطاه إمام المسجد ولا خدم المسجد، ولا السدنة؛ لأنهم أعانوا على الشرك ودعوا إلى الشرك، فهم بدعائهم إلى الشرك ورضاهم بالشرك يكونوا مشركين بهذا العمل، فإن من دعا إلى الشرك ورضي بالشرك فهو مشرك نسأل الله العافية، وهؤلاء السدنة الذين يدعون الناس إلى التقرب إلى أصحاب القبور معناه أنهم يضلونهم، ويدعونهم إلى الشرك بالله ، فلا يجوز أن تدفع إليهم هذه الأموال بل يجب أن تؤخذ من الصناديق يأخذها ولي الأمر وتدفع إلى الفقراء والمساكين الذين لا تعلق لهم بهذه القبور. وعلى ولي الأمر وعلى الدعاة إلى الله وعلى العلماء أن ينصحوا الناس وأن يعلموهم أن هذه نذور باطلة، وأنه لا يجوز لهم أن يتقربوا إلى هذه الصناديق بشيء، وأن ترفع هذه الصناديق وتقفل وأن يمنع السدنة من أعمالهم الخبيثة، وهكذا أئمة المساجد التي فيها القبور يبين لهم أن هذا باطل، وعلى ولاة الأمور أن يزيلوا القبور من المساجد وأن يجعلوها في مقابر المسلمين، وإذا كان المسجد مبني على القبر وجب هدم المسجد وألا يصلى فيه، ويبقى القبر على حاله من دون مسجد. رزق الله الجميع التوفيق والهداية وأرشد الأئمة والعلماء والأمراء لكل ما فيه صلاح العباد والبلاد، ومنح الجميع الفقه في الدين والثبات عليه، وهدى العامة لما فيه صلاحهم ونجاتهم وأعاذهم من كل ما يغضبه سبحانه ويوقع في الهلاك والعذاب في العاجل والآجل، ولا حول ولا قوة إلا بالله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17249/حكم-وضع-النذور-في-صناديق-المساجد-التي-بها-اضرحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_855/nour_85508.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":18308,"question":"من المستمع إدريس محمد، سؤال يقول فيه: هل تجوز الكتابة على القبور، أو وضع علاماتٍ مميزة؟ جزاكم الله خيرًا.","title":"حكم وضع علامة على القبر أو الكتابة عليه","answer":"الجواب: أما الكتابة على القبور فلا تجوز؛ لأن الرسول نهى عنها عليه الصلاة والسلام، لا تجوز الكتابة عليها، ولا البناء عليها، لا مسجد، ولا قبة، ولا غير ذلك، بل يعاد فيها ترابها، ويرفع القبر قدر شبرٍ تقريبًا، حتى يعرف أنه قبر، ولا يزاد عليه شيء، ولا يبنى عليه، ولا يكتب عليه، ولا يجصص، هكذا نهى الرسول ﷺ، نهى عن تجصيص القبور، وعن القعود عليها، والبناء عليها، والكتابة عليها، وأن يزاد عليها من غير ترابها؛ لأن هذا من أسباب الغلو. فالواجب ترك ذلك، أما التعليم فلا بأس، كونه يعلم بحجر خاص، أو بقطعة حديد، أو بعظم، أو لوح ما فيه كتابة، لا حرج، قد علم النبي ﷺ على قبر عثمان بن مظعون . فالحاصل أن التعليم بحجرٍ خاص، أو بلبنة، أو بلوح، أو شبه ذلك، لا بأس بهذا. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17359/حكم-وضع-علامة-على-القبر-او-الكتابة-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73205.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":18309,"question":"سماحة الشيخ! يسأل هذا السائل ويقول: يشاهد بعد الدفن بعض الناس يضع على القبر علامتان من أحجار وعلى قبر المرأة ثلاث علامات وتسمى شاهد، فما حكم ذلك؟","title":"حكم وضع حجر أو حجرين على القبر ليُعرف","answer":"الجواب: لا بأس لتعريف القبر لا بأس، بما يعرف به قبر صاحبه، أو زوجة، أو أم، أو خالة، أو أب، أو عم، لا بأس، حجر أو حجرين، لا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/17360/حكم-وضع-حجر-او-حجرين-على-القبر-ليعرف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91303.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":18496,"question":"هذا السائل الذي رمز لاسمه بـ (م .م. ص) من اليمن يقول في سؤاله الأول: لقد طلب مني رجل أن أكتب على سطح قبر زوجته الذي هو مبني، يقول: طلب مني أن أكتب آية الكرسي بالطلاء، وكتبت الآية على سطح القبر، فهل عليَّ إثم في ذلك؟","title":"حكم كتابة آية الكرسي على القبر","answer":"الجواب: أولًا: القبر لا يجوز البناء عليه، الرسول ﷺ نهى أن يبنى على القبر، وأن يجصص، وأن يقعد عليه خرجه مسلم في الصحيح، فلا يجوز البناء على القبور؛ لأن البناء عليه قبة أو غيرها قد يسبب الغلو فيه، فالواجب أن يدفن ويرفع التراب عن الأرض قدر شبر علامة أنه قبر، ولا يبنى عليه شيء، لا قبة، ولا حجرة ولا غير ذلك، ولا يجوز الكتابة عليه؛ لأن الرسول ﷺ: نهى أن يكتب على القبر، وأن يبنى عليه، وأن يقعد عليه، ولا يجصص كلها نهى عنها النبي ﷺ والكتابة عليه قد تجر إلى الشر، قد يكتب عليه أنه كذا وأنه كذا وأنه كذا فيفتن الناس به، فلا تجوز الكتابة عليه لا قليلًا ولا كثيرًا. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17594/حكم-كتابة-اية-الكرسي-على-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78604.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":18508,"question":"سؤال يقول سماحة الشيخ: ما حكم الشرع في الأموال التي تنذر للأولياء، وتوضع في صناديق أضرحتهم، وهل لأحد فيها حق لانتسابه إلى هذا المولى؟","title":"حكم النذر للموتى والتقرب لهم","answer":"الجواب: هذه الأموال التي تنذر للموتى، ويتقرب بها إليهم، هذه نذور شركية باطلة، وعلى من فعلها أن يتوب إلى الله، وأن ينيب إليه، وأن يستغفره سبحانه؛ لأن النذر عبادة كالصلاة والذبح كلها عبادات، فالذي ينذر لأصحاب القبور أو للأصنام أو للجن كالذي يدعوهم ويستغيث بهم، وكالذي يذبح لهم كله شرك بالله . فالواجب الحذر من ذلك، وهذه الأموال التي توضع في الصناديق من النذور يجب أن يأخذها ولي الأمر، وأن تصرف في وجوه البر والخير كالصدقة على الفقراء، أو في مشاريع خيرية، وأن تمنع منعًا باتًا إذا عثر عليها ولي الأمر المسلم يزيلها، ويمنع الناس من هذا الأمر، ويعلمهم أن هذا لا يجوز، وما كان موجودًا فيها يوزع في وجوه الخير كما تقدم، ولا يجوز أن يقر هذا الصندوق، بل يجب أن يمنع، وتمنع السدنة الذين يدعون إلى ذلك، ويعاقبوا بما يردعهم وأمثالهم، وينادى في الناس في المساجد والخطب والصحف المحلية: أن هذا شرك، وأنه لا يجوز حتى يرتدع الناس، حتى يعلم الناس ذلك، والواجب على العلماء أن يفعلوا ذلك. الواجب على أهل العلم في كل مكان أن يرفعوا هذا اللبس عن الناس بالكلام الطيب في الإذاعة..، في الصحافة..، في التلفاز..، حتى يكون الناس على بينة..، على بصيرة، والله يقول -جل وعلا- في كتابه العظيم: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] ويقول سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108] ويقول : وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33]. فالدعوة إلى الله من أهم الأمور، وهي فرض على المسلمين فرض كفاية، إذا قام بها من يكفي سقط عن الباقين، فإن تركها العلماء والدعاة أثموا جميعًا، فالواجب على أهل كل بلد وكل قرية من أهل العلم أن ينشروا العلم، وأن يبينوا للناس ما أوجب الله عليهم من الدعوة..، من الإخلاص لله، وتوحيد العبادة، وعدم صرفها لغير الله كائنًا من كان، وتحريم الشرك قليله وكثيره، صغيره وكبيره.\nوهكذا بقية الأوامر والنواهي يوضحوا للناس وجوب الصلاة، وأداءها في الجماعة..، وجوب الزكاة..، وجوب صوم رمضان..، حج البيت مع الاستطاعة..، بر الوالدين..، صلة الرحم..، صدق الحديث، الأمر بالمعروف، والنهي عن المنكر.. إلى غير هذا مما أوجب الله. كما أنه يجب عليهم أن يبينوا للناس ما حرم الله عليهم من الشرك، وترك الصلاة، أو التساهل بها، أو العقوق للوالدين أو أحدهما، أو قطيعة الرحم، أو أكل الربا، أو الغيبة والنميمة، أو قتل النفوس بغير حق، أو شهادة الزور، أو غير هذا مما حرم الله. هذا واجب العلماء، والله سائلهم  عما كتموا وعما لديهم من العلم، وهذا أوان نشر العلم، هذا وقت الغربة الآن وقبل هذا العام بأزمان كثيرة، فالغربة للإسلام عظيمة ومنتشرة، والعلماء قليل، العلماء بالله وبدينه أهل البصائر قليلون، فالواجب عليهم مع قلتهم أن ينشروا العلم، وأن يتقوا الله في جميع الدول؛ في الدول الإسلامية وفي الأقليات الإسلامية، وفي كل مكان، يجب عليهم أن ينشروا العلم، وأن يعلموا الناس من طريق وسائل الإعلام، فقد يسر الله للناس اليوم وسائل الإعلام من طريق الإذاعة والصحافة والتلفاز والخطابة وسائر الأمور الممكنة كالنصيحة في المجتمعات والمحافل ونحو هذا مما يتيسر لطالب العلم إذا اجتمع بإخوانه أو في حفلة وليمة أو حفلة عرس أو غير هذا من أنواع الاجتماعات. المؤمن يستغل الفرص، العالم يستغل الفرص حتى ينشر العلم، وحتى يوضح للناس ما أوجب الله عليهم، وحتى يشرح للناس ما حرم الله عليهم، وبذلك تبرأ ذمته، وينتشر العلم، وتقوم الحجة، ويحصل له من الأجور مثل أجور من هداه الله على يديه، وهذا من فضل الله . يقول -عليه الصلاة والسلام- في الحديث الصحيح: من دل على خير فله مثل أجر فاعله. ويقول -عليه الصلاة والسلام-: من دعا إلى هدى كان له من الأجر مثل أجور من تبعه، لا ينقص ذلك من أجورهم شيئًا. والعكس بالعكس لا حول ولا قوة إلا بالله، يقول ﷺ: ومن دعا إلى ضلالة كان عليه من الإثم مثل آثام من تبعه لا ينقص ذلك من آثامهم شيئًا. ويقول ﷺ لـعلي  أمير المؤمنين لما بعثه إلى خيبر لدعوة اليهود وقتالهم إن أبوا قال له -عليه الصلاة والسلام-: فوالله لأن يهدي الله بك رجلًا واحدًا خير لك من حمر النعم هكذا يقول المصطفى -عليه الصلاة والسلام- لابن عمه أمير المؤمنين علي بن أبي طالب الخليفة الراشد، رابع الخلفاء، وأحد العشرة المشهود لهم بالجنة  يقول له النبي ﷺ: (فوالله) يحلف وهو الصادق وإن لم يحلف لكن للتأكيد لأن يهدي الله بك رجلًا واحدًا خير لك من حمر النعم فلا يليق بطالب العلم ولا بالعالم أن يتساهل في هذا الأمر مع شدة الحاجة والضرورة إلى العلم، بل يجب أن يشمر أينما كان، وأن يتقي الله، وأن يراقبه، وأن ينشر العلم يريد ما عند الله من المثوبة، يريد أن يهدي الناس وأن يرشدهم وأن ينقذهم مما هم فيه من الباطل، وأن يخرجهم من الظلمات إلى النور تأسيًا برسول الله ﷺ، وعملًا بأمره. نسأل الله للجميع الهداية والتوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا، واستجاب لدعوتكم.","link":"https://binbaz.org.sa/fatwas/17610/حكم-النذر-للموتى-والتقرب-لهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_868/nour_86804.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":18584,"question":"أختنا تسأل وتقول: إن في قريتنا رجل يدعي علم الغيب، وأنه يضر وينفع، ويشفي المريض، والناس يذهبون إليه، ويسألونه حوائجهم، وهو يقول لهم: إنكم نذرتم للصالحين مثلًا للـحسين أو علي أو العباس؛ فيجب عليكم الوفاء بهذا النذر، فإن لم تفعلوا سينزل بكم عقاب شديد، وهم يفعلون ما يقوله بدون تردد، ويخشونه كثيرًا.ويدعي النذر لغير وجه الله، ويقول: أنا متكئ على العباس، وهو الذي يصيح في رأسي ويخبرني بالحقيقة؛ لأني رجل صالح، وهم عندما يسمعون هذا الكلام، يرتعدون خوفًا منه، ويتضرعون منه خوفًا من أن يصيبهم غضبه. أفتونا ووجهونا، جزاكم الله خيرًا.","title":"الحكم على من يدعي علم الغيب","answer":"الجواب: هذا الذي يدعي علم الغيب، ويزعم أن العباس ينذر في رأسه، ويعلمه بكل شيء، ويرى النذر للحسين أو لـعلي أو لغيرهم من الموتى يتقرب إليهم، هذا ضال مضل، وكافر، ولا ينبغي الالتفات إليه، ولا التعلق به، ولا الخوف منه، بل هو مدجل مشوش مشعوذ، لا خير فيه، يأتي بهذه الألفاظ للترويج وتخويف العامة؛ وليأكل من أموالهم، ويلعب عليهم في هذه الأشياء، فهذا الرجل يجب أن يرفع أمره إلى الجهة المسئولة إذا كان في البلد جهة مسئولة عن مثل هذا؛ حتى يردع عن عمله السيئ، وحتى يحاسب على عمله السيئ، وحتى يستتاب، فإن تاب وإلا قتل كافرًا. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17747/الحكم-على-من-يدعي-علم-الغيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_871/nour_87107.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":18745,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع: محمد (أ. س. د. ع) أخونا يناقش في قضية استمع إليها عبر حلقات هذا البرنامج، فيقول: أرجو عرض هذه المسألة على سماحة الشيخ عبد العزيز بن عبد الله بن باز، استمعت في إحدى حلقات (نور على الدرب) عن القراءة والصلاة والدعاء عند القبور، حيث أفتى سماحة الشيخ عبد العزيز بأن قراءة القرآن عند القبور لا تجوز، وطالب الشيخ بالدليل لمن يقول بجواز قراءة القرآن عند القبر.وقد اطلعت على كتاب الروح لابن قيم الجوزية، حيث وجدت الحديث التالي: قال الخلال، وأخبرني الحسن بن أحمد الوراق، حدثني علي بن موسى الحداد، وكان صدوقًا، قال: كنت مع أحمد بن حنبل ومحمد بن قدامة الجوهري في جنازة، فلما دفن الميت جلس رجل ضرير يقرأ عند القبر، فقال له أحمد: يا هذا، إن القراءة عند القبر بدعة، فلما خرجنا من المقابر، قال محمد بن قدامة لأحمد بن حنبل: يا أبا عبد الله، ما تقول في مبشر الحلبي؟ قال: ثقة، قال: كتبت عنه شيئًا؟ قال: نعم، فأخبرني مبشر عن عبد الرحمن بن العلاء بن اللجلاج عن أبيه أنه أوصى إذا دفن أن يقرأ عند رأسه بفاتحة البقرة وخاتمتها، وقال: سمعت ابن عمر يوصي بذلك، فقال له أحمد: ارجع، وقل للرجل يقرأ، انتهى.وقال الحسن الزعفراني: سألت الشافعي عن القراءة عند القبر؟ فقال: لا بأس بها، انتهى.وقد نقلت هذين النصين حرفيًا من كتاب الروح لابن قيم، وهناك أقوال كثيرة في هذا الكتاب تجيز القراءة والصلاة عند القبر، أرجو من سماحة الشيخ توضيح هذه المسألة، مأجورين -بإذن الله تعالى-، وفقكم الله، وجزاكم الله خيرًا.","title":"حكم الصلاة وقراءة القرآن عند القبور","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فقد اطلعت على ما ذكره السائل، وما نقله عن كتاب الروح، قد اطلعت عليه في كتاب الروح، ولكن ينبغي أن يعلم السائل أن الأدلة الشرعية منحصرة في كتاب الله وسنة رسوله ﷺ، وفي إجماع أهل العلم.  أما ما يتعلق بأقوال أفراد الصحابة فهي تعرض على الكتاب والسنة، والعبادات توقيفية، لا يجوز منها إلا ما أجازه الشرع، ولم يثبت عن رسول الله -عليه الصلاة والسلام-، ولا عن خلفائه الراشدين أنهم كانوا يقرؤون عند القبور، ولا يصلون عند القبور. أما ما فعله ابن عمر هذا اجتهاد منه ، وهكذا من فعله بعده من بعض السلف من باب الاجتهاد، والاجتهاد يخطئ ويصيب، والواجب هو عرض ما تنازع فيه الناس على كتاب الله، وعلى سنة رسوله -عليه الصلاة والسلام-، وعلى ما أجمع عليه أهل العلم. ومعلوم أن القراءة محلها البيوت والمساجد، وليس محلها المقابر، المقابر إنما تزار، ويدعى لأهلها، وهكذا الصلاة ليس محلها المقابر، وإنما محلها المساجد والبيوت، فكما أنه لا يصلى عند القبور، كذلك لا تتخذ محلًا للقراءة، لا عند الدفن، ولا بعد الدفن، لقول النبي ﷺ لعن الله اليهود و النصارى اتخذوا قبور أنبيائهم مساجد وقوله ﷺ: اجعلوا من صلاتكم في بيوتكم، ولا تتخذوها قبورًا. فدل ذلك على أن القبور ليست محلًا للصلاة، قال: لا تتخذوها قبورًا يعني: بترك الصلاة فيها، قال: صلوا في بيوتكم وهكذا قوله ﷺ: لا تصلوا إلى القبور، ولا تجلسوا عليها وكلها أحاديث صحيحة ثابتة عن رسول الله -عليه الصلاة والسلام-، وقال -عليه الصلاة والسلام- في الحديث الآخر: اجعلوا من صلاتكم في بيوتكم، فإن الشيطان يفر من البيت الذي تقرأ فيه سورة البقرة. فالمقصود؛ أن المساجد والبيوت هي محل القراءة، وهي محل الصلاة، وليست المقابر محل صلاة، ولا محل قراءة، وإنما تزار للدعاء لأهلها؛ ولتذكر الآخرة، والزهد في الدنيا، وتذكر الموت، وكان -عليه الصلاة والسلام- إذا زار القبور يدعو لأهلها، يسلم عليهم، ويدعو لهم، وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية ولم يعلمهم أن يقرؤوا عندها القرآن. وقالت عائشة -رضي الله عنها-: كان -عليه الصلاة والسلام- إذا زار القبور يقول: السلام عليكم دار قوم المؤمنين، وإنا إن شاء الله بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، اللهم اغفر لأهل بقيع الغرقد. فلم يكن -عليه الصلاة والسلام- يقرأ عند القبور، ولم يكن يصلي عند القبور -عليه الصلاة والسلام-، والخير كله في اتباعه والسير على منهاجه -عليه الصلاة والسلام-، ولهذا قال -جل وعلا- في كتابه العظيم: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] ولم يكن خلفاؤه الراشدون يفعلون ذلك، وقد قال -عليه الصلاة والسلام-: عليكم بسنتي، وسنة الخلفاء الراشدين المهديين من بعدي، تمسكوا بها، وعضوا عليها بالنواجذ. وابن عمر له اجتهادات خالف فيها السنة، فمن ذلك: أنه كان يغسل داخل عينيه، وهذا خلاف السنة، وهذا من اجتهاده ، ومن ذلك: أنه كان إذا حج أو اعتمر يأخذ من لحيته ما زاد على القبضة، وهذا خلاف السنة، فقد قال -عليه الصلاة والسلام-: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين خرجه البخاري في صحيحه، وقال -عليه الصلاة والسلام-: قصوا الشوارب، وأعفوا اللحى، خالفوا المشركين متفق على صحته، وكان يأخذ ماءً لأذنيه، والسنة أن تمسح الأذنان بماء الرأس. فالحاصل: أنه له اجتهادات  لا يوافق عليها من جهة السنة، فهكذا ما يروى عنه من القراءة عند القبر، وقت الدفن، هذا شيء اجتهد فيه  والسنة بخلافه. والإمام أحمد -رحمه الله- لما بلغه ذلك كان لاجتهاده -رضي الله عنه ورحمه- رأى أن يوافق ابن عمر، وأن يقر الكفيف على قراءته بعدما قال له: إنها بدعة، فقوله الأول هو الصواب، قول أحمد الأول هو الصواب، وهو الذي يوافق الأدلة الصحيحة الكثيرة عن رسول الله -عليه الصلاة والسلام-؛ ولأن القراءة عندها، والصلاة عندها وسيلة إلى عبادتها من دون الله؛ فالناس قد يظنون أن القراءة عندها لها مزية، ولها ثواب زائد، وهكذا الصلاة عندها، فيجرهم هذا إلى اتخاذها مساجد، وإلى دعاء أهلها، والاستغاثة بأهلها، والتوسل بأهلها، فيقع الشرك، ولا حول ولا قوة إلا بالله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17869/حكم-الصلاة-وقراءة-القران-عند-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_875/nour_87501.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":18764,"question":"في آخر أسئلة هذا السائل، يقول: أستفسر عن الحكم الشرعي في نظركم سماحة الشيخ في البناء على القبور بالتفصيل.","title":"حكم البناء على القبور","answer":"الجواب: البناء على القبور محرم، لا يجوز البناء على القبر «النبي ﷺ نهى أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه»؛ لأنه من أسباب الغلو فيه، أن يحط عليه قبة، أو مسجدًا؛ هذا لا يجوز. أما كون المقبرة، عموم المقبرة تحاش بشيء حتى لا تمتهن بالدواب والناس لا بأس، هذا من باب صيانتها، أما أن يبنى على القبر تعظيمًا له، واحترامًا له؛ لأنه قبر فلان، أو قبر فلان؛ يوضع عليه قبة، أو مسجد؛ هذا لا يجوز، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17892/حكم-البناء-على-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79018.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":18824,"question":"رسالة وصلت إلى البرنامج من أحد المستمعين، يقول مقدمه لسيادتكم: أنا المقيم بالمملكة السعودية في مدينة الخرج: عاشور عبد الرحمن عبد الله أرجو من سماحتكم الإفادة عن هذه القضية: هل جثة الحسين في العراق، أو في الشام، أو في مصر؟","title":"موضع قبر الحسين والتحذير من عبادة القبور","answer":"الجواب: المعروف أن جثة الحسين في العراق، وليست في مصر، وليست في الشام، وإنما دفن في العراق، والذي في مصر ليس له أصل، وإنما هي دعوى لا حقيقة لها، وأقبح من ذلك وأشد من ذلك دعاؤه والاستغاثة به، والطواف بقبره، هذا من أعظم المنكرات والقبائح، بل من الشرك الأكبر، فإن دعاء الأموات، والاستغاثة بالأموات، والنذر لهم، والتقرب إليهم بالذبائح، كل ذلك من المنكرات العظيمة، ومن الشرك الأكبر، سواء كان المدفون الحسين، أو غير الحسين، وهكذا ما يفعل عند قبر البدوي، أو الست زينب، أو غير ذلك، كله يجب تركه، وإنما يجوز الزيارة فقط، الميت يزار، ويدعى له بالمغفرة والرحمة، سواء كان الحسين أو غير الحسين . أما أن يدعى الأموات من دون الله، ويستغاث بهم، وينذر لهم، ويطلب منهم الشفاء، أو النصر على الأعداء؛ هذا كله من عمل الجاهلية، من عمل المشركين الأولين، من الشرك الأكبر، وهكذا الطواف بقبورهم، رغبة فيما عندهم السر فيما يقول عبادهم من دون الله، كل هذا منكر عظيم، فالطواف عبادة عظيمة لله، ولا يجوز إلا حول الكعبة المشرفة، فالقبور لا يطاف بها، ولا يسأل أهلها شفاء مرضى، ولا نصرًا على الأعداء، ولا غير هذا، وإنما يزارون إذا كانوا مسلمين يزارون، ويدعى لهم بالمغفرة والرحمة، وفي ذلك عبرة وذكرى للزائر يذكر الموت، ويذكر الآخرة، أما العبادة فحق الله وحده، هو الذي يدعى ويرجى سبحانه وتعالى، كما قال : وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] وقال سبحانه: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ [الزمر:2] وقال : وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]. والآيات في هذا المعنى كثيرة كلها تدل على وجوب إخلاص العبادة لله وحده، وأنه هو الذي يدعى سبحانه ويرجى ويخاف وهو الذي يتقرب إليه بالذبائح والنذور، وغير هذا من العبادات، كما قال سبحانه: قُلْ إِنَّ صَلَاْتِيْ .. [الأنعام:162] يعني: قل يا محمد للناس، قل يا أيها الرسول للناس: إِنَّ صَلاتِي وَنُسُكِي [الأنعام:162] يعني: ذبحي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ  ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:162-163]. وقال سبحانه يخاطب نبيه -عليه الصلاة والسلام-: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ  ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ، ويقول النبي ﷺ فيما رواه علي : لعن الله من ذبح لغير الله فالواجب على جميع المسلمين التفقه في الدين، وتبصير الجاهل وتعليمه، وهذا من حق العلماء، هذا من واجب العلماء أن يبصروا الناس، سواء كان ذلك فيما يتعلق بقبر الحسين أو غيره في مصر وغير مصر، الواجب على العلماء علماء الحق أن يبصروا الناس، وأن يعلموهم أن دعاء الأموات والاستغاثة بالأموات والنذر للأموات أمر منكر، بل من الشرك الأكبر، وهكذا الطواف بقبورهم أمر منكر، الطواف عبادة لله ولا تفعل إلا عند الكعبة عند البيت الشريف في مكة المكرمة. فالقبور لا يطاف بها، ولا يدعى أهلها من دون الله، ولا يستغاث بهم، ولا ينذر لهم، ولا يذبح لهم، نعم إذا كانوا مسلمين يسلم عليهم، ويدعى لهم بالمغفرة والرحمة، هكذا كان النبي ﷺ يزور البقيع ويدعو لأهله بالمغفرة والرحمة، ويقول لأصحابه يعلمهم إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين، اللهم اغفر لأهل بقيع الغرقد هكذا كان النبي يفعل -عليه الصلاة والسلام-، وهذا هو السنة في زيارة القبور. أما قبور الكفار فلا يسلم عليهم إنما تزار للعظة والذكرى إذا زارها يتذكر الآخرة يتذكر الموت، لكن لا يسلم عليهم ولا يدعو لهم، وقد زار النبي ﷺ قبر أمه فلم يستغفر لها نهاه الله أن يستغفر لها لأنها ماتت على دين الجاهلية فاستأذن ربه أن يستغفر لها فلم يأذن له ، وإنما أذن له في زيارتها للعبرة والاتعاظ. وبهذا يعلم السائل أن ما يدعى من وجود الحسين في مصر ليس له أصل عند أهل العلم، وإنما جثته كانت في العراق، وهو قتل في العراق، ويقال: إن رأسه نقل إلى يزيد في الشام، فلا يدرى أين ذهب هذا الرأس هل دفن في الشام، أو أعيد إلى محله في العراق مع جثته؟ فالحاصل: أن وجود جثة الحسين في مصر أمر لا أساس له. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17960/موضع-قبر-الحسين-والتحذير-من-عبادة-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_921/nour_92108.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":18832,"question":"يقول هذا السائل من السودان سماحة الشيخ: في الحديث: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له البعض من الناس يذهب لقبر أحد الأشخاص كأن يكون شيخًا، ويطلب منه كذا وكذا، هل يجوز ذلك؟ وما حكم من يفعل ذلك في الشرع؟ وكيف ندعو للميت من منطلق هذا الحديث ابن صالح يدعو له كيف ندعو بعد الممات؟جزاكم الله خيرًا.","title":"حكم دعاء الموتى من دون الله","answer":"الجواب: تقول: اللهم اغفر لأبي، اللهم اغفر له، اللهم ارحمه، اللهم نجه من النار ، ونحو ذلك، هذا الدعاء له.  أما دعاء الميت، والتوجه إلى الميت تقول له: يا فلان انصرني، أو أنا في حسبك، أو أغثني هذا الشرك الأكبر، أو اشفع لي، أو أنا في جوارك، أو ما أشبه ذلك هذا الشرك الأكبر، هذا فعل المشركين مع اللات والعزى، ومع أصنامهم، وهذا فعل المشركين مع الشيخ عبد القادر الجيلاني، ومع البدوي، ومع الحسين، ما يجوز هذا. لا يقل: يا سيدي فلان انصرني، أو أنا في حسبك، أو أنا في جوارك، أو اشفع لي، هذا ما يقال للميت يقال للحي، يقول للحي: اشفع لي، ادع الله لي؛ ما يخالف الحي، تقول: ادع الله ليغفر لي، ادع الله أن يرحمني، هذا لا بأس. أما الميت تقول له: يا فلان، يا شيخ عبد القادر، أو يا حسين، أو يا ست زينب، أو يا فلان -وهو ميت- ادع الله لي، هذا ما يجوز؛ لأنه غير قادر، لا يستطيع شيء، أو اشفع لي؛ هذا توسل بميت لا يقدر، كالذي يقول للصنم: انصرني، أو اشفع لي، جماد لا قدرة له على شيء، فسؤال الأموات، والاستغاثة بالأموات، والتشفع بالأموات؛ هذا هو عمل المشركين وهذا هو المنكر، ولا يجوز، بل هو من الشرك الأكبر، نسأل الله العافية، نعم. ومثله الغائبون يا ملائكة الله، يا جبريل، يا ميكائيل، أو يا جن الفلانيين، يا جن الظهران، يا جن الحسا، يا جن أمريكا، يا جن مصر، أو يا جني الفلاني، كل هذا من الشرك الأكبر، وقد ذم الله بعض المشركين في هذا، قال عنهم: وَأَنَّهُ كَانَ رِجَالٌ مِنَ الإِنسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا[الجن:6] يعني: زادوهم شرًا وبلاء، نسأل الله العافية، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17982/حكم-دعاء-الموتى-من-دون-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_792/nour_79202.mp3","categories":["حكم الصلاة وأهميتها","شروح الحديث","نواقض الإسلام"]},{"id":18884,"question":"سماحة الشيخ يسأل عن أولئك الذين يسافرون إلى القبور وللطواف بها، ويعملون الاحتفالات، وما شابه؟","title":"حكم الطواف حول القبور والمشاهد","answer":"الجواب: جوابه مثلما تقدم، هؤلاء الذين يتوجهون للقبور سواء كانت القبور في بلادهم، أو كانت في بلاد أخرى يسافرون إليها لسؤالها، أو الاستغاثة بها، أو الطواف بقبورهم يدعوهم ويسألهم حاجاته، كل هذا من الشرك الأكبر، قد شبهوا قبورهم بالكعبة المشرفة، وصرفوا عباداتهم لهم دون الله  والله يقول سبحانه في كتابه العظيم: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] ويقول سبحانه: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] ويقول : فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ  ۝  أَلا لِلَّهِ الدِّينُ الْخَالِصُ [الزمر:2-3] ويقول سبحانه: فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ [غافر:14] ويقول : فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] إلى أمثال هذه الآيات الكريمات. والنبي ﷺ يقول: الدعاء هو العبادة فالذي يدعو الأموات أو الأشجار أو الأحجار أو القبور قد أشرك بالله  وهكذا إذا استغاث بهم أو طاف بقبورهم يسألهم حاجته، أو ما أشبه ذلك، أو يتعبد بالطواف يتقرب به إليهم، كل هذا من الشرك الأكبر، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم. سماحة الشيخ، في الختام أتوجه لكم بالشكر الجزيل بعد شكر الله  على تفضلكم بإجابة السادة المستمعين، وآمل أن يتجدد اللقاء وأنتم على خير. الشيخ: نرجو ذلك.","link":"https://binbaz.org.sa/fatwas/18024/حكم-الطواف-حول-القبور-والمشاهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_922/nour_92214.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":18911,"question":"رسالة وصلت إلى البرنامج من المستمع: أحمد بن أحمد بن علي عاطف، أخونا يقول: يوجد في بلادنا بعض من الرجال والنساء يدعون أنهم في أثناء الليل ينزلون إلى القبور، أو بمعنى أصح: إنهم يعلمون من أقوال الموتى، وماذا يعانون في قبورهم من العذاب إذا كانوا مذنبين، أو من نعيم إذا كانوا صالحين، ويقولون أيضًا لأهل الميت: إن ميتك فلان كذا وكذا، وهو يعذب في القبر بسبب سيئة أصابها، فاقض عنه دينه، وحاول أن تكفر عنه.أفيدونا عن هؤلاء، هل يتكلمون بالصدق، أم أنهم من المشعوذين الذين يريدون ابتزاز أموال الناس؟ جزاكم الله عنا خيرًا، وإذا كان هؤلاء يتكلمون افتراءً وكذبًا فماذا يجب علينا نحوهم؟","title":"حكم من يدعي أنه يعلم أحوال الموتى","answer":"الجواب: هؤلاء يعتبرون من الكذابين والمشعوذين، والذين يريدون أن يبتزوا أموال الناس بالباطل، أو أن يعظمهم الناس ويقولون عنهم: إنهم يعلمون الغيب، هذا لا يعلمه إلا الله، فالله أخفى عن الناس عذاب المقبورين ونعيمهم، فالذي يدعي أنه يعرف المعذب من المنعم كذاب أشر، يجب أن يهجر ويزجر ويعاقب، إن كان في دولة مسلمة حتى يتوب من عمله السيء، ولا يصدق ولا يلتفت إليه بالكلية؛ لأنه مجرم كاذب، نسأل الله السلامة والعافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18049/حكم-من-يدعي-انه-يعلم-احوال-الموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_923/nour_92311.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":18994,"question":"من الأخ المستمع: محمد صبحي محمود كرم مدرس مصري رسالة بدأها على النحو التالي: بسم الله الرحمن الرحيم، الحمد لله، ونصلي ونسلم على نبينا ورسولنا محمد بن عبد الله، وآله ومن والاه.إلى العلماء الكرام، والقائمين على برنامج‎‏ نور على الدرب، السلام عليكم ورحمة الله وبركاته، أسأل الله لكم الجزاء الجزيل، وأن يهدي بكم وينفع، وأن يبلغكم غاية القصد المأمول، وأن يتوجكم بتاج القبول على ما تقدمونه للإسلام والمسلمين، إنه ولي ذلك والقادر عليه وبعد.نحن في معظم قرى ومدن مصر نعاني من مشكلة ضيق المساحة في القبور، حيث أنها محددة في أماكن معلومة، ولا يجوز ترك مكانها وخاصة في بلاد الدلتا أي البلاد البعيدة عن الصحراء، مما اضطر الناس لبنائها، وارتفاعها عن الأرض أكثر من المتر في بعض الأحيان؛ وذلك لدفن عدد من الموتى في كل قبر، فما حكم ذلك؟ وماذا نفعل إن أردنا أن نفعل الصواب في عدم بنائها فلا نجد الظروف التي تعيننا على ذلك؟ أفتونا مأجورين أثابكم الله، وجزاكم الله خيرًا.","title":"حكم رفع القبور لدفن أكثر من ميت","answer":"الجواب: أيها الأخ الكريم! نسأل الله لك المثوبة على دعواتك، ونسأل الله أن يتقبل منك دعواتك، وأن يثيبنا وإياك، وأن يجعلنا وإياك من عباد الله الصالحين، إنه خير مسئول. أما القبور فالواجب ألا تبنى هذا الواجب، وأن تحفر في الأرض، وتعمق هذا هو الواجب؛ لأنه ثبت عن رسول الله عليه الصلاة والسلام من حديث جابر بن عبد الله الأنصاري رضي الله عنهما في صحيح مسلم \"أنه نهى عن تجصيص القبور، والبناء عليها\" ولعن اليهود والنصارى على اتخاذهم المساجد على القبور، وأخبر أنهم شرار الخلق بهذا العمل وهو البناء على القبور، واتخاذ المساجد عليها. فالواجب على أهل الإسلام في مصر، وفي غير مصر؛ الواجب عليهم أن يحفروا القبور في الأرض، وأن يعمقوها إلى نصف القامة تقريبًا حتى لا تظهر رائحتها، وحتى لا تحفرها الكلاب ونحوها، فإذا كانت البلد ليس فيها محل للحفر؛ لأنها صلبة حجرية، فلا حرج أن يدفن على ظهرها، ويحوط عليها؛ لأجل حفظها عن الكلاب وغيرها، وصيانتها؛ لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]، لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا[البقرة:286]. فالبناء حينئذ لحفظها لا لتعظيمها، والغلو فيها، ولكن لحفظها عن ظهور الروائح الكريهة، وعن امتهانها، وعن تناول السباع لها، فلا حرج بقدر الحاجة، بقدر الحاجة فقط والضرورة، أما مع القدرة على الحفر فلا يجوز البناء لا متر ولا غيره، يجب أن تكون في الأرض، وأن تبين للناس، ترفع قدر شبر مثلًا تقريبًا، ترابها يكون على كل قبر ترابه، وعليه النصايب في أطرافه حتى يعلم يعرف أنه قبر، وإذا رش وجعل فيه بطحاء فذلك أفضل، هذا هو المشروع في القبور، لكن من لم يستطع ذلك في أن الأرض لا يمكن حفرها فإنه معذور بقدر الحاجة فقط. نعم. المقدم: جزاكم الله خيرًا، إذا كانت الأرض بعكس ذلك سماحة الشيخ، وكانت التربة تنهال، ولا تتماسك، فما هو الحل الذي يراه سماحتكم؟ الشيخ: إذا كانت الأرض ضعيفة لا يستطاع الحفر فيها؛ لضعفها، وانهيارها؛ يجعل ما يحفظ الميت من ألواح أو حجارة أو نحو ذلك مما يحفظ الميت، حتى لا ينهار به القبر، يفعل ما يستطيع المؤمن من ألواح أو أخشاب، أو حديد؛ المقصود الذي يستطيع به حفظ الميت، حتى لا ينهار به القبر. نعم. المقدم: والأمر متيسر في هذه الأزمنة والحمد لله؟ الشيخ: حسب الطاقة، حسب الطاقة، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]. المقدم: أحسن الله إليكم. الشيخ: نعم. المقدم: جزاكم الله خيرًا. الشيخ: وإياكم. المقدم: أرجو أن يتفهم إخواننا هذه الإجابة جيدًا، وأن يعيدوا الاستماع إليها أكثر من مرة فهي في غاية الوضوح، جزى الله الجميع كل خير. الشيخ: آمين، لا شك أن هذا مهم نسأل الله للجميع التوفيق. المقدم: اللهم آمين. الشيخ: نعم. المقدم: اللهم آمين. الشيخ: ثم نعيد أيضًا مرة أخرى. المقدم: أحسن الله إليك. الشيخ: التحذير من البناء على القبور الذي فعله اليهود والنصارى، لا يجوز أن يبنى عليها مساجد، ولا قباب ولا غير ذلك؛ لأن هذا البناء من أسباب الشرك بالله، والغلو كما فعله اليهود والنصارى، وفعله أشباههم من عباد القبور الذين ظنوا أن هذا مشروع، فاتخذوا المساجد على القبور، وغلوا فيها، واستغاثوا بأهلها، ونذروا لهم، وطافوا بقبورهم، وهذا هو البلاء العظيم، هذا الشرك الأكبر. يقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، وقال عليه الصلاة والسلام لما أخبرته أم حبيبة وأم سلمة بكنيسة في بلاد الحبشة، وما فيها من الصور قال عليه الصلاة والسلام: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجدًا، وصوروا فيه تلك الصور، أولئك شرار الخلق عند الله حكم عليهم بأنهم شرار الخلق. فالواجب الحذر، وفي الصحيح -صحيح مسلم- عن جندب بن عبد الله البجلي  عن النبي ﷺ أنه قال: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد.. ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك وهذا نهي عظيم لوجوه ثلاثة: أولًا: ذم من فعل ذلك من اليهود والنصارى وغيرهم، وهذا تحذير من التشبه بهم. الثاني: قوله: فلا تتخذوا القبور مساجد هذا نهي صريح لا تتخذوا القبور مساجد. الثالث: قوله: فإني أنهاكم عن ذلك فهذا - أيضًا - تأكيد للنهي بقوله: فإني أنهاكم عن ذلك. فالواجب الحذر، والسر في هذا - والله أعلم - كما هو معروف عند أهل العلم أنه ذريعة للشرك، أن هذا البناء، وهذا التصوير عليها من أسباب الشرك بها، واتخاذ أهلها آلهة مع الله، كما قد وقع لليهود والنصارى وغيرهم، فيجب الحذر من ذلك، وألا يبنى على القبر لا مسجد ولا غيره، ولا قبة ولا غيرها، ولا يدعى من دون الله ولا يستغاث، ولا يطاف، إلى غير ذلك. العبادة حق الله وحده، هو الذي يدعى ويرجى، ويصلى له، ويسجد له، وينذر له، ويذبح له قال تعالى: قُلْ إِنَّ صَلاتِي[الأنعام:162] يعني: قل يا محمد للناس: إِنَّ صَلاتِي وَنُسُكِي[الأنعام:162] يعني: ذبحي وعباداتي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ  ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ[الأنعام:162-163] هكذا أمره الله أن يبلغ الناس عليه الصلاة والسلام. وقال تعالى: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ[الكوثر:1-2] وقال تعالى: ثُمَّ لْيَقْضُوا تَفَثَهُمْ وَلْيُوفُوا نُذُورَهُمْ وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَتِيقِ[الحج:29] الطواف بالبيت العتيق، ما يطاف بالقبور، الطواف بالقبور عبادة لها من دون الله، وشرك بالله  فإذا طاف يتقرب إلى الميت بالطواف أو يصلي له، أو يسجد له، أو يقول: يا سيدي أغثني، أو انصرني، أو اشف مريضي أو أنا في جوارك؛ كل هذا شرك بالله، كل هذا عبادة لغيره  فالواجب الحذر غاية الحذر، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18154/حكم-رفع-القبور-لدفن-اكثر-من-ميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_793/nour_79306.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":18995,"question":"أخونا يختم رسالته بجمع من الأسئلة عن الإشراك الذي لا يغفره الله، فيقول: الإشراك الذي لا يغفره الله هل هو في العبودية فقط؟ أو حتى في الطاعة؟ وهل هناك إشراك في الطاعة أم لا يوجد إشراك إلا في العبودية؟ ثم ما هو الإشراك؟ وكيف التخلص منه في أعمالنا ومعاملاتنا مع بعضنا؟ ثم إذا أطعنا أشخاصًا فيما فيه الخير، وما فيه طاعة الله، فهل هذه الطاعة إشراك بالله؟ -والعياذ بالله من كل عمل فيه شرك- أجيبوني عن هذه الأسئلة، جزاكم الله خيرًا، وأحسن إليكم.","title":"صور للشرك الأكبر","answer":"الجواب: الشرك بالله بيَّنه الله في كتابه العظيم، وهو صرف العبادة لغير الله كدعاء الأموات، والاستغاثة بالأموات، أو الملائكة أو الجن أو الأصنام، أو نحو ذلك، أو الصلاة لهم، أو السجود لهم، أو الذبح لهم تقربًا إليهم، يرجو شفاعتهم، يرجو أنهم ينصرونه، يشفون مريضه، يتقرب إليهم. أما إذا ذبح الذبيحة يتقرب إلى الله في الضحية يضحي عن أبيه، أو عن أخيه، أو يتصدق بها عنه، يرجو ثواب الله، لا يتقرب له، هو يتقرب إلى الله بالذبيحة كالضحية، فهذا قربة إلى الله ما هو للميت. أما إذا ذبح يريد التقرب للميت حتى يشفع له الميت، حتى ينصره، حتى يشفي مريضه، هذه العبادة لغير الله. وهكذا النذر يقول: إن شفيت مريضي يا فلان فلك علي ذبيحة كذا وكذا، هذا الشرك بالله، أو يقول: يا سيدي فلان، أو يا فاطمة ! أو سيدي البدوي انصرني، أو اشف مريضي، أو يا سيدي عبد القادر! أو يا شيخ عبد القادر! أو يا أبا ذر! أو يا رسول الله! أو يا أبا بكر الصديق! أو يا عمر! أو يا عثمان! انصرني أو اشف مريضي، أو يا ابن عباس! أو غيرهم من الناس، أو يا ملائكة الله انصروني، أو يا أيها الجن انصروني، أو الجني فلان انصرني، أو اشف مريضي، أو يا الصنم الفلاني، أو الشجرة الفلانية، كل هذا شرك بالله، وعبادة لغيره. وهكذا إنكار ما هو معلوم من الدين بالضرورة بالأدلة الشرعية. إذا أنكره يكون كافرًا مشركًا كالذي ينكر أن الله أوجب الصلاة، يقول: لا الصلاة ما هي بواجبة، هذا كافر كفر أكبر، أو قال: الفجر ما هي بواجبة، أو العصر ما هي بواجبة، أو الظهر ما هي بواجبة، أو المغرب ما هي بواجبة، أو الجمعة ما هي بواجبة على الناس، كل هذا كفر أكبر. أو يقول: الزكاة ما هي بواجبة، أو صيام رمضان ما هو بواجب على الناس، أو الحج مع الاستطاعة ما هو بواجب؛ هذا كفر أكبر، أو يقول: الزنا حلال، أو الخمر حلال، إذا كان جاهل يبين له الأمر الشرعي. فإذا أصر على أن الزنا حلال، أو الخمر حلال؛ صار كافرًا كفر أكبر، أو قال: مساعدة المشركين على المسلمين، كونه يساعد الكفار على إخوانه المسلمين حتى يذبحوهم، حتى يعذبوهم؛ هذه ردة. يقول الله سبحانه: وَمَنْ يَتَوَلَّهُمْ مِنْكُمْ[المائدة:51] يعني يتولى الكفار، ينصرهم على المسلمين، يكون ردة، وهكذا من يستحل السجود لغير الله، والصلاة لغير الله ولو ما فعله، يقول: ما يخالف، كونه يصلي للملائكة، أو يصلي للجن، أو يصلي للأموات، أو يسجد لهم، ولو ما فعله يكفر بهذا الاعتقاد. وهكذا من يطيع غير الله في الشرك بالله، إن أطاعه في الشرك بالله، والسجود لغير الله؛ صار مشركًا؛ لأنها طاعة فيما هو شرك بالله ، والرسول يقول ﷺ: لا طاعة لمخلوق في معصية الخالق، فإن أطاعه في المعصية صار معصية، وإن أطاعه في الشرك صار شركًا. فإذا أطاعه أنه يذبح لغير الله، أو يسجد لغير الله؛ صار شركًا أكبر، وإذا أطاعه أنه يقتل بغير حق، يقتل إنسان بغير حق، أو يجلده بغير حق؛ يكون عاصي ظالم، أطاعه في الظلم والمعصية. أما طاعة الرسول ﷺ فهي طاعة لله مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ[النساء:80] طاعة الرسول واجبة، تطيع الرسول فيما أمر به، وما نهى عنه، الله قال: قُلْ أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ[النور:54]. قال سبحانه: مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ[النساء:80] كذلك طاعة العلماء في الحق، وطاعة الأمراء في الحق طاعة لله، إذا أمرك الأمير تصلي في الجماعة، إذا أمرك أنك تعبد الله، ولا تشرك به شيئًا ، أمرك أن تحكم بالحق، وأن تحكم بما أنزل الله، يجب أن يطاع في ذلك؛ لأنه أمر بطاعة الله، أمرك ببر والديك عليك تطيعه؛ لأن طاعته طاعة لله في هذا، نهاك عن السرقة، ونهاك عن الظلم تطيعه؛ لأن الله أمر بهذا، فولي الأمر إذا أطعته في هذا أنت مطيع لله؛ لأنه أمرك بطاعة الله ورسوله، لكن إذا قال لك: اضرب والديك لا، لا تطيعه، إذا قال لك: اشرب الخمر لا، لا تطيعه، إذا أطعته بهذا فأنت عاصي مثله؛ لأن الرسول ﷺ يقول: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق . فإذا أطعته في الشرك صرت مشركًا، وإذا أطعته في المعصية صرت عاصيًا، وإذا أطعته بطاعة الله فأنت مأجور، وفق الله الجميع. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18159/صور-للشرك-الاكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_794/nour_79405.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":19009,"question":"يقول أخونا أيضًا: يقوم مثل هؤلاء الناس أيضًا أثناء الأعياد برفع أعلام ملونة أي أقمشة مرقعة من مختلف الألوان، ويكتبون عليها آيات قرآنية وأسماء كثيرة منها القطب والغوث الأعظم الجبار العالم أحمد الرفاعي، أحمد البدوي، عبد القادر الجيلاني، ويرفع هؤلاء الناس هذه الأعلام بأعمدة، وهم يطرقون الدفوف، ويمشون في الشوارع ويضربون أنفسهم في السيوف.ولكن الأمر الغريب من ذلك أن هذه الأعلام تتحرك كما تريد أي أنها تطير في الهواء، ما حكم الإسلام في ذلك؟ وما هو مدى الضرر لتشويه الدين الإسلامي؟","title":"حكم رفع الرايات بأسماء الأقطاب والأولياء","answer":"الجواب: كل هذا منكر مثلما تقدم يجب منعهم، يجب على ولاة الأمور منعهم من ذلك، وهذا من تلبيس الشيطان، تعينهم الشياطين على هذه الأفعال القبيحة المنكرة، هذه التي يفعلونها من ضرب الدفوف تسمية هؤلاء الذين يزعمونهم الأقطاب وأنهم كبار، وكذلك ما يفعلوه من طعن أنفسهم بالرماح وبالسكاكين أو الخناجر أو غير ذلك كله منكر، ولا يجوز لأحد أن يتعاطى هذه الأمور بل يجب على ولاة الأمور أن يمنعوهم من هذه الأشياء وأن يبصروهم بدين الله وأن يلزموهم بالحق. فالشيخ عبد القادر الجيلاني و أحمد البدوي و أحمد الرفاعي وغيرهم لا يجوز أن يعبدوا من دون الله، ولا يغلى فيهم ولا يدعوا من دون الله، ولا يستغاث بهم، فهم من جنس غيرهم عباد مخلوقون مربوبون لله  لا يجوز أن يعبدوا من دون الله، ولا يستغاث بهم، ولا يذبح لهم ولا ينذر لهم، ولا يجعل لهم بيارق تكتب فيها أسماؤهم لتعظيمهم وعبادتهم من دون الله، ودعوة الناس إلى الغلو فيهم، كل هذا من عمل ضعفاء البصيرة، ضعفاء العقول، من الصوفية التي صارت أعمالها تنادي عليها بأنهم أشباه مجانين، نسأل الله السلامة. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/18175/حكم-رفع-الرايات-باسماء-الاقطاب-والاولياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_926/nour_92603.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":19021,"question":"الرسالة التالية رسالة المستمع علي محمد الخشان من الرياض أخونا يقول: نرى كثيرًا من الناس عند دفن الميت يرفعونه أكثر من شبر وإذا نهيتهم قالوا: إن ذلك وقاية له من السيل، كذلك أراهم يزيدون حصباء فوق القبر بعد الدفن زيادة على ترابه الأصلي، كذلك يرشون عليه ماء، فما حكم ما يفعلون؟","title":"حكم رفع القبر أكثر من شبر وقاية له","answer":"الجواب: كل هذا لا بأس به، الأفضل شبر وما حوله، وإذا زاد يسيرا بالحصباء أو نحوه فالأمر سهل في هذا؛ حتى تعلم القبور وتعرف، وحتى لا تمتهن فإذا دفنوه بترابه وجعلوا الحصباء؛ حتى تثبت التراب ويبقى، ويرش بالماء؛ حتى يبقى هذا لا بأس به، حفظا لترابه وبقاء له.. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18189/حكم-رفع-القبر-اكثر-من-شبر-وقاية-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_927/nour_92706.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":19106,"question":"إذا المسلم وقع في محنة أو ضيق، فدعا الله  ومن ثم دعا أحد الصالحين مثال الشيخ عبد القادر الجيلاني قدس الله سره أو غير ذلك من الصالحين، فهل هذا جائز أم لا؟دار جدال بيننا حول هذا الموضوع، وذكر أحد الإخوة بأنه سمع بإذنه بأن إحدى الإذاعات ذكرت بأن المؤمن إذا وقع في ضيق يجب عليه أن يقول: يا عبد القادر! ثلاث مرات، ويقول: يا ساكن بغداد! يا راعي الحمراء! -يبدو لي شيخ عبد العزيز -وحينئذٍ يفرج كربه في هذه الحالة أو يدعو أحد الرجال الصالحين دون ذكر الله، أفيدونا أفادكم الله، وشكر الله لكم.","title":"حكم دعاء الأولياء والصالحين لتفريج الكروب","answer":"الجواب: الواجب على المسلم إذا وقع في ضيق وحاجة أن يضرع إلى الله سبحانه ويتوجه إليه جل وعلا ويسأله حاجته وكشف كربته، كما قال الله : أَمَّنْ يُجِيبُ الْمُضطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ السُّوءَ [النمل:62]، فهو سبحانه الذي يجيب المضطر. وهو القائل : وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي لَعَلَّهُمْ يَرْشُدُونَ [البقرة:186]، وهو القائل سبحانه: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60]. فالواجب على المؤمن في هذه الحال أن يضرع إلى الله، وأن يرجع إليه ، وأن يسأله تفريج كربته وتيسير أمره، أما الفزع إلى عبد القادر أو إلى غيره من الناس فهذا هو الشرك الأكبر، هذا شرك أكبر نعوذ بالله من ذلك، فلا يجوز أن يفزع الإنسان إلى عبد القادر أو إلى السيد البدوي أو إلى الحسين أو إلى علي بن أبي طالب  أو إلى غيرهم من الناس، بل يجب الفزع إلى الله وحده، وهو القائل سبحانه: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، وهو القائل : وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106]، فهو جل وعلا الذي يجيب المضطر، ويكشف السوء، ويجود على عباده . ولا ينبغي لأحد أن يغتر بما يفعله بعض الناس من الفزع إلى الشيخ عبد القادر أو إلى غيره أو أنها تقضى حاجته في بعض الأحيان، هذا من باب الاستدراج، وقد يقضيها له بعض الجن، يستدرجه بذلك حتى يوقعه في الشرك الأكبر دائمًا، فلا ينبغي لعاقل أن يغتر بكون حاجته قضيت لما دعا الشيخ عبد القادر أو غيره، قد تقضى الحاجة بأسباب قدرها الله  صادفت وقت دعائه لـعبد القادر، وقد تكون حاجة يستطيعها بعض شياطين الجن فيقضيها لك لأجل يستدرجك في الشرك، ويوقعك في الشرك مرة أخرى. فالمقصود أن الواجب على المكلف أن يخلص لله عبادته، وألا يدعو معه أحدًا  لا نبيًا ولا غيره، وهو يقول جل وعلا: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]، ويقول سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5]، ويقول : فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ ۝ أَلا لِلَّهِ الدِّينُ الْخَالِصُ [الزمر:2-3]. وبهذا تعلم أيها السائل أن هذا الذي قيل لك أمر باطل ومنكر من الشرك الأكبر، وأن الواجب على جميع المسلمين وعلى جميع المكلفين الإخلاص لله في العبادة، وأن لا يدعى أحد معه جل وعلا، لا ملك ولا نبي ولا صالح ولا غيرهم، بل لا يدعى إلا الله وحده  لكن الأحياء، لا بأس أن تدعو الحي القادر يساعدك في شيء من الزكاة أو من غيره لا بأس، تقول لأخيك الحاضر: يا أخي! ساعدني على إصلاح سيارتي، أو على عمارة بيتي، أو على قضاء الحاجة الفلانية، وهو حي حاضر يسمع كلامك هذا لا بأس به، كما قال الله  في قصة موسى: فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15]،  وكما هو معلوم بين المسلمين يتساعدون في أمور ديناهم وفي أمور دينهم، والله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ويقول النبي ﷺ: والله في عون العبد ما كان العبد في عون أخيه. فالتعاون بين المسلمين فيما يقدرون عليه مشافهة، أو من طريق الكتابة، أو من طريق الهاتف.. التلفون، أو من غيره من الطرق الحسية المعروفة، لا بأس بهذا، هذا شيء معروف وجائز؛ لأنه طلب من المخلوق ما يقدر عليه وهو حي حاضر يسمع كلامك، أو تكاتبه في ذلك من مكاتبة أو من طريق الهاتف ونحو ذلك. أما دعاء الأموات أو دعاء الغائبين من الملائكة والجن، أو دعاء الأصنام والأشجار والأحجار، هذا الشرك الأكبر، نسأل الله العافية والسلامة، وهذا دين المشركين الأولين، دين أبي جهل وعتبة بن ربيعة وشيبة بن ربيعة وأبي لهب ونحوهم، هذا دينهم، فيعبدون الأنبياء والأولياء ويستغيثون بهم، وينذرون لهم ويذبحون لهم، فكفرهم الله بهذا، وقاتلهم نبيه محمد عليه الصلاة والسلام، حتى أسلم من أسلم منهم، حتى ظهر دين الله . فالواجب على كل مكلف أن يخص ربه بالعبادة أينما كان، وأن يفزع إليه في جميع الشئون، وجميع الحاجات وجميع الكربات دون كل ما سواه ، ولكن مثل ما تقدم لا بأس أن تستعين بأخيك الحاضر الحي، تستعين به في مزرعتك، تحط عمال في مزرعتك، تستعين بهم في شئونك، تستعين بأبيك في حاجة.. بأخيك، وهم أحياء يسمعون كلامك، أو بالمكاتبة أو بالبرقية، أو بالهاتف أو بالتلكس هذه أمور عادية، غير داخلة في الشرك، إذا صارت في أمور يقدر عليها مستعانك. فأما دعاء الأموات كالشيخ عبد القادر، أو الشيخ البدوي أو الحسين أو علي ، أو الأنبياء أو غيرهم من الصالحين هذا لا يجوز، هذا الشرك الأكبر، وهكذا دعاء الجن، أو دعاء الملائكة أو دعاء الأصنام والأشجار والأحجار، هذا هو الشرك الأكبر، هذا دين أهل الشرك، هذا الدين الذي بعث الله الرسل بإنكاره والتحذير منه عليهم الصلاة والسلام. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18285/حكم-دعاء-الاولياء-والصالحين-لتفريج-الكروب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_884/nour_88403.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":19160,"question":"هل يصح بناء القبور من الطوب والأسمنت والحديد؟","title":"حكم بناء القبور من الطوب وغيره","answer":"الجواب: لا يجوز بناء القبور، بل تحفر ولا تبنى؛ لأنه ثبت عن رسول الله عليه الصلاة والسلام أنه نهى عن بناء القبور، نهى عن تجصيصها وعن البناء عليها. ولكن يحفر في الأرض، ويدفن الميت فيه يجعل فيه لحد في جهة القبلة بقدر الميت، ويكون القبر عميقًا بقدر نصف الرجل، حتى يكون بعيدًا عن السباع والكلاب، ويكون أبعد عن الروائح الكريهة التي قد تخرج من القبر، وإذا دعت الضرورة إلى بناء، إذا دعت الضرورة بأن كانت الأرض صلبة ولا يستطيعون الحفر وليس عندهم أرض يحفرون فيها، فلا مانع من جعله بين الأحجار يجمع له أحجار، ويجمع بينها ثم يوضع فوقه ألواح أو غيرها حتى تستره عن السباع وعن الكلاب ونحو ذلك، ويوضع عليها أحجار تستره عن ذلك حسب الطاقة، من دون حاجة إلى بناء، إنما أحجار تضبط بالطين أو بالجص أو بغير ذلك، حتى لا يتصل به الكلاب ونحو ذلك. نعم. المقدم: جزاكم الله خيرًا. الشيخ: عند الضرورة. المقدم: عند الضرورة. الشيخ: نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18334/حكم-بناء-القبور-من-الطوب-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_932/nour_93204.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":19193,"question":"يسأل سؤال ويقول: ما حكم سب الدين؟ وهل يجوز معاملة من يسب الدين؟ جزاكم الله خيرًا.","title":"حكم ساب الدين وكيفية معاملته","answer":"الجواب: سب الدين سب الإسلام؛ كفر أكبر، وردة عن الإسلام عند جميع العلماء ما فيه خلاف، ذكروا هذا في باب حكم المرتد، من سب الله أو سب الرسول ﷺ أو سب بعض الرسل غير محمد ﷺ كأن يسب نوح أو هود، أو آدم أو غيرهم من الرسل والأنبياء كفر بإجماع المسلمين. وهكذا إذا سب الإسلام سب دين الإسلام، أو استهزأ به يكون كافرًا عند جميع أهل العلم؛ لقول الله تعالى: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ ۝ لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ[التوبة:66]، ولأن سب الدين مضمونه الكراهة له وإنكاره، والله يقول سبحانه وبحمده: ذَلِكَ بِأَنَّهُمْ كَرِهُوا مَا أَنزَلَ اللَّهُ فَأَحْبَطَ أَعْمَالَهُمْ[محمد:9]. فالواجب على المؤمن أن يحذر، الواجب على كل مسلم ومسلمة الحذر، وأن يحفظ لسانه ويصون لسانه عما يجره إلى الردة عن الإسلام، فسب الدين والاستهزاء بالدين أو الاستهزاء بالقرآن، أو سب القرآن، أو سب الرسول، أو سب الله، أو سب بعض الأنبياء الآخرين كله ردة وكفر بعد الإسلام نعوذ بالله. واختلف العلماء هل يستتاب أو لا يستتاب؟ فقال بعضهم: يستتاب فإن تاب وإلا قتل ويعزر أيضًا، ولو تاب يعزر عن فعله القبيح بالجلد، والسجن ونحو ذلك. وقال آخرون: لا يستتاب بل يقتل حدًا يقتل كافرًا، ولا يستتاب، ولا يغسل، ولا يصلى عليه، ولا يدفن في مقابر المسلمين؛ لأن جريمته عظيمة، وكفره عظيم، والأقرب عندي والله أعلم القول باستتابته؛ لأنه قد يقع عن جهل، قد يقع عن غضب شديد، قد يقع عن استفزاز من بعض الناس، فكونه يستتاب، ويبين له خطؤه، وظلمه لنفسه، وأنه أتى جريمة عظيمة، وكفرًا عظيمًا، فإذا تاب رفع عنه القتل، لكن لا مانع من كونه يؤدب، يؤدبه ولي الأمر الأمير، أو القاضي يؤدبه عن هذا بجلدات أو بسجن أو نحو ذلك مع التوبيخ حتى لا يعود لمثل ذلك. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18425/حكم-ساب-الدين-وكيفية-معاملته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_799/nour_79905.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":19238,"question":"يقول: هل يجوز أن نصلي خلف من يعتقد في الأولياء والصالحين ويعتقد نفعهم، ويلتجئ إليهم، ويناديهم؟ جزاكم الله خيرًا.","title":"حكم الصلاة خلف من يعتقد النفع والضر في الأولياء","answer":"الجواب: الذي يعتقد في الأنبياء والصالحين، ويلتجئ إليهم، ويسألهم قضاء الحاجات، وتفريج الكروب؛ هذا مشرك شرك أكبر، هذا شرك الجاهلية شرك أبي جهل وأشباهه قال الله تعالى: وَلا يَأْمُرَكُمْ أَنْ تَتَّخِذُوا الْمَلائِكَةَ وَالنَّبِيِّينَ أَرْبَابًا أَيَأْمُرُكُمْ بِالْكُفْرِ بَعْدَ إِذْ أَنْتُمْ مُسْلِمُونَ[آل عمران:80] سماه كفر، وقال في المشركين: اتَّخَذُوا أَحْبَارَهُمْ وَرُهْبَانَهُمْ أَرْبَابًا مِنْ دُونِ اللَّهِ[التوبة:31] يعني اليهود و النصارى عبدوهم مع الله، ودعوهم، واستغاثوا بهم، وبنوا على قبورهم المساجد فكفروا بذلك. وهكذا وقع في قوم نوح لما توفي ود وسواع ويغوث ويعوق ونسر وهم رجال صالحون في قوم نوح، لما ماتوا في زمن متقارب حزن عليهم قومهم، ودس عليهم الشيطان أن يصوروا صورهم، وأن ينصبوها في مجالسهم كما قال ابن عباس رضي الله عنهما، ففعلوا صوروهم، ونصبوا الصور في مجالسهم، فلما طال الأمد على الناس عبدوهم من دون الله، واستغاثوا بهم، ونذروا لهم، وذبحوا لهم، فوقعوا في الشرك، فبعث الله إليهم نوحًا عليه الصلاة والسلام، ودعاهم إلى الله ألف سنة إلا خمسين عام وهو يدعوهم إلى الله، إلى توحيد الله، والإخلاص له، فلما استمروا في العناد أهلكهم الله بالغرق جميعاً، ولم ينج منهم إلا من كان مع نوح في السفينة كما قال تعالى: فَأَنجَيْنَاهُ وَأَصْحَابَ السَّفِينَةِ وَجَعَلْنَاهَا آيَةً لِلْعَالَمِينَ[العنكبوت:15]. فالذي يدعو الأولياء أو يدعو الأنبياء أو الملائكة أو الجن يستغيث بهم، ينذر لهم، يسألهم الشفاعة، يسألهم شفاء المريض، والنصر على الأعداء، كل هذا كفر بالله ، ردة عن الإسلام، فلا يجوز دعاء الأموات، والاستغاثة بهم، ولا دعاء الملائكة، ولا دعاء الجن، ولا النذر لهم، ولا الذبح لهم، يتقرب إليهم يرجو نفعهم، ودفع الضر منهم، كل هذا شرك أكبر، وكل هذا عمل الجاهلية، وإذا اعتقد أنهم ينفعون ويضرون دون الله صار شركًا في الربوبية أكبر وأعظم، أعظم من شرك الجاهلية الأولى، إذا اعتقد فيهم أنهم ينفعون دون الله ويضرون، وأن الله أعطاهم هذا يتصرفون في الكون صار هذا شركًا أكبر في الربوبية، أعظم من شرك أبي جهل وعباد الأوثان من قريش وغيرهم، وهكذا إذا اعتقد في شجرة أو صنم، واستغاث به، أو نذر له، أو اعتقد أنه ينفع ويضر كل هذا كفر أكبر، نسأل الله العافية. فالواجب على كل مسلم أن يحذر ذلك، وأن يتوب إلى الله مما قد وقع منه، هذا الواجب على جميع من يشهد أن لا إله إلا الله وأن محمدًا رسول الله، بل على جميع أهل الأرض كلهم يجب عليهم أن يعبدوا الله وحده، وأن يشهدوا أنه لا إله إلا الله وأنه لا معبود بحق سواه، ويشهدوا أن محمدًا عبد الله ورسوله، ويعبدوا الله وحده دون كل ما سواه، ويقيموا الصلاة، ويؤتوا الزكاة، ويصوموا رمضان، ويحجوا البيت، وعليهم أن يمتثلوا أوامر الله كلها، وينتهوا عن نواهيه . هذا واجب على جميع أهل الأرض من جن وإنس من يهود أو نصارى، أو شيوعيين أو وثنيين أو غيرهم، يجب عليهم جميعًا أن يعبدوا الله، وأن يشهدوا له بالوحدانية سبحانه، ولنبيه محمد بالرسالة، وأن يصدقوا الله ورسوله في كل شيء، وأن يصدقوا الرسل الماضين، وأنهم جاءوا بالحق، وأن يصدقوا بما أخبر الله به ورسوله عن الجنة والنار والآخرة، وعما يكون في آخر الزمان إلى غير ذلك، يجب على كل إنسان أن يعبد الله ويدخل في الإسلام، وإذا كان مسلماً فعليه أن يستقيم على إسلامه، وأن يحفظ إسلامه، وأن يصونه عن أسباب الردة، وأن يجتهد في ترك ما نهى الله عنه، وفي فعل ما أمر الله به، يرجو ثوابه، ويخشى عقابه، وفق الله الجميع. المقدم: اللهم آمين جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18426/حكم-الصلاة-خلف-من-يعتقد-النفع-والضر-في-الاولياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_799/nour_79906.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":19327,"question":"أخونا يسأل أيضًا ويقول: كثير من الناس يبنون على القبور بالطابون، والبناء لا يكون مرتفعًا، بل يكون ارتفاعه شبرين أو ثلاثة أشبار، هل هذا البناء محرم؟","title":"حكم ارتفاع القبر شبرين أو ثلاثة","answer":"الجواب: نعم، نعم الرسول ﷺ نهى عن البناء على القبور، ونهى عن اتخاذ المساجد عليها؛ لأنه وسيلة إلى الغلو فيها والشرك وتعظيمها، فلا يجوز للمسلم أن يبني على القبور، لا مسجدًا ولا غيره، ثبت عن رسول الله عليه الصلاة والسلام أنه قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد رواه الشيخان البخاري ومسلم في الصحيحين. وروى مسلم في صحيحه عن جندب بن عبد الله البجلي  عن النبي عليه الصلاة والسلام أنه قال: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد؛ فإني أنهاكم عن ذلك رواه مسلم في الصحيح. فالرسول ﷺ نهى عن اتخاذ القبور مساجد، وأخبر أنه من عمل الماضين الذين ذمهم الله وعابهم، وأخبر أنه ينهى عن هذا عليه الصلاة والسلام، وقد وقع في الناس الشرك بسبب هذه الأبنية، وهذه المساجد؛ ولهذا لعن ﷺ من اتخذها؛ لأنها وسيلة للشرك وعبادة المخلوقين من دون الله. وفي الصحيح عن جابر بن عبد الله الأنصاري  وعن أبيه، قال: نهى رسول الله ﷺ أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه فأخبر جابر  أن الرسول ﷺ نهى عن تجصيص القبور وعن القعود عليها وعن البناء عليها، وهذا صريح في تحريم ذلك. فالبناء على القبر محرم وهكذا القعود عليه وهكذا تجصيصه؛ لأنه وسيلة إلى الغلو فيه، ثم إلى عبادته من دون الله، ولا حول ولا قوة إلا بالله كما جرى لليهود والنصارى، وكما جرى للغلاة من هذه الأمة الذين بنوا على القبور وعظموها حتى عبدت من دون الله، وحتى صارت آلهة تعبد مع الله، كما قد وقع مثل ذلك عند قبر الحسين بن علي  في مصر، وعند قبر البدوي، وعند قبر الجيلاني في العراق، وعند قبور كثيرة. حتى فعله بعض الجهلة عند قبر النبي ﷺ في المدينة لجهلهم لما رأوا أنه مبني عليه، وعليه قبة، ظنوا أن هذا مما يسبب لهم الدعاء، والرسول ﷺ إنما دفن في حجرته في بيت عائشة لم يبن عليه إنما دفن في بيت عائشة في حجرتها رضي الله عنها خوفًا أن يغلو فيه الناس إذا جعل في البقيع بارزًا عند الناس، فدفن في بيتها رضي الله عنها وأرضاها، ثم وضع القبة على الحجرة بعض الأمراء المتأخرين في المدينة قبل الدولة السعودية. فالحاصل: أن البناء على القبور لا يجوز، وهو من وسائل الشرك سواء كان البناء مسجدًا أو غير مسجد، أو قبة تبنى عليه، كل ذلك لا يجوز، والواجب أن تكون القبور ضاحية بارزة في المقابر كما كان الحال على ذلك في عهده ﷺ في البقيع وفي غير البقيع. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18531/حكم-ارتفاع-القبر-شبرين-او-ثلاثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_896/nour_89602.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":19338,"question":"أولى قضايا هذه الحلقة قضية بعث بها مجموعة من السادة المستمعين يسألون ويقولون: ما حكم الشرع في الأموال التي تنذر للأولياء وتوضع في صناديق أخر؟ وهل لأحد حق فيها لانتسابه إلى هذا الولي؟","title":"حكم النذر لغير الله كالأولياء عند القبور","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالنذر من العبادات التي يجب إخلاصها لله وحده؛ لأنها التزام المكلف ما ليس لازمًا له من جهة الشرع تعظيمًا للمنذور له وتقربًا إليه، وهذا لا يصلح إلا لله وحده، فليس لأحد أن يلتزم صلاة ولا صومًا ولا صدقة ولا غير ذلك، لا لملك مقرب ولا نبي مرسل ولا لنجم ولا لشجر ولا لحجر ولا لجني ولا لغير ذلك، فهذه النذور التي يقدمها بعض الجهال إلى الأولياء من أصحاب القبور تعتبر شركًا أكبر كالذبح لغير الله وكالاستغاثة بالأموات كل ذلك من قسم الشرك الأكبر، قال الله : وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23]، وقال سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5]، قال : إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]، قال سبحانه: وَمَا أَنفَقْتُمْ مِنْ نَفَقَةٍ أَوْ نَذَرْتُمْ مِنْ نَذْرٍ فَإِنَّ اللَّهَ يَعْلَمُهُ [البقرة:270]، المعنى فيجازيكم عليه . فالنذور عبادات وقرب يجب أن تكون لله وحده، ومع ذلك فالرسول ﷺ نهى عن النذر قال: إنه لا يأتي بخير وإنما يستخرج به من البخيل. فلا ينبغي للمؤمن النذر، ولكن متى نذر فليكن لله وحده لا لغيره ، فإذا قال: لله عليه أن يصلي كذا أو يصوم كذا أو يتصدق بكذا لزمه الوفاء؛ لما ثبت عنه ﷺ أنه قال: من نذر أن يطيع الله فليطعه ومن نذر أن يعصي الله فلا يعصه خرجه البخاري في صحيحه من حديث أم المؤمنين عائشة رضي الله تعالى عنها، فإذا قال: لله عليه أن يصلي الضحى ركعتين وجب عليه الوفاء، لله عليه أن يتصدق بكذا وكذا درهم أو بكذا وكذا صاعًا من بر أو شعير أو أرز أو غير ذلك وجب عليه الوفاء أو قال: لله عليه أن يحج وجب عليه الحج لله عليه أن يعتمر وجب عليه العمرة وهكذا، لقوله عليه الصلاة والسلام: من نذر أن يطيع الله فليطعه. أما أن ينذر للأولياء لأصحاب القبور للجن للكواكب للرسل عليهم الصلاة والسلام لغيرهم من المخلوقين هذا شرك بالله، كما لو ذبح لغير الله أو استغاث بغير الله من الأموات أو من الجن أو من الكواكب أو ما أشبه ذلك، كله شرك بالله بإجماع أهل العلم، وإنما وقع هذا من المتأخرين من الذين جهلوا توحيد الله وجهلوا أحكام شريعته فوقعوا في الشرك، وقد يقع في هذا بعض من ينتسب إلى العلم؛ لعدم بصيرته بالعقيدة الصحيحة التي درج عليها سلف الأمة. وهذه النذور التي تكون من الأموال وتجمع في الصناديق حول القبور هذه حكمها حكم الأموال التي لا رب لها تؤخذ لبيت مال المسلمين أو يأخذها ولي الأمر ويصرفها في مصالح المسلمين كمساعدة الفقراء والمساكين، أو إصلاح الطرق أو دورات المياه أو ما أشبه هذا من المصالح العامة، ولا ترد على أهلها، وليس لأحد أن يأخذها من الناس بل هذه ترجع لولي الأمر إذا كان ولي الأمر صالحًا ينفذ شرع الله وإلا فلأصحاب البصيرة من أهل العلم يأخذونها ويوزعونها في وجوه البر والخير على الفقراء والمحاويج ونحو ذلك، ويبصرون الناس وينذرونهم منها ويحذرونهم منها وأنها منكر وأنها من الشرك حتى لا يعودوا إليها، وتزال هذه الصناديق وترفع من المساجد وغيرها؛ لأنها منكر ولأنها دعوة للشرك بالله  فالواجب إزالتها والتحذير منها وتوعية الناس وتبصيرهم بأن هذا من الشرك الأكبر، وما وجد فيها حين إزالتها من نقود تصرف في أعمال الخير كما تقدم، مع إزالتها من المساجد ومع تنبيه العامة وتحذيرهم من مثل هذا، وأنه لا يجوز التقرب إلى غير الله لا بالصلاة ولا بالنذور ولا بالصدقات ولا غير هذا، لا لأصحاب القبور ولا للأصنام ولا للكواكب ولا للجن ولا لغير هذا، العبادة لله وحده  كما قال : فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ [الزمر:2]، وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ [البينة:5]. والعبادة كل ما أمر الله به ورسوله، قال بعض أهل العلم: معناها: اسم جامع لكل ما يحبه الله ويرضاه من الأقوال والأعمال الظاهرة والباطنة وتكون قولية وتكون عملية وتكون بالقلب وتكون باللسان تكون بالجوارح فخوف الله وتعظيمه ومحبته هذه عبادات قلبية وهكذا رجاؤه سبحانه ونحو ذلك من سائر العبادات القلبية. وهناك عبادات عملية كالصلاة والزكاة والصدقات والذبح والنذر هذه عبادات عملية. وتكون قولية كالنذر من جهة القول فالنذر عبادة قولية وما يحصل به من صدقات ونحو ذلك عبادات مالية. فالحاصل أن جميع العبادات قولية أو عملية قلبية أو لسانية يجب أن تكون لله وحده ، ولا يجوز لأي أحد أن يصرفها لأي مخلوق من ولي أو رسول أو ملك أو جني أو صنم أو غير ذلك نسأل الله للجميع الهداية و السلامة. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18536/حكم-النذر-لغير-الله-كالاولياء-عند-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_897/nour_89701.mp3","categories":["الأيمان والنذور","نواقض الإسلام"]},{"id":19377,"question":"هل الصلاة صحيحة خلف من يقول: بعذر عباد القبور، فإنني وكثير من إخواني لا نصلي خلفهم لعدم تكفيرهم القبوريين، وإذا صليت خلفهم ارتبت في صلاتي وصليتها من جديد؟","title":"حكم الصلاة خلف القبوريين","answer":"الجواب: لا يصلى خلف القبوريين الذين بين المسلمين لا يصلى خلفهم؛ لأن الصلاة لا تصح خلف المشرك، فالذي يعبد القبور لا يصلى خلفه، كعباد الحسين وعباد البدوي وأشباههم، وعباد الشيخ عبد القادر الجيلاني ، وعباد الأصنام وغير هذا، كل من كان يعبد غير الله يدعوه ويستغيث به أو يطوف بقبره ويسأله قضاء الحاجة أو يصلي له أو يذبح له وما أشبه ذلك، فهؤلاء لا يصلى خلفهم؛ لأن ظاهرهم الكفر فلا يصلى خلفهم، وهكذا من يدعو إلى ذلك ويجيز ذلك، ويحبذه لا يصلى خلفه. المقدم: جزاكم الله خيرا. إذًا هؤلاء القبوريون لا يصلى خلفهم ومن صلى خلفهم فعليه أن يعيد صلاته؟\nالشيخ: نعم، عليه أن يعيد الصلاة.\nالمقدم: إذًا فعل أخينا صحيح والحالة هذه؟\nالشيخ: إذا صلى خلف القبوري يعيد صلاته، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18598/حكم-الصلاة-خلف-القبوريين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_934/nour_93407.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":19381,"question":"ما هو القبر الشرعي في الإسلام؟ وهل يجوز أن يرتفع القبر عن الأرض؟ أو يوضع عليه لوحات رخامية؟ أو يلحق به غرف للجلوس عند القبر؟","title":"حكم الكتابة على القبور والبناء عليها","answer":"الجواب: تقدم إيضاح القبر الشرعي، تقدم إيضاحه، ولا يجوز أن يوضع عليه لوحات مكتوب عليها شيء ولا أن يكتب عليه؛ لأن الرسول ﷺ نهى عن الكتابة على القبور لا في لوحات، ولا في غيرها، ونهى عن البناء عليها وعن تجصيصها، لا تجصص ولا يبنى عليها، ولا يوضع عليها لوحات ولا كتابات. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18603/حكم-الكتابة-على-القبور-والبناء-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73921.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":19405,"question":"له سؤال آخر عن أولئك الذين يزورون القباب وقبور بعض الصالحين كما يسميهم، ما هو توجيهكم شيخ عبد العزيز ؟","title":"حكم زيارة القباب والقبور","answer":"الجواب: يعلمون الزيارة الشرعية، يعلمون زيارة القبور الزيارة الشرعية، كان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية. وفي حديث آخر قال: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون غدًا مؤجلون وأتاكم ما توعدون، اللهم اغفر لأهل بقيع الغرقد، وفي حديث آخر قال عليه الصلاة والسلام: يرحم الله المستقدمين منا والمستأخرين، يغفر الله لنا ولكم، أنتم سلفنا ونحن بالأثر هذا وأشباهه يدعى به للموتى.\nأما وضع القباب على القبور أو المساجد هذا لا يجوز، يقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد ويقول ﷺ لـعلي : لا تدع صورة إلا طمستها، ولا قبرًا مشرفًا إلا سويته وصح عنه عليه الصلاة والسلام من حديث جابر عند مسلم في صحيحه: أنه نهى عليه الصلاة والسلام عن تجصيص القبور، والقعود عليها، والبناء عليها فالقبور لا يبنى عليها بنص النبي عليه الصلاة والسلام، ولا يتخذ عليها مساجد ولا قباب، ولا تجصص ولا يقعد عليها فتمتهن، كل هذا ممنوع، ولا تكسى بالستور كل هذا ممنوع، وإنما يرفع القبر عن الأرض قدر شبر تقريبًا ليعرف أنه قبر حتى لا يمتهن ولا يوطأ. فالمؤمن يبلغ إخوانه ويعلمهم وهكذا طالب العلم، وهكذا العلماء يعلمون الناس ما شرعه الله، والمؤمن يتعلم من العلماء ويعلم من يأتي القبور، يقول لهم: إن الزيارة الشرعية كذا وكذا، أما البناء على القبور أو سؤال الميت أو التبرك بتراب القبر أو تقبيل القبر أو الصلاة عنده كل هذه من البدع، لا يصلى عند القبور، ولا تتخذ محلًا للدعاء تقصد للدعاء عندها ولا القراءة عندها، كل هذا من البدع.\nكذلك طلب البركة منها أو الشفاعة منها أو الشفاء هذا من أنواع الشرك الأكبر، إذا قال: يا سيدي فلان! اشفع لي إلى الله، ويقول للميت: انصرني أو اشف مريضي، هذا لا يجوز؛ لأن الميت انقطع عمله بعد موته إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له. أما أنه يطلب منه شفاء المرضى أو النصر على الأعداء أو الشفاعة إلى الله في كذا هذا قد انقطع، لا يجوز طلبهم، بل يطلب من الله  اللهم اشفني .. اللهم أعطني كذا .. اللهم شفع في أنبياءك .. اللهم شفع في نبيك محمد ﷺ .. اللهم شفع في أفراطي، اللهم شفع في الملائكة والمؤمنين، هذا لا بأس به تطلب من الله جل وعلا. فالخلاصة أن المسلمين ينصح بعضهم بعضًا، ويعلم بعضهم بعضًا بأمر الشرع، والعلماء عليهم بيان ذلك وتوجيه العامة لما شرع الله  ومن ذلك أن يعلموا الزيارة الشرعية للقبور التي جاءت في الأحاديث عن رسول الله عليه الصلاة والسلام والتي تقدم بيانها. ويعلمون أنه لا يجوز البناء على القبور لا قباب ولا مساجد ولا أبنية أخرى، ولا تجصص ولا يقعد عليها، ولا تتخذ محلًا للدعاء عندها، أو الصلاة عندها، أو القراءة عندها، هذه من البدع التي هي من وسائل الشرك، الصلاة عندها والقعود عندها للدعاء أو القراءة هذا من وسائل الشرك من البدع، أما دعاء الميت والاستغاثة بالميت والنذر له والذبح له، هذا من الشرك الأكبر نعوذ بالله، من عمل الجاهلية. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18631/حكم-زيارة-القباب-والقبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_936/nour_93602.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":19606,"question":"رسالة وصلتنا من السائل أخيكم أبي محمد يقول: يا سماحة الشيخ! هل يجوز مدح الرسول ﷺ بمثل هذا الشعر وإنشاده بالمجالس:\tيا أكرم الخلق ما لي من ألوذ به\tسواك عند حدوث الحادث العمم\tفإن من جودك الدنيا وضرتها\tومن علومك علم اللوح والقلم","title":"التعليق على بعض أبيات البوصيري في البردة","answer":"الجواب: هذه أبيات منكرة، شرك، هذه من أبيات البردة للبوصيري لا تجوز، بل هذه من الشرك الأكبر نعوذ بالله، فإن الرسول ﷺ ليس من جوده الدنيا وضرتها، ضرتها الآخرة، هذا من جود الرب جل وعلا، من ملك الرب جل وعلا، ما يملكه النبي ﷺ ولا يعلم ما في اللوح والقلم عليه الصلاة والسلام، ما يعلم الغيب عليه الصلاة والسلام، وكذلك قوله:\nما لي من ألوذ به سواك عند ...\nهذا معناه جعله المعاذ والملاذ، هذا شرك أكبر، أعوذ بالله.","link":"https://binbaz.org.sa/fatwas/18869/التعليق-على-بعض-ابيات-البوصيري-في-البردة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94807.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]},{"id":19665,"question":"تقول في آخر أسئلتها السائلة من اليمن: هناك قبور تزار من قبل بعض الناس، فهل يجوز لهم ذلك، حيث أنهم يذبحون عندها؟ وهل يجوز أن يأكلوا اللحم عند هذه القبور؟","title":"حكم الذبح والدعاء والقراءة عند القبور","answer":"الجواب: الذبح عند القبور لا يجوز، ولا الجلوس عندها للقراءة والدعاء، بل يجب الحذر من ذلك، بل هذا من وسائل الشرك، وإذا ذبح يتقرب إلى أصحاب القبور أو دعاهم أو استغاث بهم أو نذر لهم هذا شرك أكبر، هذا شرك أكبر نعوذ بالله. أما زيارة القبور للسلام عليهم والدعاء لهم لا بأس سنة، يقول النبي ﷺ: زوروا القبور فإنها تذكركم الآخرة فإذا زارها المؤمن ليدعو لهم ويسلم عليهم ويستغفر لهم فلا بأس، أما أن يزورهم للذبح عندهم أو للقراءة عندهم أو للدعاء عند قبورهم هذا منكر لا يجوز ومن وسائل الشرك، فإذا ذبح لهم أو دعاهم أو استغاث بهم أو نذر لهم فقد صار هذا شركًا أكبر نعوذ بالله. أما النساء فلا يزرن القبور، يدعون لأمواتهم وهن في البيوت، لا حاجة إلى زيارة القبور. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18954/حكم-الذبح-والدعاء-والقراءة-عند-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95018.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":19715,"question":"هذه رسالة من عبد العزيز علي حسن قناوي مصري يعمل بالعراق، يقول عبد العزيز علي حسن في رسالته: أنا أعمل بالعراق وأسكن وأعمل مع جماعة منهم من يسب دين الله، ونصحتهم ولكن ما زال بعضهم على ما هو عليه.ف ما حكم الشرع فيمن يسب الدين؟ وإذا كان يصلي هل صلاته صحيحة؟ وماذا عليّ تجاههم؟ أفيدوني أفادكم الله.","title":"حكم الشرع فيمن يسب الدين","answer":"الجواب: إذا رأيت من يسب الدين أو سمعت من يسب الدين تنصحه وتنكر عليه؛ لأن سب الدين كفر أكبر، وردة عن الإسلام إذا كان الساب مسلمًا يرتد يكون كافرًا؛ فعليك أن تنصح له، وأن تنكر عليه المنكر، لقول الله -سبحانه-: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاء بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ[التوبة: 71] ولقول : وَلْتَكُن مِّنكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ[آل عمران: 104] ولقول النبي ﷺ: من رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان خرجه مسلم في الصحيح. فالواجب عليك وعلى غيرك من المؤمنين: إنكار المنكر؛ فإذا رأيتم من يسب الدين، أو لا يصلي، أو يشرب الخمر، أو يعق والديه، أو يفعل شيئًا من المنكرات الأخرى؛ فإن عليكم الإنكار وتوجيهه إلى الخير ونصيحته لعل الله يهديه بأسبابك، فإذا هداه الله صار لك مثل أجره، وإن أبى فينبغي السعي في إبعاده من العمل والقضاء عليه، وإذا كان في دولة مسلمة فينبغي رفعه إلى الدولة حتى تعاقبه، فإن تاب وإلا وجب قتله مرتدًا عن الإسلام؛ لقول النبي ﷺ : من بدل دينه فاقتلوه فإن تاب من سبه ورجع جاز عند بعض أهل العلم تركه وعدم قتله، ولكن يؤدب. وبعض أهل العلم يرى أنه يقتل مطلقًا ولو تاب، لكن الأرجح -إن شاء الله- أنه متى تاب إلى الله ورجع وندم واستقام؛ فإنه لا يقتل، ولكن لا مانع من تأديبه على ما أذنب عليه، وعلى ما فعله، بجلدات أو سجن أو نحو ذلك. والحاصل والخلاصة: أن الواجب على من لديه من المؤمنين الإنكار عليه وتحذيره، والاجتهاد في رده إلى الصواب؛ فإن لم يجدي ذلك ولم يتيسر ذلك فعل المؤمن ما يستطيع من السعي في فصله وإبعاده من العمل، ورفع أمره إلى ولاة الأمور، إذا كان في بلد ينكر فيها المنكر؛ فإن خشيت على نفسك ولم يتيسر الرفع عن هؤلاء ولا توبتهم فابتعد عن مخالطتهم إلى عمل آخر، لعلك تنجو. والله ولي التوفيق. المقدم: أثابكم الله، ولكن السائل يقول إن صاحبه هذا الذي يسب الدين يصلي، فيسأل ما حكم صلاته؟ الشيخ: سب الدين يبطل الأعمال، سب الدين كفر، والكفر يبطل العمل إذا مات عليه صاحبه، إذا مات الكافر على كفره بطل عمله، أما إن تاب قبل أن يموت بقي له عمله الصالح. المقدم: أثابكم الله","link":"https://binbaz.org.sa/fatwas/27597/حكم-الشرع-فيمن-يسب-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/%D8%AD%D9%83%D9%85%20%D8%A7%D9%84%D8%B4%D8%B1%D8%B9%20%D9%81%D9%8A%D9%85%D9%86%20%D9%8A%D8%B3%D8%A8%20%D8%A7%D9%84%D8%AF%D9%8A%D9%86.mp3","categories":["صلاة الجماعة","نواقض الإسلام"]}]
